E["item:a-bloodstained-journal-page"] = {t="item",n="A Bloodstained Journal Page",z="duskwood",s="During the investigation into Stalvan Mistmantle, Commander Althea Ebonlocke has a torn, bloodstained journal page examined. A few words remain legible, so she asks Clerk Daltry to compare its handwriting with the Town Registry.",h="During the investigation into Stalvan Mistmantle, Commander Althea Ebonlocke has a torn, bloodstained journal...",sec={{t="A Grim Piece of Evidence",b="Commander Althea Ebonlocke watches over Darkshire and asks for the handwriting on a torn, bloodstained page to be examined. Thick blood covers it, but a few words remain legible. Clerk Daltry is asked to compare them with the Town Registry.",sp=0},{t="Handwriting and Guilt",b="Clerk Daltry keeps the registry in Darkshire's Town Hall. Years of archiving signatures have taught him local handwriting. He compares the page with municipal records and confirms Stalvan wrote it. The tutor's guilt is beyond doubt.",sp=1,bt={"q66.6"}}},faq={{q="What is this bloodstained journal page?",a="The torn, bloodstained journal page is being examined in the investigation into Stalvan Mistmantle. Commander Althea Ebonlocke asks Clerk Daltry to check its handwriting.",al={"bloodstained journal page","stalvan journal page","blood page"},it="identity"},{q="Who can confirm who wrote this page?",a="Clerk Daltry in Darkshire's Town Hall can confirm who wrote the page. He keeps the town registry and compares the writing with old signatures to verify Stalvan's hand.",al={"who reads the page","clerk daltry journal","who identifies handwriting"}},{q="Why does Althea Ebonlocke need this page examined?",a="Commander Althea Ebonlocke has watched Stalvan for some time. She wants Clerk Daltry to compare the page with the Town Registry and learn whether both were written by the same hand.",al={"why althea needs page","why check handwriting"},it="why_wanted"},{q="Where does this page lead in the investigation?",a="The page goes to Clerk Daltry in Darkshire for comparison with the registry. After he examines its handwriting, the investigation continues with Commander Ebonlocke.",al={"what happens after page","stalvan chain next"},sp=1,it="next_step"},{q="Where does the Bloodstained Journal Page come from, and who made it?",a="The page is a torn remnant of Stalvan Mistmantle's personal journal. Its surviving words describe his despair and his intention to spill blood.",al={"who wrote bloodstained journal page","stalvan journal page origin","where did the bloodstained page come from"},sp=1,it="origin",add="e0fa872a"}},ang={["faction:Alliance"]="As a protector of the realm, you can see Darkshire's Night Watch examining this grim document as evidence in the investigation."},kw={"bloodstained","daltry","darkshire","duskwood","ebonlocke","handwriting","journal","stalvan"},rel={"quest:66","npc:althea-ebonlocke","npc:clerk-daltry","subzone:darkshire","zone:duskwood"},src={"A Bloodstained Journal Page","The Legend of Stalvan (11)"}}
E["item:a-dusty-unsent-letter"] = {t="item",n="A Dusty Unsent Letter",z="duskwood",s="In Moonbrook, an unsent letter bears on Stalvan Mistmantle’s past. Found in an old footlocker, it confirms that he lived there before his disappearance.",h="In Moonbrook, an unsent letter bears on Stalvan Mistmantle’s past.",sec={{t="A Clue in the Dust",b="Investigators searching Moonbrook find an unsent letter in an old footlocker. Darkshire’s town registry still lists Stalvan Mistmantle’s last address as the Moonbrook Schoolhouse. Clerk Daltry wants to know if he truly lived there. The letter confirms that Stalvan resided in the Westfall township for a time.\n\nFinding the letter disturbs a vengeful Forlorn Spirit. The spirit guards the remnants of Stalvan’s past with bitter malice.",sp=0},{t="Updating the Registry",b="At Darkshire’s Town Hall, Clerk Daltry receives the letter as evidence for the town registry. He finds it strange that the correspondence was never sent. Its trail hints at Stalvan’s path across the southern kingdoms of the Alliance.",sp=1}},faq={{q="Where is this letter found?",a="The letter lies in an abandoned footlocker in Moonbrook, Westfall. Dilapidated houses overrun by the Defias Brotherhood surround it.",al={"letter location","where to get dusty unsent letter","moonbrook letter"},it="place",gp=true},{q="Why was the letter never sent?",a="No one knows why the letter was never sent. Clerk Daltry finds this suspicious and suggests Stalvan may have fled Moonbrook in haste or left his correspondence behind before moving on.",al={"why unsent","stalvan letter unsent","who was the letter for"}},{q="Who needs to see this letter?",a="Clerk Daltry needs to see the letter. He manages the town registry inside Darkshire’s Town Hall.",al={"who do i give the letter to","clerk daltry letter","turn in letter"},it="target",gp=true},{q="Why does a spirit attack when finding it?",a="Disturbing the footlocker summons a Forlorn Spirit tied to Stalvan’s haunting legacy. It attacks anyone prying into his forgotten life and afflicts intruders with the debilitating Curse of Stalvan.",al={"forlorn spirit","why ghost spawn","curse of stalvan"},it="danger"},{q="What is A Dusty Unsent Letter?",a="This worn parchment is an unmailed piece of correspondence tucked away inside an old footlocker in Moonbrook. It serves as tangible proof that the elusive Stalvan Mistmantle once lived in the Westfall settlement before vanishing from local history.",al={"dusty unsent letter","what is dusty unsent letter","unsent letter moonbrook"},it="identity",add="f7d2f799"},{q="Where does A Dusty Unsent Letter come from, and who made it?",a="The letter was left behind in Moonbrook, stored inside a footlocker in the abandoned town. Written during Stalvan Mistmantle's stay in Westfall, it was penned by him to correspond with contacts outside the village, though for unknown reasons it was abandoned before it could ever be dispatched.",al={"who wrote the dusty unsent letter","where did the letter come from","dusty letter origin"},it="origin",add="9d1bfc16"},{q="Why does anyone want A Dusty Unsent Letter?",a="Clerk Daltry in Darkshire needs official evidence to update the town registry regarding Stalvan Mistmantle. Since town records have gaps, this letter provides the necessary verification that Stalvan resided in Moonbrook, allowing Daltry to properly document his past movements.",al={"who wants dusty unsent letter","why keep the dusty letter","why bring letter to daltry"},it="why_wanted",add="ab0e7a8a"}},ang={["faction:Alliance"]="As an Alliance traveler, you can help Darkshire keep accurate records by learning Stalvan’s trail between the human settlements of Westfall and Duskwood."},kw={"clerk daltry","darkshire","dusty unsent letter","forlorn spirit","moonbrook","stalvan mistmantle","the legend of stalvan"},rel={"quest:66","npc:clerk-daltry","subzone:moonbrook","zone:duskwood"},src={"A Dusty Unsent Letter","The Legend of Stalvan (3)"}}
E["item:a-faded-journal-page"] = {t="item",n="A Faded Journal Page",z="duskwood",s="In eastern Elwynn, an old page lies unread in Marshal Haggard's home, tied to Stalvan Mistmantle's grim history.",h="In eastern Elwynn, an old page lies unread in Marshal Haggard's home, tied to Stalvan Mistmantle's grim...",sec={{t="Parchment in the Chest",b="For years, the Faded Journal Page lay in an old trunk at Marshal Haggard's home near Elwynn Forest's eastern border. Haggard had retired there, but failing eyesight kept him from reading the weathered parchment. The page remained neglected until investigators seeking the truth about Stalvan Mistmantle retrieved it.",sp=0},{t="The Trail to Darkshire",b="Unable to read the brittle writing, Marshal Haggard sent investigators across the river to the Scarlet Raven Tavern in Duskwood. Tavernkeep Smitts examined the page and recognized the handwriting. It tied the page to the grim saga that haunts the region.",sp=1}},faq={{q="Where is the Faded Journal Page found?",a="The page is found in an upstairs chest in a house near Marshal Haggard, in eastern Elwynn Forest by the river boundary with Duskwood.",al={"page location","where is faded journal page","chest location"},it="place",gp=true},{q="Why couldn't Marshal Haggard read the page himself?",a="Age has so weakened Marshal Haggard's eyesight that he can no longer make out the faded writing.",al={"why didn't haggard read it","marshal haggard blindness"}},{q="Who recognizes the handwriting on the journal page?",a="Tavernkeep Smitts, the barkeep at the Scarlet Raven Tavern in Darkshire, recognizes the handwriting when he examines the page.",al={"who knows the handwriting","who reads the page"},it="ties"},{q="What protects the chest containing the page?",a="A hostile Forlorn Spirit attacks anyone who opens the upstairs chest, before the page can be examined safely.",al={"chest ghost","what attacks at the chest"},it="danger"},{q="What is the Faded Journal Page?",a="It is an aged, weathered parchment recovered from a chest in Marshal Haggard's home. The writing across it has grown faint with time, but it preserves an authentic entry detailing the private thoughts and movements of Stalvan Mistmantle, serving as a tangible clue in unraveling his dark history.",al={"what is faded journal page","faded journal page","faded journal page info"},it="identity",add="6378278c"},{q="Where did the Faded Journal Page come from?",a="The page was written by Stalvan Mistmantle himself as part of his personal diary. It ended up among a bundle of abandoned parchments tucked inside a chest upstairs in the dwelling where Marshal Haggard later took up residence near the border between Elwynn Forest and Duskwood.",al={"origin faded journal page","who wrote faded journal page","where did faded journal page come from"},it="origin",add="0f9a7ce9"},{q="Why is the Faded Journal Page wanted?",a="Investigators seeking the truth behind the enigmatic figure known as Stalvan Mistmantle need the page to piece together his past. Because the handwriting on it is distinct, showing it to knowledgeable locals such as Tavernkeep Smitts in Darkshire can unlock vital leads regarding Stalvan's history and whereabouts.",al={"why want faded journal page","why do you need faded journal page","faded journal page purpose"},it="why_wanted",add="200aee1d"}},ang={["faction:Alliance"]="As an Alliance traveler, you can use this forgotten record to help solve a mystery troubling townsfolk on both sides of the river between Elwynn and Duskwood."},kw={"darkshire","elwynn forest","faded journal page","marshal haggard","smitts","stalvan"},rel={"quest:66","quest:1666","npc:tavernkeep-smitts","subzone:scarlet-raven-tavern","zone:elwynn","zone:duskwood","subzone:darkshire"},src={"A Faded Journal Page","The Legend of Stalvan (8)","The Legend of Stalvan (9)"}}
E["item:a-torn-journal-page"] = {t="item",n="A Torn Journal Page",z="duskwood",s="In Stormwind, A Torn Journal Page carries a clue to Stalvan Mistmantle's past. Its worn script points toward old records in Elwynn Forest.",h="In Stormwind, A Torn Journal Page carries a clue to Stalvan Mistmantle's past.",sec={{t="A Clue in the Canals",b="A Torn Journal Page rests in a sealed storage crate beside Stormwind City's canals. Forgotten personal effects surround it, including old books, family heirlooms, and a ceramic vase. The writing points to Stalvan Mistmantle's past, though the page is damaged and hard to read. Who in the kingdom might know that hand?",sp=0},{t="Tracing the Mistmantle Trail",b="Marshal Haggard lives in Elwynn Forest, far from Stormwind. The aging officer's eyesight is failing, yet he remembers the distinctive handwriting from an earlier chapter in the tragic Mistmantle saga. The weathered page must reach someone familiar with the kingdom's older records.",sp=1}},faq={{q="Where is the torn journal page found?",a="A Torn Journal Page lies in a sealed storage crate beside Stormwind City's canals. Forgotten household items, hunting trophies, and an old ceramic vase lie beneath it.",al={"torn journal page location","where to find torn journal page","sealed crate stormwind"},it="place",gp=true},{q="Whose journal did this page come from?",a="The page came from Stalvan Mistmantle's personal writings. He was a former tutor whose dark past and sudden disappearance prompted an investigation across Duskwood and Elwynn Forest.",al={"who wrote the journal page","torn page author","who is stalvan"},it="origin"},{q="Who can read the handwriting on the torn page?",a="Marshal Haggard can recognize the handwriting. The elderly, nearly blind retired officer lives near the Eastvale Logging Camp in eastern Elwynn Forest and remembers seeing it before his eyesight failed.",al={"who do i take the torn page to","who reads the torn journal page","marshal haggard journal"}},{q="Why does finding the page matter to Duskwood?",a="The page matters because the Town Council of Darkshire is piecing together Stalvan Mistmantle's history. They seek the truth behind unsettling occurrences and long-buried crimes tied to him.",al={"why duskwood care about journal","stalvan connection duskwood"},it="why_wanted"},{q="What is the Torn Journal Page?",a="The Torn Journal Page is a tattered sheet discovered hidden beneath old household heirlooms, books, and hunting trophies inside a sealed storage crate in Stormwind City. It serves as a vital piece of written evidence concerning Stalvan Mistmantle, offering a distinctive handwriting sample that ties his quiet former life to the dark mysteries haunting Duskwood.",al={"torn journal page lore","what is torn journal page","what is this journal page"},it="identity",add="8b619691"}},ang={["faction:Alliance"]="As an Alliance member, you can see how unresolved crimes and forgotten records in Stormwind and Elwynn reach outward to trouble Duskwood's struggling frontier."},kw={"canals","duskwood","legend of stalvan","marshal haggard","sealed crate","stalvan mistmantle","stormwind","torn journal page"},rel={"quest:66","quest:1666","subzone:canals-stormwind-city","zone:elwynn","zone:duskwood","topic:stormwind-kingdom"},src={"A Torn Journal Page","The Legend of Stalvan (7)"}}
E["item:abercrombie-s-crate"] = {t="item",n="Abercrombie's Crate",z="duskwood",s="Near the Vul'Gol Ogre Mound, Abercrombie's Crate waits for its owner. Ogres drove him off while he gathered herbs, leaving his delicate tools behind.",h="Near the Vul'Gol Ogre Mound, Abercrombie's Crate waits for its owner.",sec={{t="Lost to the Ogres",b="Abercrombie left his shack in western Duskwood to gather plants. Far from home, he met a hostile band of ogres and fled for his life. He left his crate of instruments and gathered plants behind. The ogres carried it to the Vul'Gol Ogre Mound, where the heavy chest rests near the cave mouth.",sp=0},{t="Peculiar Contents",b="Abercrombie calls the tools and plants in his crate harmless. Yet when the crate is returned, his excitement gives him away. He nearly thanks the “Nec-” before catching himself. The purpose of his stolen tools remains in doubt.",sp=1}},faq={{q="Where is the crate located?",a="The crate lies outdoors beside the cave mouth at the Vul'Gol Ogre Mound, in the southern hills of Duskwood.",al={"crate location","where is abercrombie's crate","vul'gol crate"},it="place",gp=true},{q="Why did Abercrombie lose it?",a="Abercrombie was gathering herbs far from his home when ogres attacked him. He fled on foot, leaving his supplies behind. The ogres carried them to their lair.",al={"how did ogres get crate","why is crate at ogres"},it="history"},{q="What is inside the crate?",a="Abercrombie says the crate holds rare herbs and specialized harvesting tools. His excitement and slip of the tongue when it is returned suggest the tools may serve a darker purpose.",al={"crate contents","what did abercrombie lose"},sp=1,it="item"},{q="Why does Abercrombie almost thank 'the Nec-'?",a="When Abercrombie gets his crate back, he blurts out, “Thank the Nec-...” then corrects himself and thanks the adventurer. He never says who or what he almost thanked.",al={"abercrombie nec slip","thank the nec meaning"},sp=1,it="motive"},{q="What is Abercrombie's Crate?",a="It is a wooden supply container belonging to Abercrombie, the hermit dwelling at a dilapidated shack along Duskwood's northern road. Abercrombie claims the crate holds rare harvested herbs and delicate tools indispensable to his solitary craft, though his eccentric behavior and secretive slip of the tongue suggest he values its contents for far darker purposes.",al={"abercrombie crate","what is the crate","abercrombies crate"},it="identity",add="7a42047e"},{q="Why does Abercrombie want his crate retrieved?",a="Abercrombie was ambushed while foraging by ogres from the southern hills and was forced to abandon his supplies to escape. He sorely misses his equipment and claims he cannot resume his herbal research without it, promising that recovering the crate ensures happy, productive nights of work ahead.",al={"why retrieve abercrombies crate","why does abercrombie want the crate","why want crate"},it="why_wanted",add="c6e454ed"}},ang={["profession:Herbalism"]="Abercrombie ventures deep into the forest for rare plants. Recovering his botanist's kit is familiar work for a local herbalist.",["faction:Alliance"]="You venture into the Vul'Gol Ogre Mound to retrieve lost goods. Ogres threaten southern Duskwood."},kw={"abercrombie","abercrombie's crate","duskwood","ogre mound","ogre thieves","vul'gol"},rel={"quest:134","npc:abercrombie","subzone:vul-gol-ogre-mound","zone:duskwood","npc:watcher-dodds","npc:viktori-prism-antras"},src={"Abercrombie's Crate","Ogre Thieves (Classic)"}}
E["item:an-undelivered-letter"] = {t="item",n="An Undelivered Letter",z="duskwood",s="In Goldshire, an old letter waits in the Lion's Pride Inn, carrying a clue to Stalvan Mistmantle's past.",h="In Goldshire, an old letter waits in the Lion's Pride Inn, carrying a clue to Stalvan Mistmantle's past.",sec={{t="A Midnight Flight",b="Years ago, a storm drove a traveling courier to the Lion's Pride Inn for shelter. Near midnight, fear sent the messenger downstairs in his sleeping clothes and out into the pouring rain. He vanished and never returned. In an upstairs chest, he left his belongings and a letter from Stalvan Mistmantle addressed to an estate in Stormwind City's Canal District.",sp=0},{t="Tracing the Scholar",b="In the inn's upper rooms, the unopened letter remained untouched for years. Now investigators retrace Stalvan's steps through Elwynn Forest. Taking the parchment to Caretaker Folsom in the capital carries the mystery from the inn to the heart of Stormwind.",sp=1}},faq={{q="Where is the undelivered letter found?",a="The letter rests in a storage chest on the second floor of Goldshire's Lion's Pride Inn, at the foot of a bed in a guest room.",al={"where is letter","storage chest location","lion's pride chest"},it="place",gp=true},{q="Why was the letter never delivered?",a="During a rainstorm, the courier carrying the letter took shelter at the Lion's Pride Inn. Around midnight, he panicked, ran downstairs in his nightclothes, and vanished into the storm, leaving his chest and its contents behind.",al={"why undelivered","what happened to the messenger","courier fled"},it="history"},{q="Who wrote this letter?",a="Stalvan Mistmantle wrote the letter. He had spent several nights at the inn around the same time as the frightened courier.",al={"who sent the letter","stalvan author","sender"},it="origin"},{q="Where is the letter supposed to go?",a="The letter is addressed to the Canal District of Stormwind City. It can be brought to Caretaker Folsom near the Park.",al={"who receives letter","stormwind destination","canal district letter"},it="target"},{q="What is the Undelivered Letter?",a="It is an old, forgotten missive penned years ago by Stalvan Mistmantle. A courier carrying it took shelter at the Lion's Pride Inn in Goldshire on a stormy night, only to flee into the dark in sheer terror near midnight. Left behind inside the messenger's storage chest, the letter remains sealed and unread, holding clues to Stalvan's past.",al={"what is an undelivered letter","undelivered letter item","stalvan letter"},it="identity",add="72dbe9c7"},{q="Why is the Undelivered Letter wanted?",a="You need it to uncover the dark history of Stalvan Mistmantle. With his trail running cold across Duskwood and Elwynn Forest, this forgotten missive—addressed to someone in Stormwind's Canal District—serves as the next crucial clue to piecing together who he was and what became of him.",al={"why do i need the undelivered letter","who wants the undelivered letter","undelivered letter purpose"},it="why_wanted",add="e9e7c880"}},ang={["faction:Alliance"]="For Alliance investigators, the courier's forgotten route runs from Goldshire's pastoral heart to Stormwind City's upper-class quarters."},kw={"canal district","courier","folsom","goldshire","lion's pride inn","messenger","mistmantle","stalvan"},rel={"quest:66","subzone:lion-s-pride-inn","subzone:goldshire","npc:innkeeper-farley","npc:caretaker-folsom","subzone:canals-stormwind-city","zone:elwynn","zone:duskwood"},src={"An Undelivered Letter","The Legend of Stalvan (5)"}}
E["item:book-from-sven-s-farm"] = {t="item",n="Book from Sven's Farm",z="duskwood",s="In Duskwood, a hidden journal at Sven's ruined farm holds fragments of the attack on his family, seen by an unknown onlooker.",h="In Duskwood, a hidden journal at Sven's ruined farm holds fragments of the attack on his family, seen by an...",sec={{t="A Clue in the Dirt",b="A damaged journal lies beneath loose dirt among the charred remains of Sven's farm in southern Duskwood. Its anonymous writer left frantic, incomplete notes about the tragedy at the homestead. The pages support Sven Yorgen's suspicion that someone watched from the shadows as his family was slain. The account breaks off without naming the writer or telling what happened next.\n\nSven's clue leads investigators to carry the book to Darkshire. They hope someone there will recognize the handwriting.",sp=0},{t="Unraveling the Shadowy Figure",b="In Darkshire, mystics and townsfolk help reveal that the journal's owner was a stranger who fled through the woods in terror. Faded impressions on its pages lead to Jitters, a vagrant hiding in the forest. Jitters's missing entries tell how the Defias Brotherhood meddled with forbidden artifacts and accidentally unleashed ravenous worgen into Duskwood. Finding him brings the fragments together in his completed journal.",sp=1}},faq={{q="Where is the Book from Sven's Farm found?",a="The book lies beneath loose dirt at Sven Yorgen's ruined farm in southern Duskwood.",al={"where to find sven book","dirt mound sven farm","sven book location"},it="place",gp=true},{q="Who wrote the book found at Sven's farm?",a="The book has no title or author's name. Its writer was a terrified man who fled a horror elsewhere in Duskwood, hid in Sven's barn, witnessed Sven's family being slain, and lost his journal.",al={"author of sven book","who wrote the dirt-stained book","who wrote the journal"},sp=1,it="origin"},{q="Why does Sven Yorgen want this book?",a="After the attack on his family, Sven saw an unknown figure near his barn. The book confirms that the onlooker was real and gives Sven a lead to learn what happened that night.",al={"why does sven care","sven yorgen book reaction"},it="why_wanted"},{q="What happens to the book after you investigate it?",a="After you show the partial journal to Darkshire's residents and find its owner, Jitters's Completed Journal takes its place and tells the full story.",al={"what replaces sven book","do you keep sven book"},sp=1,it="next_step",gp=true},{q="What larger secret is connected to the book's contents?",a="The complete journal tells what drove its author into hiding and why Sven's family was attacked. Its story reaches beyond one farm to the darkness over Duskwood.",al={"what lore is in sven book","worgen connection","defias connection"},sp=1,it="ties"},{q="What is the Book from Sven's Farm?",a="It is an untitled, dirt-stained journal dug up from the ruins of Sven Yorgen's devastated homestead in Duskwood. Though weathered and incomplete, its handwritten pages contain an eyewitness account of the horrors that fell upon Sven's farm and family. More importantly, it serves as physical proof that a shadowy bystander was present during the massacre, holding critical answers about who attacked the farm and why.",al={"what is book from svens farm","dirt stained book duskwood","what is the dirt stained book"},it="identity",add="fd4c7f5f"}},ang={["faction:Alliance"]="As an Alliance investigator, you can use this weather-damaged book to pursue the horrors gripping southern Duskwood and learn how the feral worgen pack gained a foothold."},kw={"book from sven's farm","darkshire","defias brotherhood","duskwood","jitters","shadowy figure","sven yorgen","worgen"},rel={"npc:jitters","quest:262","quest:453","item:jitters-completed-journal","topic:worgen","zone:duskwood","subzone:darkshire","topic:defias-brotherhood"},src={"Book from Sven's Farm","Sven's Camp","The Shadowy Figure"}}
E["item:bottle-of-zombie-juice"] = {t="item",n="Bottle of Zombie Juice",z="duskwood",s="In Darkshire, Bottle of Zombie Juice is bound for Abercrombie, a reclusive hermit in Duskwood. He says the potent liquor, brewed from rot blossom, keeps him warm.",h="In Darkshire, Bottle of Zombie Juice is bound for Abercrombie, a reclusive hermit in Duskwood.",sec={{t="A Pungent Concoction",b="Rot blossoms gathered in Duskwood go into this harsh brew. The bartender in Darkshire warns it is potent enough to raise the dead. Most folk want nothing to do with such a vile drink. Yet Abercrombie, an eccentric hermit, says it alone keeps him warm on cold, damp nights by his lonely shack.",sp=0},{t="Questionable Thirst",b="Abercrombie calls the liquor a fiery nightcap. When he receives the bottle, he nearly praises the courier’s foolishness instead of their kindness. What use could he have for a drink so potent?",sp=1}},faq={{q="What is Zombie Juice made from?",a="Zombie Juice is distilled from rot blossoms, a foul-smelling plant found in Duskwood’s corrupted soil.",al={"zombie juice ingredients","what is in zombie juice"},it="item"},{q="Who wants this bottle delivered?",a="Abercrombie wants the bottle delivered to his solitary shack along Duskwood’s western borders.",al={"who needs zombie juice","who is zombie juice for","zombie juice delivery"}},{q="Why does Abercrombie want Zombie Juice?",a="Abercrombie claims the fiery drink keeps his old bones warm through Duskwood’s bitter, dark nights. His strange manner suggests he may have another use for so potent a brew.",al={"why does abercrombie drink it","abercrombie zombie juice reason"},it="why_wanted"},{q="Can players drink the Bottle of Zombie Juice?",a="No. You must carry the bottle safely to Abercrombie’s shack for delivery.",al={"can i drink zombie juice","is zombie juice consumable"},it="power",gp=true},{q="What is the Bottle of Zombie Juice?",a="The Bottle of Zombie Juice is a potent brew of rot blossom liquor mixed in Duskwood. Described as foul and incredibly strong—purportedly strong enough to raise the dead—it is an unsavory concoction that tavern keepers handle with extreme caution.",al={"what is zombie juice","bottle of zombie juice lore","what is the juice"},it="identity",add="f1488eba"},{q="Where does the Bottle of Zombie Juice come from, and who made it?",a="The juice is brewed in Darkshire by the local barkeep, Tavernkeep Smitts, who distills it from rot blossoms. It is prepared specifically upon order for delivery out to Abercrombie's shack in the haunted wilds of Duskwood.",al={"who made zombie juice","where does zombie juice come from","who brews zombie juice"},it="origin",add="b862f5ea"}},ang={["profession:Herbalism"]="Herbalists familiar with Duskwood know rot blossom is unfit for ordinary restorative tonics. Its use in a drink is unsettling.",["faction:Alliance"]="Errands between Darkshire and the shadowed wilderness connect Duskwood’s troubled inhabitants, even when the work seems dubious."},kw={"abercrombie","bottle of zombie juice","darkshire","duskwood","juice delivery","rot blossom","zombie juice"},rel={"quest:159","quest:158","npc:abercrombie","item:rot-blossom","zone:duskwood"},src={"Bottle of Zombie Juice","Juice Delivery (Classic)"}}
E["item:calor-s-note"] = {t="item",n="Calor's Note",z="duskwood",s="In Duskwood, Calor's Note carries a woodsman's recommendation to Master Jonathan Carevin. Calor writes it on a scrap of faded parchment for a proven adventurer, opening a path to a hidden band that fights beside Darkshire's militia but remains apart from it.",h="In Duskwood, Calor's Note carries a woodsman's recommendation to Master Jonathan Carevin.",sec={{t="A Rare Recommendation",b="Calor is hard to impress, and Duskwood gives strangers little warmth. Survive the bloodthirsty worgen stalking the woods, and he grants his respect with a brief message. Written on faded parchment, the note travels to Darkshire and introduces the outsider directly to Jonathan Carevin.",sp=0},{t="A Private Crusade",b="Darkshire relies on the Night Watch for public defense. Calor and Carevin pursue a grimmer, hidden fight apart from the town guard. Calor laments that the guard outnumbers them, and hopes to find enough capable fighters to advance their private war. Hand over the note, and Carevin admits you to his campaign against demons, undead, and the hidden sympathizers aiding Duskwood's decline.",sp=0}},faq={{q="What is Calor's Note?",a="Calor's Note is a handwritten message on a scrap of faded parchment. It recommends an adventurer as capable and reliable against Duskwood's horrors.",al={"calor note","what is this note","what does the note say"},it="identity"},{q="Who receives the note?",a="Jonathan Carevin receives the note. He is a stern figure stationed in Darkshire who coordinates an effort against the dark forces threatening the region.",al={"who do i give the note to","who gets calors note","jonathan carevin note"}},{q="How does Calor regard the Night Watch?",a="Calor believes the Night Watch cannot meet Duskwood's true threats. As he hands over the note, he says he wants to recruit enough capable allies to outnumber the militia and finish the urgent work his small faction carries on alone.",al={"calor and night watch","why does calor want to outnumber night watch"}},{q="What kind of battle does Jonathan Carevin fight?",a="Master Carevin fights demons, the undead, and mortal collaborators who aid them in Duskwood. He values vigilance and devotion to the Holy Light, and accepts only proven people into his confidence.",al={"carevin cause","what does carevin do","who does carevin fight"}},{q="Who wrote Calor's Note, and where does it come from?",a="The note is written by Calor, a grim fighter stationed in the haunted expanse of Duskwood. After you prove your mettle against the vicious worgen terrorizing the woods, he jots this message onto a slip of faded parchment to send you onward to his superior.",al={"calor's note origin","who made calors note","where does calor note come from"},it="origin",add="d10add4c"},{q="Why does Jonathan Carevin want Calor's Note?",a="Master Jonathan Carevin demands proof before trusting anyone in a land overrun by shadow. Calor's note serves as an official commendation, letting Carevin know you have Calor's rare respect and are capable of assisting their covert fight against demons, undead, and darker forces.",al={"why bring calors note to carevin","why does carevin want calors note","calor note purpose carevin"},it="why_wanted",add="fe7f9dd8"}},ang={["class:Paladin"]="Jonathan Carevin greets the bearer with 'Glory under the Light,' a sign of shared ideals with holy warriors committed to cleansing Duskwood of demons and undead.",["faction:Alliance"]="With the Stormwind army absent from Duskwood, Carevin's circle and the Night Watch are unofficial factions guarding the southern border against darkness."},kw={"calor","calor's note","darkshire","duskwood","jonathan carevin","night watch","recommendation","worgen"},rel={"npc:calor","npc:jonathan-carevin","quest:173","topic:night-watch","topic:worgen","zone:duskwood","topic:light"},src={"Calor's Note","Worgen in the Woods (Classic, 4)"}}
E["item:dusky-crab-cakes"] = {t="item",n="Dusky Crab Cakes",z="duskwood",s="In Darkshire, Chef Grual makes Dusky Crab Cakes for the hungry Jitters. Jitters finds the local delicacy exquisite.",h="In Darkshire, Chef Grual makes Dusky Crab Cakes for the hungry Jitters.",sec={{t="A Questionable Delicacy",b="Chef Grual makes Dusky Crab Cakes for Jitters, a terrified vagrant whose hunger has overcome him. Duskwood has few fresh provisions, so cooks make do with meat from the forest.\n\nThe cakes look like ordinary seafood patties, but Grual uses meat from the legs of Duskwood’s monstrous arachnids. Jitters devours them, unaware of what he is eating.",sp=1,bt={"q5.2"}}},faq={{q="What are Dusky Crab Cakes actually made of?",a="Chef Grual keeps his recipe to himself. Its secret ingredient comes to light while supplies are gathered for him in Duskwood.",al={"crab cakes ingredients","what is in dusky crab cakes","spider meat"},it="identity"},{q="Who eats the Dusky Crab Cakes?",a="Chef Grual makes the cakes for Jitters, an anxious man sheltering at Raven Hill who complains of a rumbling stomach.",al={"who gets the crab cakes","who are these for","jitters food"},it="why_wanted"},{q="How does Jitters react to the cakes?",a="Starving, Jitters happily devours the cakes without questioning their recipe. He is grateful for a meal that satisfies his hunger.",al={"jitters reaction","does jitters enjoy the cakes"}},{q="Who cooks the Dusky Crab Cakes?",a="Chef Grual, cook at the Scarlet Raven Tavern in Darkshire, prepares the cakes from supplies gathered for him.",al={"who makes the crab cakes","chef grual","cook darkshire"},it="origin"}},ang={["profession:Cooking"]="Grual’s cakes show how a cook can make a tangy local specialty from ingredients found in Duskwood."},kw={"darkshire","duskwood","dusky crab cakes","grual","jitters","spider legs"},rel={"quest:240","quest:93","quest:5","npc:jitters","zone:duskwood"},src={"Dusky Crab Cakes","Return to Jitters"}}
E["item:ebonlocke-s-response-to-solomon"] = {t="item",n="Ebonlocke's Response to Solomon",z="duskwood",s="In Darkshire, Lord Ello Ebonlocke refuses Solomon's plea for aid in Redridge. His letter says the Night Watch cannot leave Duskwood undefended.",h="In Darkshire, Lord Ello Ebonlocke refuses Solomon's plea for aid in Redridge.",sec={{t="A Bitter Refusal",b="Magistrate Solomon asked Duskwood for reinforcements against the blackrock orcs after Stormwind ignored his petitions. Lord Ello Ebonlocke answers in anger and promises no aid. He reminds Solomon that the Night Watch formed because Stormwind abandoned Darkshire when corrupting magic first gripped the woods. If its defenders march to Redridge, Duskwood will be left defenceless and fall to evil before the militia reaches the forest's edge.",sp=0},{t="The Crumbling Frontier",b="Solomon is shaken when Ebonlocke's letter reaches him. The Stormwind Army has withdrawn from Westfall, and the royal guard is absent from Darkshire. The whole southern frontier has been left to decay. Solomon sees a terrible pattern in Stormwind's neglect of its outlying lands and suspects treachery among the kingdom's highest powers.",sp=1,bt={"q120.5"}}},faq={{q="What is Ebonlocke's Response to Solomon?",a="Lord Ello Ebonlocke of Darkshire sends Magistrate Solomon of Lakeshire a sealed letter. He refuses to send the Night Watch to defend Redridge, saying Duskwood is barely holding back its own nightmares.",al={"ebonlocke letter","ebonlocke response","letter to solomon"},it="identity"},{q="Why won't Darkshire send help to Lakeshire?",a="Darkshire has no royal troops of its own. The Night Watch is made up of local volunteers left to defend the region after Stormwind abandoned it. Lord Ebonlocke warns that undead and vile creatures will overrun Darkshire if the Watch marches away, before they leave the forest.",al={"why night watch wont help","why did darkshire refuse","ebonlocke refuse solomon"},it="motive"},{q="How does Magistrate Solomon react to the letter?",a="Magistrate Solomon is shocked and disturbed. The royal guard's absence from Darkshire, alongside the army's withdrawal from Westfall, leads him to suspect foul play or treachery among Stormwind's leaders.",al={"solomon reaction","what does solomon say"},sp=1,bt={"q120.5"}},{q="Who wrote this letter?",a="Lord Ello Ebonlocke, Darkshire's beleaguered mayor and leader of the Council of Darkshire, wrote the letter. He oversees the town's defence.",al={"who is ebonlocke","lord ebonlocke"},it="origin"},{q="Why does Magistrate Solomon want Ebonlocke's Response?",a="Magistrate Solomon is desperate for reinforcements to defend Lakeshire against the Blackrock orcs. After Stormwind repeatedly ignored his pleas for military aid, he reached out to Darkshire in hopes that Lord Ello Ebonlocke could spare the Night Watch. Solomon eagerly awaits this letter to learn whether any help is coming from Duskwood, only to discover Darkshire is just as abandoned and beleaguered as Redridge.",al={"why solomon needs letter","why deliver ebonlockes response","why send response to solomon"},it="why_wanted",add="de19eb29"}},ang={["faction:Alliance"]="As an Alliance member, you can see how Stormwind's royal court has left Redridge, Duskwood, and Westfall adrift."},kw={"darkshire","duskwood","ebonlocke","lakeshire","letter","messenger","night watch","redridge","solomon"},rel={"quest:145","npc:magistrate-solomon","subzone:darkshire","subzone:lakeshire","topic:night-watch","topic:stormwind-kingdom","zone:duskwood","subzone:forest-s-edge"},src={"Ebonlocke's Response to Solomon","Messenger to Darkshire (2)"}}
E["item:ghost-hair-comb"] = {t="item",n="Ghost Hair Comb",z="duskwood",s="In Duskwood, Madame Eva sends Ghost Hair Comb to Blind Mary, whose grief leaves ghostly hair caught in its teeth.",h="In Duskwood, Madame Eva sends Ghost Hair Comb to Blind Mary, whose grief leaves ghostly hair caught in its...",sec={{t="A Tragic Vanity",b="Madame Eva sends Ghost Hair Comb from Darkshire to Blind Mary, who lives in a lonely, dilapidated dwelling on Duskwood’s outskirts. At its sight, the ghost recoils in horror. Mary must face that she is no longer the lovely living woman she remembers. Grief-stricken, she thrusts the comb away, leaving strands of ghostly hair tangled in its teeth.",sp=0},{t="Spun from Sorrow",b="Madame Eva receives Ghost Hair Comb back in Darkshire with Blind Mary’s spectral hair still caught between its teeth. Eva gathers the delicate strands and spins them into Ghost Hair Thread. In Duskwood’s shadowy realm, the mystical thread stitches and binds occult creations.",sp=1}},faq={{q="What is the Ghost Hair Comb?",a="Madame Eva of Darkshire sends Ghost Hair Comb to Blind Mary, a spirit. The comb catches strands of Mary’s spectral hair, which Eva spins into Ghost Hair Thread.",al={"ghost hair comb","what is this comb","eva's comb"},it="identity"},{q="Why does Blind Mary scream and reject the comb?",a="Blind Mary rejects the comb because it reminds her of the mortal beauty she has lost. It forces her to face that she is now a terrifying spectral monstrosity, not the lovely woman she remembers from life.",al={"why does blind mary scream","blind mary comb reaction","why did mary throw the comb"},it="motive"},{q="Who needs the comb returned?",a="Madame Eva, the diviner and hedge-mage who lives in Darkshire, asks for Ghost Hair Comb back so she can gather the trapped ghost hair.",al={"who wants the comb","where to take the comb","return comb to who"},it="target"},{q="What is the ghost hair used for?",a="Madame Eva spins the ghostly strands into Ghost Hair Thread. In Duskwood, the unusual material is used for occult rituals and crafting.",al={"ghost hair use","what is ghost hair thread","ghost hair thread purpose"},it="why_wanted"}},ang={["profession:Tailoring"]="As a tailor, you can see the uncanny textile in the strands caught in the comb. They are spun from spectral sorrow, not sheep’s wool or silkworms.",["class:Priest"]="As a priest, you can hear mortal vanity and deep spiritual torment in Mary’s anguished rejection of the comb. Such torment is familiar among Duskwood’s restless dead."},kw={"blind mary","darkshire","duskwood","ghost hair comb","ghost hair thread","madame eva"},rel={"quest:154","quest:149","npc:blind-mary","npc:madame-eva","subzone:darkshire","zone:duskwood"},src={"Ghost Hair Comb","Return the Comb (Classic)"}}
E["item:ghost-hair-thread"] = {t="item",n="Ghost Hair Thread",z="duskwood",s="In Darkshire, Madame Eva spins Ghost Hair Thread from the spirit world. Its occult power can bind spirits or stitch life into inanimate things, and Abercrombie asks for it to ward his shack against restless ghosts.",h="In Darkshire, Madame Eva spins Ghost Hair Thread from the spirit world.",sec={{t="Spun of the Spirit World",b="In Darkshire, Madame Eva spins Ghost Hair Thread, a spectral strand with strange powers. Eva says it can bind malevolent spirits or stitch vitality into inanimate objects. In Duskwood, people use it in rituals and wards.",sp=0},{t="Abercrombie's Ward",b="Abercrombie lives in a ramshackle shack just north of Raven Hill Cemetery. The hermit asks travelers to bring him Ghost Hair Thread from Darkshire. He says he needs to string it across his windows and doorframe to keep wandering undead from entering his home. What else might the thread do?",sp=1}},faq={{q="What is Ghost Hair Thread?",a="Madame Eva spins Ghost Hair Thread in Darkshire. Its occult power can bind spirits or stitch life into inanimate things.",al={"ghost hair","what is ghost hair thread","ghost thread"},it="identity"},{q="Why does Abercrombie want Ghost Hair Thread?",a="Abercrombie says he needs Ghost Hair Thread across his windows and doorway to ward off restless spirits near Raven Hill Cemetery.",al={"abercrombie thread","why abercrombie wants thread","abercrombie ward"},it="why_wanted"},{q="Who makes the thread?",a="Madame Eva, Darkshire's fortune teller, spins the thread and provides it upon request.",al={"who spins ghost hair thread","madame eva thread"},it="origin"},{q="Can players use the thread for tailoring?",a="No. Ghost Hair Thread cannot be used in standard tailoring recipes; it is meant for Abercrombie.",al={"tailoring ghost hair thread","can i craft with ghost hair thread"},gp=true}},ang={["profession:Tailoring"]="Tailors usually work with wool, silk, and mageweave. Madame Eva's ghostly thread shows that supernatural essences can also be spun into fabric that holds enchantments.",["class:Warlock"]="As a warlock, you may recognize the thread's power to bind spirits and give life to inanimate matter from the dark arts of soul manipulation and construct binding."},kw={"abercrombie","darkshire","duskwood","ghost hair thread","madame eva","raven hill","spirits"},rel={"npc:abercrombie","npc:madame-eva","quest:157","quest:149","subzone:raven-hill-cemetery","zone:duskwood"},src={"Ghost Hair Thread","Deliver the Thread (Classic)"}}
E["item:ghoul-fang"] = {t="item",n="Ghoul Fang",z="duskwood",s="In Duskwood, travelers face the forest’s encroaching darkness, and Ghoul Fang is gathered for Madame Eva’s protective talismans. The fangs are essential to her work in Darkshire.",h="In Duskwood, travelers face the forest’s encroaching darkness, and Ghoul Fang is gathered for Madame Eva’s...",sec={{t="Trophies of the Restless Dead",b="Ravenous undead haunt Duskwood’s woods and graves. Flesh Eaters lurk near the burial grounds, while Rotted Ones roam among the trees. Taking a fang from these creatures is grim work. It proves survival against the dead threatening Darkshire’s borders.",sp=0},{t="Occult Reagents",b="Madame Eva is Darkshire’s fortune teller and mystic. She sees terrible omens around travelers crossing Duskwood, so she enchants the Totem of Infliction with ghoul fangs, skeletal fingers, and arachnid venom. The charm turns the forest’s dark forces against violent assault and protects its bearer.",sp=0}},faq={{q="Where can Ghoul Fangs be found?",a="Various ghouls haunt Duskwood’s graveyards and lonely pathways. They include Plague Spreaders, Brain Eaters, Bone Chewers, Fetid Corpses, Rotted Ones, and Flesh Eaters.",al={"where do ghoul fangs drop","who drops ghoul fangs","ghoul fang location"},it="place",gp=true},{q="Who wants Ghoul Fangs?",a="Madame Eva, the mystic in Darkshire, needs Ghoul Fangs to craft the defensive Totem of Infliction.",al={"who needs ghoul fangs","ghoul fang turn in","madame eva quest"},it="why_wanted"},{q="Why does Madame Eva need them?",a="Madame Eva senses danger gathering around travelers. She combines the fangs with skeleton fingers and spider venom to enchant a protective totem that punishes anyone who strikes its bearer.",al={"why ghoul fangs","totem of infliction materials","what does madame eva do with fangs"},it="purpose"},{q="What is a Ghoul Fang?",a="A Ghoul Fang is a sharp tooth pried from the maw of the undead ghouls haunting Duskwood. Tainted by necromantic blight and flesh-eating hunger, these fangs retain a vestige of the dark magic that animates the undead, making them potent reagents for protective charms and occult rituals.",al={"what is ghoul fang","ghoul fang lore","about ghoul fang"},it="identity",add="7c703fef"},{q="Where does a Ghoul Fang come from?",a="These fangs come from the various undead ghouls wandering the shadows of Duskwood, such as Plague Spreaders, Brain Eaters, Bone Chewers, and Flesh Eaters. They are not crafted by hand, but scavenged directly from the jaws of the roaming dead.",al={"ghoul fang origin","where do ghoul fangs come from","who drops ghoul fangs"},it="origin",add="87f3f6fc"}},ang={["faction:Alliance"]="As an Alliance adventurer helping embattled Darkshire, you can turn Duskwood’s horrors into tools for survival against the encroaching Scourge-like taint."},kw={"darkshire","duskwood","ghoul fang","ghouls","madame eva","totem of infliction","undead"},rel={"quest:101","npc:madame-eva","subzone:darkshire","zone:duskwood","item:skeleton-finger","item:vial-of-spider-venom"},src={"Ghoul Fang","The Totem of Infliction"}}
E["item:ghoul-rib"] = {t="item",n="Ghoul Rib",z="duskwood",s="In Duskwood, Abercrombie gathers Ghoul Rib to guard his shack from the dead. He says a fearsome effigy will frighten the flesh-eating horrors away from his home.",h="In Duskwood, Abercrombie gathers Ghoul Rib to guard his shack from the dead.",sec={{t="A Gruesome Ward",b="Ghouls haunt Duskwood in many forms. Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones and Plague Spreaders are among them.\n\nAbercrombie lives alone in a shack north of Raven Hill Cemetery. He asks travelers for their sturdy, rotted ribs. His home lies beyond the Night Watch’s protection in Darkshire, so he says he needs a fearsome effigy to frighten the dead away.",sp=0},{t="Suspicions Around the Shack",b="Abercrombie’s request for ghoul parts raises questions. Darkshire’s palisades could offer shelter, and consecrated wards might guard his home. Yet the hermit insists on gathering raw necromantic remains to protect his secluded shack.",sp=1}},faq={{q="What creatures carry Ghoul Ribs?",a="Several kinds of ghouls in Duskwood carry Ghoul Rib. They include Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones and Plague Spreaders. These creatures haunt old graveyards, roadside ruins and abandoned homesteads across the forest.",al={"where do ghoul ribs drop","which ghouls have ribs","ghoul rib sources"},it="target",gp=true},{q="Why does Abercrombie want these bones?",a="Abercrombie says his home lies too far from Darkshire for the Night Watch to protect him. He asks for ribs to build a crude scarecrow or effigy that he believes will keep roving undead from his walls.",al={"why does abercrombie need ribs","ghoulish effigy purpose","what does abercrombie do with ribs"},it="why_wanted"},{q="Do scarecrows actually keep ghouls away?",a="Ghouls are driven by hunger or dark necromantic force and generally feel no fear. Abercrombie still insists that a scarecrow made of bones will keep his home safe.",al={"does the effigy work","can effigies scare undead","do ghouls fear scarecrows"}},{q="Where is Abercrombie's shack located?",a="Abercrombie’s shack stands in western Duskwood, just north of Raven Hill Cemetery.",al={"abercrombie location","where is the hermit","where to turn in ghoul ribs"},it="place",gp=true},{q="What is a Ghoul Rib?",a="A Ghoul Rib is exactly what it sounds like: a bone taken from the rotted, reanimated undead that prowl Duskwood. Stripped from fiends such as Flesh Eaters, Brain Eaters, and Bone Chewers, these remnants still carry the faint taint of the foul magic that animates the walking dead in this blighted forest.",al={"ghoul rib info","what are ghoul ribs","ghoul ribs item"},it="identity",add="3e8ffb18"},{q="Where do Ghoul Ribs come from?",a="These ribs come directly from the various ghouls haunting the gloomy roads and barrows of Duskwood. They are natural skeletal remains rather than crafted relics, harvested from undead monstrosities like Plague Spreaders and Rotted Ones that roam far beyond the relative safety of Darkshire.",al={"ghoul rib source","where to get ghoul ribs lore","who made ghoul ribs"},it="origin",add="f2829c95"}},ang={["class:Paladin"]="Handling the desecrated bones of the restless dead is grim work. Helping an isolated hermit face ravenous horrors fits your paladin’s duty to guard the living in Duskwood.",["class:Priest"]="The twisted force that reanimates these bones shows the deep shadow over Duskwood. Fallen villagers become ravenous scavengers."},kw={"abercrombie","beggar's haunt","bone chewer","darkshire","duskwood","flesh eater","ghoul rib","ghoulish effigy","undead"},rel={"quest:133","npc:abercrombie","zone:duskwood","subzone:manor-mistmantle","subzone:darkshire"},src={"Ghoul Rib","Ghoulish Effigy (Classic)"}}
E["item:jitters-completed-journal"] = {t="item",n="Jitters' Completed Journal",z="duskwood",s="In Duskwood, Jitters gives up his completed journal and hopes it will clear his name. He fears Sven Yorgen's vengeance after fleeing the massacre at Sven's farm.",h="In Duskwood, Jitters gives up his completed journal and hopes it will clear his name.",sec={{t="A Coward's Confession",b="Jitters fled Sven's farm when the attack began, leaving his half-finished diary in the ruins. In the completed journal, he recounts how mysterious dark riders slaughtered Sven's family. For weeks, its pages were his only comfort while he hid in Duskwood. Now he gives the finished volume willingly, hoping the truth will spare him Sven's fury.",sp=1},{t="Unraveling the Darkness",b="The journal leads Sven to speak of black-cloaked riders he saw talking with the wizard Morbent Fel at the Forlorn Rowe. Sven sends the manuscript north with travelers bound for the Cathedral of Light in Stormwind. There, Bishop Farthing reads Jitters' account to learn of Duskwood's vile taint. Its revelations help him craft a holy weapon that can pierce Fel's dark wards.",sp=1,bt={"q164.5"}}},faq={{q="Why did Jitters give up his journal?",a="Jitters fled Sven's farm during the attack and left an unfinished journal behind. He gives adventurers the completed version to bring to Sven, hoping the full truth will clear his name and protect him from Sven's anger.",al={"why does jitters give journal","jitters diary","why did jitters write this"},it="motive"},{q="What does the journal reveal about Sven's farm?",a="Jitters' completed journal gives his eyewitness account of the tragedy at Sven Yorgen's farm, filling in what his unfinished diary left out.",al={"what happened at sven farm","sven family attack","dark riders sven farm"},sp=1,it="purpose"},{q="Who is Morbent Fel and how is he connected to the journal?",a="Morbent Fel is a necromancer at the Forlorn Rowe. The journal leads Sven to share that he has seen the black-cloaked riders speaking with Fel.",al={"morbent fel connection","who is morbent fel","forlorn rowe wizard"},sp=1,it="threat",bt={"q164.5"}},{q="Why is the journal taken to Stormwind?",a="Sven sends the journal to Bishop Farthing at the Cathedral of Light in Stormwind. Farthing reads it to understand Duskwood's taint and help prepare a holy weapon that can pierce Morbent Fel's magical wards.",al={"why bishop farthing","take journal to cathedral","seeking wisdom journal"},sp=1,it="target"},{q="What is Jitters' Completed Journal?",a="It is the full personal chronicle kept by Jitters, a terrified vagrant hiding in Duskwood. Unlike the fragmentary notes left behind when he fled Sven Yorgen's farm, this completed manuscript lays out the entire sequence of tragedies that struck the homestead, the encroaching horrors of the woods, and the sinister figures moving through the shadows.",al={"jitters completed journal","what is this journal","jitters diary"},it="identity",add="3f8dfebe"},{q="Where does Jitters' Completed Journal come from, and who made it?",a="The journal was penned by Jitters himself. After fleeing the massacre at Sven's farm and abandoning an earlier diary, he spent weeks in hiding, frantically setting down his thoughts and chronicling the sinister forces stalking Duskwood. He retained the finished volume as his sole companion until surrendering it to avoid facing Sven Yorgen's wrath.",al={"who wrote jitters completed journal","jitters journal origin","where did the journal come from"},it="origin",add="e7121643"},{q="Why is Jitters' Completed Journal wanted?",a="Sven Yorgen seeks the journal for Jitters' eyewitness account of the tragedy at his farm. Later, Bishop Farthing in the Cathedral of Light studies it to help prepare an adventurer to face the evil afflicting Duskwood.",al={"why do they want the journal","why is jitters journal important","who wants the journal"},sp=1,it="why_wanted",add="5c3c5710"}},ang={["class:Priest"]="As a priest, you bring the journal to Bishop Farthing at the Cathedral of Light and serve the cleansing of unholy defilement through holy relics.",["faction:Alliance"]="As an Alliance member, you see how far Duskwood has fallen into peril while Stormwind's leaders focus elsewhere."},kw={"bishop farthing","cathedral of light","dark riders","duskwood","forlorn rowe","jitters","journal","morbent fel","sven yorgen"},rel={"quest:268","quest:269","npc:jitters","npc:farthing","quest:55","subzone:forlorn-rowe","topic:dark-riders","zone:duskwood"},src={"Jitters' Completed Journal","Return to Sven","Seeking Wisdom"}}
E["item:letter-to-ello"] = {t="item",n="Letter to Ello",z="duskwood",s="Abercrombie sends a sealed letter to Mayor Ello Ebonlocke in Darkshire. The hermit lives in a shack just north of Raven Hill Cemetery, claims an old friendship, and writes the missive in an archaic script.",h="Abercrombie sends a sealed letter to Mayor Ello Ebonlocke in Darkshire.",sec={{t="A Bizarre Greeting",b="After you help Abercrombie with tasks around Duskwood, the old recluse gives you a note for Mayor Ello Ebonlocke. He says the mayor is an old friend who will celebrate what you have accomplished. When Ello breaks the seal, he has no recollection of anyone named Abercrombie and cannot read a single phrase of the archaic script. He sends the note to Darkshire scholar Sirra Von'Indi for translation.",sp=0},{t="Dark Omens",b="Abercrombie's runes carry a grim meaning for Darkshire. The letter does not describe an old friendship between town acquaintances; it spells doom for the whole town.",sp=1}},faq={{q="Who wrote the Letter to Ello?",a="Abercrombie wrote the letter. He is a hermit living in a ramshackle hut near Raven Hill Cemetery in western Duskwood.",al={"who wrote the letter","letter to ello author","who sent the letter"},it="origin"},{q="Can Mayor Ello Ebonlocke read the letter?",a="No. When Ello Ebonlocke breaks the seal, the script is completely incomprehensible to him and appears to be written in an ancient, unrecognizable language.",al={"can ello read it","why cant ello read the note","ello letter language"}},{q="Who can translate the note?",a="Sirra Von'Indi can translate the note. Mayor Ebonlocke sends it to the resident scholar in Darkshire, who knows ancient scripts and esoteric languages.",al={"who translates the note","translate abercrombie note","who can read the letter"},it="next_step",gp=true},{q="Does Mayor Ebonlocke actually know Abercrombie?",a="No. Though Abercrombie claims they are old friends, Ello Ebonlocke says he has never heard of anyone named Abercrombie.",al={"does ello know abercrombie","are ello and abercrombie friends","abercrombie old friends ello"},sp=1,it="ties"},{q="What is the Letter to Ello?",a="The Letter to Ello is a mysterious missive written in an ancient, illegible tongue, penned by Abercrombie the hermit. Addressed directly to Mayor Ello Ebonlocke of Darkshire, the hermit claims the note will inform his 'old friend' of the deeds you performed out in the cemetery.",al={"letter to ello","what is letter to ello","abercrombies note"},it="identity",add="74d18927"},{q="Why does Mayor Ebonlocke want the Letter to Ello?",a="Mayor Ebonlocke wants the letter only because you arrive bearing word that an old friend named Abercrombie sent it to him. Upon receiving it, however, the mayor finds he cannot read its archaic script and urgently seeks to have it translated to uncover what the hermit actually intended.",al={"why does ello want the letter","why want letter to ello","why deliver letter to ello"},it="why_wanted",add="ee8215fa"}},ang={["faction:Alliance"]="As an Alliance traveler in Duskwood, you may carry a dispatch from an eccentric recluse to a town mayor. Darkshire's officials remain on edge around strange missives."},kw={"abercrombie","darkshire","duskwood","ello ebonlocke","letter to ello","note to the mayor","sirra von'indi"},rel={"quest:160","quest:251","npc:abercrombie","npc:sirra-von-indi","subzone:darkshire","zone:duskwood","quest:165"},src={"Letter to Ello","Note to the Mayor (Classic)","Translate Abercrombie's Note"}}
E["item:mary-s-looking-glass"] = {t="item",n="Mary's Looking Glass",z="duskwood",s="In Duskwood, Mary's discarded looking glass passes from a ghoul to a stargazer.",h="In Duskwood, Mary's discarded looking glass passes from a ghoul to a stargazer.",sec={{t="A Forsaken Treasure",b="Blind Mary once treasured the polished mirror. After her death and the loss of her eyes, her reflection became a painful reminder of what she had lost. She threw the looking glass behind her barn. Duskwood's gloom gathered around it, until an Insane Ghoul found it among the ruined outskirts and carried it south to the crypts of Tranquil Gardens Cemetery.",sp=0},{t="Eyes to the Heavens",b="In Darkshire, the stargazer Viktori Prism'Antras dreams of looking past Duskwood's eternal twilight to the clear heavens above. His telescope needs special optical lenses and reflective glass. Mary sends adventurers to the ruined chapel in the cemetery, where feral undead hold her looking glass. Viktori needs it as a reflector in his machine for viewing the stars.",sp=0}},faq={{q="Why did Mary throw the looking glass away?",a="The looking glass was once one of Mary's finest treasures, but she threw it behind the barn after an incident she does not fully describe. In another encounter, she explains that she tore out her own eyes because she could not bear her appearance.",al={"why mary threw it away","why discard mirror","blind mary mirror lore"},it="motive"},{q="Who ended up with the mirror after Mary discarded it?",a="An Insane Ghoul roaming the woods behind Mary's old farmstead scavenged the discarded mirror. The undead creature eventually took up residence in the abandoned chapel at Tranquil Gardens Cemetery.",al={"who has the mirror","who dropped looking glass","where is looking glass"}},{q="Why does Viktori Prism'Antras want Mary's looking glass?",a="Viktori is building an elaborate telescope to pierce Duskwood's gloom and study the stars. He needs a fine reflective surface to direct light through the device, and Mary's glass fits his design.",al={"why does viktori need mirror","viktori looking glass use","telescope mirror"},it="why_wanted"},{q="Where can the Insane Ghoul holding the mirror be found?",a="The Insane Ghoul lurks in Duskwood's far southeastern corner, haunting the ruined stone chapel in Tranquil Gardens Cemetery.",al={"insane ghoul location","where is insane ghoul","tranquil gardens ghoul"},it="target",gp=true},{q="What is Mary's Looking Glass?",a="Mary's Looking Glass is a reflective hand mirror that once belonged to Blind Mary before tragedy befell her. Regarded by Mary as one of her finest personal treasures, she ultimately cast it away behind her barn following a horrifying incident. It later fell into the clutches of a wandering undead ghoul in Duskwood.",al={"what is mary's looking glass","mary looking glass item","blind mary looking glass"},it="identity",add="afb2ba8d"}},ang={["profession:Engineering"]="Engineers can appreciate how Viktori repurposes an antique household mirror as an optical reflector for a device that views the stars.",["faction:Alliance"]="Recovering relics from the horrors in Tranquil Gardens Cemetery brings some closure to Darkshire's troubled citizens and aids the town's projects."},kw={"blind mary","darkshire","duskwood","insane ghoul","look to the stars","looking glass","mary's looking glass","tranquil gardens cemetery","viktori prism'antras"},rel={"quest:174","npc:blind-mary","subzone:tranquil-gardens-cemetery","zone:duskwood","subzone:darkshire"},src={"Mary's Looking Glass","Look To The Stars (3)"}}
E["item:muddy-journal-pages"] = {t="item",n="Muddy Journal Pages",z="duskwood",s="Muddy Journal Pages were recovered from a murder scene in Duskwood years ago. Weathered and stained with soil, they remain with Tavernkeep Smitts, who kept them without proof of authorship as evidence in an unresolved local investigation.",h="Muddy Journal Pages were recovered from a murder scene in Duskwood years ago.",sec={{t="The Evidence of the Massacre",b="Tavernkeep Smitts found the pages in the mire after visiting nobles were slaughtered in Duskwood. He had gone to the scene with Haggard, the investigator. The town had no handwriting samples or confirmed records to connect the writing to a suspect, so Smitts kept the pages quietly in Darkshire's tavern. He waited for an investigator to gather scattered records from across the southern kingdoms and match the script to the recluse living deep in the woods.",sp=1}},faq={{q="Where were the muddy journal pages found?",a="Tavernkeep Smitts and Haggard found the pages at the scene where visiting nobles were slaughtered in the woods of Duskwood several years ago.",al={"where did smitts find the pages","origin of muddy pages","muddy journal location"},it="place"},{q="Why couldn't Smitts use the pages when he first found them?",a="The local investigators had no writing samples to compare with the pages, so they could not connect the handwriting to a suspect.",al={"why keep the pages secret","why didn't smitts turn them in","smitts evidence problem"},it="motive"},{q="Who needs to see these pages?",a="The pages must be brought to Commander Althea Ebonlocke, leader of the Night Watch in Darkshire, to report the investigation into the nobles' slaughter.",al={"who do i give the muddy pages to","turn in muddy journal pages","ebonlocke muddy pages"},sp=1,it="target"},{q="What crime do these pages connect to?",a="The pages connect to the slaughter of visiting nobles in the woods of Duskwood several years ago, a crime Darkshire could not solve at the time.",al={"what massacre","what did stalvan do","visiting nobles slaughtered"},it="history"},{q="What are the Muddy Journal Pages?",a="These are soiled, torn diary leaves recovered years ago from the site of a brutal massacre of visiting nobles in Duskwood. Written by Stalvan Mistmantle, they document his descent and provide the long-sought written proof of his presence and madness at the scene of the slaughter.",al={"what are muddy journal pages","muddy journal pages","what is this item"},sp=1,it="identity",add="7e79311d"},{q="Where do the Muddy Journal Pages come from, and who wrote them?",a="They were written by Stalvan Mistmantle and left behind in the mud when the nobles were murdered. Tavernkeep Smitts and Haggard discovered them while investigating the bloodbath, but Smitts held onto them for years because he lacked handwriting samples to confirm who had penned them.",al={"who wrote the muddy journal pages","where did muddy pages come from","author of muddy journal pages"},sp=1,it="origin",add="bcc5553e"},{q="Why does Commander Ebonlocke need the Muddy Journal Pages?",a="Commander Althea Ebonlocke oversees Darkshire's defense and requires definitive proof before acting against the threat in the woods. Paired with the handwriting evidence you gathered across the kingdom, these pages establish Stalvan's guilt beyond doubt and urge the Night Watch to finally deal with him.",al={"why take pages to ebonlocke","who wants muddy journal pages","why are the muddy pages important"},sp=1,it="why_wanted",add="f7c3dc88"}},ang={["faction:Alliance"]="For the Alliance, solving the slaughter of Stormwind nobles brings overdue closure to a lingering case in Duskwood's embattled settlements.",["class:Rogue"]="As a Rogue, piecing together forgotten handwriting samples and weathered diary scraps shows the methodical forensic work needed before striking down a hidden killer."},kw={"darkshire","ebonlocke","haggard","muddy journal pages","smitts"},rel={"quest:66","npc:tavernkeep-smitts","npc:althea-ebonlocke","subzone:darkshire","zone:duskwood","topic:light"},src={"Muddy Journal Pages","The Legend of Stalvan (10)"}}
E["item:ogre-s-monocle"] = {t="item",n="Ogre's Monocle",z="duskwood",s="In southern Duskwood, Zzarc'Vul wears a monocle Viktori Prism'Antras needs for a telescope. Its lens has the size and curve to focus light through the stargazing instrument in Darkshire.",h="In southern Duskwood, Zzarc'Vul wears a monocle Viktori Prism'Antras needs for a telescope.",sec={{t="A Curious Lens",b="Zzarc'Vul, an ogre, wears a monocle made for his massive stature. When Viktori Prism'Antras of Darkshire began building a stargazing instrument from the gnome engineer Cog's blueprints, ordinary lenses proved too small. Zzarc'Vul's eyewear is the only polished glass in the region with the size and curve to focus light through the finished telescope.",sp=0},{t="Prying It from Vul'Gol",b="At the Vul'Gol Ogre Mound in southern Duskwood, Zzarc'Vul lives among his brute brethren. He shows little wish to give up his distinctive accessory. You must defeat him on his own ground to claim the lens, then carry it back to Darkshire so Viktori can turn his gaze to the night skies.",sp=0}},faq={{q="Who carries the Ogre's Monocle?",a="Zzarc'Vul, an ogre, carries the monocle at the Vul'Gol Ogre Mound in southern Duskwood.",al={"who drops the monocle","who has the ogre monocle","zzarc'vul item"},it="target"},{q="Why does Viktori Prism'Antras need an ogre's eyepiece?",a="Viktori Prism'Antras needs an unusually large lens for a telescope built from the gnome Cog's blueprints. Zzarc'Vul's monocle is the only piece of glass in Duskwood that fits.",al={"why need monocle","what is the monocle for","telescope lens"},it="why_wanted"},{q="How did an ogre get a giant monocle?",a="The account does not explain how Zzarc'Vul acquired the monocle. It says only that he has one large enough for Viktori's telescope.",al={"why does an ogre have a monocle","ogre reading glasses lore"},it="origin"},{q="Where is the Vul'Gol Ogre Mound located?",a="The Vul'Gol Ogre Mound lies in the southern hills of Duskwood, south of the main road between Darkshire and the western border.",al={"where is vulgol","ogre mound duskwood"},it="place",gp=true},{q="What is the Ogre's Monocle?",a="The Ogre's Monocle is an oversized optical lens worn as an eyepiece by Zzarc'Vul, a prominent ogre residing within the Vul'Gol Ogre Mound in southern Duskwood. While such fine optical wear is exceedingly rare among ogres, its massive glass lens makes it uniquely suited for heavy optical machinery.",al={"what is ogres monocle","ogre monocle item","ogre eyepiece"},it="identity",add="94fbe42d"}},ang={["profession:Engineering"]="Cog's blueprint shows typical gnomish ambition: when precision-ground lenses are unavailable in the field, giant eyewear must do.",["faction:Alliance"]="Recovering the lens removes a dangerous brute from the southern woods and helps Darkshire's beleaguered citizens find solace in the stars."},kw={"cog","darkshire","look to the stars","ogre's monocle","telescope","viktori prism'antras","vul'gol ogre mound","zzarc'vul"},rel={"quest:174","subzone:vul-gol-ogre-mound","subzone:darkshire","zone:duskwood"},src={"Ogre's Monocle","Look To The Stars (4)"}}
E["item:rot-blossom"] = {t="item",n="Rot Blossom",z="duskwood",s="In Duskwood, Rot Blossoms rise from desecrated graves, fed by blighted soil and undead remains. Their foul alchemical properties make them sought after.",h="In Duskwood, Rot Blossoms rise from desecrated graves, fed by blighted soil and undead remains.",sec={{t="Flora of the Crypts",b="In Duskwood, Rot Blossoms grow in defiled graveyard earth, including the Tranquil Gardens Cemetery. Local rumors say they take root inside the cracked skulls of Skeletal Horrors and Skeletal Fiends that stalk the barrows. Gathering them is grim work for people in Darkshire. Disturb the soil, and the unrested dead must be faced.",sp=0},{t="A Gruesome Ingredient",b="Rot Blossoms provide an ingredient for local brews. Their dark essences are needed to make Zombie Juice, a foul draft tied to Duskwood's struggle to survive. Those sent to gather the flowers often aid the Night Watch by cutting down restless skeletons wandering the haunted graves.",sp=0}},faq={{q="Where can Rot Blossoms be found?",a="Rot Blossoms grow in Duskwood's corrupted burial grounds, particularly in the Tranquil Gardens Cemetery. They also sprout from the remains of undead skeletal fiends.",al={"where do rot blossoms grow","rot blossom location","find rot blossoms"},it="place",gp=true},{q="What are Rot Blossoms used for?",a="Local brewers and alchemists use Rot Blossoms to make Zombie Juice, a potent and foul mixture.",al={"rot blossom use","why gather rot blossoms","what makes rot blossoms useful"},it="why_wanted"},{q="Why do these blossoms grow in skeletons?",a="Duskwood's lingering dark magic infects the earth and restless dead. Rot Blossoms feed on necrotic corruption and decay, and can sprout inside the skulls and ribcages of roaming skeletons.",al={"rot blossoms in skulls","skeletal horror flower","skeletons rot blossom"},it="origin"},{q="How does gathering Rot Blossoms help Darkshire?",a="Gathering Rot Blossoms in places such as the Tranquil Gardens means cutting down the Skeletal Horrors and Fiends that plague the grounds. This gives needed relief to Althea Ebonlocke and the beleaguered Night Watch.",al={"althea ebonlocke rot blossom","night watch rot blossom","helping darkshire"}},{q="What is a Rot Blossom?",a="A Rot Blossom is a morbid botanical oddity found taking root across the blighted graveyards of Duskwood. Rather than sprouting in healthy soil, these grim flowers thrive amidst decay, notoriously germinating inside the hollow skulls of undead Skeletal Horrors and Skeletal Fiends. Infused with foul energies, they are sought after by eccentric locals who brew potent concoctions from the rot.",al={"what are rot blossoms","rot blossom item","what is rot blossom"},it="identity",add="93f3afdd"}},ang={["profession:Herbalism"]="Rot Blossoms are foul plants fed by necrotic rot and graveyard soil, unlike herbs nurtured by light and rain. They offer a grim study in corrupted flora.",["faction:Alliance"]="Gathering these morbid blooms in cursed soil also helps the Night Watch keep ravenous skeletons from Darkshire's borders."},kw={"althea ebonlocke","darkshire","duskwood","rot blossom","skeletal fiend","skeletal horror","tranquil gardens cemetery","zombie juice"},rel={"quest:156","quest:158","subzone:tranquil-gardens-cemetery","subzone:raven-hill-cemetery","npc:althea-ebonlocke","topic:night-watch","zone:duskwood","quest:56"},src={"Rot Blossom","Gather Rot Blossoms (Classic)"}}
E["item:skeleton-finger"] = {t="item",n="Skeleton Finger",z="duskwood",s="In Duskwood, restless dead yield Skeleton Finger to Madame Eva of Darkshire. She gathers them with ghoul fangs and spider venom to make protective talismans.",h="In Duskwood, restless dead yield Skeleton Finger to Madame Eva of Darkshire.",sec={{t="Bones of the Restless",b="Skeletal raiders and warriors rise across Duskwood, along with necrotic mages and fiends. Most travelers leave their foul remains alone, but fortune tellers and mystics prize their cold essence. Madame Eva, the seer of Darkshire, gathers their bony fingers for the Totem of Infliction. She binds their lingering necrotic energies into a ward that strikes back at attackers.",sp=0}},faq={{q="What creatures drop a Skeleton Finger?",a="Skeleton Fingers come from Skeletal Raiders, Healers, Warders, Warriors, Horrors, Fiends, and Skeletal Mages across Duskwood.",al={"where do skeleton fingers drop","what drops skeleton fingers","skeleton finger source"},it="origin",gp=true},{q="Who wants Skeleton Fingers in Duskwood?",a="Madame Eva, the seer of Darkshire, needs Skeleton Fingers to make a protective ward.",al={"who needs skeleton fingers","skeleton finger quest giver","what are skeleton fingers for"},it="why_wanted"},{q="What is the Totem of Infliction?",a="Madame Eva makes the Totem of Infliction from skeleton fingers, ghoul fangs, and spider venom. She binds their dark energies into an aura that harms anyone who attacks its bearer.",al={"totem of infliction purpose","what does madame eva make"},it="purpose"},{q="Why does Madame Eva need undead remains for a protective charm?",a="Madame Eva uses the lingering taint and aggression of local creatures in her rituals. She binds the violent essences of Duskwood's skeletons, ghouls, and venomous beasts into a ward that punishes attackers.",al={"why bone magic","why skeleton fingers for totem"},it="motive"},{q="What is a Skeleton Finger?",a="A Skeleton Finger is the severed, desiccated bone fragment taken from one of the animated skeletal horrors wandering the blighted forests and crypts of Duskwood. Preserved by the necromantic taint that has overtaken the region, these digits retain traces of the dark magic that keeps the undead restless and moving.",al={"skeleton finger what is it","what are skeleton fingers","identify skeleton finger"},it="identity",add="7c732e26"},{q="Where does a Skeleton Finger come from?",a="These fingers come from the skeletal remains raised throughout Duskwood's haunted cemeteries and ruins. Rather than being crafted or manufactured, they are harvested directly from the animated corpses—such as skeletal warriors, fiends, warders, and raiders—that crawl through the gloom, animated by the mysterious and creeping taint corrupting the woods.",al={"skeleton finger origin","where do skeleton fingers come from","who made skeleton finger"},it="origin",add="a7de6990"}},ang={["class:Mage"]="As a mage studying folk divination, you may find Madame Eva's use of skeletal digits and natural venoms in a retaliatory enchantment an unusual blend of hedge witchcraft and sympathetic magic.",["class:Paladin"]="As a paladin, you may shudder at desecrating skeletal remains and carrying their severed parts. In Duskwood's dire gloom, using the bones of the unholy to shield the living is a grim necessity."},kw={"darkshire","duskwood","ghoul fang","madame eva","skeletal raider","skeleton finger","totem of infliction"},rel={"quest:101","npc:madame-eva","item:ghoul-fang","item:vial-of-spider-venom","subzone:darkshire","zone:duskwood"},src={"Skeleton Finger","The Totem of Infliction"}}
E["item:spectral-comb"] = {t="item",n="Spectral Comb",z="duskwood",s="South of Darkshire, the Spectral Comb gathers ghost hair from Blind Mary at a ruined farmstead.",h="South of Darkshire, the Spectral Comb gathers ghost hair from Blind Mary at a ruined farmstead.",sec={{t="A Tool for Restless Dead",b="Ordinary combs cannot reach a spirit’s hair, so few mortal craftsmen can gather it. The Spectral Comb passes through those unseen tresses. At a ruined farmstead south of Darkshire, it is offered to Blind Mary, a weeping ghost who wails alone. Grooming brings her solace, and she willingly takes up the comb. The fibers she leaves behind can be woven into Ghost Hair Thread.",sp=0}},faq={{q="What is the Spectral Comb used for?",a="You give the Spectral Comb to Blind Mary, a weeping ghost south of Darkshire. As she combs her hair, the comb gathers ethereal strands that can be spun into supernatural thread.",al={"spectral comb purpose","why do i need spectral comb","what does the comb do"},it="why_wanted"},{q="Who is Blind Mary?",a="Blind Mary is a tormented spirit haunting an abandoned house in the hills south of Darkshire. Driven mad by tragedy, she tore out her own eyes and fears others find her hideous in death.",al={"blind mary lore","who is the ghost with the comb","blind mary"}},{q="Why can an ordinary comb not be used?",a="An ordinary comb cannot touch a spirit’s intangible hair. The Spectral Comb passes through an apparition’s tresses.",al={"why spectral comb","normal comb ghost"},it="power"},{q="What is the Spectral Comb?",a="The Spectral Comb is an ethereal grooming tool specifically enchanted to interact with the incorporeal. While ordinary implements would pass right through a phantom without effect, this comb can actually touch, untangle, and collect the spectral strands of a ghost's hair.",al={"what is spectral comb","spectral comb","spectral comb identity"},it="identity",add="e893aa2f"}},ang={["profession:Tailoring"]="As a tailor, you can use the Spectral Comb to gather ethereal fibers from willing ghosts instead of shearing them by ordinary means.",["faction:Alliance"]="As an Alliance traveler, you can carry the comb south of Darkshire and see the tragic fate of Duskwood’s former homesteaders."},kw={"blind mary","comb","darkshire","duskwood","ghost","ghost hair thread","spectral comb"},rel={"quest:149","npc:blind-mary","zone:duskwood","subzone:darkshire"},src={"Spectral Comb","Ghost Hair Thread (Classic)"}}
E["item:supplies-for-sven"] = {t="item",n="Supplies for Sven",z="duskwood",s="In northwestern Duskwood, Sven Yorgen's camp depends on provisions from Darkshire. The Carevin family keeps his small band supplied as they hold their watch against the shadows.",h="In northwestern Duskwood, Sven Yorgen's camp depends on provisions from Darkshire.",sec={{t="A Lifeline for the Camp",b="Sven Yorgen and his few followers keep camp in the northwestern wilderness, far from Darkshire. Their numbers are too small to leave the watch and make the journey into town. So the Carevin family sends food, bandages, and other necessities to help the band hold its ground.",sp=0}},faq={{q="Who sent these supplies?",a="The Carevin family of Darkshire sends these supplies. They arrange provisions for Sven Yorgen and his camp in the wilderness.",al={"who sent supplies for sven","who packed sven's supplies","carevin family supplies"},it="origin"},{q="Why can't Sven fetch his own supplies?",a="Sven's band has too few people to leave the camp. His surviving companions guard it in northwestern Duskwood against beasts and undead, and none can be spared for the dangerous road to Darkshire.",al={"why doesn't sven get food","why delivery for sven","why need supplies"},it="why_wanted"},{q="Where is Sven's camp located?",a="Sven's camp lies along the northwestern edge of Duskwood, in the hills beyond the Night Watch's direct protection.",al={"where is sven yorgen","sven camp location","find sven duskwood"},it="place",gp=true},{q="Who is Sven Yorgen?",a="Sven Yorgen is a frontiersman and devout believer in the Light who once farmed in Duskwood. After tragedy struck his homestead, he established an armed camp on the frontier to strike back at the dark forces plaguing the region.",al={"who is sven","sven yorgen backstory"},it="identity"},{q="What are the Supplies for Sven?",a="These supplies are a care package gathered to support Sven Yorgen and his small band of followers holding out in Duskwood. The Carevin family regularly prepares such aid so these devoted crusaders can continue doing the Light's work against the horrors haunting the dark forest without abandoning their vigil.",al={"supplies for sven what is it","what are sven's supplies","supplies for sven item"},it="identity",add="0c0166a3"}},ang={["class:Paladin"]="As a paladin, you can see Sven's defiance against Duskwood's darkness as work of the Light. These provisions go to a brother in faith.",["faction:Alliance"]="With the Night Watch stretched thin defending Darkshire, Alliance travelers often carry supplies to isolated outposts like Sven's camp."},kw={"camp","carevin","darkshire","duskwood","provisions","supplies for sven","sven yorgen"},rel={"quest:164","npc:sven-yorgen","quest:1042","quest:95","zone:duskwood","topic:light"},src={"Supplies for Sven","Deliveries to Sven"}}
E["item:the-embalmer-s-heart"] = {t="item",n="The Embalmer's Heart",z="duskwood",s="In Duskwood, Eliza's buried corpse still holds a beating heart. The Embalmer placed his own heart in his dead wife through dark magic, and it became the anchor of his power.",h="In Duskwood, Eliza's buried corpse still holds a beating heart.",sec={{t="A Love That Defied Death",b="Darkshire remembers the Embalmer as a gentle alchemist. When his wife Eliza died, grief broke his mind. He turned to foul sorcery, cut out his own heart, and placed it in her lifeless chest. The magic stirred her corpse to unlife. But Eliza returned as a ravenous creature, hungry for living human flesh. Horrified by what he had done, the alchemist buried her again.",sp=0},{t="A Shield for Darkshire",b="The Embalmer's heart still beats inside Eliza's tomb and sustains his dark power. Mayor Ello Ebonlocke believes Darkshire can weaken the Embalmer's sorcery by destroying his reanimated bride and claiming the heart. If they secure it while it still beats, the town's leaders hope to turn its essence against the necromancer. They hope it will become a ward against his terrors.",sp=1}},faq={{q="Why does Eliza have the Embalmer's heart?",a="Grief drove the Embalmer to place his own beating heart in Eliza's corpse with forbidden magic. The ritual returned her to unlife, but left her ravenous for human flesh.",al={"why does eliza have the heart","embalmer heart in eliza","who put heart in eliza"},it="origin"},{q="Why does Mayor Ebonlocke want the heart brought back to Darkshire?",a="Mayor Ello Ebonlocke hopes the heart's dark magic will weaken the Embalmer and become a ward that protects Darkshire.",al={"why does ello want the heart","ebonlocke heart plan","what does darkshire do with heart"},it="why_wanted"},{q="How does the Embalmer survive without his heart?",a="The Embalmer bound his life force and power to the heart through dark sorcery. It still beats inside his wife's buried remains, while he endures without it.",al={"is the embalmer alive","how is embalmer alive without heart"}},{q="Where can the heart be found?",a="The heart lies inside Eliza, buried in a hidden grave plot in Duskwood. It can be claimed only by confronting and defeating the ravenous bride, returned to unlife.",al={"where is embalmer heart","eliza grave location","how to get embalmers heart"},it="place",gp=true},{q="What is the Embalmer's Heart?",a="It is the literal, magically sustained beating heart of the renegade alchemist known as the Embalmer. Driven mad by grief over the death of his wife, Eliza, he cut out his own heart and placed it within her corpse to restore her to life. Even separated from his chest, the heart serves as the vessel and conduit of his necromantic power, maintaining both Eliza's cursed undead state and his own unholy vitality.",al={"what is embalmers heart","embalmer heart lore","the embalmers heart"},it="identity",add="cac9cdef"}},ang={["class:Warlock"]="As a warlock, you can recognize how the heart anchors necromantic unlife through fleshcraft and the binding of a soul.",["race:Human"]="As a human, you hear Duskwood's beleaguered people whisper of the kindly alchemist's tragic fall."},kw={"bride of the embalmer","darkshire","duskwood","eliza","ello ebonlocke","embalmer's heart","the embalmer"},rel={"quest:253","subzone:darkshire","zone:duskwood","topic:human"},src={"The Embalmer's Heart","Bride of the Embalmer"}}
E["item:translated-letter"] = {t="item",n="Translated Letter",z="duskwood",s="In Darkshire, Sirra Von'Indi translates Abercrombie's letter for Mayor Ello Ebonlocke. The message sheds light on the hermit's dealings with the town.",h="In Darkshire, Sirra Von'Indi translates Abercrombie's letter for Mayor Ello Ebonlocke.",sec={{t="A Gruesome Revelation",b="The errands began as acts of mercy for a seemingly helpless hermit in Raven Hill. Abercrombie's obscure message to Mayor Ello Ebonlocke remained a mystery until Sirra Von'Indi translated it. The words reveal that the hermit is the Embalmer. He used the supplies brought to him to build Stitches, a monstrous abomination, then unleashed the hulking creation on Darkshire's people to trample and slaughter them.",sp=1,bt={"q165.5"}},{t="The Price of Good Intentions",b="When the translated message is presented to Lord Ello Ebonlocke, the mayor's face drains of color. The traveler's help came from goodwill, but Abercrombie used that labor to build an instrument of slaughter. As the town council scrambles to marshal the Night Watch, the letter reveals how charity can be twisted into devastation on Duskwood's haunted roads.",sp=1}},faq={{q="What does the Translated Letter say?",a="The letter carries an alarming message from Abercrombie to Lord Ello Ebonlocke. Its full contents are revealed when you deliver the translated note to him in Darkshire.",al={"letter text","what did abercrombie write","what does it say"},sp=1},{q="Who translates the letter?",a="Sirra Von'Indi, a scholar in Darkshire, translates Abercrombie's cryptic handwriting and warns you to hurry back to Lord Ello with the alarming news.",al={"who translates it","who decoded the letter","sirra von indi letter"},it="origin"},{q="What happens when Ello reads the letter?",a="Ello is deeply alarmed by the translation. Bring the letter to him to learn what it means for Darkshire.",al={"ello reaction","turning in translated letter","what happens after translation"},sp=1},{q="Can I throw away the Translated Letter after the quest?",a="Yes. Once Lord Ello inspects the parchment and advances the town's defense, the letter remains in your pack as a souvenir and has no further use.",al={"safe to delete translated letter","can i destroy translated letter","keep translated letter"},sp=1,gp=true},{q="What is the Translated Letter?",a="The Translated Letter is an ominous missive penned by the hermit Abercrombie and decrypted by Sirra Von'Indi. It reveals the horrifying consequences of Abercrombie's grim schemes in Raven Hill and serves as a direct warning of impending doom threatening the people of Darkshire.",al={"translated letter","what is translated letter","about translated letter"},sp=1,it="identity",add="ad927ea8"},{q="Why does Lord Ello Ebonlocke need the Translated Letter?",a="Lord Ello Ebonlocke, the mayor of Darkshire, must read the decrypted contents to understand the grave peril facing his town. The letter uncovers the horrific nature of Abercrombie's handiwork and gives the township advance notice that a monstrous abomination is lumbering straight toward their gates.",al={"why bring translated letter to ello","why does ello want translated letter","who needs the translated letter"},sp=1,it="why_wanted",add="7688c5ef"}},ang={["faction:Alliance"]="As an Alliance traveler in Duskwood, you learn how good intentions can be turned against Darkshire's fragile defenders."},kw={"abercrombie","darkshire","letter to ello","lord ello ebonlocke","sirra von'indi","translated letter"},rel={"item:letter-to-ello","quest:252","npc:lord-ello-ebonlocke","npc:sirra-von-indi","npc:abercrombie","npc:stitches","quest:253","zone:duskwood"},src={"Translated Letter","Translation to Ello"}}
E["item:vial-of-spider-venom"] = {t="item",n="Vial of Spider Venom",z="duskwood",s="In Duskwood, Madame Eva gathers venomous spiders' poison to make a ward against attackers. She needs it alongside undead remains for a Totem of Infliction.",h="In Duskwood, Madame Eva gathers venomous spiders' poison to make a ward against attackers.",sec={{t="Duskwood's Venomous Threat",b="Duskwood's thickets shelter venomous spiders, from pygmy venom webs and green recluses to black widows and Naraxis. Their fangs carry poison potent enough to paralyze travelers and decay flesh. Those who kill the spiders can draw the fluid into intact vials.",sp=0},{t="Crafting the Totem of Infliction",b="In Darkshire, fortune teller Madame Eva sees ominous portents for travelers setting out into the dark world. She needs five vials of spider venom, ghoul fangs, and skeleton fingers to craft a ward of retribution. Her craft turns the venom’s biting nature against attackers. The Totem of Infliction returns harm to anyone who strikes its bearer.",sp=0}},faq={{q="Where does this spider venom come from?",a="Predatory spiders in Duskwood carry this venom. They include Venom Web Spiders, Carrion Recluses, Green Recluses, Black Widow Hatchlings, and the monstrous broodmother Naraxis.",al={"spider venom source","who drops spider venom","where to get spider venom duskwood"},it="origin",gp=true},{q="Who wants Vials of Spider Venom?",a="In Darkshire, Madame Eva asks for five vials of spider venom, skeletal fingers, and ghoul fangs to make a magical ward.",al={"who needs spider venom","spider venom duskwood turn in","madame eva venom"},it="why_wanted"},{q="What is the venom used to craft?",a="Madame Eva combines the venom with undead remains to enchant a Totem of Infliction. The defensive talisman magically harms attackers.",al={"what does eva make","totem of infliction materials","why collect spider venom"},it="purpose"},{q="Why does Madame Eva need dangerous venom for a protective ward?",a="Madame Eva uses the deadly, retaliatory qualities of forest predators and the undead to make a charm that turns violence back on the aggressor.",al={"why venom for ward","eva totem ingredients lore"},it="motive"},{q="What is a Vial of Spider Venom?",a="It is a small phial containing the potent, corrosive venom harvested from the monstrous arachnids that infest Duskwood. While naturally deadly to the touch, such dark and virulent substances are prized by local mystics and hedge witches who weave hexes or enchant talismans capable of turning an attacker's own malice back upon them.",al={"what is spider venom","vial of spider venom lore","what is vial of spider venom"},it="identity",add="cd5271e6"}},ang={["class:Rogue"]="As a rogue, you may brew poisons and coat blades. This raw spider venom is meant for mystic shielding rather than direct assassination.",["faction:Alliance"]="As an Alliance adventurer on Duskwood’s shadowed roads, you can help Madame Eva make protective totems for travelers facing the woods’ horrors."},kw={"darkshire","duskwood","madame eva","naraxis","recluse","spider venom","totem of infliction","vial of spider venom"},rel={"quest:101","npc:madame-eva","zone:duskwood","item:ghoul-fang","item:skeleton-finger","subzone:darkshire"},src={"Vial of Spider Venom","The Totem of Infliction"}}
E["npc:abercrombie"] = {t="npc",n="Abercrombie",z="duskwood",s="Near Raven Hill Cemetery, Abercrombie asks travelers to bring supplies from Darkshire. In western Duskwood, the old hermit seems worn and troubled by the woods.",h="Near Raven Hill Cemetery, Abercrombie asks travelers to bring supplies from Darkshire.",sec={{t="The Recluse of Raven Hill",b="Abercrombie lives in a ruined shack near Raven Hill Cemetery. Duskwood's decay has left him looking like a broken old man. He says he is trying to survive the terrors of the woods, and asks travelers to bring supplies, herbs, and thread from Darkshire. To anyone who does not know the region's history, he seems another unfortunate soul left behind as the province fell into ruin.",sp=0},{t="The Embalmer's Madness",b="Abercrombie once lived in Raven Hill as a respected and kindly alchemist. When his beloved wife, Eliza, died, grief broke his sanity. He turned to forbidden necromantic arts, cut out his own heart, and placed it in Eliza's dead breast to bring her back. The ritual made her a monster with an insatiable hunger for living flesh, and Abercrombie kept her buried in the cemetery.",sp=2,bt={"q165.5"}},{t="A Monstrous Deception",b="Abercrombie, known in dark folklore as the Embalmer, nurses a deep, psychotic grudge against Darkshire and its leaders. He sends helpful travelers for ghoul ribs, specialty thread, and caustic brews. These supplies are the final parts needed to assemble Stitches, a colossal abomination stitched from flesh and built to slaughter the Night Watch and ravage the town.",sp=1,bt={"q165.5"}}},faq={{q="Who is Abercrombie?",a="Abercrombie is a hermit near Raven Hill Cemetery in Duskwood. Once a skilled alchemist, he lost his mind after his wife died and became the necromantic figure known as the Embalmer.",al={"who is the hermit","abercrombie lore","who is abercrombie"},sp=2,it="identity",bt={"q165.5"}},{q="Why does Abercrombie want supplies from Darkshire?",a="Abercrombie says he needs domestic supplies and thread to survive in the wilderness. In truth, he tricks travelers into gathering the parts needed to assemble Stitches, a monstrous abomination.",al={"why does abercrombie need thread","abercrombie supplies","what is abercrombie building"},sp=1,it="wants"},{q="Who was Eliza?",a="Eliza was Abercrombie's wife. After her death, he tried to resurrect her with dark magic by placing his own heart in her corpse. She returned as a ravenous undead monster, and Abercrombie kept her buried in Raven Hill Cemetery.",al={"eliza abercrombie","abercrombie wife","bride of the embalmer"},sp=1,it="ties",bt={"q165.5"}},{q="What happens when you deliver the Note to the Mayor?",a="Lord Ello cannot read the Note, which is written in an ancient language, so he asks Sirra Von'Indi to translate it. The translation reveals that Abercrombie has done something unspeakable. Once Ello reads it, monstrous Stitches lumbers down the road from Raven Hill toward Darkshire.",al={"note to the mayor","what does the note say","abercrombie letter"},sp=2,it="conflict"},{q="Why does Abercrombie hate Darkshire?",a="Abercrombie never explains his hatred of Darkshire. Grief and dark magic drove him mad after his wife's death, and he mockingly calls Mayor Ello Ebonlocke an old friend as he sends his monstrous creation down the road to destroy the town.",al={"why does abercrombie attack darkshire","embalmer motive","abercrombie revenge"},sp=1,it="motive"},{q="Is Abercrombie allied with the Scourge?",a="No. Abercrombie is a lone hermit with no ties to the Lich King's armies.",al={"is abercrombie scourge","who does abercrombie work for"},it="side"},{q="Why does Abercrombie live near Raven Hill Cemetery?",a="Abercrombie keeps to a lonely shack just northeast of Raven Hill Cemetery in western Duskwood, far from Darkshire. He presents himself as a harmless, eccentric hermit and asks passing travelers to fetch supplies from town for him.",al={"why is abercrombie here","why raven hill abercrombie","abercrombie location reason"},it="why_here",add="5abf44f4"},{q="Why is Abercrombie feared across Duskwood?",a="Though he masquerades as a harmless hermit, Abercrombie is secretly the dread figure known as the Embalmer. Local tales and children's stories recount his descent into mad necromancy, carving out his own heart to reanimate his dead wife into a flesh-craving ghoul. His very name evokes the horror of forbidden stitched horrors unleashed upon the living.",al={"why is abercrombie feared","abercrombie the embalmer reputation","the embalmer duskwood"},sp=1,it="fame",add="a3c5130f",bt={"q165.5"}}},ang={["faction:Alliance"]="Alliance heroes who help the miserable hermit unknowingly provide the materials for an assault on Darkshire.",["class:Paladin"]="As a paladin, you can see in Abercrombie how necromancy's sinister corruption hides beneath the guise of an ordinary townsman seeking charity.",["class:Warlock"]="As a warlock, you can see in Abercrombie's sacrifice of his own heart the extreme, self-destructive lengths mortals will go to wield dark magic."},kw={"abercrombie","abomination","darkshire","duskwood","eliza","ghoulish effigy","raven hill","the hermit"},rel={"subzone:raven-hill-cemetery","subzone:darkshire","zone:duskwood","quest:165","quest:253","quest:160","topic:night-watch"},src={"Abercrombie"}}
E["npc:althea-ebonlocke"] = {t="npc",n="Althea Ebonlocke",z="duskwood",s="In Darkshire, Althea Ebonlocke leads the Night Watch against Duskwood’s horrors. A relative of Mayor Ello Ebonlocke, she guards an isolated region left without Stormwind’s regular troops.",h="In Darkshire, Althea Ebonlocke leads the Night Watch against Duskwood’s horrors.",sec={{t="Commander of the Watch",b="Althea Ebonlocke directs Darkshire’s defense while Mayor Ello Ebonlocke, her relative, governs from the town hall. Stormwind sent no royal troops to guard Duskwood, so the townspeople formed the Night Watch. Under Althea’s firm command, its volunteers patrol the foggy roads and keep undead skeletons, fierce wolves, and spiders from overrunning the town’s edge.",sp=0},{t="A Town on the Brink",b="Althea knows her militia cannot face the dangers alone. Recruits are scarce and the Watch keeps losing them, so she enlists passing mercenaries and travelers to thin the threats near Darkshire. She directs efforts against ghouls and skeletons in the forest’s quiet, sorrowful graveyards. All the while, she watches for darker rumors from deep in the woods.",sp=0},{t="Tragedies of the Wood",b="Althea coordinates the search for Duskwood’s greatest blights and the effort to destroy them. She helps unravel the dark fate of Stalvan Mistmantle and seeks answers to the restless wandering of Mor'Ladim, the fallen knight Morgan Ladimore.\n\nWhen Abercrombie sends the monstrous abomination Stitches down the main road, Althea’s Night Watch turns out along the road to face it.",sp=1}},faq={{q="Who is Althea Ebonlocke?",a="Althea Ebonlocke commands the Night Watch, Darkshire’s militia in Duskwood. She organizes the region’s defense against undead and beasts lurking in the shadows.",al={"who is althea","commander ebonlocke","who is the night watch commander"},it="identity"},{q="What is the Night Watch?",a="The Night Watch is a volunteer militia formed by Darkshire’s citizens. With almost no military support from Stormwind, the townspeople patrol the roads under Althea’s command and fight the horrors in the woods.",al={"what is night watch","who are the night watch","darkshire militia"}},{q="How is Althea related to Mayor Ello Ebonlocke?",a="Althea is a relative of Mayor Ello Ebonlocke, who governs Darkshire from the town hall. She commands the militia in the field.",al={"ello ebonlocke relative","is althea ello daughter","althea family"},it="ties"},{q="Why is Stormwind not helping Althea defend Darkshire?",a="Stormwind’s resources are strained, and with King Varian Wrynn missing, the House of Nobles has largely neglected the kingdom’s outer territories. Darkshire receives almost no soldiers or relief, so Althea relies on local volunteers and freelance adventurers.",al={"why no stormwind guards","stormwind duskwood support","where are the soldiers"},it="conflict"},{q="What quests does Commander Althea offer?",a="Althea sends adventurers to hunt wolves, skeletal fiends, and ghouls across Duskwood. She also helps investigate the Legend of Stalvan and confront the wandering terror Mor'Ladim.",al={"althea quests","night watch questline"},gp=true},{q="What does Althea do when Stitches attacks Darkshire?",a="When Abercrombie’s stitched abomination Stitches lumbers down the road toward Darkshire, Althea’s Night Watch guards turn out to face it. Without help from adventurers, the monster can cut straight through them.",al={"althea stitches","who fights stitches","darkshire under attack"},sp=1,it="danger"},{q="Whose side is Commander Althea Ebonlocke on?",a="Commander Althea stands firmly with the people of Darkshire and the Alliance. While Stormwind has largely abandoned Duskwood to its shadowy fate, Althea refuses to forsake her home. She leads the Night Watch—a desperate local militia sworn to hold the line against the feral beasts, restless dead, and creeping horrors that threaten to wipe the town off the map.",al={"althea ebonlocke faction","who does althea fight for","is althea alliance"},it="side",add="4a666294"},{q="What does Commander Althea Ebonlocke want?",a="Her paramount goal is the survival of Darkshire. With regular army reinforcements absent, Althea works tirelessly to keep the encroaching wilderness at bay. She directs the Night Watch against encroaching skeletal fiends, rabid wolves, and spiders, and she actively seeks brave adventurers to eliminate deadly threats lingering in the shadows of the woods before they slaughter her beleaguered town.",al={"what does althea want","althea ebonlocke goal","althea mission duskwood"},it="wants",add="37e849b9"},{q="Why is Commander Althea Ebonlocke in Darkshire?",a="Duskwood is her home and her duty. Related to Mayor Lord Ello Ebonlocke, she stays at the town square to command the Night Watch from the heart of the settlement. Rather than fleeing to the safety of Stormwind, Althea remains on the front line to coordinate patrols and rally any capable traveler into defending the borders.",al={"why is althea in darkshire","why is commander althea here","althea ebonlocke location"},it="why_here",add="288c0322"}},ang={["faction:Alliance"]="Althea shows the Alliance’s grim resolve on forgotten frontiers, holding the kingdom together where the crown’s armies have withdrawn.",["class:Warrior"]="As a warrior, you may respect Althea’s stern, practical command. She values discipline and fighters willing to hold the line against overwhelming odds.",["class:Paladin"]="As a paladin, you can help Althea put restless souls to peace on Duskwood’s gloomy roads, easing some of the spiritual dread weighing on her militia."},kw={"althea","commander","darkshire","duskwood","ebonlocke","militia","mor'ladim","night watch","stitches"},rel={"topic:night-watch","npc:lord-ello-ebonlocke","subzone:darkshire","zone:duskwood","quest:56","topic:mor-ladim","quest:66"},src={"Althea Ebonlocke"}}
E["npc:blind-mary"] = {t="npc",n="Blind Mary",z="duskwood",s="In a ruined farmhouse southeast of Darkshire, Blind Mary wanders as a tormented banshee. Once a vain and beautiful woman, she was slain when the undead swept through Duskwood and rose in a form she could not bear.",h="In a ruined farmhouse southeast of Darkshire, Blind Mary wanders as a tormented banshee.",sec={{t="A Tragic Vanity",b="Before the shadows fell across Duskwood, Mary was known for her beauty. She took great pride in it and rarely went without her treasured looking glass. When the undead swept through the region, Mary and many of her neighbors were slain. Her spirit found no rest in the earth. She became an ethereal banshee, condemned to wander the mortal realm in a ghastly, translucent form.",sp=0},{t="Blinded by Despair",b="Sorrow, horror, and fury overwhelmed Mary when she awoke among the undead. Unable to bear her monstrous reflection, she clawed out her own eyes with her bare hands. She cast away her beloved looking glass and drifted through her abandoned home, blind and weeping. Faint memories of the mortal life she lost were all she could cling to.",sp=0}},faq={{q="Who is Blind Mary?",a="Blind Mary haunts a ruined homestead southeast of Darkshire as a banshee. She was a beautiful local woman, slain when Duskwood fell into darkness and raised as an undead spirit.",al={"who is blind mary","blind mary backstory","blind mary lore","blind mary duskwood"},it="identity"},{q="Why is she called Blind Mary?",a="Grief and despair at her banshee form made Mary unable to bear her reflection, so she clawed out her own eyes.",al={"why is she blind","how did blind mary lose her eyes","blind mary eyes"},it="origin"},{q="Where does Blind Mary dwell?",a="Blind Mary lingers in a dilapidated farmhouse called Blind Mary's Haunt, southeast of Darkshire in eastern Duskwood.",al={"blind mary location","where is blind mary","blind mary haunt"},it="place"},{q="Is Blind Mary hostile to living travelers?",a="Blind Mary does not attack travelers on sight. Unlike the aggressive ghouls and skeletons in the surrounding woods, she remains trapped in mourning. Those who approach her ruined home can speak to her.",al={"is blind mary hostile","does blind mary attack","can you talk to blind mary"},it="hostile"},{q="What happened to Mary's looking glass?",a="After tearing out her eyes in horror at her spectral form, Mary cast away her prized looking glass. It remains lost somewhere in Duskwood's haunted reaches.",al={"mary mirror","blind mary looking glass","what happened to her mirror"},it="item"},{q="Why do adventurers seek out Blind Mary?",a="Travelers and local artisans visit Mary while carrying out work around Darkshire. Some seek her old looking glass for Viktori Prism'Antras's star-gazing device; others bring Madame Eva's spectral comb to gather ghost hair for special thread.",al={"blind mary quests","why visit blind mary","blind mary questline"},it="purpose"},{q="Whose side is Blind Mary on?",a="Blind Mary belongs to no army or faction. Though she is a banshee risen from Duskwood's tragedy, she does not march with the Scourge or wage war upon the living. Trapped in her solitary torment, she remains neutral to wandering adventurers, dealing with anyone willing to listen to her sorrow or return tokens of her past life.",al={"is blind mary alliance or horde","blind mary faction","whose side is mary on"},it="side",add="d3776a58"},{q="What does Blind Mary want?",a="Mary longs for the beauty she lost and cannot bear to be seen. She once carried a looking glass everywhere and still speaks of it to those who ask, but when someone brings her a comb, it only reminds her of what she has become, and she sends it away.",al={"what does mary want","what does blind mary seek","blind mary desires"},it="wants",add="45d21972"},{q="Why is Blind Mary here?",a="Blind Mary haunts an abandoned farmhouse just southeast of Darkshire because it is where she met her tragic end. Slain by the roaming undead that overrun Duskwood, she arose as a weeping banshee, bound by grief and madness to the ruins of her former home.",al={"why is blind mary in duskwood","why does blind mary haunt the farmhouse","blind mary location story"},it="why_here",add="5b1d02ea"}},ang={["profession:Tailoring"]="As a tailor, you may seek spectral beings like Mary for ghost hair thread, a delicate material woven from ethereal remnants.",["class:Priest"]="As a priest, you can see a soul left untethered by horrific trauma in Mary, caught between life and damnation through grief and vanity.",["faction:Alliance"]="As an Alliance defender, you can see in Mary's fate how deeply Duskwood's curse has devastated its everyday townsfolk."},kw={"banshee","blind mary","darkshire","duskwood","ghost hair","haunt","looking glass","wraith"},rel={"subzone:darkshire","zone:duskwood","quest:149","quest:154","quest:174"},src={"Blind Mary"}}
E["npc:calor"] = {t="npc",n="Calor",z="duskwood",s="In Darkshire, Calor directs the fight against worgen stalking Duskwood. Under Jonathan Carevin, he helps the Carevin family hunt the beasts threatening the forests.",h="In Darkshire, Calor directs the fight against worgen stalking Duskwood.",sec={{t="A Loyalist in the Shadows",b="In Darkshire, Calor helps the Carevin family fight the horrors closing in on town. He works under Jonathan Carevin, one of Darkshire's defenders. Together they seek to destroy the supernatural threats before the remaining townsfolk are slaughtered.",sp=0},{t="The Worgen Menace",b="Calor sends fighters after the worgen prowling Duskwood, especially near the Rotting Orchard. These wolf-men are more dangerous than common beasts. They slaughter travelers and patrols alike. So Calor calls on capable fighters to thin their ranks and investigate where they came from, hoping to stem their attacks.",sp=0}},faq={{q="Who is Calor?",a="Calor lives in Darkshire and supports the Carevin family. He helps defend the town by sending fighters after dangerous threats in Duskwood.",al={"calor darkshire","who is calor","calor duskwood"},it="identity"},{q="Where can Calor be found?",a="Calor can be found in Darkshire, the Alliance town in the forests of Duskwood.",al={"where is calor","calor location","calor coordinates"},gp=true},{q="What is Calor's relationship with Jonathan Carevin?",a="Calor supports the Carevin family and follows Jonathan Carevin's direction in the fight against monsters in the forest.",al={"calor and carevin","who does calor work for","carevin family calor"},it="ties"},{q="What enemies does Calor have you fight?",a="Calor sends fighters to hunt worgen in the woods, especially near the Rotting Orchard.",al={"calor quests","what does calor want","worgen quests calor"},it="target",gp=true},{q="Why is the worgen threat so urgent in Duskwood?",a="The worgen are vicious predators that attack anything on sight. Without regular culls, they could overrun Darkshire's thin defenses. Calor coordinates the effort alongside the Night Watch.",al={"why kill worgen duskwood","duskwood worgen threat"},it="threat"},{q="Is Calor a member of the Night Watch?",a="No. Calor grew disillusioned with what he saw as the Night Watch's complacency. He joined Jonathan Carevin and supports the Carevin family's fight against worgen.",al={"calor night watch","is calor in night watch"},it="side"},{q="What does Calor want?",a="Calor is determined to eradicate the worgen infesting Duskwood. Working directly on the orders of Jonathan Carevin, he enlists capable adventurers to hunt down the feral beasts lurking in places like the Rotting Orchard and stem the spread of their shadowy corruption before it overwhelms Darkshire.",al={"calor goal","what is calor doing","what does calor want"},it="wants",add="e997a1f9"},{q="Why is Calor in Darkshire?",a="Calor remains stationed in Darkshire to assist the Carevin family in their crusade against the beasts of the woods. From this beleaguered town, he coordinates scouting and hunting efforts against the savage worgen packs that stalk the surrounding groves and abandoned orchards.",al={"why is calor here","calor darkshire why","why is calor in duskwood"},it="why_here",add="f0ff266f"}},ang={["faction:Alliance"]="As an Alliance champion, you can help Calor defend Darkshire's isolated townsfolk in the gloomy woods.",["class:Hunter"]="As a hunter, you can work with Calor to track and cull savage beasts that threaten the forest's natural order."},kw={"calor","carevin","darkshire","duskwood","jonathan carevin","night watch","rotting orchard","worgen"},rel={"npc:jonathan-carevin","quest:173","subzone:darkshire","zone:duskwood","topic:worgen","subzone:rotting-orchard","quest:1042"},src={"Calor"}}
E["npc:chef-grual"] = {t="npc",n="Chef Grual",z="duskwood",s="In Darkshire, Chef Grual keeps the Scarlet Raven Tavern's kitchen working. He feeds the Night Watch and weary travelers, though some ingredients raise eyebrows.",h="In Darkshire, Chef Grual keeps the Scarlet Raven Tavern's kitchen working.",sec={{t="Cooking Under Siege",b="Darkshire's cook works with scarce supplies. Highwaymen, wolves, and undead trouble the roads from Westfall and Stormwind, so fresh provisions are hard to find. Grual makes do with what the wilderness offers. He cooks wolf flank and meat scavenged by local adventurers, using whatever reaches his kitchen.",sp=0},{t="Secret Ingredients",b="Chef Grual is known for Dusky Crab Cakes and seasoned wolf kabobs. Duskwood lies far from the coast, so he makes his crab cakes with gooey legs from the local Venom Web Spiders. Whether patrons know what they are eating or prefer not to ask, Grual keeps the kitchen working without apology.",sp=1,bt={"q5.2"}}},faq={{q="Who is Chef Grual?",a="Chef Grual cooks at the Scarlet Raven Tavern in Darkshire. He prepares meals for the town's defenders, travelers, and refugees hiding from Duskwood's dangers.",al={"chef grual","grual darkshire","darkshire cook"},it="identity"},{q="Where can I find Chef Grual?",a="Chef Grual works in the back room and kitchen of the Scarlet Raven Tavern in central Darkshire, along the southern edge of the main road.",al={"grual location","where is chef grual","find chef grual"},it="place",gp=true},{q="What are Dusky Crab Cakes actually made of?",a="Dusky Crab Cakes contain gooey legs from the Venom Web Spiders infesting the surrounding forests. Grual minces them into patties that mimic seafood.",al={"crab cake ingredients","spider crab cakes","what is in dusky crab cakes"},sp=1,it="item",bt={"q5.2"}},{q="What quests does Chef Grual offer?",a="Chef Grual asks travelers to gather wolf flanks for his seasoned wolf kabobs and spider legs for his Dusky Crab Cakes. He also cooks Dusky Crab Cakes for Jitters, a starving man hiding in Duskwood.",al={"grual quests","chef grual recipes"},sp=1,gp=true,bt={"q5.2"}},{q="Why does he feed Jitters?",a="Jitters has hidden in a Duskwood ghost town for weeks, living on grubs and weeds. Starving for decent food, he sends travelers to Grual for Dusky Crab Cakes.",al={"jitters food","jitters growling gut grual"},it="motive"},{q="Is Grual affiliated with the Night Watch?",a="Chef Grual is a civilian cook, not a guardsman. His kitchen feeds the Night Watch and local militia as they face constant siege.",al={"grual night watch","does grual fight"},it="ties"},{q="Whose side is Chef Grual on?",a="Chef Grual stands firmly with the people of Darkshire and the Alliance. While the town remains isolated and plagued by shadows, Grual keeps the hearth burning at the Scarlet Raven Tavern, preparing meals for local residents, weary travelers, and the town's defenders.",al={"chef grual faction","who does chef grual serve","chef grual alliance"},it="side",add="ccc14f35"},{q="What does Chef Grual want?",a="Grual wants to keep the Scarlet Raven Tavern well-provisioned despite Duskwood's perilous state. With trade routes severed and fresh livestock scarce, he relies on adventurous travelers to gather unorthodox local ingredients—like wolf meat and gooey spider legs—to feed the town's hungry patrons.",al={"what does chef grual need","chef grual ingredients","chef grual goal"},it="wants",add="3ac222da"},{q="Why is Chef Grual here?",a="Grual is the resident cook of Darkshire, working out of the Scarlet Raven Tavern. While many have fled Duskwood's creeping darkness, Grual stays to run the kitchen, doing his part to support the survival of the isolated settlement.",al={"why is chef grual in duskwood","why does grual stay in darkshire","chef grual role"},it="why_here",add="91c4d31a"}},ang={["profession:Cooking"]="Grual shows how a cook in an isolated region makes use of local wildlife, whether it walks or skitters through the trees.",["faction:Alliance"]="At the Scarlet Raven Tavern in Darkshire, Grual keeps Alliance defenders fed despite the shortage of regular supply caravans from Stormwind.",["race:Human"]="Like many of Darkshire's remaining residents, Grual endures the horrors of the shadowed woods with grim, stubborn resilience and practical skill."},kw={"chef grual","crab cakes","darkshire","duskwood","grual","jitters","scarlet raven tavern","wolf kabobs"},rel={"subzone:scarlet-raven-tavern","subzone:darkshire","zone:duskwood","quest:93","quest:90","npc:jitters","quest:5","quest:240"},src={"Chef Grual"}}
E["npc:clerk-daltry"] = {t="npc",n="Clerk Daltry",z="duskwood",s="In Darkshire Town Hall, Clerk Daltry keeps the village’s records and searches its past with them. Ledgers and registry books fill his care, though the archives have fallen behind and are often neglected.",h="In Darkshire Town Hall, Clerk Daltry keeps the village’s records and searches its past with them.",sec={{t="Town Record Keeper",b="Clerk Daltry keeps Darkshire’s records as beasts, undead horrors, and supernatural gloom press against the town. He works in Darkshire Town Hall with Lord Ello Ebonlocke and the local council. His ledgers hold the town’s history, property rolls, and census data. After disaster broke the region apart, these records remain among the few links to the days before Grand Hamlet fell into shadow.",sp=0},{t="The Paper Trail",b="Since Darkshire was cut off from regular Stormwind administration, Clerk Daltry’s records have suffered. Documents go missing, ledgers fall behind, and town files are often misplaced or damaged. Those investigating old cases or searching for residents come to him for help. Answers may lie in overlooked notes, or in papers lost in the woods.",sp=0},{t="The Legend of Stalvan",b="Clerk Daltry searches Darkshire’s archives when investigators follow the family legend of Stalvan Mistmantle. His registry entries on the former schoolteacher are fragmented, so he sends seekers across town and to forgotten homesteads across the kingdom. They must piece together the tragic and bloody truth.",sp=1}},faq={{q="Where is Clerk Daltry located?",a="Clerk Daltry works inside Darkshire Town Hall, in the central village of Darkshire in Duskwood. He keeps municipal records among the town officials and council members.",al={"clerk daltry location","where is daltry","darkshire clerk location"},it="place",gp=true},{q="What is Clerk Daltry's job in Darkshire?",a="Clerk Daltry keeps Darkshire’s documents, town rolls, and legal registries. He helps people seeking records about former residents, land claims, or the town’s history.",al={"what does daltry do","daltry role","who is clerk daltry"},it="purpose"},{q="Why are his records incomplete?",a="Clerk Daltry’s records are incomplete because Duskwood has endured years of isolation, magical corruption, and violent turmoil. With the Night Watch’s enemies threatening survival, keeping the ledgers current has often fallen behind.",al={"why are daltry's records bad","outdated records duskwood","missing ledgers daltry"}},{q="What questlines does Clerk Daltry start or participate in?",a="Clerk Daltry helps investigators follow the story of Stalvan Mistmantle and track down his past. He also assists with investigations such as ‘The Carevin Family’ and ‘The Shadowy Search Continues’.",al={"daltry quests","what quests from daltry","clerk daltry quest chain"},gp=true},{q="Who sends investigators to Clerk Daltry?",a="Madame Eva sends those following the Stalvan mystery to Clerk Daltry at the Town Hall. Travelers seeking Velinde Starsong have also been directed to him. When his records run dry, Daltry sends seekers elsewhere, such as to the inn to ask about a stranger.",al={"who sends people to daltry","daltry contacts"},it="ties"},{q="Can Horde players speak with Clerk Daltry?",a="No. Clerk Daltry serves the Alliance, and the Night Watch guards Darkshire and its town hall against Horde adventurers.",al={"is daltry friendly to horde","can horde talk to daltry"},it="side",gp=true},{q="Who is Clerk Daltry?",a="Clerk Daltry is a human bureaucrat stationed within the Darkshire Town Hall in Duskwood. He is tasked with keeping civic records, census information, and family histories for the town's citizens, serving as a resident archivist for an isolated settlement plagued by shadows and forgotten pasts.",al={"who is daltry","who is clerk daltry","clerk daltry darkshire"},it="identity",add="063859f4"},{q="Whose side is Clerk Daltry on?",a="Daltry stands firmly with the Alliance and the township of Darkshire. As an official of the town hall, he serves the local civil authority and works to assist travelers and investigators who are helping to unravel the town's troubles or locate missing persons.",al={"is daltry alliance","daltry faction","clerk daltry allegiance"},it="side",add="7e4b683b"},{q="What does Clerk Daltry want?",a="Clerk Daltry seeks to maintain orderly records and assist investigators looking into the dark mysteries surrounding Duskwood. He frequently aids travelers in searching through town logs, family registries, and old documents to trace lost citizens like Stalvan Mistmantle, though his archives are far from complete.",al={"what does daltry want","clerk daltry goal","daltry motive"},it="wants",add="3b37b748"},{q="Why is Clerk Daltry here?",a="Daltry remains in Darkshire to fulfill his municipal duties inside the Town Hall. Despite the darkening forests and constant perils encroaching on the settlement, the township still relies on a civic clerk to preserve deeds, letters, and the identities of those who dwell in the region.",al={"why is daltry in darkshire","why is clerk daltry here","daltry town hall reason"},it="why_here",add="7e737b61"}},ang={["faction:Alliance"]="As an Alliance investigator, you can turn to Clerk Daltry for long-lost records and old cases amid Duskwood’s sinister mysteries.",["race:Human"]="As a human, you can look to Daltry to preserve the history that remains of Grand Hamlet from before darkness fell over the woodland."},kw={"carevin","clerk daltry","darkshire","duskwood","ledgers","mistmantle","records","stalvan","town hall"},rel={"subzone:darkshire-town-hall","subzone:darkshire","zone:duskwood","quest:66","quest:265","quest:266","quest:1042","subzone:roland-s-doom"},src={"Clerk Daltry"}}
E["npc:glorin-steelbrow"] = {t="npc",n="Glorin Steelbrow",z="duskwood",s="At the Deepwater Tavern in Menethil Harbor, Glorin Steelbrow aids Bishop Farthing from afar. He directs travelers to sacred relics and metals lost with the Third Fleet, joining Duskwood’s troubles to the wrecks off the Wetlands coast.",h="At the Deepwater Tavern in Menethil Harbor, Glorin Steelbrow aids Bishop Farthing from afar.",sec={{t="A Harbor Connection",b="Bishop Farthing works from Stormwind’s Cathedral of Light, aiding the people of Duskwood against its creeping terrors. In Menethil Harbor, Glorin Steelbrow keeps the bishop’s ties to the north from inside the Deepwater Tavern. He offers travelers direction as they seek sacred metals and forgotten relics. Through Glorin, the troubled forest in the south is linked to the sunken wreckage off the Wetlands coast.",sp=0},{t="The Doomed Fleet and Lost Relics",b="Glorin Steelbrow knows the Third Fleet’s fate. Its ships were battered and dragged beneath the waves along the Wetlands shore. He guides travelers through the haunted wreckage to seek lost ingots of Lightforge iron and the powerful, cursed artifact called the Eye of Paleth. Glorin knows these holy arms are vital to forging weapons that can hold back the dark forces threatening the Alliance.",sp=1,bt={"q288.4"}}},faq={{q="Who is Glorin Steelbrow?",a="Glorin Steelbrow is a dwarf who works in the Deepwater Tavern in Menethil Harbor. He coordinates with Bishop Farthing of Stormwind and directs travelers searching for sunken cargo and relics off the Wetlands coast.",al={"who is glorin","glorin steelbrow lore","what does glorin do"},it="identity"},{q="Where can I find Glorin Steelbrow?",a="You can find Glorin on the ground floor of the Deepwater Tavern in Menethil Harbor, on the western coast of the Wetlands.",al={"glorin location","where is glorin steelbrow","glorin deepwater tavern"},it="place",gp=true},{q="Why is a dwarf in Menethil Harbor involved with Duskwood?",a="Bishop Farthing of Stormwind’s Cathedral of Light seeks powerful holy relics and consecrated metals to fight the darkness encroaching on Duskwood. He sends trusted emissaries to Glorin Steelbrow, who knows the Wetlands coast and directs salvagers to the sunken remains of the Third Fleet.",al={"why duskwood quest in wetlands","connection to farthing","why send to wetlands"},it="why_here"},{q="What is the Third Fleet that Glorin talks about?",a="The Third Fleet was an Alliance naval expedition that met catastrophe off the Wetlands coast. Its shattered hulls lie across the seabed, haunted by drowned sailors and hiding valuable cargo, including Lightforge iron and ancient artifacts.",al={"what is the doomed fleet","third fleet wetlands","the doomed fleet quest"},it="history"},{q="What is the Eye of Paleth?",a="The Eye of Paleth is an ancient religious relic carried aboard the sunken fleet. With Glorin’s guidance, you can recover it from the ocean floor, then the priesthood must cleanse the dark corruption lingering around the shipwreck.",al={"eye of paleth","paleth relic","what is eye of paleth"},sp=1,it="item",bt={"q288.4"}},{q="What is Lightforge iron used for?",a="Lightforge iron is a rare, sanctified metal used to craft blessed weapons that can strike down powerful undead and demonic forces. Glorin helps recover ingots lost in the shipwrecks for Duskwood’s defenders.",al={"lightforge iron","lost ingots","blessed arm"},it="purpose"},{q="Whose side is Glorin Steelbrow on?",a="Glorin stands firmly with the Alliance and the Church of the Holy Light. Stationed in Menethil Harbor, he works in coordination with leaders like Bishop Farthing of Stormwind, seeking aid from trustworthy Alliance adventurers to recover lost sanctified relics and materials lost along the treacherous coastlines.",al={"glorin steelbrow faction","who does glorin steelbrow serve","glorin steelbrow alliance"},it="side",add="65727266"},{q="What does Glorin Steelbrow want?",a="Glorin wants to recover lost sacred cargo claimed by the sea, particularly shipments carried by the sunken Third Fleet. His efforts center on enlisting adventurers to retrieve rare Lightforge iron ingots and sacred relics such as the Eye of Paleth, ensuring they are cleansed and restored to the Church.",al={"what does glorin steelbrow need","glorin steelbrow goal","what is glorin steelbrow looking for"},it="wants",add="cbae8fd4"},{q="Who is Glorin Steelbrow tied to?",a="Glorin is an associate of Bishop Farthing of Stormwind's Cathedral of Light. He coordinates directly with the clergy of Stormwind to secure lost holy relics, acting as their liaison in the Wetlands harbor to salvage shipments bound for or lost from the church's efforts.",al={"glorin steelbrow connections","who does glorin steelbrow know","glorin steelbrow bishop farthing"},it="ties",add="72c86ba2"}},ang={["race:Dwarf"]="As a dwarf, you can see Glorin’s enterprise and solidarity at work from Menethil Harbor, supporting allies across Khaz Modan and the southern human kingdoms.",["class:Paladin"]="As a paladin following Farthing’s orders, you can rely on Glorin to help recover Lightforge iron, a sacred metal used to craft weapons blessed by the Holy Light.",["faction:Alliance"]="As an Alliance member, you can help recover military relics and sanctified materials lost in naval disasters off the Wetlands coast."},kw={"bishop farthing","deepwater tavern","doomed fleet","duskwood","eye of paleth","glorin steelbrow","lightforge iron","menethil harbor","wetlands"},rel={"npc:farthing","quest:270","quest:321","quest:324","quest:292","subzone:deepwater-tavern","subzone:menethil-harbor","zone:wetlands"},src={"Glorin Steelbrow"}}
E["npc:jitters"] = {t="npc",n="Jitters",z="duskwood",s="In western Duskwood, Jitters shelters alone among Raven Hill's ruins. He depends on travelers for food and watches the shadows for danger.",h="In western Duskwood, Jitters shelters alone among Raven Hill's ruins.",sec={{t="A Haunted Hermit",b="At Raven Hill, Jitters fears the predators along Duskwood's western trails. He depends on travelers for food and keeps watch for danger. Long ago, his habit of flinching and leaping clear of sudden threats earned him his name. The fear comes from horrors he faced himself.",sp=0},{t="The Awakening at Roland's Doom",b="Jitters once belonged to the Defias Brotherhood, who came into Duskwood. While digging at Roland's Doom, he found the Scythe of Elune jutting from the rock. The artifact brought fierce, bloodthirsty worgen into the woods. Jitters watched his comrades die beneath their claws and barely escaped alive.",sp=1},{t="Flight and the Farmstead",b="After fleeing the mine, Jitters went to Darkshire. He bought a blank tome from Clerk Daltry and wrote down the nightmare while hiding in the Scarlet Raven Tavern. Panicked, he took shelter in a barn at the Yorgen Farmstead. There, black-cloaked Dark Riders killed Sven Yorgen's family as they searched for the Scythe. Afraid of blame and discovery, Jitters buried pages of his journal in the soil, then fled to Raven Hill with guilt and dread close behind.",sp=1}},faq={{q="Who is Jitters?",a="Jitters is a frightened human who lives among Raven Hill's ruins. He is hungry, alone, and haunted by what he has experienced in Duskwood.",al={"who is this guy","jitters lore","jitters background"},sp=1,it="identity"},{q="Why is he called Jitters?",a="Jitters earned his name from wary habits: he flinched from blows and leapt clear of sudden pitfalls. His isolation and fear in Duskwood have made him more nervous.",al={"why jitters","where did his name come from","jitters name origin"},it="name"},{q="What danger do the worgen pose in Duskwood?",a="Worgen stalk Duskwood's woods and roads. They threaten travelers and isolated settlements.",al={"worgen threat duskwood","beasts near jitters","duskwood worgen danger"},sp=1,it="origin"},{q="What happened to Sven Yorgen's family?",a="Sven Yorgen's family was murdered at their farmstead. He is determined to discover who was responsible.",al={"sven farm massacre","who killed sven family","yorgen farmstead murder"},sp=1,it="history"},{q="How can Jitters help Sven Yorgen's investigation?",a="Jitters' journal records his experiences in Duskwood and may help Sven investigate what happened to his family.",al={"jitters and sven investigation","how can jitters help sven","jitters account of duskwood"},sp=1,it="conflict"},{q="What is Jitters' journal?",a="Jitters' journal records his experiences in Duskwood. It is part of the investigation into Raven Hill and Sven Yorgen's family.",al={"jitters diary","jitters completed journal","daltry book"},sp=1,it="item"},{q="Whose side is Jitters on?",a="Jitters is a frightened, hungry survivor hiding at Raven Hill, whose troubling experiences have left him isolated and deeply shaken.",al={"jitters faction","is jitters evil","who does jitters work for","jitters loyalty"},sp=1,it="side",add="9934be9b"},{q="What does Jitters want?",a="Jitters wants food and safety. His hunger brings him into contact with adventurers investigating the troubles around Raven Hill.",al={"what does jitters need","jitters motive","why does jitters send you"},sp=1,it="wants",add="3395ed32"},{q="Why is Jitters here in Raven Hill?",a="Raven Hill offers Jitters a hiding place among Duskwood's abandoned buildings, though it gives him little comfort or protection.",al={"why is jitters in raven hill","how did jitters end up here","why does jitters hide here"},sp=1,it="why_here",add="af0d9be3"},{q="Who is Jitters tied to?",a="His story intersects with Sven Yorgen's investigation and the accounts preserved in his journal.",al={"jitters connections","who is jitters affiliated with","jitters defias"},sp=1,it="ties",add="b49992e9"}},ang={["faction:Alliance"]="Jitters shows the human cost of Duskwood's troubles. He lives in fear while the Night Watch struggles to protect its people.",["class:Rogue"]="As a rogue, you can recognize Jitters' quick instincts for avoiding danger. They have not spared him from fear and isolation in Duskwood."},kw={"clerk daltry","dark riders","duskwood","jitters","raven hill","roland's doom","scythe of elune","sven yorgen","worgen"},rel={"npc:sven-yorgen","subzone:roland-s-doom","subzone:yorgen-farmstead","topic:worgen","topic:dark-riders","topic:elune","quest:5","quest:163"},src={"Jitters"}}
E["npc:jonathan-carevin"] = {t="npc",n="Jonathan Carevin",z="duskwood",s="In Darkshire, Jonathan Carevin leads his family against the dangers gathering in Duskwood. They hunt undead, worgen, demons, and heretics beyond the Night Watch's patrols.",h="In Darkshire, Jonathan Carevin leads his family against the dangers gathering in Duskwood.",sec={{t="The Carevin Crusade",b="The Night Watch guards Darkshire and patrols its roads. Jonathan Carevin believes defense alone cannot keep the township safe. So he hunts the unholy creatures roaming Duskwood with his family and allies such as Calor. In the name of the Light, they pursue demons, undead, and heretics across the region.",sp=0},{t="The Shadow of the Worgen",b="Jonathan Carevin watches the forest's savage, wolf-like worgen as closely as its skeletons and ghouls. The worgen threaten a settlement already under siege. Jonathan coordinates investigations to learn where they came from and to stop their nightly prowling.",sp=1}},faq={{q="Who is Jonathan Carevin?",a="Jonathan Carevin hunts monsters in Duskwood from his home in Darkshire. He leads his family in a direct fight against the creatures haunting the forest.",al={"who is carevin","jonathan carevin lore","carevin darkshire"},it="identity"},{q="How does he differ from the Night Watch?",a="The Night Watch guards Darkshire and watches its roads. Jonathan and his allies pursue undead and other abominations through Duskwood, seeking to destroy them at their source.",al={"is he night watch","carevin vs night watch"},it="conflict"},{q="What threats does he fight?",a="Jonathan hunts undead, worgen, demons, and anyone who shelters or aids these creatures.",al={"what does carevin hunt","carevin targets"},it="threat"},{q="Is Jonathan affiliated with the Scarlet Crusade?",a="Jonathan's fierce words, devotion to the Light, and intolerance of corruption echo Scarlet beliefs. He operates independently with his family in Darkshire.",al={"carevin scarlet crusade","is carevin scarlet"},it="side"},{q="Who assists Jonathan in his mission?",a="Jonathan's family and allies such as Calor help him hunt the monsters moving through the woods.",al={"carevin allies","who helps carevin"},it="allies"},{q="What is his connection to the worgen?",a="Jonathan sees the worgen as an unnatural threat to Duskwood's people. He asks travelers to investigate where they came from in the wilderness.",al={"carevin worgen","why carevin hate worgen"}},{q="What does Jonathan Carevin want?",a="Jonathan Carevin seeks nothing less than the complete eradication of evil, heresy, and the undead plaguing Duskwood. Unlike the local Night Watch, which focuses on keeping Darkshire safe behind defensive lines, Jonathan believes in taking the offensive. He wants to actively hunt down demonic and undead forces, purging the region of corruption under the righteous power of the Light.",al={"jonathan carevin goals","what is carevins goal","carevin mission"},it="wants",add="8aa9d9d7"},{q="Why is Jonathan Carevin in Darkshire?",a="Darkshire is the frontline of a shadow-drenched land overrun with ghouls, skeletons, and darker horrors. Jonathan Carevin and his family have made it their personal crusade to stand their ground here, coordinating attacks against the undead and rallying any capable adventurers willing to take up arms against the terrors lurking beneath Duskwood's darkened boughs.",al={"why is carevin in darkshire","why is jonathan carevin here","carevin duskwood reason"},it="why_here",add="24497d50"}},ang={["faction:Alliance"]="If you fight for the Alliance to steady Duskwood, Jonathan Carevin strikes at supernatural threats Stormwind has left unchecked.",["class:Paladin"]="As a paladin, you may recognize Carevin's zeal and his call on the Light against demonic and undead corruption.",["class:Hunter"]="As a hunter, you share Carevin's practice of tracking and hunting Duskwood's night predators."},kw={"calor","carevin family","darkshire","duskwood","jonathan carevin","night watch","undead","worgen"},rel={"quest:1042","subzone:darkshire","zone:duskwood","npc:calor","quest:173","quest:1043","topic:night-watch","topic:worgen"},src={"Jonathan Carevin"}}
E["npc:lars"] = {t="npc",n="Lars",z="duskwood",s="At a small camp on the northern edge of the Hushed Bank, Lars and Sven Yorgen struggle to survive Duskwood. Beasts, undead, and worgen roam the surrounding woods.",h="At a small camp on the northern edge of the Hushed Bank, Lars and Sven Yorgen struggle to survive Duskwood.",sec={{t="A Precarious Perch",b="Lars keeps to a small camp on the northern edge of the Hushed Bank, far from the uncertain safety of Darkshire. Duskwood is dangerous, with ferocious beasts, undead, and worgen in the woods. He stays close to Sven Yorgen and tries to endure the forest.",sp=0},{t="Threat from the Wilds",b="Starving dire wolves prowl near Lars and Sven's camp. Lars cannot keep watch or drive them off alone, so he relies on travelers to thin their packs before the predators overrun the camp.",sp=0}},faq={{q="Who is Lars?",a="Lars is a human survivor who camps in Duskwood with his companion Sven Yorgen. Together they endure the forest's dangers on the northern edge of the Hushed Bank.",al={"lars duskwood","who is lars","lars npc"},it="identity"},{q="Where can Lars be found?",a="Lars stays at a small camp on the northern edge of the Hushed Bank in western Duskwood.",al={"where is lars","lars location","lars camp"},it="place",gp=true},{q="What problem does Lars face?",a="Hungry dire wolves and other predators threaten Lars and Sven's camp. Lars asks passing travelers to hunt the wolves before they overrun it.",al={"lars quest","wolves at our heels quest","why does lars need help"},it="wants"},{q="What is Lars's relationship to Sven Yorgen?",a="Lars and Sven Yorgen are companions surviving together in the wilderness. Sven has a dark history and a vendetta in the region, while Lars helps keep their isolated camp going.",al={"lars and sven","who is sven to lars"},it="ties"},{q="Whose side is Lars on?",a="Lars is an independent human survivor allied with the Alliance. Rather than serving the Night Watch or Stormwind's military directly, he is simply an ordinary man trying to endure the perils of Duskwood alongside his companion, Sven Yorgen.",al={"lars faction","is lars alliance","who does lars serve"},it="side",add="05f5e77d"},{q="Why is Lars camped in Duskwood?",a="Lars has taken refuge at a rugged camp along the northern edge of the Hushed Bank. He stays there trying to survive the dark forest day by day in the company of Sven Yorgen, holding out against the encroaching predators and horrors of the woods.",al={"why is lars here","lars duskwood reason","why did lars come here"},it="why_here",add="2eb2df94"}},ang={["faction:Alliance"]="As a champion of the Alliance, you can help Lars, a human civilian beyond the town guard's reach, by driving off the wolves circling his camp."},kw={"camp","duskwood","hushed bank","lars","sven yorgen","wolves","wolves at our heels"},rel={"npc:sven-yorgen","subzone:hushed-bank","zone:duskwood","quest:226","topic:worgen"},src={"Lars"}}
E["npc:lord-ello-ebonlocke"] = {t="npc",n="Lord Ello Ebonlocke",z="duskwood",s="At Darkshire's Town Hall, Lord Ello Ebonlocke works to keep order as danger grows. Stormwind gives little aid, and horrors press in from the surrounding woods.",h="At Darkshire's Town Hall, Lord Ello Ebonlocke works to keep order as danger grows.",sec={{t="A Beleaguered Mayor",b="Lord Ello Ebonlocke governs Darkshire from the Town Hall as danger closes around the settlement. Darkshire was once part of the prosperous rural haven called Grand Hamlet. Now perpetual shadow hangs over it, while ravenous ghouls, skeletal abominations, and feral beasts press against its borders. Ello leads the Council of Darkshire and struggles to keep the remnants of civic life working. Stormwind offers little help as the town fights to endure.",sp=0},{t="A Divided Frontier",b="Darkshire depends on local volunteer militias like the Night Watch because Stormwind's garrison will not spare soldiers for the borderlands. His relative, Althea Ebonlocke, commands the Night Watch. Magistrate Solomon of Lakeshire asks for reinforcements against Blackrock orcs, but Lord Ebonlocke cannot spare a single blade. He explains to messengers from Redridge that sending guards beyond the forest's edge would leave Darkshire's homes open to the surrounding evils.",sp=0},{t="Blind to the Hermit's Designs",b="Lord Ello Ebonlocke relies on wandering adventurers to handle unusual matters around the woods. In his wish to help Duskwood's residents, he coordinates communications with solitary figures such as the hermit Abercrombie. Ello cannot understand the hermit's cryptic writings, and fails to see the grisly, stitched nightmare growing just beyond town until nearly too late.",sp=1}},faq={{q="Who is Lord Ello Ebonlocke?",a="Lord Ello Ebonlocke governs Darkshire and leads the Council of Darkshire. From the Town Hall, he oversees the town's defense and civic affairs as its human residents struggle to survive.",al={"who is ello","mayor of darkshire","ello ebonlocke lore"},it="identity"},{q="How is he related to Commander Althea Ebonlocke?",a="Commander Althea Ebonlocke is Lord Ello's relative and leads the Night Watch. He handles Darkshire's civic and diplomatic affairs while she commands the militia guarding the settlement.",al={"althea ebonlocke relation","is althea ello's daughter"},it="ties"},{q="Why does Lord Ebonlocke refuse to send troops to Lakeshire?",a="Lord Ebonlocke refuses Magistrate Solomon's request for aid against the Blackrock orcs in Redridge. Darkshire faces undead and other horrors, and sending its guards away would leave the town open to being overrun.",al={"why no help for redridge","messenger to darkshire","magistrate solomon ello ebonlocke"}},{q="Where can Lord Ello Ebonlocke be found?",a="Lord Ello Ebonlocke can be found inside the Darkshire Town Hall, at the center of Darkshire in eastern Duskwood.",al={"ello ebonlocke location","where is mayor ebonlocke"},it="why_here",gp=true},{q="Why doesn't Stormwind send troops to help Lord Ebonlocke?",a="Stormwind's resources are strained by internal political strife after King Varian Wrynn's disappearance. The House of Nobles has largely abandoned the southern regions, leaving local leaders like Lord Ebonlocke to organize their own defenses.",al={"why won't stormwind help duskwood","stormwind neglect"}},{q="What is Lord Ebonlocke's involvement with Abercrombie?",a="Lord Ebonlocke helps handle communications with the hermit Abercrombie and arranges translations of his strange notes.",al={"ello abercrombie note","translate abercrombie's note"},sp=1},{q="Whose side is Lord Ello Ebonlocke on?",a="Lord Ello Ebonlocke is loyal to the Grand Alliance and serves as the mayor of Darkshire, leading its council. Though sworn to the kingdom of Stormwind, he must prioritize the survival of his own terrified citizens over broader regional calls for aid.",al={"lord ebonlocke faction","who does ello ebonlocke serve","is ebonlocke alliance"},it="side",add="0007fc63"},{q="What does Lord Ello Ebonlocke want?",a="Mayor Ebonlocke wants above all to keep the beleaguered town of Darkshire from falling to the encroaching darkness. Abandoned by the crown, his sole focus is preserving his people and keeping the local Night Watch manned against the surrounding horrors.",al={"what does lord ello want","ebonlocke goal","ello ebonlocke purpose"},it="wants",add="48b49947"},{q="Why is Lord Ello Ebonlocke in Darkshire?",a="Lord Ebonlocke presides over Darkshire from within the Town Hall because he is the head of the Council of Darkshire. As the civic leader of Duskwood's last surviving bastion of civilization, he oversees local defense and government from the heart of the settlement.",al={"why is lord ebonlocke in duskwood","why is ebonlocke at darkshire","ello ebonlocke location why"},it="why_here",add="26db90ba"}},ang={["faction:Alliance"]="As an Alliance traveler, you see how isolated mayors on its forgotten edges lead their people through nightmare conditions with little aid from Stormwind.",["race:Human"]="As a human traveling from Stormwind, you find in Lord Ebonlocke a sobering reminder of how far the southern provinces have fallen into ruin and abandonment."},kw={"abercrombie","althea","council","darkshire","duskwood","ebonlocke","ello","lakeshire","mayor"},rel={"subzone:darkshire-town-hall","subzone:darkshire","zone:duskwood","npc:althea-ebonlocke","topic:night-watch","quest:145","npc:magistrate-solomon","npc:abercrombie"},src={"Lord Ello Ebonlocke"}}
E["npc:madame-eva"] = {t="npc",n="Madame Eva",z="duskwood",s="In Darkshire, Madame Eva reads the cards for those troubled by Duskwood’s dark mysteries. She practices ancient divination and cartomancy, and is often the first in town to sense unnatural disturbances. Townspeople and travelers seek her help and the occult charms she makes against the creeping dark.",h="In Darkshire, Madame Eva reads the cards for those troubled by Duskwood’s dark mysteries.",sec={{t="The Fortune-Teller of Darkshire",b="Madame Eva reads cards and keeps ancient folk rituals in Darkshire. Many in Stormwind’s cathedral would look on her ways with suspicion. Yet Duskwood is troubled by feral beasts, the undead, and darker horrors. Desperate townspeople and visiting adventurers come to her for eerie insight.",sp=0},{t="Ties of Blood and Prophecy",b="Madame Eva is devoted to her family, including her granddaughter Alyssa Eva and young Lohgan. When her cards warn of dark omens threatening Alyssa, Eva calls on passing wanderers to search the woods. They must uncover long-buried tragedies before history can repeat itself.",sp=0},{t="Weaving Protection Against the Night",b="Madame Eva’s knowledge reaches beyond cards to ritual craft and warding. She spins Ghost Hair Thread from a spirit’s hair and makes folk relics such as the Totem of Infliction. Few in town understand the strange twilight logic of Duskwood’s restless spirits as well as Eva does.",sp=0}},faq={{q="Who is Madame Eva?",a="Madame Eva is an elderly human fortune-teller and diviner who lives in Darkshire. Through cartomancy and ancient folk crafts, she seeks glimpses of the unseen perils stalking Duskwood.",al={"madame eva","who is eva","darkshire fortune teller"},it="identity"},{q="What is Madame Eva's role in the mystery of Stalvan?",a="Madame Eva reads the cards and senses supernatural danger closing around her granddaughter Alyssa. Her readings lead adventurers to forgotten documents and trails, where they uncover the grim history of Stalvan Mistmantle.",al={"eva stalvan","legend of stalvan eva","why does eva care about stalvan"},it="purpose"},{q="Is Madame Eva a witch or a mage?",a="Eva is a seer who practices older mystic arts, including cartomancy, spirit-thread weaving, and folk effigies. Her magic follows traditional fortune-telling and occult lore, unlike Dalaran’s structured arcanum or the Holy Light.",al={"is eva a witch","eva magic type","what magic does eva use"},it="power"},{q="Who is related to Madame Eva in Darkshire?",a="Madame Eva is the grandmother of Alyssa Eva and Lohgan Eva. Watcher Eva, who serves in the town’s Night Watch, is believed to share family ties with her.",al={"eva family","madame eva grandchildren","alyssa eva grandmother"},it="ties"},{q="What is Ghost Hair Thread used for?",a="Madame Eva spins Ghost Hair Thread from the hair of a restless spirit. She says it has a thousand uses, from binding evil spirits to sewing life into inanimate objects. She makes it for those who bring her the ghost hair she needs.",al={"ghost hair thread","eva thread quest"},it="item"},{q="Why does Madame Eva craft the Totem of Infliction?",a="Madame Eva crafts the Totem of Infliction as a dark, sympathetic effigy. Bound with specific creature materials, it directs curses and harm back onto the fell beasts terrorizing the woods.",al={"totem of infliction","eva totem"},it="motive"},{q="Whose side is Madame Eva on?",a="Madame Eva stands firmly with the people of Darkshire and the Alliance. Though she dabbles in cartomancy and the obscure 'old arts,' her loyalties remain with her beleaguered neighbors and her family, using her divination and rituals to safeguard the town against the dark perils creeping through Duskwood.",al={"madame eva allegiance","who does eva serve","is madame eva alliance"},it="side",add="b3bc0c21"},{q="What does Madame Eva want?",a="Madame Eva seeks to protect her community and kin from the dark forces haunting Duskwood. Using her cartomancy, she foresees hidden threats—such as the lurking doom surrounding the mystery of Stalvan Mistmantle—and directs travelers to gather ritual reagents to ward off evil and protect her family.",al={"what is eva trying to do","eva goals","why does madame eva need help"},it="wants",add="d6f73346"},{q="Why is Madame Eva here in Darkshire?",a="Darkshire is Madame Eva's ancestral home. She resides in her cottage as a matriarch to her grandchildren, Alyssa and Lohgan Eva, offering guidance, fortune-telling, and mystical aid to the frightened folk trying to endure life amidst the shadowy woods.",al={"why does eva live in duskwood","why is madame eva in darkshire","madame eva home"},it="why_here",add="6bf59259"}},ang={["faction:Alliance"]="For Alliance champions entering Duskwood’s oppressive shadow, Madame Eva offers an indispensable guide. Her premonitions cut through the deadly confusion of the woods.",["class:Priest"]="The Holy Light brings solace to the living. As a priest, you may find Eva’s cartomancy and use of spirit remnants an earthen counterpoint to traditional church liturgy.",["profession:Tailoring"]="As a tailor, you may value Eva’s knowledge of strange weaving materials. She works spectral thread plucked directly from the ghosts of the region."},kw={"alyssa eva","cartomancy","darkshire","duskwood","fortune teller","ghost hair thread","madame eva","stalvan"},rel={"quest:66","subzone:darkshire","zone:duskwood","quest:149","quest:101","quest:157","quest:262","quest:148"},src={"Madame Eva"}}
E["npc:sirra-von-indi"] = {t="npc",n="Sirra Von'Indi",z="duskwood",s="In Darkshire, Sirra Von'Indi studies the records that preserve Duskwood's history. The town's historian knows ancient languages and helps explain mysterious documents and the region's past.",h="In Darkshire, Sirra Von'Indi studies the records that preserve Duskwood's history.",sec={{t="The Town Historian",b="In Darkshire Town Hall, Sirra Von'Indi keeps the settlement's archives. While the town guard faces threats in the woods, he studies old texts and preserves the history of Grand Hamlet from before shadow fell across the region.",sp=0},{t="Deciphering the Hermit's Words",b="When Darkshire's leaders grow suspicious of Abercrombie, the hermit who lives on Duskwood's hills, they ask Sirra Von'Indi to translate his notes. His knowledge of languages helps the council make sense of the strange requests coming from the haunted woods.",sp=1},{t="Tragedies of the Past",b="Sirra Von'Indi knows the sorrowful history behind a weathered grave in Darkshire's cemetery. Few remember how the paladin Morgan Ladimore fell, and Sirra is among them. He gives travelers the context they need to bring peace to restless spirits.",sp=1}},faq={{q="Who is Sirra Von'Indi?",a="Sirra Von'Indi is Darkshire's human scholar and official historian. In the town hall, he studies ancient arts, translates obscure languages, and keeps the town's historical records.",al={"who is sirra","sirra von'indi lore","darkshire historian"}},{q="Where can Sirra Von'Indi be found?",a="Sirra Von'Indi can be found in Darkshire Town Hall, in central Duskwood. He stands among desks and bookshelves, consulting historical texts.",al={"where is sirra","sirra von'indi location","find sirra darkshire"}},{q="What role does he play with Abercrombie's note?",a="When a strange note from the hermit Abercrombie reaches Lord Ello Ebonlocke and no one in the town hall can read it, Sirra Von'Indi translates it. His work helps the council understand Abercrombie's odd demands.",al={"abercrombie letter translator","translate abercrombie note","sirra note translation"}},{q="What does Sirra know about Morgan Ladimore?",a="Sirra Von'Indi knows the full history of Morgan Ladimore, the fallen paladin buried in the Weathered Grave. He recounts Ladimore's descent into madness and tragedy after the Third War.",al={"sirra weathered grave","morgan ladimore lore sirra","story of the weathered grave"}},{q="Why does Sirra make travelers wait while translating?",a="Sirra Von'Indi often asks travelers to give him time while he translates. Deciphering obscure dialects and old handwriting takes care, and he cross-checks his references to make the translation reliable.",al={"why is sirra busy","wait for sirra to finish","sirra translating wait"}}},ang={["class:Mage"]="As a mage visiting Darkshire, you may recognize Sirra Von'Indi's academic discipline. His study of ancient languages and history echoes the archival research practiced in the Kirin Tor.",["faction:Alliance"]="As an Alliance traveler, you can see Sirra Von'Indi helping preserve Darkshire's civic life and the heritage of the Kingdom of Stormwind in a province consumed by darkness."},kw={"abercrombie","darkshire","duskwood","historian","morgan ladimore","sirra","town hall","translation","von'indi","weathered grave"},rel={"subzone:darkshire-town-hall","subzone:darkshire","zone:duskwood","quest:251","quest:401","quest:252","npc:abercrombie"},src={"Sirra Von'Indi"}}
E["npc:stitches"] = {t="npc",n="Stitches",z="duskwood",s="Along Duskwood's western road, Stitches marches east toward Darkshire, crushing the Night Watch and unwary travelers in his path.",h="Along Duskwood's western road, Stitches marches east toward Darkshire, crushing the Night Watch and unwary...",sec={{t="The Terror of the Main Road",b="Near Abercrombie's shack, northeast of Raven Hill Cemetery, Stitches sets out east along the road to Darkshire. Unholy sorcery and harvested corpses have made him an undead abomination. His immense strength and malice overwhelm the Night Watch checkpoints. Across from Vul'Gol Ogre Mound and outside the Rotting Orchard, he tears through the defense camp and outpost, slaughtering travelers and town defenders as he goes.",sp=0},{t="The Embalmer's Twisted Revenge",b="Abercrombie, whom passersby know as a harmless hermit, bears a deep grudge against Lord Ello Ebonlocke, Darkshire's mayor. Under innocent guises, he relied on unsuspecting adventurers to gather occult reagents, tools, and materials. Then Abercrombie completed his horrific creation and sent Stitches to Darkshire as a mocking gift. He means to break the town's defenses and punish Lord Ebonlocke.",sp=1}},faq={{q="Who created Stitches?",a="Stitches was assembled in Duskwood through necromancy. Who made him remains part of the mystery surrounding the undead near Raven Hill.",al={"stitches creator","who made stitches","abercrombie stitches"},sp=2,it="origin"},{q="Why is Stitches marching toward Darkshire?",a="Stitches marches along Duskwood's main road toward Darkshire, attacking the Night Watch and anyone else in his path. The reason for his attack emerges during the local investigation.",al={"why stitches darkshire","stitches attack goal","where is stitches walking"},sp=2,it="why_here"},{q="Can the Night Watch stop Stitches on their own?",a="No. Stitches easily overwhelms the Night Watch checkpoints outside Vul'Gol Ogre Mound and the Rotting Orchard. He can reach Darkshire's gates unless the militia joins forces with traveling adventurers to bring him down.",al={"guards vs stitches","night watch beat stitches","can darkshire guards kill stitches"},it="conflict"},{q="Where does Stitches spawn?",a="Stitches appears behind Abercrombie's shack, along the road northeast of Raven Hill Cemetery. Then he begins his long, deadly march east across Duskwood.",al={"where does stitches spawn","stitches location","stitches start point"},sp=1,gp=true},{q="Who is Stitches?",a="Stitches is a massive, horrific undead abomination assembled from salvaged body parts by the hermit necromancer Abercrombie the Embalmer. Stitched together in secret near Raven Hill, he was crafted as an instrument of vengeance meant to march straight down the road and lay waste to Darkshire.",al={"who is stitches","what is stitches","stitches lore"},sp=1,it="identity",add="66b85146"},{q="Whose side is Stitches on?",a="Stitches serves only his creator, Abercrombie the Embalmer. He is not aligned with the Scourge or any grand faction, but acts entirely as the mad hermit's personal weapon of spite against Lord Ello Ebonlocke and the people of Darkshire.",al={"stitches faction","is stitches scourge","who does stitches serve"},sp=1,it="side",add="74b258bc"},{q="What does Stitches want?",a="As a mindless undead construct, Stitches has no complex desires of his own. He obeys the directive imbued into his reanimated flesh by Abercrombie: to march relentlessly into Darkshire, slaughter anyone standing in his way, and deliver bloody vengeance upon the town.",al={"what does stitches want","stitches goal","stitches purpose"},sp=1,it="wants",add="c18e0cb4"},{q="Who is Stitches tied to?",a="Stitches is intimately tied to Abercrombie the Embalmer, who pieced him together, and to Mayor Lord Ello Ebonlocke, for whom the monster was conceived as a spiteful \"gift.\" Unwitting adventurers who assisted Abercrombie with seemingly harmless errands in Duskwood also played an unwitting part in his creation.",al={"stitches ties","who is stitches connected to","stitches and abercrombie"},sp=1,it="ties",add="3c61022e"},{q="Why is Stitches so feared?",a="Stitches is a terrifying menace because of his sheer, overwhelming brute strength. Towering over normal men and far stronger than the wild beasts or lesser undead roaming Duskwood, he easily cuts down the Night Watch patrols sent to bar his passage along the main road.",al={"why is stitches feared","is stitches dangerous","why is stitches famous"},it="fame",add="f85c8148"}},ang={["faction:Alliance"]="Stitches threatens Darkshire's beleaguered citizens and makes Duskwood's high road a deadly gauntlet for fresh Alliance recruits.",["class:Paladin"]="As a grotesque product of necromancy and profane flesh-crafting, Stitches embodies what the Holy Light is called upon to purge."},kw={"abomination","darkshire","ello ebonlocke","night watch","raven hill","stitches"},rel={"npc:abercrombie","npc:lord-ello-ebonlocke","topic:night-watch","subzone:darkshire","zone:duskwood","quest:252","subzone:raven-hill-cemetery","subzone:rotting-orchard"},src={"Stitches"}}
E["npc:sven-yorgen"] = {t="npc",n="Sven Yorgen",z="duskwood",s="At the Hushed Bank, Sven Yorgen grieves his murdered family and seeks vengeance. With Lars, he camps on the bank’s northern edge in western Duskwood and searches for the one who ruined his home.",h="At the Hushed Bank, Sven Yorgen grieves his murdered family and seeks vengeance.",sec={{t="A Life Shattered",b="Sven Yorgen remembers Duskwood before Medivh’s fall brought gloom to the region. Born before the First War, he worked the soil at Yorgen Farmstead in southern Duskwood for years with his wife and children. Their quiet life ended when mysterious Dark Riders raided the homestead while Sven was away. They butchered his family and left the farm a graveyard.",sp=0},{t="Vengeance from the Hushed Bank",b="Unable to return to his ruined home, Sven made a secluded refuge on the Hushed Bank with his friend Lars. He distrusts outsiders and asks travelers to prove their loyalty before he shares his burden. Near the devastated farmstead, Sven saw a figure skulking about. He became convinced the stranger was responsible for the massacre or tied to the sinister horsemen who destroyed his life.",sp=0},{t="Uncovering the Truth",b="Jitters, an errant vagrant, was the shadowy figure stalking Sven's property. His blundering drew the Dark Riders into Duskwood as they searched for the Scythe of Elune. Jitters did not strike the fatal blows, but his actions unleashed the nightmare that destroyed the Yorgen family. Sven's fury now turns toward the dark forces haunting Raven Hill and the necromancer Morbent Fel.",sp=1,bt={"q164.5"}}},faq={{q="Who is Sven Yorgen?",a="Sven Yorgen camps on the northern edge of the Hushed Bank in Duskwood. After his family was massacred at their homestead, he devoted himself to seeking retribution against those responsible.",al={"sven yorgen","who is sven","sven lore"},it="identity"},{q="What happened to Sven's family?",a="While Sven was away, black-cloaked figures called the Dark Riders came to Yorgen Farmstead. Searching for a powerful artifact, they slaughtered Sven's wife and children and left the land tainted by undead.",al={"yorgen farmstead tragedy","sven family dead","what happened to sven's farm"},it="history"},{q="Why is Sven hiding in the Hushed Bank?",a="Sven left his ruined farmstead after the massacre and made a temporary camp along the riverbank with Lars. He hides from the undead roaming western Duskwood while planning his revenge.",al={"where is sven","sven's camp","why is sven camped out"},it="why_here"},{q="Who is the shadowy figure Sven saw?",a="Sven does not know who the shadowy figure was. He saw someone skulking near the ruins of his homestead and asks trustworthy travelers to find out who it was and whether they had a hand in his family's deaths.",al={"shadowy figure sven","who was at yorgen farmstead","shadowy figure duskwood"},sp=1,it="target"},{q="Why did the Dark Riders attack Sven's farm?",a="The Dark Riders crossed Sven's lands while searching Duskwood for the Scythe of Elune, an ancient artifact of immense power. Their pursuit of the relic left death in their wake.",al={"why dark riders attack","what were dark riders looking for","scythe of elune sven"},sp=1,it="motive"},{q="How long has Sven lived in Duskwood?",a="Sven remembers Duskwood before it fell into darkness, so he lived there before the First War. The forest was still bright and peaceful, and Darkshire was known as Grand Hamlet.",al={"sven age","how old is sven","sven before dark"},it="history"},{q="Whose side is Sven Yorgen on?",a="Sven is loyal to the Alliance, though grief and fury drive him far more than any oath to Stormwind. Having lost his home and family to the horrors stalking Duskwood, he works with any dependable Alliance adventurer willing to take up arms against the dark forces infesting the woods.",al={"sven yorgen faction","is sven alliance","who does sven fight for"},it="side",add="be3c9ddb"},{q="What does Sven Yorgen want?",a="Sven wants vengeance. After the mysterious Dark Riders butchered his wife and children at the Yorgen Farmstead, he swore retribution against those responsible. He seeks the identity of a shadowy figure seen lingering near his ruined home and demands the destruction of the necromantic threats, like Morbent Fel, corrupting the land.",al={"what does sven want","sven yorgen goal","why does sven need help"},it="wants",add="d6fc644e"},{q="Who is Sven Yorgen tied to?",a="Sven's camp is shared with Lars, a steadfast companion who aids him in the wilderness. His quest for vengeance also binds him to the tragic mystery of Jitters, whom Sven observed lurking around his farmstead, and pits him directly against the necromancer Morbent Fel and the enigmatic Dark Riders of Deadwind Pass.",al={"sven yorgen allies","who does sven know","sven connections"},sp=1,it="ties",add="0ba4293f"}},ang={["faction:Alliance"]="Sven's story reflects the collapse of rural life in the kingdom's frontier territories. There, ordinary subjects face dark magic and shadowy horrors without protection.",["class:Paladin"]="Sven's heartbreak and thirst for justice speak to a paladin's duty to avenge innocent blood. Undead still rise across the soil of his family's farm."},kw={"dark riders","duskwood","hushed bank","jitters","lars","morbent fel","scythe of elune","sven yorgen","yorgen farmstead"},rel={"subzone:yorgen-farmstead","subzone:hushed-bank","npc:lars","npc:jitters","topic:dark-riders","quest:55","quest:95","quest:262"},src={"Sven Yorgen"}}
E["npc:tavernkeep-smitts"] = {t="npc",n="Tavernkeep Smitts",z="duskwood",s="At the Scarlet Raven in Darkshire, Tavernkeep Smitts hears the town’s gossip and remembers its unsolved tragedies. His keen eye makes him a valuable contact for those seeking Duskwood’s dark history.",h="At the Scarlet Raven in Darkshire, Tavernkeep Smitts hears the town’s gossip and remembers its unsolved...",sec={{t="Heart of Darkshire",b="Tavernkeep Smitts tends the Scarlet Raven’s hearth and pours drinks for weary travelers, townsfolk, and nervous Night Watch guards facing Duskwood’s perils. For years, he has been a familiar face in Darkshire, where rumors pass through his tavern each day.\n\nWhile other townsfolk stay behind locked shutters, Smitts watches who comes and goes. He notices strange patrons, hurried departures, and behavior that does not fit the town.",sp=0},{t="The Memory of Stalvan",b="Years ago, Smitts joined Marshal Haggard to investigate the slaughter of a visiting Stormwind noble family. At the scene, he found torn, muddy pages from a journal and kept them.\n\nInvestigators could not formally link the handwriting to Stalvan Mistmantle then. Smitts kept the faded scraps for years, certain the grim truth would come to light.",sp=1},{t="The Shadowy Patron",b="Terrified hermit Jitters once took refuge in the Scarlet Raven. There, Smitts saw him scribbling feverishly in a personal diary. Jitters fled in blind panic and left the journal behind.\n\nWhen an investigator brings it back, Smitts recognizes the book and points the tracker toward Raven Hill. His help unravels the cursed events that plague the woods.",sp=1}},faq={{q="Where can I find Tavernkeep Smitts?",a="Find Smitts behind the counter on the Scarlet Raven Tavern’s ground floor, on Darkshire’s town square.",al={"smitts location","where is tavernkeep smitts","scarlet raven barkeep"},it="place",gp=true},{q="What does Smitts know about Stalvan Mistmantle?",a="Years ago, Smitts joined Marshal Haggard in investigating the slaughter of visiting nobles. At the scene, he found and kept muddy, torn journal pages. When shown new evidence linking Stalvan to the crime, Smitts gives up the pages to be delivered to Commander Althea Ebonlocke.",al={"smitts stalvan","stalvan legend smitts","muddy pages stalvan"},sp=1},{q="What does Smitts know about Jitters?",a="Jitters stayed at the Scarlet Raven, where Smitts saw him write frantically in a journal before fleeing in terror. Bring Jitters’s journal back to the tavern, and Smitts recognizes it and directs you west toward Raven Hill to track him down.",al={"smitts jitters","jitters journal smitts","inquire at the inn smitts"},sp=1},{q="What drinks does Smitts brew or request?",a="Smitts helps procure ingredients for local drinks. He sends adventurers into the cursed wilds for Rot Blossoms to brew a potent mixture known locally as Zombie Juice.",al={"zombie juice","smitts rot blossoms","smitts brew"},it="wants"},{q="Who is Marshal Haggard, and how does Smitts know him?",a="Marshal Haggard is an old Stormwind Guard veteran who lives in a secluded cottage in the hills. He and Smitts investigated the grisly murders of nobles years ago and formed a bond over the unsolved case.",al={"smitts haggard","haggard connection"},it="ties"},{q="Does Smitts have any known family in Darkshire?",a="No family of Smitts is known in Darkshire. He keeps the Scarlet Raven on his own, and no relatives of his are known there.",al={"smitts relatives","mary smitts"}},{q="Who is Tavernkeep Smitts?",a="Tavernkeep Smitts is the proprietor of the Scarlet Raven Tavern in Darkshire. Beyond pouring drinks and serving patrons seeking shelter from Duskwood's gloom, he serves as an informal historian for the town. Having spent years observing travelers and residents alike, Smitts keeps a keen ear to local gossip, dark folklore, and past tragedies that still haunt the region.",al={"who is smitts","tavernkeep smitts","darkshire innkeeper"},it="identity",add="9f4b5837"},{q="Whose side is Tavernkeep Smitts on?",a="Smitts stands firmly with the people of Darkshire and the Alliance. He works closely with local defenders like Marshal Haggard and directs adventurers to Commander Althea Ebonlocke and the Night Watch when threats arise. He does what he can to protect his beleaguered community from the myriad horrors creeping through the surrounding woods.",al={"smitts faction","smitts allegiance","is smitts alliance"},it="side",add="657fa8c4"},{q="Why is Tavernkeep Smitts here?",a="Smitts makes his living running the Scarlet Raven Tavern, the central gathering place for Darkshire's exhausted inhabitants and passing travelers. Running the tavern puts him at the crossroads of all local rumors, giving him a front-row seat to the mysteries and tragedies that plague Duskwood.",al={"why is smitts in darkshire","why is smitts at the tavern"},it="why_here",add="32ff845a"}},ang={["faction:Alliance"]="As an Alliance traveler emerging from the shadowed woods, you can find shelter, drinks, and Smitts’s knowledge of the threats haunting Duskwood.",["class:Rogue"]="As a Rogue investigating cold cases and shadowy figures, you can rely on Smitts to notice what patrons write, when they panic, and what they leave behind."},kw={"darkshire","duskwood","haggard","jitters","scarlet raven","smitts","stalvan","tavernkeep","zombie juice"},rel={"subzone:scarlet-raven-tavern","subzone:darkshire","zone:duskwood","quest:66","quest:266","quest:453","quest:158","npc:althea-ebonlocke"},src={"Tavernkeep Smitts"}}
E["npc:viktori-prism-antras"] = {t="npc",n="Viktori Prism'Antras",z="duskwood",s="Above Darkshire, Viktori Prism'Antras keeps watch on the stars. In Duskwood's gloom, he hopes a telescope will bring them into clear view.",h="Above Darkshire, Viktori Prism'Antras keeps watch on the stars.",sec={{t="Eyes Upon the Heavens",b="Beyond the gryphon roost, up the slope, Viktori Prism'Antras peers into Duskwood's gloom. Undead incursions, ravenous spiders, and creeping shadows surround him. Yet he looks past the suffocating canopy, hoping to build a fine telescope that brings the stars into clear focus. In the heavens, he seeks quiet refuge from the dread engulfing the hamlet.",sp=0},{t="Gnomish Schematics and Scattered Parts",b="Building a delicate telescope takes work in this cursed forest. Viktori follows blueprints from his gnomish friend, Cog Glitzspinner. He asks passersby to find rare materials for crafting lenses and mechanical housings. Finely cut glass and metal lenses lie scattered across perilous ground.",sp=0}},faq={{q="Who is Viktori Prism'Antras?",a="Viktori is an eccentric human stargazer in Darkshire. While political and supernatural threats face the town, he devotes himself to building a telescope to study the stars.",al={"who is viktori","viktori prism'antras lore","viktori duskwood"},it="identity"},{q="Where can I find Viktori in Darkshire?",a="Viktori lives in a small wooden hut up the hill, just past the Darkshire gryphon master and to the right as you climb the path.",al={"viktori prism'antras location","where is viktori","find viktori darkshire"},it="place",gp=true},{q="What is Viktori trying to build?",a="Viktori is building an astronomical telescope from blueprints by his gnomish colleague Cog Glitzspinner. It needs several specialized lenses and components.",al={"viktori telescope","look to the stars device","what does viktori make"},it="wants"},{q="Why is he studying the stars from Duskwood?",a="Viktori is consumed by curiosity about the heavens despite Duskwood's darkness and terror. Studying the night sky gives him an intellectual refuge from the decaying land around him.",al={"why darkshire telescope","why study stars in duskwood"},it="why_here"},{q="Who designed the plans for Viktori's telescope?",a="Cog Glitzspinner, Viktori's inventive gnome acquaintance, designed the telescope blueprints.",al={"cog glitzspinner","who made the telescope schematics"},it="ties"},{q="Does Viktori help defend Darkshire?",a="No. Viktori is a civilian scholar, not a warrior. He leaves Darkshire's defense to Commander Althea Ebonlocke and the Night Watch, devoting his energies to his astronomical work.",al={"is viktori a night watchman","does viktori fight"}},{q="Whose side is Viktori Prism'Antras on?",a="Viktori is a peaceful human citizen aligned with the Alliance and the beleaguered community of Darkshire. While the town struggles under shadows, curses, and feral beasts, he keeps to himself and avoids local warfare, remaining dedicated purely to scholarly pursuits and stargazing.",al={"viktori prism'antras faction","is viktori alliance","who does viktori serve"},it="side",add="27dfc9ca"}},ang={["profession:Engineering"]="Tinkers will appreciate Viktori's project. His precision-built viewing instrument depends on sophisticated gnomish schematics.",["race:Gnome"]="Viktori's project depends on Cog Glitzspinner's ingenuity. It shows how far gnomish engineering reaches, even in desolate human towns.",["faction:Alliance"]="As an Alliance townsman, you can help Viktori pursue a rare, peaceful interest amid Darkshire's pervasive tragedy."},kw={"astronomy","cog glitzspinner","darkshire","duskwood","look to the stars","prism'antras","stargazer","telescope","viktori"},rel={"zone:duskwood","subzone:darkshire","quest:174"},src={"Viktori Prism'Antras"}}
E["npc:watcher-dodds"] = {t="npc",n="Watcher Dodds",z="duskwood",s="At the crossroads in central Duskwood, Watcher Dodds keeps watch for the Night Watch. From his roadside post, he watches for danger and asks travelers to thin the giant spider population.",h="At the crossroads in central Duskwood, Watcher Dodds keeps watch for the Night Watch.",sec={{t="On the Crossroads Watch",b="Watcher Dodds guards the crossroads for the Night Watch, under Commander Althea Ebonlocke. The roads from Darkshire, Raven Hill, and Deadwind Pass meet at his post.\n\nDarkshire's palisades shelter the town, but Dodds watches for threats beyond them. Wolf packs, ravenous ghouls, and oversized spiders roam the roads. From his roadside camp, he asks passing mercenaries to kill spiders emerging from the undergrowth before they overrun the roads.",sp=0}},faq={{q="Who is Watcher Dodds?",a="Watcher Dodds is a human member of the Night Watch, the militia defending Duskwood from the undead and beasts that plague the region. He is stationed at the central crossroads, beyond Darkshire's protection.",al={"watcher dodds","who is dodds","dodds duskwood"},it="identity"},{q="Where can I find Watcher Dodds?",a="Watcher Dodds keeps a small roadside camp at the main crossroads in central Duskwood. The roads from Darkshire, Raven Hill, and the southern passes meet there.",al={"watcher dodds location","where is dodds","dodds coords"},it="place",gp=true},{q="Why does he want spiders killed?",a="Giant venomous spiders infest the surrounding woods and prey on wanderers and supply couriers using the road. Watcher Dodds asks passing adventurers to thin the venom web spiders before they make the paths impassable.",al={"eight-legged menaces","dodds spider quest","why kill spiders"},it="wants"},{q="Who does Watcher Dodds report to?",a="Watcher Dodds answers to Commander Althea Ebonlocke, who leads the Night Watch from Darkshire's town hall.",al={"dodds commander","who leads night watch"},it="ties"},{q="Whose side is Watcher Dodds on?",a="Watcher Dodds serves the Night Watch, the stalwart militia defending the beleaguered town of Darkshire and the roads of Duskwood. By extension, his loyalty lies with the people of Duskwood and the Grand Alliance, standing firm against the shadows when Stormwind's official garrison cannot be spared to aid them.",al={"dodds faction","watcher dodds allegiances","who does dodds fight for"},it="side",add="06158fc1"},{q="Why is Watcher Dodds stationed at the crossroads?",a="Watcher Dodds maintains an outpost at the main crossroads of Duskwood to keep the vital thoroughfares open. Cut off from substantial reinforcements, he monitors the wilderness and recruits capable travelers to stem the predatory horrors—especially giant spiders and encroaching beasts—that threaten anyone journeying beyond Darkshire's immediate perimeter.",al={"why is dodds here","watcher dodds location reason","why is dodds camping here"},it="why_here",add="7998837a"}},ang={["faction:Alliance"]="As an Alliance traveler crossing Duskwood, you can find friendly support at Watcher Dodds's campfire. It is one of the few such places along the dark roads between Darkshire and the western lands."},kw={"althea ebonlocke","crossroads","darkshire","duskwood","night watch","spiders","watcher dodds"},rel={"npc:althea-ebonlocke","quest:245","zone:duskwood","subzone:crossroads","subzone:darkshire","quest:163"},src={"Watcher Dodds"}}
E["quest:101"] = {t="quest",n="The Totem of Infliction",z="duskwood",s="In Darkshire, Madame Eva offers travelers a ward against Duskwood's dangers. She needs ghoul fangs, skeleton fingers, and spider venom to enchant a charm that strikes back at attackers.",h="In Darkshire, Madame Eva offers travelers a ward against Duskwood's dangers.",sec={{t="A Fortune of Bloodshed",b="Madame Eva reads fortunes in her candle-lit home in Darkshire. She sees danger and violence ahead, then offers practical sorcery beside her divinations. To ward against Duskwood's predators, she needs ten ghoul fangs, ten skeleton fingers, and five vials of spider venom from the haunted woods.",sp=0},{t="Eva's Enchantment",b="Madame Eva binds ghoul fangs, fingers from restless skeletons, and spider venom with enchantments. When its bearer faces mortal peril, the totem gives off a magical aura. It reflects cruelty and harms anyone who strikes its bearer.",sp=0}},faq={{q="Who is Madame Eva?",a="Madame Eva is a fortune teller and mystic who lives in Darkshire. She reads omens and makes protective wards for locals and travelers facing Duskwood's supernatural dangers.",al={"madame eva","who gives this quest","eva darkshire"},it="identity"},{q="What is the purpose of the Totem of Infliction?",a="The Totem of Infliction wards off attackers with an enchanted charm. When its bearer is threatened, its magic strikes back at those who try to harm them.",al={"totem of infliction purpose","what does totem do","totem lore"},it="purpose"},{q="Why does Madame Eva need ghoul fangs, skeleton fingers, and spider venom?",a="Madame Eva uses ghoul fangs, skeleton fingers, and spider venom to make a protective enchantment. Its magic retaliates against attackers.",al={"why spider venom","ingredients for totem","why skeleton fingers"},it="item"},{q="Where are the components for the totem found?",a="The components come from undead and beasts in Duskwood. Ghouls and skeletons haunt its cemeteries and orchards, while large venomous spiders live throughout the shadowed woods.",al={"where find fangs","where to get materials","where are ghouls and spiders"},it="item",gp=true},{q="What danger does Madame Eva foresee?",a="Madame Eva warns of danger and bloodshed ahead. She says whispering winds speak of a threat on your path.",al={"eva fortune","what danger coming","future bloodshed"},it="threat"},{q="Is crafting the totem considered dark magic?",a="Eva's work draws on grim folk sorcery and corpse parts, but Duskwood's dangers make protective charms an accepted means of defense.",al={"is this necromancy","is eva evil","dark magic totem"},it="power"},{q="Why does Madame Eva want the Totem of Infliction crafted?",a="Madame Eva listens closely to the whispers on the wind and foresees a great and violent danger waiting patiently for you in the near future. While the encroaching mystical taint threatens all of Duskwood, her offer to forge the Totem of Infliction is meant specifically to shield you against the looming bloodshed she divines in your path.",al={"madame eva motive","why craft totem of infliction","why does eva help me"},it="motive",add="c4af218f"}},ang={["faction:Alliance"]="As an Alliance traveler in a borderland cut off from major military reinforcements, you may rely on local mystics like Madame Eva for folk charms and wards.",["class:Paladin"]="As a paladin, you may question making a ward from undead bones and spider venom. Duskwood's dangers can make practical folk sorcery hard to dismiss.",["class:Warlock"]="As a warlock, you recognize the retaliatory curses woven into Eva's protective charm.",["class:Priest"]="As a priest, you know the Church of the Holy Light teaches faith and devotion, while mystics like Madame Eva channel spiritual will through grim, tangible charms."},kw={"darkshire","duskwood","ghoul fangs","madame eva","protective ward","skeleton fingers","spider venom","totem of infliction"},rel={"npc:madame-eva","subzone:darkshire","zone:duskwood"},m={start="Madame Eva",level="25",faction="Alliance",id=101,ri={"Ghoul Fang","Skeleton Finger","Vial of Spider Venom"}},src={"The Totem of Infliction"}}
E["quest:133"] = {t="quest",n="Ghoulish Effigy",z="duskwood",s="In Duskwood, the dead press against Abercrombie’s shack. He asks you for ghoul ribs to make a grim scarecrow and guard his home.",h="In Duskwood, the dead press against Abercrombie’s shack.",sec={{t="A Hermit's Plight",b="Beyond Darkshire’s guarded bounds, Abercrombie lives alone among Duskwood’s shadowed trees. Flesh Eaters and Bone Chewers roam the wilds freely. He says ravenous corpses recently battered down his walls, so he asks you to bring him their ribs. He hopes a grisly effigy will keep the hungry dead from his home.",sp=0},{t="A Bizarre Defense",b="For his wooden shack, Abercrombie trusts a grim plan over the Night Watch or stronger walls. He believes an effigy made from ghoul remains will frighten off other scavenging dead. A scarecrow built from slain undead is unsettling. Yet travelers in Duskwood often do as the hermit asks to earn needed coin.",sp=0}},faq={{q="Where does Abercrombie live?",a="Abercrombie lives in a solitary shack in western Duskwood, just northeast of Raven Hill Cemetery and far from Darkshire’s protection.",al={"abercrombie location","where is abercrombies shack","hermit shack duskwood"},it="place"},{q="Why does Abercrombie need ghoul ribs?",a="Abercrombie says packs of ghouls are pounding on his shack’s walls. He plans to make a gruesome scarecrow from their bones to frighten away scavenging undead.",al={"ghoul ribs purpose","why ghoul ribs","what is the effigy for"},it="motive"},{q="Which creatures drop the Ghoul Ribs?",a="You can gather the ribs from undead roaming Duskwood’s roads and cemeteries: Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones, and Plague Spreaders.",al={"where to get ribs","ghoul rib drops","which ghouls drop ribs"},it="target",gp=true},{q="Does building an undead scarecrow actually repel ghouls?",a="Undead rarely fear much, so seasoned monster hunters doubt Abercrombie’s plan. The hermit insists on it, and few question someone who pays in such desperate woods.",al={"do effigies work on ghouls","ghoul scarecrow logic"}},{q="Why doesn't Abercrombie simply relocate to Darkshire?",a="Abercrombie chooses to live alone, away from the Night Watch and town governance. Despite Duskwood’s dangers, he prefers tending his shack and relying on his own peculiar defenses.",al={"why live in woods","why doesn't abercrombie move","darkshire safety"},it="why_here"},{q="What comes next after gathering the ribs?",a="Once Abercrombie has the ghoul ribs, another strange problem comes to light: local ogres have stolen his belongings, and he sends you into the wild to deal with them.",al={"next quest","what after ghoulish effigy"},it="next_step",gp=true},{q="What are the Ghoul Ribs used for?",a="Abercrombie claims he needs the ribs of local ghouls to construct a macabre effigy—an undead scarecrow—to place outside his isolated shack. Living far outside the safety of Darkshire, he insists the grotesque construct will frighten off the flesh-eating horrors prowling his walls.",al={"what are ghoul ribs for","ghoul rib use","why gather ghoul ribs"},it="item",add="d0d16021"},{q="Why does Abercrombie need you to collect the ribs?",a="Abercrombie is an eccentric, frail hermit stranded out in the woods with no love for Darkshire or its Night Watch. Terrified by the ghouls pounding on his shack's walls, he lacks the martial strength to face the rotting horrors himself, leaving him dependent on passing adventurers willing to risk Duskwood's perils for coin.",al={"why ask me","why doesn't abercrombie do it","why not ask the night watch"},it="why_me",add="0ad10362"},{q="Why are ghouls roaming Duskwood?",a="The encroaching shadow that swallowed the region into eternal dusk also disturbed its dead. Restless undead, from ravenous Bone Chewers to flesh-eating ghouls, now rise throughout the gloom and cemetery grounds, prowling the decaying woods and relentlessly preying upon any living soul foolish enough to venture outside fortified settlements.",al={"why are there ghouls here","duskwood ghouls","where do the ghouls come from"},it="target",add="cd024384"}},ang={["faction:Alliance"]="The Night Watch struggles to protect the roads, so isolated forest dwellers like Abercrombie rely on passing Alliance travelers for protection from the restless dead.",["class:Paladin"]="As a paladin, you can hunt Flesh Eaters and Bone Chewers to cleanse Duskwood’s soil. Giving their remains to a hermit may unsettle you.",["class:Priest"]="As a priest, you can aid a frightened hermit among dark spirits. Making effigies from harvested remains may test your stomach."},kw={"abercrombie","bone chewers","darkshire","duskwood","effigy","flesh eaters","ghoul rib","hermit"},rel={"npc:abercrombie","zone:duskwood","subzone:manor-mistmantle","subzone:darkshire"},m={start="Abercrombie",level="27",faction="Alliance",id=133,ri={"Ghoul Rib"}},src={"Ghoulish Effigy (Classic)"}}
E["quest:134"] = {t="quest",n="Ogre Thieves",z="duskwood",s="In western Duskwood, Abercrombie sends travelers to the ogres’ stronghold at Vul'Gol Ogre Mound. He says they ambushed him while he foraged and took a crate of irreplaceable herbs and tools.",h="In western Duskwood, Abercrombie sends travelers to the ogres’ stronghold at Vul'Gol Ogre Mound.",sec={{t="A Hermit's Lost Goods",b="On the damp roads of western Duskwood, Abercrombie says he was attacked while gathering supplies. Brutes from the southern ogre mound drove the aged hermit off. He left behind a sturdy wooden crate filled with precious herbs and delicate instruments.",sp=0},{t="The Vul'Gol Threat",b="In southern Duskwood, Vul'Gol Ogre Mound is a danger to unwary wanderers. Hostile ogres harass travelers there, and Abercrombie's crate rests near the entrance among roaring brutes and spell-weaving magi.",sp=0},{t="A Slip of the Tongue",b="When Abercrombie gets his goods back, his eccentric manner gives way to manic excitement. He nearly shouts praise to 'the Nec—' before catching himself and thanking you instead. Then he eagerly shuts himself away in the dark to put his recovered supplies to use.",sp=1}},faq={{q="Who is Abercrombie?",a="Abercrombie is an eccentric hermit in a worn shack in western Duskwood. He acts frail and helpless and seems to need assistance, though his frantic behavior and strange requests hint at darker motives.",al={"abercrombie lore","who gave me this quest","who is the hermit"},it="identity"},{q="Where did the ogres take Abercrombie's crate?",a="The ogres took Abercrombie's crate to Vul'Gol Ogre Mound in southern Duskwood. It rests exposed on the dirt right outside the mound's entrance.",al={"where is the crate","crate location","vul'gol crate"},it="place",gp=true},{q="Why are there ogres in Duskwood?",a="The aggressive and opportunistic ogres of the Vul'Gol clan carved out a foothold in Duskwood's rugged southern hills. They raid passersby, ambush solitary wanderers, and hoard stolen plunder around their mound.",al={"duskwood ogres","vul'gol ogres origin","why ogres here"},it="origin"},{q="What is actually inside the crate?",a="Abercrombie claims the crate holds rare herbs and specialized harvesting tools he abandoned during the attack. He is overjoyed to have them back.",al={"what did abercrombie lose","contents of crate"},sp=1,it="item"},{q="What did Abercrombie almost say when receiving the crate?",a="As Abercrombie gets his crate back, he starts to thank someone else, then abruptly catches himself and thanks you instead. He gleefully looks forward to the nights ahead.",al={"thank the nec","what was abercrombie saying","abercrombie quote"},sp=1},{q="Does this quest connect to other tasks at the ogre mound?",a="Travelers headed to Vul'Gol Ogre Mound may also be gathering ogre monocles for Viktori Prism'Antras.",al={"ogre mound quests","quests near vulgol"},it="ties",gp=true},{q="Why does Abercrombie want his crate back?",a="Abercrombie claims he was foraging far from his shanty when ogres ambushed him, forcing him to abandon a collection of rare herbs and delicate tools. To an isolated hermit living on the edge of the cemetery, replacing such supplies is nearly impossible on his own. Yet his intense agitation and desperate relief upon its return hint that the contents serve an endeavor far more sinister than ordinary herbalism.",al={"why retrieve crate","abercrombie crate motive","why does he want the crate"},it="motive",add="7ac39a32"},{q="Who are the ogres holding the crate?",a="The thieves belong to the Vul'Gol ogres, brute outcasts who carved out a foul mound in the crags of southern Duskwood. Known for pillaging travelers along the dark trails, they stumbled across Abercrombie while he was wandering outside his usual haunts, drove the old hermit off, and dragged his cargo back to their settlement alongside other looted plunder.",al={"who took the crate","vul'gol ogres","duskwood ogres crate"},it="target",add="1d020e8a"},{q="Why does Abercrombie ask you instead of the Night Watch?",a="Abercrombie is a frail, reclusive hermit who lacks both the strength to confront a camp of hulking brutes and any goodwill from Darkshire. Suspicious townsfolk and the overstretched Night Watch keep their distance from his shack, guarding only the main roads and town perimeter. Unable to rely on local authorities, the hermit depends on traveling adventurers willing to brave the perils of Vul'Gol Ogre Mound.",al={"why ask me","why not night watch","why abercrombie needs help"},it="why_me",add="504b8e87"}},ang={["class:Warlock"]="As a warlock, you may recognize Abercrombie's slip of the tongue as praise for dark spellcraft, rather than simple love of plants.",["class:Paladin"]="As a paladin, you may take Abercrombie's eager, secretive delight at recovering his crate as a reason to be wary of helping the reclusive hermit blindly.",["profession:Herbalism"]="As an herbalist, you may wonder what bizarre flora could make Abercrombie so desperate to retrieve his crate from an ogre mound."},kw={"abercrombie","crate","duskwood","hermit","ogre","vul'gol"},rel={"npc:abercrombie","zone:duskwood","npc:viktori-prism-antras"},m={start="Abercrombie",level="30",faction="Alliance",id=134,ri={"Abercrombie's Crate"}},src={"Ogre Thieves (Classic)"}}
E["quest:146"] = {t="quest",n="Messenger to Darkshire",z="duskwood",s="In Darkshire, Lord Ello Ebonlocke answers a plea for help from Lakeshire. Blackrock orcs and gnolls press against the town, but the plea cannot be granted.",h="In Darkshire, Lord Ello Ebonlocke answers a plea for help from Lakeshire.",sec={{t="A Desperate Request Denied",b="Magistrate Solomon of Redridge asks his old peer in Duskwood for troops. Blackrock orcs and gnolls are closing in on his town. Lord Ello Ebonlocke answers in anger. Darkshire struggles against the living dead, ravenous beasts, and cursed magic on every side. Ebonlocke says the Night Watch exists because Stormwind abandoned Duskwood. Without its defenders, Darkshire would fall before a patrol could cross the forest.",sp=0},{t="A Pattern of Abandonment",b="Magistrate Solomon reads Ebonlocke's reply and sees a pattern of retreat across the kingdom. The Stormwind Army left Westfall, Darkshire was left to fend for itself, and Lakeshire's calls for aid have gone unanswered. Leaders across the kingdom whisper that this may be more than oversight or incompetence. Solomon now faces their suspicion of treachery at Stormwind's heart.",sp=1}},faq={{q="Why won't Lord Ebonlocke send the Night Watch to help Lakeshire?",a="Darkshire is beset by undead, beasts, and foul sorcery. The Night Watch is a local militia formed after Stormwind withdrew its garrisons. If Ebonlocke sent his guards to Redridge, Darkshire would fall before they crossed the forest.",al={"why ebonlocke refuse","why no night watch for lakeshire","darkshire refuses help"},it="motive"},{q="What does Magistrate Solomon realize upon reading the response?",a="Solomon sees Lakeshire's plight as part of a kingdom-wide crisis. The army has retreated from Westfall and Darkshire has been left to defend itself. He suspects treachery in Stormwind's leadership, not simple neglect.",al={"solomon reaction","what does solomon realize"},it="conflict"},{q="Who formed the Night Watch?",a="Duskwood's beleaguered citizens and leaders formed the Night Watch under Lord Ello Ebonlocke after Stormwind's forces abandoned the territory to darkness and rot.",al={"night watch origins","who made night watch"},it="origin"},{q="Where does Solomon go from here to get help?",a="With Darkshire refusing aid and Westfall overrun by the Defias Brotherhood, Lakeshire stands alone. Solomon looks to Stormwind's palace court for answers about why the crown will not protect its outlying territories.",al={"what does solomon do next","who else can help lakeshire"},it="next_step"},{q="Did Stormwind officially pull out of Duskwood and Westfall?",a="Yes. As dark magic corrupted Duskwood and unrest erupted in Westfall, Stormwind's regular forces withdrew. Frontier towns raised local militias, including the Night Watch and the People's Militia, to survive.",al={"why did stormwind leave","stormwind abandoned towns"},it="history"},{q="What is the relation between Solomon and Ebonlocke?",a="Solomon and Ebonlocke are long-standing peers and fellow magistrates who govern frontier towns. Solomon counted on their personal ties when he asked for troops, but Duskwood's dangers made it impossible for Ebonlocke to comply.",al={"are solomon and ebonlocke friends","solomon and ello relationship"},it="ties"},{q="Why does Lord Ebonlocke send you to deliver the letter instead of his own guards?",a="Lord Ebonlocke cannot spare a single member of the Night Watch. Darkshire stands besieged by darkness and foul horrors, and every sword is desperately needed to keep the town from being overrun. Because you arrived from Lakeshire as Magistrate Solomon's courier, sending you back with his reply costs Darkshire none of its precious defenders.",al={"why send me","why not send the night watch","why use an adventurer"},it="why_me",add="ec08915e"}},ang={["faction:Alliance"]="For the Alliance, this dispatch reveals deep cracks in the southern kingdom. Outlying settlements are left discarded and defenseless.",["race:Human"]="As a human traveler, you can see how isolated the realm's towns have become while the royal court looks away."},kw={"darkshire","ebonlocke","lakeshire","messenger","night watch","solomon","stormwind"},rel={"quest:145","npc:lord-ello-ebonlocke","npc:magistrate-solomon","topic:night-watch","subzone:darkshire","subzone:lakeshire","zone:duskwood","topic:stormwind-army"},m={start="Lord Ello Ebonlocke",["end"]="Magistrate Solomon",level="18",faction="Alliance",id=146},src={"Messenger to Darkshire (2)"}}
E["quest:148"] = {t="quest",n="Supplies from Darkshire",z="duskwood",s="Abercrombie in western Duskwood asks you to fetch a rare thread from Darkshire. He says he is too frail to cross the haunted woods and asks for Ghost Hair Thread from Madame Eva.",h="Abercrombie in western Duskwood asks you to fetch a rare thread from Darkshire.",sec={{t="A Feeble Request",b="North of Raven Hill Cemetery, you find Abercrombie alone in a shack in western Duskwood. Age and frailty keep him from making the dangerous journey through the woods to buy goods in Darkshire. So he asks you to go to the township's town square and speak with Madame Eva for a spool of Ghost Hair Thread.",sp=0},{t="A Curious Material",b="In Darkshire, Madame Eva has no Ghost Hair Thread ready. The local diviner spins strange artifacts, and this thread is no ordinary sewing supply. To make it, she needs ghost hair from Blind Mary, a sorrowful spirit haunting a farmhouse south of Darkshire. So gathering what Madame Eva needs comes first.",sp=1}},faq={{q="Who starts the quest Supplies from Darkshire?",a="Abercrombie, a hermit in a shack north of Raven Hill Cemetery in western Duskwood, asks for your help.",al={"quest giver supplies from darkshire","who starts supplies from darkshire","abercrombie errand"},gp=true},{q="Who do I speak with in Darkshire to get the supplies?",a="Speak with Madame Eva, who lives in a house overlooking Darkshire's central square.",al={"where to turn in supplies from darkshire","supplies from darkshire turn in","madame eva location"},it="target",gp=true},{q="What specific item is Abercrombie looking for?",a="Abercrombie asks for Ghost Hair Thread, an unusual material Madame Eva weaves.",al={"what does abercrombie want","what are the supplies","abercrombie item"},it="item",gp=true},{q="Does Madame Eva have the Ghost Hair Thread ready?",a="No. Madame Eva has none ready when you arrive. She agrees to spin it if you gather the spectral materials she needs from nearby spirits.",al={"does eva have thread","supplies from darkshire completion"},it="next_step",gp=true},{q="What quest precedes Supplies from Darkshire?",a="The Hermit sends travelers from Darkshire to find Abercrombie at his dwelling.",al={"prerequisite supplies from darkshire","supplies from darkshire prequest"},gp=true},{q="What quest follows Supplies from Darkshire?",a="Speaking with Madame Eva leads directly to Ghost Hair Thread. You are asked to bring a Spectral Comb to Blind Mary and gather her hair.",al={"next quest after supplies from darkshire","supplies from darkshire followup"},it="next_step",gp=true},{q="Why does Abercrombie need supplies from Darkshire?",a="Abercrombie claims he is simply an impoverished, frail old man living out in the dangerous wilds of Duskwood who is unable to make the long and perilous journey into town. He specifically requests Ghost Hair Thread, ostensibly needing everyday tailoring supplies from Madame Eva to sustain his solitary life in the woods.",al={"why supplies from darkshire","why does abercrombie need thread","abercrombie ghost hair thread"},it="motive",add="b4c47635"},{q="Why does Abercrombie ask you instead of getting the thread himself?",a="Abercrombie pleads that he is far too old, feeble, and physically frail to brave the haunted, beast-ridden paths between his shack and Darkshire. Having an able-bodied traveler cross the shadowed wilderness on his behalf is his only apparent means of securing the materials he desires from Madame Eva.",al={"why cant abercrombie go to town","why me supplies from darkshire","why doesnt abercrombie get supplies"},it="why_me",add="2d5a916c"}},ang={["faction:Alliance"]="As an Alliance adventurer, you may carry messages and goods for hermits along the hazardous backroads around Darkshire.",["profession:Tailoring"]="As a tailor, you know woven items usually use linen or silk. Madame Eva's work spinning ethereal hair into thread is a macabre curiosity."},kw={"abercrombie","darkshire","duskwood","ghost hair thread","madame eva","supplies from darkshire","the hermit"},rel={"npc:abercrombie","npc:madame-eva","quest:149","subzone:darkshire","zone:duskwood"},m={start="Abercrombie",["end"]="Madame Eva",level="24",faction="Alliance",id=148},src={"Supplies from Darkshire (Classic)"}}
E["quest:149"] = {t="quest",n="Ghost Hair Thread",z="duskwood",s="In Duskwood, Madame Eva seeks ghost hair to spin into Ghost Hair Thread for Abercrombie. She sends you south of Darkshire to Blind Mary at an abandoned farmhouse, where an ethereal comb can gather hair from the tormented spirit.",h="In Duskwood, Madame Eva seeks ghost hair to spin into Ghost Hair Thread for Abercrombie.",sec={{t="A Fortuneteller's Request",b="Madame Eva needs ghost hair to spin thread for Abercrombie. Linen and wool cannot serve Duskwood's rituals, so she gives you a Spectral Comb to gather strands from a spirit. The comb passes through the veil of death and catches loose spectral hair without violence.",sp=0},{t="The Sorrow of Blind Mary",b="South of Darkshire, Blind Mary haunts an abandoned farmhouse. The tormented spirit despairs over her appearance and screams at intruders to look away. In anguish over what she had become, she tore out her own eyes. The Spectral Comb offers brief comfort: she can groom her ghostly hair, though her torment continues.",sp=0}},faq={{q="Who is Blind Mary?",a="Blind Mary is a sorrowful ghost haunting an abandoned farmhouse in the hills south of Darkshire. Despair over her perceived ugliness drove her to tear out her own eyes so she would never see herself again. Though blind, she remains painfully aware when anyone looks at her.",al={"blind mary lore","who is mary duskwood","spectral comb woman"},it="target"},{q="Why does Madame Eva need ghost hair?",a="Madame Eva needs ghost hair to spin spectral thread. Ordinary craft supplies do not suit Duskwood's rituals, so she relies on occult materials for her work and protective enchantments.",al={"why ghost hair","what is ghost hair thread for","madame eva hair thread"},it="motive"},{q="Where can Blind Mary's house be found?",a="Blind Mary's ruined farmhouse lies in the hills south of Darkshire, past the town cemetery. Horrors and undead prowl the surrounding woods.",al={"where is blind mary","blind mary location","farmhouse south of darkshire"},it="place",gp=true},{q="How does the Spectral Comb work on a spirit?",a="The Spectral Comb can touch apparitions and gather their hair. It passes through spiritual matter as an ordinary comb moves through living hair, collecting strands that remain ethereal.",al={"how does spectral comb work","spectral comb lore","comb ghost hair"},it="item"},{q="Is Blind Mary hostile to travelers?",a="No. Blind Mary screams and weeps, but she is not hostile to living visitors. Her anguish turns inward, while aggressive creatures and undead haunt the woods and nearby structures.",al={"will blind mary attack","is blind mary dangerous"},it="hostile"},{q="What happens after giving Mary the comb?",a="After Mary uses the comb, she returns it tangled with her spectral hair. Bring it back to Madame Eva in Darkshire so she can spin the strands into Ghost Hair Thread.",al={"what next ghost hair","return the comb quest","after ghost hair thread"},it="next_step"},{q="Why does Madame Eva need an adventurer to visit Blind Mary?",a="Madame Eva remains in Darkshire to aid the town with her divinations and rituals, but reaching Blind Mary requires traveling deep into the haunted hills south of the village. The surrounding woods and Mary's farmhouse crawl with undead and shadowy beasts that standard townspeople cannot risk facing alone.",al={"why send me","why not go herself","why does eva need me"},it="why_me",add="212c26a1"}},ang={["profession:Tailoring"]="Spinning thread from a ghost's incorporeal remains is an occult craft, far removed from ordinary spinning wheels and looms.",["class:Priest"]="As a priest, you can see in Blind Mary's torment the tragedy and lingering shadows that afflict Duskwood's restless dead.",["faction:Alliance"]="As an Alliance traveler, you can see in the tragic specters haunting farms near Darkshire how quickly prosperous Grand Hamlet fell into darkness and isolation."},kw={"blind mary","darkshire","duskwood","farmhouse","ghost","ghost hair thread","madame eva","spectral comb"},rel={"npc:blind-mary","npc:madame-eva","subzone:darkshire","zone:duskwood"},m={start="Madame Eva",["end"]="Blind Mary",level="24",faction="Alliance",id=149},src={"Ghost Hair Thread (Classic)"}}
E["quest:154"] = {t="quest",n="Return the Comb",z="duskwood",s="In Darkshire, Madame Eva waits for the comb Blind Mary has returned. Its ghostly strands can be spun into Ghost Hair Thread.",h="In Darkshire, Madame Eva waits for the comb Blind Mary has returned.",sec={{t="A Bitter Reflection",b="Blind Mary waits in a shack south of Darkshire, grieving the death that changed her. Madame Eva’s comb recalls the grooming of her mortal life, and deepens her sorrow. She sees only a wraith, a monster stripped of mortal grace. Certain no one can love her again, she thrusts the comb and the ghostly hair tangled in its teeth back into your hands.",sp=0},{t="Weaving the Supernatural",b="Madame Eva awaits the comb in Darkshire, knowing the work was grim. With the ghostly hair, the fortune teller can spin a spool of Ghost Hair Thread. She pays you for any strands left after the delicate work.",sp=0}},faq={{q="Why does Blind Mary react with horror to the comb?",a="The comb recalls Blind Mary’s mortal life and beauty. Seeing herself as a withered spirit overwhelms her with grief, and she rejects the comb, convinced she has become a monster no one will cherish.",al={"why is mary upset","why did blind mary scream","mary comb reaction"},it="motive"},{q="What does Madame Eva do with the hair on the comb?",a="Madame Eva weaves the hair from the comb into Ghost Hair Thread, a mystical thread used to bind evil spirits and sew life into inanimate objects.",al={"why ghost hair","what does eva do with ghost hair","madame eva thread"},it="why_wanted"},{q="Where is Blind Mary located?",a="Blind Mary haunts a dilapidated shack south of Darkshire, near Tranquil Gardens Cemetery in Duskwood.",al={"where is blind mary","blind mary location"},it="place",gp=true},{q="Who is Madame Eva?",a="Madame Eva is a human mystic and diviner who lives in Darkshire. She offers fortune readings, cryptic guidance, and magical trinkets and reagents to those facing Duskwood’s dangers.",al={"who is madame eva","eva darkshire"},it="identity"},{q="What follows after returning the comb to Madame Eva?",a="After taking the comb and preparing the Ghost Hair Thread, Madame Eva asks you to deliver it to Abercrombie, the hermit near Raven Hill Cemetery.",al={"what comes next","next quest after return the comb"},sp=1,it="next_step"},{q="Why does Madame Eva give you coins upon completion?",a="Madame Eva says the comb held more than enough ghostly hair for the spool. She gives you a few coins for the extra strands she keeps.",al={"why do i get coins","extra strands money"},it="for_you"}},ang={["profession:Tailoring"]="Spinning Ghost Hair Thread shows how Duskwood’s spectral material can be harvested and carded into durable supernatural textiles.",["class:Priest"]="As a priest, you can see how grief torments spirits bound to the mortal world, even when they mean no harm.",["faction:Alliance"]="As an Alliance traveler, you cross gloomy roads between Darkshire and Mary’s home, where Duskwood’s decay reaches the roads."},kw={"blind mary","darkshire","duskwood","ghost hair","ghost hair thread","madame eva","return the comb"},rel={"quest:149","npc:blind-mary","npc:madame-eva","subzone:darkshire","zone:duskwood"},m={start="Blind Mary",["end"]="Madame Eva",level="24",faction="Alliance",id=154},src={"Return the Comb (Classic)"}}
E["quest:156"] = {t="quest",n="Gather Rot Blossoms",z="duskwood",s="In Duskwood, Tavernkeep Smitts needs rot blossoms for his zombie juice. They grow inside the skulls of skeletal horrors and fiends in the graveyards.",h="In Duskwood, Tavernkeep Smitts needs rot blossoms for his zombie juice.",sec={{t="A Bizarre Ingredient",b="At the Scarlet Raven Tavern, Tavernkeep Smitts sometimes brews a strange drink. His zombie juice calls for rot blossoms, which root inside the empty skulls of animated skeletons. Smitts avoids the undead, so passing mercenaries gather the blossoms for him.",sp=0},{t="Graveyard Pest Control",b="Rot blossoms grow on skeletal horrors and fiends in the overgrown plots of Tranquil Gardens Cemetery and Raven Hill Cemetery. The Night Watch militia is stretched thin against the terrors creeping through the woods. Smitts commends those who hunt the dead to Commander Althea Ebonlocke, helping thin the restless ranks that threaten Darkshire.",sp=0}},faq={{q="What is a rot blossom?",a="Rot blossoms are foul plants that grow amid dark magic and decay. In Duskwood, they sprout inside the skulls of animated skeletal horrors and fiends.",al={"rot blossom","what is rot blossom","where do rot blossoms come from"},it="item"},{q="Why does Tavernkeep Smitts need rot blossoms?",a="Tavernkeep Smitts uses rot blossoms to brew zombie juice, a drink requested by certain patrons in the region.",al={"why smitts want blossoms","zombie juice ingredients","smitts drink"},it="motive"},{q="Where can the skeletons bearing these blossoms be found?",a="Skeletal horrors and fiends bearing rot blossoms haunt Duskwood’s burial grounds. They are found especially at Tranquil Gardens Cemetery near Darkshire and Raven Hill Cemetery to the west.",al={"where are skeletal horrors","rot blossom location","tranquil gardens skeletons"},gp=true},{q="Does this task help the defense of Darkshire?",a="Yes. Darkshire relies on the Night Watch against constant undead attacks. Hunting skeletons for their blossoms thins the monsters threatening the town and helps Commander Althea Ebonlocke.",al={"night watch help","althea ebonlocke skeleton killing"}},{q="What comes next after delivering the blossoms?",a="After Smitts receives the blossoms and brews the zombie juice, he asks you to deliver the draught to Abercrombie, an eccentric hermit near Raven Hill Cemetery.",al={"next quest after rot blossoms","juice delivery follow up"},sp=1,it="next_step"},{q="Is zombie juice a normal beverage served in Darkshire?",a="No. The Scarlet Raven Tavern usually serves regional fare. Smitts prepares zombie juice, a strange brew with necrotic ingredients, only when he receives an eccentric order.",al={"is zombie juice normal","scarlet raven drinks"}},{q="What are the skeletons carrying rot blossoms?",a="You are sent against the Skeletal Horrors and Skeletal Fiends that infest the burial grounds of Duskwood, particularly Tranquil Gardens Cemetery and Raven Hill. These undead monstrosities rise from disturbed graves across the shadowed woods, harboring strange, necrotic rot blossoms right inside their skull cavities.",al={"skeletal horrors duskwood","skeletal fiends tranquil gardens","what skeletons drop rot blossoms"},it="target",add="1d59b9b9"},{q="Why does Tavernkeep Smitts send you rather than the Night Watch?",a="Smitts runs the Scarlet Raven Tavern and admits he has never dared get close enough to examine a living skeleton. Meanwhile, the Night Watch is stretched dangerously thin defending Darkshire from fiends on all sides. An able adventurer hunting near the cemeteries frees the local watch to guard the town perimeter.",al={"why doesn't night watch kill skeletons","why send me smitts","why tavernkeep smitts needs you"},it="why_me",add="1e6a32cf"}},ang={["profession:Herbalism"]="Rot blossoms are dark growths rooted in necromantic decay and animated bone. Ordinary herbs flourish in rich soil and sunlight.",["faction:Alliance"]="As an Alliance adventurer, you ease the Night Watch’s daily fight by hunting undead in Duskwood’s cemeteries and helping keep Darkshire from falling."},kw={"darkshire","night watch","raven hill cemetery","rot blossom","skeletal fiend","skeletal horror","tavernkeep smitts","tranquil gardens cemetery","zombie juice"},rel={"quest:158","npc:tavernkeep-smitts","subzone:tranquil-gardens-cemetery","subzone:raven-hill-cemetery","npc:althea-ebonlocke","topic:night-watch","subzone:darkshire","zone:duskwood"},m={start="Tavernkeep Smitts",level="24",faction="Alliance",id=156,ri={"Rot Blossom"}},src={"Gather Rot Blossoms (Classic)"}}
E["quest:157"] = {t="quest",n="Deliver the Thread",z="duskwood",s="In Darkshire, Madame Eva sends Ghost Hair Thread west through Duskwood to Abercrombie near Raven Hill Cemetery. The hermit says he needs it to guard his hut from restless spirits.",h="In Darkshire, Madame Eva sends Ghost Hair Thread west through Duskwood to Abercrombie near Raven Hill...",sec={{t="A Crossing in the Dark",b="Madame Eva gives you a spool of Ghost Hair Thread, spun from hair gathered from the ghost Blind Mary. You carry it west through Duskwood, where spiders and undead roam. Abercrombie waits in his ramshackle shack just north of Raven Hill Cemetery.",sp=0},{t="Threads of Life and Death",b="Abercrombie says he will line his windows and doorframe with the spectral thread to keep out Raven Hill's wailing dead. Madame Eva says Ghost Hair Thread can bind malevolent spirits and sew the semblance of life into dead and inanimate matter. Abercrombie welcomes the spool with delight, then sets his hidden craft in motion.",sp=1}},faq={{q="What is ghost hair thread?",a="Ghost Hair Thread is an enchanted spool Madame Eva spins in Darkshire from hair gathered from the ghost Blind Mary. She says it can bind spirits or sew life into inanimate objects.",al={"ghost hair","what is the thread","ghost thread"},it="item"},{q="Who is Abercrombie?",a="Abercrombie is a reclusive old man in a lonely shack just north of Raven Hill Cemetery. He appears frail and harmless, and says he fears the undead near his home.",al={"hermit","who is abercrombie","shack guy"},it="identity"},{q="Why does Abercrombie claim he needs the thread?",a="Abercrombie says he will string Ghost Hair Thread along his windows and doorways to ward off the ghouls and spirits roaming Duskwood.",al={"why thread","abercrombie excuse","warding spirits"},it="wants"},{q="Where is Abercrombie located?",a="Abercrombie lives in an isolated wooden shack north of Raven Hill Cemetery's main grounds, just off the western road through Duskwood.",al={"abercrombie location","where is the shack","hermit shack"},it="place",gp=true},{q="What happens after giving the thread to Abercrombie?",a="After Abercrombie receives the thread, he rewards you and complains of other pressing needs. He sends travelers after odd alchemical ingredients such as Zombie Juice.",al={"next quest","what comes after","after deliver thread"},it="next_step"},{q="Does Madame Eva know what Abercrombie is up to?",a="Madame Eva does not accuse Abercrombie of foul play. She remarks that Ghost Hair Thread can sew life into inanimate objects, showing she knows its necromantic potential, yet she fulfills the request without protest.",al={"does eva know","madame eva complicit","eva warning"}},{q="Why does Madame Eva want the Ghost Hair Thread delivered to Abercrombie?",a="Madame Eva is fulfilling her end of a bargain. Abercrombie asked for ghost hair thread to ward his hermitage against the restless dead, and Eva agreed to spin it once you brought her Blind Mary's ghost hair. Seeing him as merely a frail, eccentric hermit trying to survive the terrors near Raven Hill, she entrusts you with carrying the completed spool safely to his door.",al={"why does Madame Eva help Abercrombie","Madame Eva motive","why deliver the thread"},it="motive",add="011e87a7"}},ang={["profession:Tailoring"]="Spinning spectral hair into usable spools blends needlecraft with hedge necromancy. The thread can stitch matter beyond the physical realm.",["class:Priest"]="As a priest, you would usually turn to holy rites of the Light to ward a home against restless dead. Abercrombie's reliance on woven remnants of the dead points to a darker path.",["faction:Alliance"]="As an Alliance traveler, you help carry aid from Darkshire through the dangerous western woods to an isolated hermit, while the Night Watch strains to guard the frontier."},kw={"abercrombie","darkshire","deliver the thread","duskwood","ghost hair thread","madame eva","raven hill","raven hill cemetery","zombie juice"},rel={"quest:149","npc:abercrombie","npc:madame-eva","subzone:raven-hill-cemetery","zone:duskwood","quest:163"},m={start="Madame Eva",["end"]="Abercrombie",level="24",faction="Alliance",id=157},src={"Deliver the Thread (Classic)"}}
E["quest:158"] = {t="quest",n="Zombie Juice",z="duskwood",s="Abercrombie sends travelers from his lonely shack in Duskwood to Darkshire for Zombie Juice. He says the night’s chill leaves him cold.",h="Abercrombie sends travelers from his lonely shack in Duskwood to Darkshire for Zombie Juice.",sec={{t="A Chilly Request",b="Abercrombie lives alone among the horrors of Duskwood’s shadowed woods and often sends travelers on strange errands. He says the creeping dusk drains his warmth and vitality, then asks you to travel east to Darkshire. At the Scarlet Raven Tavern, Tavernkeep Smitts sells the potent drink Abercrombie seeks. Its ominous name is Zombie Juice, and Abercrombie says it will put fire back in his veins.",sp=0},{t="At the Scarlet Raven",b="Tavernkeep Smitts serves weary guards and frightened townsfolk at Darkshire’s tavern, but few ask for Zombie Juice. The drink is known for its dangerous strength, and Smitts recognizes the vintage. Abercrombie’s taste for such a morbid brew raises quiet eyebrows in a region besieged by the restless dead.",sp=0}},faq={{q="What is Zombie Juice?",a="Zombie Juice is an exceptionally strong liquor with a morbid name, sold by Tavernkeep Smitts at the Scarlet Raven Tavern in Darkshire. Ordinary patrons rarely ask for it.",al={"zombie juice drink","what is the liquor","zombie juice lore"},it="item"},{q="Who sends you to fetch Zombie Juice?",a="The hermit Abercrombie sends you to fetch Zombie Juice. He lives alone in a shack in western Duskwood and says the drink will warm his cold bones.",al={"who gives quest zombie juice","abercrombie quest drink","hermit drink request"},it="identity"},{q="Where do you turn in the quest?",a="You speak with Tavernkeep Smitts inside the Scarlet Raven Tavern, Darkshire’s central inn in eastern Duskwood.",al={"where is smitts","turn in zombie juice","smitts location"},it="place",gp=true},{q="Why does Abercrombie want it?",a="Abercrombie says Duskwood’s gloomy, shadowed nights leave him shivering, and he needs the fiery drink to warm his blood.",al={"why does abercrombie need juice","abercrombie cold","why does he drink zombie juice"},it="motive"},{q="Is Tavernkeep Smitts surprised by the order?",a="Yes. Smitts says Zombie Juice is extraordinarily potent, and his regular customers rarely ask for it.",al={"smitts reaction","does smitts have zombie juice","smitts dialogue"}},{q="Does this quest involve fighting any monsters?",a="No. You travel along the road from Abercrombie’s secluded hut to Darkshire and speak with Tavernkeep Smitts. Duskwood’s roads are also fraught with wandering beasts and undead.",al={"zombie juice combat","is zombie juice dangerous","zombie juice mobs"},gp=true},{q="Why does Abercrombie need you to get the Zombie Juice?",a="Abercrombie lives as a frail, solitary hermit secluded out in the gloomy haunted woods near Raven Hill. Traveling across the creature-infested roads of Duskwood all the way to Darkshire just to visit the Scarlet Raven Tavern is far too dangerous for an elderly recluse, especially when capable adventurers like you are willing to run his errands.",al={"why can't Abercrombie get it","why me zombie juice","why send me for zombie juice"},it="why_me",add="aa8c42e6"}},ang={["faction:Alliance"]="As an Alliance adventurer, you may carry messages for the eccentric recluses along Duskwood’s perilous roads while supporting Darkshire’s embattled outpost."},kw={"abercrombie","darkshire","duskwood","liquor","scarlet raven tavern","tavernkeep smitts","zombie juice"},rel={"npc:abercrombie","npc:tavernkeep-smitts","subzone:scarlet-raven-tavern","subzone:darkshire","zone:duskwood"},m={start="Abercrombie",["end"]="Tavernkeep Smitts",level="24",faction="Alliance",id=158},src={"Zombie Juice (Classic)"}}
E["quest:159"] = {t="quest",n="Juice Delivery",z="duskwood",s="In Darkshire, you carry Zombie Juice west to a hermit on Duskwood’s edge. Tavernkeep Smitts says the brew is stout enough to raise the dead. It is meant to warm Abercrombie, though its potency raises questions.",h="In Darkshire, you carry Zombie Juice west to a hermit on Duskwood’s edge.",sec={{t="A Dubious Concoction",b="Tavernkeep Smitts brews a legendary draught in Darkshire. When the Zombie Juice is ready, he hands you the bottle and warns you to handle it gently. He says the concoction is stout enough to raise the dead. You carry it across the haunted forest to an eccentric loner, in what seems a simple act of charity.",sp=0},{t="The Hermit's Slip",b="Abercrombie lives in a shack on the edge of the woods, where you bring him the volatile brew. The frail recluse says he needs the liquor to warm his aching bones through Duskwood’s freezing, fog-choked nights. As he takes the bottle, he nearly thanks you for your “foolishness,” then quickly corrects himself and praises your “kindness.” His slip hints that he has plans for the brew beyond an evening drink.",sp=1}},faq={{q="What is Zombie Juice?",a="Zombie Juice is an extremely potent brew made by Tavernkeep Smitts at the Scarlet Raven Tavern in Darkshire. He says it is stout enough to wake the dead, far stronger than ordinary spirits.",al={"zombie juice lore","what is smitts juice","abercrombie drink"},it="item"},{q="Who orders the Zombie Juice?",a="Abercrombie, an eccentric old hermit, requests the Zombie Juice. He lives in a lonely shack near Duskwood’s western boundary.",al={"who wants the juice","who is juice delivery for"},it="identity"},{q="Why does Abercrombie want the drink?",a="Abercrombie claims he needs the drink to keep warm during Duskwood’s bitterly cold, damp nights. When he receives it, his slip of the tongue hints at sinister designs for the brew.",al={"why does abercrombie need juice","abercrombie cold"},it="purpose"},{q="Who brews the Zombie Juice?",a="Tavernkeep Smitts brews Zombie Juice himself at the Scarlet Raven Tavern in the heart of Darkshire, once he has the pungent ingredients he needs.",al={"who makes zombie juice","smitts barkeep"},it="origin"},{q="Where is Abercrombie's shack?",a="Abercrombie’s isolated shack is in western Duskwood, just north of Raven Hill Cemetery.",al={"abercrombie location","where is abercrombie shack"},it="place",gp=true},{q="What does Abercrombie do next after receiving the juice?",a="After securing the Zombie Juice, Abercrombie keeps imposing on gullible travelers. He sends them into Raven Hill Cemetery to gather ghoul ribs for a ghoulish effigy he claims will keep the undead away.",al={"next quest after juice delivery","what happens next"},it="next_step"},{q="Why does Tavernkeep Smitts want the juice delivered?",a="Smitts runs the Scarlet Raven Tavern in Darkshire and has completed his part of the transaction by brewing the potent concoction Abercrombie requested. With the beverage bottled and ready, his only interest is seeing the promised order fulfilled and sent out of his hands, warning you along the way to handle the volatile drink with care.",al={"why does smitts want this done","tavernkeep smitts motive","why deliver zombie juice"},it="motive",add="9f2016f2"},{q="Why does Smitts have an adventurer deliver the juice instead of going himself?",a="Tavernkeep Smitts must tend the bar at the Scarlet Raven Tavern, and wandering the shadowy roads of Duskwood is far too perilous an undertaking for an ordinary barkeep. Abercrombie's hermitage sits across the shadowed woods near Raven Hill, an area crawling with undead and wild beasts that only an armed traveler can safely traverse.",al={"why me smitts","why cant smitts deliver the juice","why doesnt the barkeep go"},it="why_me",add="6bab1f80"}},ang={["faction:Alliance"]="As an Alliance courier, you brave Duskwood’s perilous roads for Darkshire’s citizens. Trusting every hermit in the woods can bring unforeseen trouble.",["profession:Cooking"]="As a cook, you can see that Tavernkeep Smitts’ Zombie Juice recipe relies on pungent, unconventional ingredients and tests what belongs in a tavern beverage."},kw={"abercrombie","darkshire","duskwood","juice delivery","scarlet raven","tavernkeep smitts","zombie juice"},rel={"quest:158","npc:abercrombie","npc:tavernkeep-smitts","zone:duskwood"},m={start="Tavernkeep Smitts",["end"]="Abercrombie",level="24",faction="Alliance",id=159},src={"Juice Delivery (Classic)"}}
E["quest:160"] = {t="quest",n="Note to the Mayor",z="duskwood",s="In western Duskwood, Abercrombie sends a message to Darkshire, where the mayor awaits an unexpected delivery. He calls himself an old friend of Mayor Lord Ello Ebonlocke, but the note raises questions.",h="In western Duskwood, Abercrombie sends a message to Darkshire, where the mayor awaits an unexpected delivery.",sec={{t="A Friendly Message?",b="You return Abercrombie’s stolen chest from the ogres at Vul'Gol Ogre Mound, then carry his message down the misty roads to town. The hermit laughs with delight. He says he and Mayor Lord Ello Ebonlocke are old friends, and insists the mayor will be just as thrilled by what you have done.",sp=0},{t="Puzzled Leadership",b="At Darkshire’s town hall, Mayor Lord Ello Ebonlocke says he has never heard of Abercrombie. The parchment offers no greeting he can read. Its ancient script leaves the mayor baffled.",sp=1}},faq={{q="Who sends the Note to the Mayor?",a="Abercrombie gives you the letter after you recover his stolen possessions from the local ogres. He lives alone in a shack on Duskwood’s western edge.",al={"who gives note to the mayor","who starts note to the mayor","abercrombie letter sender"},it="identity"},{q="Are Abercrombie and Mayor Ebonlocke actually friends?",a="No. Abercrombie calls them old acquaintances, but Mayor Lord Ello Ebonlocke has never heard of him and cannot make sense of the message.",al={"do they know each other","is abercrombie friends with the mayor","abercrombie ello ebonlocke relationship"},it="ties"},{q="What is written in the note?",a="The note is written in an ancient, obscure language. Neither you nor Mayor Ebonlocke can decipher it, so he asks for help with a translation.",al={"what does abercrombie note say","can ello read the note","what language is the letter"},it="item"},{q="Where is Lord Ello Ebonlocke located?",a="Mayor Lord Ello Ebonlocke is inside the Darkshire Town Hall, on the east side of town along Duskwood’s main road.",al={"where is the mayor","ello ebonlocke location","where do i turn in note to the mayor"},it="place",gp=true},{q="What happens after Mayor Ebonlocke receives the letter?",a="Unable to read the mysterious script, Lord Ebonlocke asks you to find someone who can interpret it. He sends you to have Abercrombie’s note translated.",al={"what is next after note to the mayor","what follows note to the mayor"},it="next_step"},{q="Why was Abercrombie laughing when he gave you the letter?",a="Abercrombie laughs with delight when he gives you the letter, but the text gives no reason why. His claim of friendship leaves Darkshire’s mayor baffled.",al={"why does abercrombie laugh","is abercrombie evil","abercrombie laugh note"},sp=1,it="motive"},{q="Why does Abercrombie send you with the letter instead of delivering it himself?",a="Abercrombie lives as a frail, solitary hermit sequestered away in the haunted woods far to the west of Darkshire. Having an unsuspecting traveler who just assisted him carry his message lets him deliver his ominous surprise directly to the town hall without ever setting foot near Darkshire's suspicious Night Watch or its town council.",al={"why send me note to the mayor","why abercrombie doesnt deliver letter","why use player to deliver letter"},it="why_me",add="7816d016"}},ang={["faction:Alliance"]="Darkshire’s safety depends on finding the cause of strange disturbances before they reach the Night Watch’s perimeter. The suspicious letter needs the attention of Alliance agents.",["race:Human"]="As a human courier serving the Night Watch and the House of Ebonlocke, you may find that the old hermit on Duskwood’s outskirts is not as straightforward as he seems."},kw={"abercrombie","darkshire","duskwood","ello ebonlocke","letter","mayor","note to the mayor"},rel={"npc:abercrombie","npc:lord-ello-ebonlocke","quest:251","subzone:darkshire","zone:duskwood"},m={start="Abercrombie",["end"]="Lord Ello Ebonlocke",level="30",faction="Alliance",id=160},src={"Note to the Mayor (Classic)"}}
E["quest:163"] = {t="quest",n="Raven Hill",z="duskwood",s="In far western Duskwood, a light flickers in a ruined window at Raven Hill. Elaine Carevin sends travelers from Darkshire to learn what has taken shelter there.",h="In far western Duskwood, a light flickers in a ruined window at Raven Hill.",sec={{t="Eyes in the West",b="The Night Watch has long left Duskwood’s far west to the dead and the wilderness. Yet signs of life there demand attention. Calor, a watcher on the gloomy roads, saw movement among Raven Hill’s silent houses two nights in a row. A lantern flickered in a window. With ghouls, skeletons, and beasts across the land, the Night Watch cannot ignore what stirs among the ruins.",sp=0},{t="A Rattled Hermit",b="Inside Raven Hill, Jitters trembles at every sound in the dark. The vagabond huddles among the ruined buildings and insists there is no danger beyond harmless Jitters. His frantic rambling hints that he knows more about the nightmare consuming Duskwood than he dares to say.",sp=1}},faq={{q="Who sends you to investigate Raven Hill?",a="Elaine Carevin lives in Darkshire and assists the Night Watch. Concerned for Duskwood’s safety, she asks travelers to investigate disturbing reports from the west.",al={"who gives raven hill quest","quest giver raven hill","elaine carevin quest"},it="identity"},{q="What did Calor actually see in Raven Hill?",a="Calor saw shadows moving through Raven Hill’s abandoned settlement two nights in a row. The night before, he saw a lantern or candle burning in a building window.",al={"what did calor see","calor sighting raven hill","shadows in raven hill"},it="threat"},{q="What monster is haunting the ruins?",a="You are sent to discover what haunts Raven Hill. Calor saw moving shadows and a light in a window, but only a visit to the ruined buildings can reveal what lurks there.",al={"who is haunting raven hill","what is in raven hill","is raven hill monster real"},sp=1,it="target"},{q="Who is Jitters?",a="Jitters is a paranoid vagrant living in western Duskwood, always close to terror. He claims to be harmless, but his guilt and frantic rambling hint at a connection to the region’s darker mysteries.",al={"jitters lore","who is jitters duskwood","why is jitters hiding"},sp=1,it="identity"},{q="Where is Raven Hill located?",a="Raven Hill lies in far western Duskwood, just south of the great undead-infested cemetery that shares its name.",al={"raven hill location","where to find raven hill","raven hill map"},it="place",gp=true},{q="Why is the Night Watch so concerned about moving shadows?",a="Darkshire’s defenders are stretched thin by skeletal uprisings, feral worgen, and lurking spiders. Strange inhabitants or organized movement in the abandoned west could threaten the remaining living settlements.",al={"why care about raven hill","night watch raven hill"},it="threat"},{q="Why does Elaine Carevin want Raven Hill investigated?",a="Elaine Carevin is dedicated to keeping Duskwood safe. With the Night Watch already stretched thin against the horrors creeping through the woods, strange lights and moving shadows in the abandoned settlement of Raven Hill cannot be ignored. She needs someone to discover whether a new threat is taking root on the western edge of the region.",al={"why does elaine send you","elaine carevin motive","why investigate raven hill"},it="motive",add="2c575d43"},{q="Why does Elaine Carevin ask an adventurer instead of the Night Watch?",a="The Night Watch is dangerously undermanned and overwhelmed just trying to hold Darkshire's perimeter and protect the roads. With every able-bodied defender tied down guarding against the undead, spiders, and worgen, Elaine relies on capable travelers willing to venture into the derelict ruins of Raven Hill.",al={"why me raven hill","why doesn't elaine send night watch","why ask an adventurer"},it="why_me",add="2a1c77d7"}},ang={["faction:Alliance"]="The Night Watch receives little or no aid from Stormwind’s garrison. As an Alliance hero, you may be called on to investigate threats in Duskwood’s ruined corners.",["class:Paladin"]="As a paladin, you are trained to hunt the restless undead in the neighboring cemetery. The trembling, flesh-and-blood Jitters may be an unexpected discovery."},kw={"calor","darkshire","duskwood","elaine carevin","jitters","night watch","raven hill"},rel={"zone:duskwood","npc:jitters","npc:calor","topic:light"},m={start="Elaine Carevin",["end"]="Jitters",level="20",faction="Alliance",id=163},src={"Raven Hill (quest)"}}
E["quest:164"] = {t="quest",n="Deliveries to Sven",z="duskwood",s="In Darkshire, Elaine Carevin sends supplies to Sven Yorgen's camp in northwestern Duskwood. Sven and his few followers face the dangers of the blighted woods.",h="In Darkshire, Elaine Carevin sends supplies to Sven Yorgen's camp in northwestern Duskwood.",sec={{t="A Lifeline to the Wilderness",b="Sven Yorgen and a few companions keep a camp on Duskwood's northwestern frontier. Wolves, spiders, and restless dead threaten Darkshire, yet Sven's band holds its ground beyond the town's walls. Danger keeps them from sparing anyone for the perilous journey back to town for provisions. Elaine Carevin arranges for travelers to carry supplies so the fighters can hold on.",sp=0},{t="The Carevin Connection",b="The Carevin family respects Sven and sees his stand as devotion to the Light. Elaine organizes supplies and sends them to his camp. When Sven receives the crate, he knows the Carevins are supporting him. His attention stays on the battle at hand.",sp=0}},faq={{q="Who is Sven Yorgen?",a="Sven Yorgen is a frontiersman with an armed camp on Duskwood's northwestern edge. Elaine Carevin sees him as an upright fighter serving the Light. He and his small band face the terrors of the surrounding woods.",al={"who is sven","sven lore","sven yorgen info"},it="identity"},{q="Why does Sven need supplies brought to him?",a="Sven's small band must stay on guard against the dangers around them. They cannot spare anyone for the dangerous journey to Darkshire and back, so they rely on townsfolk and passing couriers for supplies.",al={"why can't sven get supplies","sven supplies","why delivery"},it="why_wanted"},{q="Who provides the supplies?",a="Elaine Carevin provides supplies from Darkshire. Her family respects Sven's devotion and arranges aid for his camp.",al={"who sends supplies","elaine carevin","carevin family"},it="origin"},{q="Where is Sven's camp located?",a="Sven's camp lies against Duskwood's northwestern mountains, far past the road and north of the blighted farmland, on the edge of the wilderness.",al={"where is sven","sven location","sven camp"},it="place",gp=true},{q="Is this delivery mandatory before helping Sven further?",a="No. Travelers who find Sven's camp on their own can help him without carrying Elaine's crate.",al={"is deliveries to sven required","do i need deliveries to sven","deliveries prerequisite"},gp=true},{q="What does Sven do after receiving the delivery?",a="Sven thanks the Carevin family for its support, then turns to the threats facing his camp and his family's past. He seeks fighters to help him pursue vengeance.",al={"what happens next","after deliveries to sven","sven next quest"},it="next_step"},{q="Why does Elaine Carevin want supplies delivered to Sven?",a="Elaine Carevin holds Sven Yorgen in high regard, viewing his crusade in the wilderness as true work of the Light. Her family regularly supports his cause with essential provisions, but Sven's band is far too small to spare anyone to walk into Darkshire and collect them safely.",al={"why does elaine send supplies","elaine carevin motive","why help sven elaine"},it="motive",add="cd88e308"},{q="Why does Elaine Carevin ask you instead of the Night Watch?",a="The Night Watch is already stretched to its breaking point just guarding Darkshire and patrolling the main roads from the undead and beasts of Duskwood. They have no guards to spare for supply runs to an isolated camp out in the northwestern wild.",al={"why does elaine need me","why not send the night watch","why deliver supplies myself"},it="why_me",add="d0ad7f5e"}},ang={["faction:Alliance"]="Outlying sentinels like Sven show how far the Alliance's reach has frayed in Duskwood. Voluntary couriers bring supplies where regular garrison lines no longer reach.",["class:Paladin"]="Elaine sees Sven as a man doing the work of the Light. As a paladin, you can aid a fellow fighter under siege.",["race:Human"]="The Carevins and Sven's followers show the grit of Stormwind's rural folk. As a human, you know they refuse to abandon Duskwood despite its gloom."},kw={"carevin","darkshire","duskwood","elaine carevin","light","supplies for sven","sven yorgen"},rel={"npc:sven-yorgen","quest:95","zone:duskwood","quest:1042","topic:light"},m={start="Elaine Carevin",["end"]="Sven Yorgen",level="23",faction="Alliance",id=164},src={"Deliveries to Sven"}}
E["quest:165"] = {t="quest",n="The Hermit",z="duskwood",s="In Darkshire, Elaine Carevin asks you to check on Abercrombie, an elderly recluse who has stopped coming for provisions. His rickety shack stands at the edge of Raven Hill Cemetery.",h="In Darkshire, Elaine Carevin asks you to check on Abercrombie, an elderly recluse who has stopped coming for...",sec={{t="A Neighborly Check-In",b="Elaine Carevin recalls an old man who once came to Darkshire for provisions, then stopped appearing. With danger on Duskwood’s roads, she asks you to visit his shack by Raven Hill Cemetery and find out whether he is safe.",sp=0},{t="The Recluse of Raven Hill",b="At the shack, you find Abercrombie alive. He chuckles at the Carevins’ concern and says age and the monsters in the woods have kept him from town. Glad to have an able traveler at his door, he quickly asks for help with a few errands.",sp=0}},faq={{q="Who starts this errand?",a="Elaine Carevin, who lives in Darkshire, asks you to check on an old hermit who once came to town for supplies.",al={"who gives the hermit","where to start the hermit","elaine carevin quest"},gp=true},{q="Where is the hermit located?",a="Abercrombie lives in a wooden shack at the northern edge of Raven Hill Cemetery in western Duskwood.",al={"where is abercrombie","hermit location duskwood","shack near raven hill"},gp=true},{q="Why was Elaine Carevin worried about him?",a="Abercrombie used to visit Darkshire for supplies, but stopped coming. With beasts and undead on the roads, Elaine feared he had died.",al={"why check on abercrombie","why is elaine worried","what happened to the old man"},it="motive"},{q="Is Abercrombie actually in danger when you find him?",a="No. Abercrombie is alive when you reach his shack. He says age and dangerous roads made travel too burdensome.",al={"is abercrombie ok","is the hermit dying","did the hermit get attacked"},it="threat"},{q="Why does someone choose to live right next to Raven Hill Cemetery?",a="Abercrombie says he prefers the seclusion. His home beside one of the Eastern Kingdoms’ most necromantically corrupted graveyards unsettles many travelers.",al={"why live by raven hill","abercrombie cemetery shack","why is the hermit near graves"},it="place"},{q="What does Abercrombie ask for once you reach him?",a="Abercrombie quickly asks you to help with a few errands around the woods.",al={"what does abercrombie want","hermit followup quest","what comes after the hermit"},it="next_step"},{q="Why does Elaine Carevin ask an adventurer to check on Abercrombie?",a="Darkshire's local Night Watch is already stretched dangerously thin holding the perimeter against ravenous beasts, feral worgen, and the restless dead. Venturing deep into the western forests toward Raven Hill simply to check on an eccentric hermit is a luxury the town guards cannot afford, making capable travelers the only real option.",al={"why send me","why does elaine need an adventurer","why don't the guards check on the hermit"},it="why_me",add="e8a34d53"}},ang={["faction:Alliance"]="The Night Watch struggles to protect the roads between Darkshire and Raven Hill. Recluses like Abercrombie are left cut off from the town’s safety.",["race:Human"]="As a human, you know the Carevin family’s neighborly ties. They look out for Duskwood’s elders even as shadow falls over the region."},kw={"abercrombie","darkshire","duskwood","elaine carevin","raven hill cemetery","shack","the hermit"},rel={"npc:abercrombie","subzone:raven-hill-cemetery","zone:duskwood","quest:163"},m={start="Elaine Carevin",["end"]="Abercrombie",level="25",faction="Alliance",id=165},src={"The Hermit (Classic)"}}
E["quest:173"] = {t="quest",n="Worgen in the Woods",z="duskwood",s="In Darkshire, Calor sends hunters against Nightbane Shadow Weavers in Duskwood. The disillusioned former guardsman is stationed in town, and the hunt runs through Brightwood Grove and the Rotting Orchard. Those who face the worgen prove their mettle to Master Jonathan Carevin's monster hunters.",h="In Darkshire, Calor sends hunters against Nightbane Shadow Weavers in Duskwood.",sec={{t="A Private Vigil",b="The Night Watch struggles against undead, spiders, and outlaws along Darkshire's borders. Calor grew weary of guards too slow and complacent to cleanse the land. He left the Watch and joined Master Jonathan Carevin, turning his blade against heresy and corruption.\n\nCarevin admits no one lightly to his circle. Those who want to aid him must first show they can survive the woods' fiercest horrors.",sp=0},{t="The Nightbane Lurkers",b="Feral worgen rule Brightwood Grove and the blighted Rotting Orchard. Among them, Nightbane Shadow Weavers use dark magic to blind and ensnare their victims before tearing them apart. Calor sends aspiring hunters to slay these spell-weaving beasts. Their courage is tested as the threat is thinned, though its origins deeply unsettle Darkshire's defenders.",sp=0},{t="Monsters from Nowhere",b="Worgen have become an inescapable nightmare in Duskwood, yet no one can explain their presence. Calor says they seemed to appear from thin air, with no natural lineage in the region. Unlike ravenous feral wolves or corpses risen from local barrows, these bipedal predators wield bizarre, alien sorceries and bring ravenous fury.\n\nSlaying the Shadow Weavers proves a hunter's skill, but only touches the surface of an unnatural infestation taking root across the forest.",sp=1}},faq={{q="Who is Calor?",a="Calor is a hunter and former member of Darkshire's Night Watch. Frustrated by the town militia's cautious ways, he joined Master Jonathan Carevin to hunt the creatures threatening Duskwood.",al={"calor","calor darkshire","who gives worgen in the woods"},it="identity"},{q="Why does Calor want Nightbane Shadow Weavers killed?",a="Calor uses the Nightbane Shadow Weavers to test skill and courage. Those who want to aid Master Carevin must show they can hunt dangerous spell-weaving worgen and help defend the town.",al={"why kill shadow weavers","worgen in the woods goal"},it="motive"},{q="Where are the Nightbane Shadow Weavers found?",a="Nightbane Shadow Weavers prowl Brightwood Grove and the Rotting Orchard, west and southwest of Darkshire. The orchard grounds are abandoned and overgrown.",al={"where are nightbane shadow weavers","shadow weaver location"},it="place",gp=true},{q="Where did the worgen in Duskwood come from?",a="The worgen's sudden appearance is a mystery to Duskwood's people. Calor says the beasts seemed to materialize from nowhere, bringing dark shadow magic and ravenous fury to a forest already on the brink of collapse.",al={"worgen origin duskwood","why are worgen in duskwood","where do worgen come from"},it="origin"},{q="Who is Master Carevin?",a="Master Jonathan Carevin is an independent monster hunter based in Darkshire. He and his followers work outside the Night Watch, hunting evil, undead, and bizarre monstrosities across the region.",al={"carevin","master carevin","who is master carevin"},it="identity"},{q="Why did Calor leave the Night Watch?",a="Calor grew disillusioned with what he saw as the Night Watch's passivity and complacency. Rather than manning perimeter fences while darkness closed in, he chose Carevin's active hunt against evil.",al={"why did calor leave the watch","calor night watch"},it="history"},{q="What are the Nightbane Shadow Weavers?",a="Nightbane Shadow Weavers are spellcasting worgen lurking in places like Brightwood Grove and the Rotting Orchard. These lupine beasts appeared suddenly across Duskwood, wielding dark magics that threaten Darkshire's borders. Calor and Master Carevin view their sudden arrival as an active blight upon the woods that must be stamped out.",al={"who are nightbane shadow weavers","nightbane shadow weaver","what are the worgen"},it="target",add="e85e2f18"},{q="Why does Calor need you to hunt the worgen instead of doing it himself?",a="Calor has broken away from the Night Watch, having grown disillusioned with their complacency and inaction. Now serving Master Carevin in their dedicated quest to purge heresy and evil from Duskwood, Calor expects newcomers seeking to join their cause to prove themselves through deeds rather than empty words.",al={"why send me","why does calor need me","why not night watch"},it="why_me",add="5ce72e6e"}},ang={["faction:Alliance"]="Darkshire feels abandoned by Stormwind's high seat, leaving townspeople and vigilantes like Calor to seek out any roaming Alliance adventurer who can hold back the monsters.",["race:Human"]="For humans from Elwynn or Westfall, Duskwood's ruined farms, such as the Rotting Orchard, warn what unchecked dark magic can do to a kingdom's breadbaskets.",["class:Hunter"]="Hunting the Nightbane tests tracking and knowledge of beasts to the limit. Worgen are neither natural wildlife nor ordinary human outlaws; they are bipedal horrors wielding shadow spells."},kw={"brightwood grove","calor","carevin","darkshire","duskwood","nightbane","rotting orchard","shadow weaver","worgen"},rel={"npc:calor","zone:duskwood","subzone:brightwood-grove","subzone:rotting-orchard","subzone:darkshire","topic:worgen"},m={start="Calor",level="28",faction="Alliance",id=173},src={"Worgen in the Woods (Classic)"}}
E["quest:174"] = {t="quest",n="Look To The Stars",z="duskwood",s="In Duskwood, Viktori Prism'Antras looks to the skies for answers to the forest's curse. He trusts observation over arcane superstition and asks you to gather parts for a telescope designed by his gnomish associate.",h="In Duskwood, Viktori Prism'Antras looks to the skies for answers to the forest's curse.",sec={{t="Searching the Skies",b="Many in fearful Darkshire blame Duskwood's troubles on black magic, curses, and restless dead. Viktori Prism'Antras doubts these alone explain the land's corruption. He believes answers may lie above the canopy. With blueprints from his gnomish partner, Cog, he plans to build an instrument for studying the heavens.",sp=0},{t="A Matter of Engineering",b="Viktori needs a sturdy frame to begin building his instrument for stargazing. Cog's plans call for a machined bronze tube, and Viktori asks you to find one. He trusts practical engineering and careful observation to shed light where mysticism has failed.",sp=0}},faq={{q="Who is Viktori Prism'Antras?",a="Viktori Prism'Antras is a scholarly resident of Darkshire who seeks rational answers to Duskwood's corruption by studying the stars.",al={"viktori","who gives look to the stars","viktori prismantras"},it="identity"},{q="Why does Viktori want to build a telescope?",a="Viktori believes the skies may hold a tangible answer to Duskwood's strange transformation, beyond what magic and local legends can explain.",al={"why look at stars","why bronze tube duskwood","telescope quest darkshire"},it="motive"},{q="Who is Cog?",a="Cog is Viktori's gnomish engineer friend, who drew the blueprints for the stargazing device.",al={"cog gnome","who designed telescope"},it="ties"},{q="Where does one obtain a bronze tube?",a="Engineers craft bronze tubes. Travelers who cannot make one may find one through trade, at auction houses, or from traveling engineering peddlers with spare stock.",al={"how to get bronze tube","bronze tube location","where find bronze tube"},gp=true},{q="Is this part of a longer questline?",a="Yes. It begins a longer effort to assemble and calibrate Viktori's stargazing apparatus in Darkshire.",al={"look to the stars chain","how many look to the stars quests"},it="next_step",gp=true},{q="Why is Viktori looking for natural explanations in Duskwood?",a="Though undead and dark enchantments fill the forest, Viktori believes natural laws may govern its transformation. He studies the heavens in search of answers.",al={"why scientific explanation duskwood","magic vs science duskwood"},it="why_wanted"},{q="What is the Bronze Tube for?",a="The bronze tube serves as the structural body for the telescope Viktori Prism'Antras is constructing. Following the blueprints provided by his gnomish partner, Cog, the metal casing forms the essential housing needed to assemble optical lenses and align the instrument toward the heavens.",al={"what is bronze tube used for","why does viktori need a bronze tube","viktori bronze tube purpose"},it="item",add="45e6e811"}},ang={["profession:Engineering"]="Gnomish design and skilled metalwork drive Viktori's effort, giving engineers a direct hand in his study of the stars.",["race:Gnome"]="Viktori depends on his gnomish associate, Cog, whose craft brings order and reason to a dark corner of the kingdom.",["faction:Alliance"]="Night Watch patrols fend off horrors along Darkshire's roads, while Viktori's project gives the town hope of understanding what poisoned their home."},kw={"bronze tube","cog","darkshire","duskwood","look to the stars","telescope","viktori prism'antras"},rel={"npc:viktori-prism-antras","subzone:darkshire","zone:duskwood"},m={start="Viktori Prism'Antras",level="25",faction="Alliance",id=174,ri={"Bronze Tube"}},src={"Look To The Stars (Classic)"}}
E["quest:175"] = {t="quest",n="Look To The Stars",z="duskwood",s="Viktori Prism'Antras needs a mirror for the telescope he is building in Darkshire from Cog's blueprints. He sends you south to find Mary, known for carrying a looking glass.",h="Viktori Prism'Antras needs a mirror for the telescope he is building in Darkshire from Cog's blueprints.",sec={{t="A Reflective Surface",b="Viktori Prism'Antras has the bronze tube for his telescope. Cog's blueprints call for a mirror to guide and reflect light through it. Fine silvered glass is hard to make while Darkshire faces shortages. So Viktori recalls Mary, a local woman known across the region for carrying a looking glass.",sp=0},{t="Searching the South",b="Mary's old home lies deep in southern Duskwood, just north of Tranquil Gardens Cemetery. To reach it, you pass beyond the Night Watch's safe patrols. Blighted groves lie ahead, where ravenous wolves, feral spiders, and wandering undead roam.",sp=0},{t="A Tragic Resident",b="Blind Mary is a wandering spirit near her old home and the cemetery. Her shack in the south reveals what became of the woman Viktori remembered. Bound to memories and possessions from her former life, she remains near the place she once called home.",sp=1}},faq={{q="What is Viktori Prism'Antras building?",a="Viktori is building an astronomical telescope in his hut up the hill in Darkshire. He follows designs made by Cog, a tinker.",al={"viktori telescope","look to the stars project","what is viktori making"},it="purpose"},{q="Why does Viktori need a looking glass?",a="Cog's blueprints call for a mirror to reflect and focus light through the telescope. Viktori remembers Mary carried a looking glass and hopes to use it in the assembly.",al={"why need mirror","reflective surface telescope"},it="why_wanted"},{q="Where can Mary be found?",a="Mary's ruined home is in southeastern Duskwood, just north of Tranquil Gardens Cemetery.",al={"where is mary","mary location duskwood","find blind mary"},it="place",gp=true},{q="Who is Mary?",a="Mary lived in southern Duskwood before the land fell into cursed darkness. People around Darkshire knew her for carrying a looking glass. At her old home near Tranquil Gardens Cemetery, you can learn what became of her.",al={"who is blind mary","blind mary backstory"},sp=1,it="target"},{q="Does Mary still have her looking glass?",a="Mary says she once owned a looking glass, but no longer has it. She can only point you toward where it went.",al={"does mary have mirror","blind mary looking glass"},sp=1,it="item"},{q="What dangers surround Mary's cottage?",a="Undead, feral duskbats, venom web spiders, and rabid wolves prowl the southeastern woods and Tranquil Gardens Cemetery. They prey on travelers who venture south of Darkshire.",al={"hazards near mary","tranquil gardens cemetery threats"},it="danger"},{q="Why is Viktori Prism'Antras so focused on finishing his telescope?",a="Viktori Prism'Antras is consumed by his ambition to complete an astronomical telescope in his hut in Darkshire. Following the blueprints provided by the gnome Cog, he requires specialized components to reflect and focus light. He hopes to peer beyond the perpetual gloom shrouding Duskwood, and gathering each obscure part is essential to bringing his grand contraption to life.",al={"why does viktori want this done","viktori prism'antras motive","why build the telescope"},it="motive",add="9372b916"}},ang={["faction:Alliance"]="As an Alliance member, helping Viktori build his telescope brings a rare glimmer of curiosity and progress to a town consumed by terror and rot.",["profession:Engineering"]="As an engineer, you follow precise optical plans for telescope assembly. Gnomish blueprints guide the work of reflecting and magnifying faint starlight."},kw={"blind mary","darkshire","duskwood","look to the stars","looking glass","mary","telescope","tranquil gardens","viktori prism'antras"},rel={"npc:viktori-prism-antras","npc:blind-mary","zone:duskwood","subzone:tranquil-gardens-cemetery","topic:light","quest:174"},m={start="Viktori Prism'Antras",["end"]="Blind Mary",level="25",faction="Alliance",id=175},src={"Look To The Stars (2)"}}
E["quest:177"] = {t="quest",n="Look To The Stars",z="duskwood",s="In Darkshire, Viktori Prism'Antras needs Blind Mary's looking glass for his telescope. An Insane Ghoul carried it to Tranquil Gardens Cemetery in southern Duskwood.",h="In Darkshire, Viktori Prism'Antras needs Blind Mary's looking glass for his telescope.",sec={{t="A Relic of Better Days",b="Blind Mary once treasured an ornate looking glass. An incident took her sight and sanity and left her a weeping spirit. In despair, she threw the glass into the dirt behind her family barn. Now Viktori Prism'Antras, an astronomer in Darkshire, needs the mirror for his telescope. The looking glass was taken long before he began studying the heavens.",sp=0},{t="The Graveyard Scavenger",b="An Insane Ghoul scavenged the looking glass from behind the ruined farmsteads. Restless hunger drove it south, carrying the mirror to Tranquil Gardens Cemetery. It haunts an abandoned chapel among overgrown tombstones. You face the flesh-eating horrors of the southern woods to reclaim Mary's lost treasure from its rotting claws.",sp=0}},faq={{q="Why does Viktori need Mary's looking glass?",a="Viktori Prism'Antras needs Mary's looking glass for the telescope he is assembling in his hut up the hill in Darkshire. Its reflective surface suits his invention, which gathers dim starlight.",al={"viktori mirror","why looking glass","what is the mirror for"},it="item"},{q="Who is the Insane Ghoul that stole the mirror?",a="The Insane Ghoul is an undead scavenger that gathered trinkets from abandoned homesteads near Mary's house. It fled south to the ruined chapel in Tranquil Gardens Cemetery.",al={"where is the insane ghoul","who has the looking glass","ghoul in chapel"},it="target"},{q="Why did Blind Mary throw her looking glass away?",a="An incident took Blind Mary's sight and sanity and left her a restless shade. Unable to bear looking at or holding her looking glass, she cast it behind her barn in despair.",al={"why did mary throw it away","blind mary mirror","mary looking glass incident"},it="origin"},{q="Where is the Tranquil Gardens Cemetery?",a="Tranquil Gardens Cemetery lies in southeastern Duskwood, south of the main road. Once a peaceful burial ground for Duskwood's people, it is now infested with aggressive ghouls, skeletons, and carrion beasts.",al={"tranquil gardens location","where is cemetery"},it="place",gp=true},{q="Who is Cog?",a="Cog is a gnome tinkerer who lives in Darkshire. Viktori relies on Cog's engineering skill to assess and help build the delicate mechanisms of his star-viewing machine.",al={"who is cog","viktori cog"},it="identity"},{q="What happens after returning the mirror to Viktori?",a="The mirror brings Viktori closer to completing his apparatus. He moves on to the final stage of assembling his telescope and asks for one last component for its lens system.",al={"look to the stars next quest","what comes next"},sp=1,it="next_step"},{q="Why does Blind Mary help you find the looking glass?",a="Mary harbors no desire to keep her looking glass. Once among her finest treasures, it became unbearable to her after a tragic incident blinded and undid her. Having already cast it away behind her barn in despair, she has no reason to withhold its fate and willingly directs you to the scavenger who took it.",al={"why does blind mary help","blind mary motive looking glass","why does mary tell you where the mirror is"},it="motive",add="9a9407cc"},{q="Why does Blind Mary need you to retrieve the mirror instead of getting it herself?",a="Blind Mary is a helpless, sightless ghost lingering in isolation outside Darkshire. Even in life, facing down a feral ghoul would have been impossible for her, and in death she is tethered to her haunted hovel. An armed adventurer is the only one capable of braving the Tranquil Gardens Cemetery to reclaim it.",al={"why cant mary get the mirror","why does mary need me","why doesnt mary retrieve the glass"},it="why_me",add="f9c44b13"}},ang={["profession:Engineering"]="Engineers can appreciate how Viktori adapts ordinary polished hand mirrors into reflective parts for an astronomical instrument.",["class:Priest"]="As a priest, you can witness the terrible fate of Duskwood's dead in Tranquil Gardens Cemetery, where fallen villagers have become insane scavengers.",["faction:Alliance"]="As an Alliance member, you see the bitter fate of Duskwood's people when lost town relics fall into the hands of ravenous undead on the dangerous fringes of the Kingdom of Stormwind."},kw={"blind mary","cog","darkshire","insane ghoul","look to the stars","mary's looking glass","telescope","tranquil gardens cemetery","viktori prism'antras"},rel={"quest:174","npc:viktori-prism-antras","npc:blind-mary","subzone:tranquil-gardens-cemetery","subzone:darkshire","zone:duskwood","quest:1599"},m={start="Blind Mary",["end"]="Viktori Prism'Antras",level="25",faction="Alliance",id=177,ri={"Mary's Looking Glass"}},src={"Look To The Stars (3)"}}
E["quest:181"] = {t="quest",n="Look To The Stars",z="duskwood",s="In Darkshire, Viktori Prism'Antras seeks the last piece for his telescope. Its frame is ready, but no local glass is large enough for the lens his plans require.",h="In Darkshire, Viktori Prism'Antras seeks the last piece for his telescope.",sec={{t="The Final Piece",b="Viktori Prism'Antras is building a telescope in Darkshire from plans by Cog Glitzspinner, a gnome engineer. He has gathered brass tubes and sturdy mountings from local supplies. But the design calls for an unusually large focusing lens. Magnifying glasses and optical parts from Stormwind traders are too small, so Viktori searches beyond ordinary materials for the piece he needs.",sp=0},{t="The Ogre's Eyepiece",b="At Vul'Gol Ogre Mound, hostile ogres crowd the southern hills. One of them, Zzarc'Vul, wears a glass monocle large enough for Viktori's telescope. Taking it from Zzarc'Vul would give Viktori the lens Cog's plans call for. Then he could finish the telescope and look into the heavens above Duskwood's shadowed canopy.",sp=1}},faq={{q="Who is Viktori Prism'Antras?",a="Viktori Prism'Antras is an astronomer and scholar who lives in a hut up the hill in Darkshire. Though gloom lies over Duskwood, he remains devoted to finishing his telescope and studying the stars.",al={"who is viktori","viktori prism'antras"},it="identity"},{q="Where can I find Zzarc'Vul?",a="Zzarc'Vul is in Vul'Gol Ogre Mound in southern Duskwood. He roams the camp and cave network, among heavily guarded ogre territory.",al={"zzarc'vul location","where is the ogre","ogre monocle location"},it="target",gp=true},{q="Why does an ogre possess a monocle?",a="Zzarc'Vul wears an oversized monocle. It is the only lens in the region large enough to fit Cog's telescope plans.",al={"why ogre monocle","ogre's monocle lore"}},{q="What happens once the device is completed?",a="The monocle lets Viktori fit the telescope's final lens. Once the device is complete, he can return to studying the stars above the bleak forest.",al={"telescope finished","quest conclusion"},it="next_step"},{q="Who designed the telescope?",a="Cog, a gnome engineer, designed the telescope. His plans call for specialized parts, a metal frame, and a lens far larger than standard dwarven or gnomish spectacles.",al={"cog blueprints","who built telescope"},it="origin"},{q="Is Vul'Gol Ogre Mound safe to enter alone?",a="No. Hostile ogres fill Vul'Gol Ogre Mound, patrolling in packs and guarding narrow paths. Searching deep inside for Zzarc'Vul is dangerous for a lone traveler.",al={"vul'gol difficulty","ogre mound safe"},it="danger",gp=true},{q="Why does Viktori Prism'Antras want this done?",a="Viktori is an eccentric scholar dedicated to building a specialized stargazing apparatus from Cog's blueprints. He has spent considerable effort gathering delicate parts, but his design still lacks a lens of sufficient size to peer into the heavens. Once the telescope is fully assembled, he will finally be able to resume his astronomical research from the gloom of Darkshire.",al={"why Viktori needs monocle","viktori prism'antras goal","look to the stars motive"},it="motive",add="ac1c4dd0"},{q="What is the Ogre's Monocle for?",a="The blueprints for Viktori's stargazing device call for an unusually large optical lens. Rather than grinding one from scratch in the shadowed isolation of Duskwood, Viktori realized that the oversized monocle worn by the ogre Zzarc'Vul provides the exact dimensions and focal glass needed to complete the apparatus.",al={"ogre monocle purpose","why ogres monocle","what is the monocle used for"},it="item",add="f331a2d2"},{q="Who is Zzarc'Vul?",a="Zzarc'Vul is a notable ogre dwelling among his kin at the Vul'Gol Ogre Mound in the southern hills of Duskwood. Unlike his brutal companions, he carries an enormous monocle that has caught the attention of Viktori Prism'Antras, making him the final obstacle between the scholar and his completed telescope.",al={"who is zzarcvul","who is the ogre","target zzarc'vul"},it="target",add="bbeac028"}},ang={["faction:Alliance"]="As an Alliance traveler, you can see Darkshire endure against the horrors and beasts around it. Viktori's pursuit of the stars offers a small sign of civilian perseverance.",["race:Gnome"]="As a gnome, you know ingenuity can turn an unlikely find into a useful part. Viktori's telescope plans call for a lens taken from an ogre's monocle.",["profession:Engineering"]="As an engineer, you can appreciate the audacity of using a massive ogre monocle to meet the demands of an astronomical lens."},kw={"cog","darkshire","look to the stars","monocle","telescope","viktori prism'antras","vul'gol ogre mound","zzarc'vul"},rel={"npc:viktori-prism-antras","subzone:vul-gol-ogre-mound","subzone:darkshire","zone:duskwood","quest:174"},m={start="Viktori Prism'Antras",level="30",faction="Alliance",id=181,ri={"Ogre's Monocle"}},src={"Look To The Stars (4)"}}
E["quest:221"] = {t="quest",n="Worgen in the Woods",z="duskwood",s="Nightbane Dark Runners press toward Darkshire from the Rotting Orchard in Duskwood. Calor sends you to thin their ranks before the pack can surround the town.",h="Nightbane Dark Runners press toward Darkshire from the Rotting Orchard in Duskwood.",sec={{t="A Tightening Perimeter",b="Calor's scouting has revealed a greater danger than the lone worgen first seen weaving shadowy magic at the forest's edge. Larger and swifter Nightbane Dark Runners have gathered in the Rotting Orchard, just southwest of Darkshire. They make up most of the pack and have made the orchard a staging ground within striking distance of the village gates.",sp=0},{t="An Inexhaustible Tide",b="When you fell a Dark Runner, the Night Watch gains only brief relief. Calor sees another prowling the mists in its place, and the defenders cannot explain the Nightbane's resilience or numbers. They look to veteran monster hunters such as Master Jonathan Carevin to discover what foul catalyst called these alien horrors to Duskwood.",sp=1}},faq={{q="What are Nightbane Dark Runners?",a="Nightbane Dark Runners are larger, imposing worgen who form the pack's main front-line force in Duskwood. Unlike the mystical Shadow Weavers, they rely on speed, claws, and predatory ferocity.",al={"dark runners","what are dark runners","nightbane dark runner"},it="target"},{q="Where is the Rotting Orchard located?",a="The Rotting Orchard lies just southwest of Darkshire. Once productive farmland, it is now a corrupted clearing seized by the Nightbane pack as a foothold near town.",al={"rotting orchard location","where is rotting orchard"},it="place",gp=true},{q="Who is Calor?",a="Calor is a ranger in Darkshire who serves Master Jonathan Carevin. He scouts the settlement's outskirts and tracks the worgen packs threatening the town's survival.",al={"who is calor","calor duskwood","calor questgiver"},it="people"},{q="Why do the worgen numbers seem endless to the defenders?",a="The defenders cannot explain the supernatural presence of the worgen. They believe an evil power is summoning or drawing the beasts into Duskwood, so fresh waves appear as quickly as others are slain.",al={"why so many worgen","inexhaustible worgen","where do worgen come from"},it="threat"},{q="Who is Master Carevin?",a="Master Jonathan Carevin leads his family's fight against the undead and other evils of Duskwood from Darkshire. Calor trusts his expertise to find the cause of the monstrous infestations troubling the region.",al={"master carevin","jonathan carevin","who is carevin"},it="people"},{q="How does this task fit into the defense of Darkshire?",a="Darkshire is isolated, its supplies dwindling, and Stormwind has sent no aid. Clearing the Rotting Orchard keeps the Nightbane from staging direct, overwhelming ambushes on the town's southwest perimeter.",al={"why kill dark runners","darkshire defense"},it="purpose"},{q="Why does Calor want the Nightbane Dark Runners culled?",a="Calor tracks the beastly incursions around Darkshire and knows the Dark Runners form the sheer bulk of the worgen forces prowling the forest. Worse still, they have completely overrun the Rotting Orchard just southwest of town. Leaving such a large and savage pack unchecked so close to Darkshire invites disaster, so he needs their numbers thinned before the settlement is overwhelmed.",al={"calor motive","why kill dark runners","why does calor want this done"},it="motive",add="e2dcc78b"},{q="Why does Calor rely on you instead of clearing the orchard himself?",a="Calor is a scout and ranger whose primary duty is keeping watch on the woods, tracking beast movements, and reporting threats back to Darkshire. The Nightbane worgen are aggressive, tough, and seemingly inexhaustible, stretching the town's defenders to their limits. With Darkshire besieged by horrors on all sides, rangers like Calor depend on capable adventurers to take the fight directly into infested groves like the Rotting Orchard.",al={"why me","why doesn't calor do it","why calor needs help"},it="why_me",add="99fe833d"}},ang={["faction:Alliance"]="Duskwood has received almost no reinforcement from the Stormwind crown. Local volunteers in the Night Watch rely on traveling Alliance heroes to thin the predator packs pressing in.",["class:Hunter"]="As a hunter, you face unnatural, bipedal wolves at the Rotting Orchard. Their instincts defy Azeroth's natural order."},kw={"calor","carevin","dark runner","darkshire","duskwood","night watch","nightbane","rotting orchard","worgen"},rel={"npc:calor","subzone:rotting-orchard","subzone:darkshire","topic:worgen","zone:duskwood"},m={start="Calor",level="29",faction="Alliance",id=221},src={"Worgen in the Woods (Classic, 2)"}}
E["quest:222"] = {t="quest",n="Worgen in the Woods",z="duskwood",s="Calor sends you into southern Duskwood against the Nightbane pack. Their dens and mines bring the worgen threat close to Darkshire.",h="Calor sends you into southern Duskwood against the Nightbane pack.",sec={{t="A Feral Foothold",b="South of Darkshire, Nightbane worgen fortify caves and abandoned mine shafts as camps. Calor watches their bonfires and fears what their growing hold means for the town. Among the pack, the Vile Fangs and Tainted Ones are its fiercest breeds. Their savagery and stubbornness threaten Darkshire’s perimeter.",sp=0},{t="Calor's Endorsement",b="Calor watches Darkshire’s front line and knows how dangerous the worgen are. Defeating the Vile Fangs and Tainted Ones tests any hero. Those who defeat them earn his respect and a personal recommendation to Master Carevin, who coordinates the wider fight against the worgen.",sp=1}},faq={{q="Where are the Vile Fangs and Tainted Ones located?",a="The Vile Fangs and Tainted Ones gather around caves and the mine in southern Duskwood, often near bonfires.",al={"where are tainted ones","where are vile fangs","worgen locations duskwood"},it="place",gp=true},{q="Who is Calor?",a="Calor lives in Darkshire and watches the worgen threat in the woods. He enlists capable adventurers to halt their advance.",al={"calor darkshire","who gives worgen in the woods 3"},it="identity"},{q="Who is Master Carevin?",a="Master Carevin is Jonathan Carevin of Darkshire. His family fights the region’s evils, and he coordinates efforts to eradicate the nearby worgen.",al={"master carevin","carevin duskwood"},it="allies"},{q="Why do the worgen have bonfires?",a="The Nightbane worgen gather in organized camps, use fire, and hold fortified positions such as mines. Their camps reveal an unsettling intelligence beneath their monstrous, wolf-like appearance.",al={"why do worgen make fires","nightbane bonfires"}},{q="What happens after completing this hunt?",a="Impressing Calor earns you a letter of recommendation to Master Carevin. Then you can help him in the next phase of the hunt.",al={"next quest after worgen in the woods 3","worgen in the woods follow up"},it="next_step"},{q="Why is Darkshire so concerned about these specific worgen?",a="The Vile Fangs and Tainted Ones are among the pack’s most lethal and aggressive members. If left unchecked near the southern mines, they could overrun the surrounding roads.",al={"why nightbane vile fang","vile fang danger"},it="threat"},{q="Why does Calor want these worgen killed?",a="Calor is working to protect Darkshire and aid Master Carevin's ongoing crusade against the lupine menace. The Nightbane pack has entrenched itself in the south, lighting bonfires and establishing footholds in caves and mines. By sending you to cull their deadliest fighters, Calor hopes to blunt the pack's strength before they overwhelm what little defense remains in Duskwood.",al={"why kill the worgen","calor motive","why does calor want this"},it="motive",add="0c2f2969"},{q="What are the Vile Fangs and Tainted Ones you are hunting?",a="They are among the most lethal and ferocious members of the Nightbane pack. Unlike the lesser beasts prowling the wilderness, these worgen have organized camps near Roland's Doom and other southern caves, burning fires and demonstrating a cunning, coordinated presence that threatens all of Darkshire.",al={"who are the vile fangs","tainted ones duskwood","target worgen"},it="target",add="5cfb2401"},{q="Why does Calor recruit you instead of handling the beasts himself?",a="Darkshire's defenders, the Night Watch, are stretched impossibly thin guarding the town perimeter against undead, spiders, and rogue beasts. Taking the fight deep into worgen territory requires seasoned champions who can withstand dark magic and brute savagery, and your past successes have proven to Calor that you have the skill to survive.",al={"why does calor need me","why send me","why doesn't the night watch handle it"},it="why_me",add="5e6f00dd"}},ang={["faction:Alliance"]="As an Alliance traveler, you help protect Darkshire’s supply lines and Duskwood’s remaining homesteads by clearing the southern caves.",["class:Hunter"]="As a hunter, you face unusual prey in the cunning Nightbane pack. Stay vigilant near their dark dens."},kw={"calor","carevin","darkshire","duskwood","nightbane","tainted one","vile fang","worgen"},rel={"npc:calor","topic:worgen","subzone:darkshire","zone:duskwood","topic:light"},m={start="Calor",level="31",faction="Alliance",id=222},src={"Worgen in the Woods (Classic, 3)"}}
E["quest:223"] = {t="quest",n="Worgen in the Woods",z="duskwood",s="In Worgen in the Woods, Calor sends you to Darkshire with a letter for Jonathan Carevin. Your hunts against the worgen in Duskwood have earned his trust, and he believes your skill can aid Carevin.",h="In Worgen in the Woods, Calor sends you to Darkshire with a letter for Jonathan Carevin.",sec={{t="A Rare Recommendation",b="You drove the Nightbane pack from Roland's Doom and the shadowed glades, earning Calor's respect. He serves on the dark frontier of the woods and rarely offers praise or formal introductions. Now he gives you a faded scrap of parchment for Jonathan Carevin in Darkshire. Calor believes more fighters like you could help his small company outshine the town's beleaguered Night Watch.",sp=0},{t="Carevin's Vigil",b="Jonathan Carevin works in Darkshire under heavy strain. Worgen, restless undead, demonic forces, and cultists who aid the corruption from within all threaten the town. Wary of outsiders and short on time, Carevin trusts Calor's recommendation. He sees you as a dependable fighter who can help preserve the Light against Duskwood's terrors.",sp=0}},faq={{q="Who sends me on this mission?",a="Calor sends you to deliver a faded letter of recommendation to Jonathan Carevin. Your success against the worgen packs across Duskwood has earned his respect.",al={"quest giver","who starts this","calor"},it="identity"},{q="Who is Jonathan Carevin?",a="Jonathan Carevin lives in Darkshire and coordinates the town's defense against supernatural threats. Wary of strangers, he works with trusted allies such as Calor against undead, demons, and those who aid them.",al={"carevin","who is carevin","master carevin"},it="identity"},{q="Why is Calor so dismissive of the Night Watch?",a="Calor believes the Night Watch is struggling to meet Duskwood's many dangers. He thinks a few capable fighters can do more than the town's small company.",al={"calor night watch","outnumber the night watch","why compete with night watch"},it="motive"},{q="What threats does Carevin warn about upon delivery?",a="Carevin faces worgen, restless undead, demonic forces, and cultists who help the corruption from within. Threats press in on the town from every side.",al={"carevin enemies","what does carevin say","what are we fighting"},it="threat"},{q="Does this quest require any combat?",a="No. You only need to take Calor's letter to Carevin in Darkshire. Your earlier hunts against the Nightbane worgen are already behind you.",al={"any fighting","do i kill anything","delivery only"},gp=true},{q="Where can I find Jonathan Carevin?",a="Jonathan Carevin is in Darkshire, attending to the town's defense.",al={"carevin location","where is carevin","where to turn in"},it="place",gp=true},{q="Why does Calor send you to Jonathan Carevin?",a="Calor believes you have proven your mettle in the woods and wants to formally introduce you to his superior, Master Jonathan Carevin. His small order operates in the shadows of Duskwood apart from the beleaguered Night Watch, and he hopes that bringing competent fighters like you into their circle will bolster their clandestine efforts against the darker threats plaguing the region.",al={"why send to carevin","calor motive","why bring note to carevin"},it="motive",add="f56a577c"},{q="Why does Calor rely on you rather than the Night Watch?",a="Calor has little faith in the conventional town guards, viewing the Night Watch as inadequate for the grim, specialized work his order undertakes. Because you demonstrated your ability by dealing directly with the worgen threat where others faltered, he sees you as someone genuinely capable of aiding their secret crusade against Duskwood's darker terrors.",al={"why not night watch","why trust me over guards","why does calor need me"},it="why_me",add="47a08b52"}},ang={["faction:Alliance"]="With the Kingdom of Stormwind unable to spare soldiers for Duskwood's borderlands, independent Alliance adventurers and vigilantes like Carevin are the town's only line of defense.",["class:Paladin"]="As a paladin, Carevin welcomes proven allies in the name of the Holy Light and seeks holy champions to face Duskwood's unholy evils.",["class:Priest"]="As a priest, you hear Carevin's parting blessing, “Glory under the Light.” It speaks to the defenders' faith amid Darkshire's unending corruption."},kw={"calor","calor's note","darkshire","duskwood","jonathan carevin","night watch","worgen in the woods"},rel={"npc:calor","npc:jonathan-carevin","topic:night-watch","zone:duskwood","quest:56","topic:light"},m={start="Calor",["end"]="Jonathan Carevin",level="31",faction="Alliance",id=223},src={"Worgen in the Woods (Classic, 4)"}}
E["quest:226"] = {t="quest",n="Wolves at Our Heels",z="duskwood",s="In western Duskwood, Lars faces hungry, rabid dire wolves. Hunting them gives him room to gather food while he and Sven Yorgen pursue their vendetta against the necromancer Morbent Fel.",h="In western Duskwood, Lars faces hungry, rabid dire wolves.",sec={{t="A Precarious Camp",b="Sven Yorgen and Lars keep an isolated camp in Duskwood’s western hills, near the Westfall border. Far from Darkshire, they rely on hunting and foraging to survive. As Lars carries fresh game through the dark woods, ravenous predators prowl the riverbanks and underbrush.",sp=0},{t="Clearing the Woods",b="Starving, rabid dire wolves prowl north and east of the camp, toward the river. Killing the frenzied beasts makes Lars’s hunt safer. With less danger as they gather their daily food, Sven and Lars can focus on Morbent Fel, the necromancer farther east.",sp=0}},faq={{q="Who is Lars?",a="Lars helps Sven Yorgen at their small camp in the hills of western Duskwood. He hunts and forages for their daily needs while Sven fixates on vengeance against the dark forces threatening the region.",al={"lars","who gives wolves at our heels","quest giver lars"},it="identity"},{q="Where are the wolves prowling?",a="Dire wolves prowl the woods north and east of Sven's Camp, especially along the riverbanks that divide Duskwood from the zones to the north.",al={"wolf location","where are rabid dire wolves","where are starving dire wolves"},gp=true},{q="Why are the dire wolves so aggressive?",a="Duskwood's wilderness has grown harsher under an encroaching shadow. With scarce game, the dire wolves are near starvation. Disease or dark corruption has made many rabid and recklessly violent toward anyone carrying fresh meat.",al={"why are wolves attacking","rabid wolves duskwood"}},{q="Who is Morbent Fel?",a="Morbent Fel is a powerful necromancer who practices dark arts from the cemetery and mounds to the east. Sven and Lars bear him a bitter grudge and prepare to take him down once their basic needs are met.",al={"morbent fel","the necromancer","who is the necromancer to the east"},it="threat"},{q="What are the Flash Bundles Lars gives as a reward?",a="Flash Bundles are blinding devices made by the townsfolk of Darkshire. Sympathetic residents donated them to Sven's camp to aid his fight against the undead and beasts infesting the woods.",al={"flash bundles","lars reward","what is flash bundle"},it="item"},{q="Why don't Sven and Lars live in Darkshire?",a="Sven's family suffered a tragedy that made him an embittered, driven vigilante. Sven and Lars live in the wild rather than under the Night Watch's protection in Darkshire, so they can stalk the evils plaguing the woods firsthand.",al={"why live in a camp","svens camp location","why not in town"},it="why_here"},{q="Why does Lars want the dire wolves killed?",a="Living isolated in western Duskwood, Sven and Lars must hunt their own game to survive. Every time Lars tries to haul meat back to camp, packs of ravenous dire wolves ambush him. Clearing out the predators secures their camp's food supply and frees them to focus on the looming threat of the necromancer Morbent Fel.",al={"why kill wolves","lars wolves motive","why does lars need wolf kills"},it="motive",add="e2641657"},{q="What are the dire wolves prowling western Duskwood?",a="These vicious beasts prowl the woods and riverbanks north and east of Sven's camp. Pushed by extreme famine and spreading sickness, the starving and rabid dire wolves have become reckless scavengers, drawn instantly to fresh meat and posing a lethal hazard to anyone traversing the western wilderness.",al={"what are the wolves","starving dire wolves duskwood","rabid dire wolves"},it="target",add="8ad2a450"},{q="Why can't Lars deal with the wolves himself?",a="Lars and Sven are on their own on the far edge of the territory, far beyond the reach of the Night Watch or Stormwind's guards. Already consumed by preparing for their struggle against Morbent Fel and barely managing day-to-day hunting, Lars simply cannot afford to battle full packs of vicious wolves without an adventurer's aid.",al={"why doesn't lars kill wolves","why ask me wolves","why not lars"},it="why_me",add="6ca73ecd"}},ang={["class:Hunter"]="As a hunter, you need sharp awareness to tame or cull Duskwood's warped wildlife. These dire wolves are more desperate and vicious than ordinary forest beasts.",["faction:Alliance"]="As an Alliance traveler, you help steady Lars's remote camp and secure an allied staging ground against the undead forces plaguing western Duskwood."},kw={"dire wolf","duskwood","flash bundles","lars","morbent fel","rabid dire wolf","starving dire wolf","sven","sven's camp"},rel={"npc:lars","quest:230","quest:55","zone:duskwood"},m={start="Lars",level="21",faction="Alliance",id=226},src={"Wolves at Our Heels (Classic)"}}
E["quest:230"] = {t="quest",n="Sven's Camp",z="duskwood",s="In Duskwood's western hills, Sven Yorgen still grieves for his slain family and seeks answers. A journal buried at his ruined farm may tell who saw the massacre.",h="In Duskwood's western hills, Sven Yorgen still grieves for his slain family and seeks answers.",sec={{t="A Clue in the Dirt",b="You find a small, dirt-stained book beneath freshly turned earth at the ruined Yorgen farm. Dark riders struck while Sven Yorgen was away, leaving his family dead and the farm in ruins. Grief and vengeance sent his allies to search the wreckage. Someone had hastily hidden the book there.",sp=0},{t="A Silent Witness",b="At his camp in the western hills, Sven learns what the journal holds. Its entries show that an unknown figure watched his family's massacre. The discovery brings no peace. Sven now seeks the onlooker and demands answers.",sp=1}},faq={{q="What is the book found in the mound of dirt?",a="The book is a small, untitled, dirt-stained journal buried at the Yorgen farm. Its entries show that an unidentified onlooker watched the massacre of Sven Yorgen's family.",al={"what book is this","book from svens farm","what did i dig up"},it="item"},{q="Where does this quest lead next?",a="Delivering the book to Sven Yorgen begins a search for the mysterious witness and leads into The Shadowy Figure.",al={"what comes next","next quest after svens camp","who is the shadowy figure"},it="next_step"},{q="Where is Sven Yorgen located?",a="Sven has taken refuge in a camp in Duskwood's northwestern hills. He grieves for his family and plots retribution.",al={"where is sven","sven yorgen location","where do i turn this in"},gp=true},{q="Why was the book buried at the farm?",a="The book lay hidden in loose dirt amid the ruined homestead. The observer at the scene may have discarded or concealed it in haste.",al={"why buried","who hid the book","mound of loose dirt"},it="why_here"},{q="Who killed Sven's family?",a="Dark riders from Deadwind Pass slaughtered Sven's family while he was away from the farm.",al={"who attacked the farm","who killed svens family","svens family killers"},it="threat"},{q="What faction can complete this quest?",a="Only Alliance members can help Sven Yorgen, who seeks aid from Duskwood's defenders and the Alliance.",al={"is this alliance only","can horde do svens camp"},it="side",gp=true}},ang={["faction:Alliance"]="As an Alliance member, you can help investigate the Yorgen massacre while the Alliance struggles to understand the dark forces encroaching on Duskwood."},kw={"dark riders","duskwood","mound of loose dirt","shadowy figure","sven yorgen","yorgen farm"},rel={"quest:95","quest:262","npc:sven-yorgen","zone:duskwood"},m={start="Mound of loose dirt",["end"]="Sven Yorgen",level="25",faction="Alliance",id=230},src={"Sven's Camp"}}
E["quest:240"] = {t="quest",n="Return to Jitters",z="duskwood",s="At Raven Hill, you bring Jitters a meal from Chef Grual. The cakes ease his hunger, though fear still holds him there.",h="At Raven Hill, you bring Jitters a meal from Chef Grual.",sec={{t="A Dubious Delicacy",b="Chef Grual cooks at the Scarlet Raven Tavern in Darkshire. With little livestock or sea life in Duskwood, he makes use of what the blighted forest provides. His Dusky Crab Cakes contain no crab meat. Instead, gooey legs from venom web spiders make up his specialty. Grual calls it resourceful cooking, though delicate stomachs may disagree.",sp=0},{t="Soothing Jitters' Nerves",b="At Raven Hill, Jitters cowers in fear, unable to face the horrors that drove him from the woods. Terror keeps him from hunting or foraging, and hunger only deepens his distress. The warm cakes bring him a rare moment of relief. Desperate for food, he eats without asking what kind of crab Grual used.",sp=0}},faq={{q="What is in the Dusky Crab Cakes?",a="Dusky Crab Cakes contain no crab. Chef Grual uses gooey legs from local venom web spiders and seasons them to mimic traditional seafood cakes.",al={"crab cakes ingredients","what are dusky crab cakes made of","are they real crab"},it="item"},{q="Does Jitters know the cakes are made of spider goo?",a="Chef Grual keeps the recipe to himself. Starved and terrified, Jitters eagerly eats the cakes without asking what is in them.",al={"does jitters know","does jitters know about the spiders"}},{q="Why couldn't Jitters get his own food?",a="Jitters is overwhelmed by fear after what he encountered in Duskwood's wild woods. Panic keeps him near Raven Hill, where he depends on sympathetic travelers for food.",al={"why is jitters starving","why doesn't jitters hunt"},it="motive"},{q="Who is Chef Grual?",a="Chef Grual cooks at the Scarlet Raven Tavern in Darkshire. With the town cut off by shadows and beasts, he uses unconventional ingredients scavengers bring him to feed the tavern's patrons.",al={"chef grual role","cook in darkshire"},it="identity"},{q="Where does this quest chain begin?",a="Jitters asks for help with his hunger at Raven Hill in Jitters' Growling Gut. You hunt venom web spiders for Chef Grual, then return with the finished meal.",al={"how to start jitters food quest","jitters quest chain start"},it="origin",gp=true},{q="Does Jitters recover after eating?",a="The meal satisfies Jitters' hunger, and he gives you his heartfelt gratitude. Food cannot ease his deep terror; he remains anxious and haunted by the forest's dark secrets.",al={"is jitters cured","does food help jitters"},it="next_step"},{q="Why does Chef Grual want the crab cakes delivered to Jitters?",a="Chef Grual runs the kitchen at the Scarlet Raven Tavern in Darkshire and takes pride in filling orders, even bizarre ones cooked up from local spider innards. Jitters is starving out in the perilous gloom of Raven Hill, too frightened to make the journey into town himself. Having prepared his special 'Crab' Cakes ala Grual, the chef entrusts them to you to fulfill Jitters' order and ensure the poor wretch gets fed.",al={"why deliver crab cakes","grual motive jitters","why send food to jitters"},it="motive",add="deba9bdd"}},ang={["profession:Cooking"]="Chef Grual turns gooey venom web spider legs into palatable cakes, showing how cooking draws on whatever the frontier provides.",["faction:Alliance"]="Darkshire's meager, unusual diet reflects how cut off the town is from Stormwind's supplies. Locals rely on whatever creeps in the shadows."},kw={"chef grual","darkshire","duskwood","dusky crab cakes","growling gut","jitters","scarlet raven tavern"},rel={"quest:93","quest:5","npc:jitters","npc:chef-grual","zone:duskwood"},m={start="Chef Grual",["end"]="Jitters",level="20",faction="Alliance",id=240},src={"Return to Jitters"}}
E["quest:245"] = {t="quest",n="Eight-Legged Menaces",z="duskwood",s="In Duskwood, venom web spiders crowd the western border, and Watcher Dodds fears for the Night Watch. He asks travelers to thin their numbers before more guards fall into their webs.",h="In Duskwood, venom web spiders crowd the western border, and Watcher Dodds fears for the Night Watch.",sec={{t="A Border Under Siege",b="Pygmy venom web spiders swarm the brush beside the western road from Westfall into Duskwood. Beneath the dense canopy, their webs choke the thickets. Travelers and the Night Watch's already fragile defenses are in danger.",sp=0},{t="The Burden on the Night Watch",b="Watcher Dodds keeps a small camp far from Darkshire, with too few troops to hold the border. Commander Althea Ebonlocke cannot send help while undead and worgen press against the township. Dodds has lost comrades to the spiders. He found them hanging upside down in the canopy, paralyzed by venom as it liquefied their flesh.",sp=0}},faq={{q="Who offers this quest?",a="Watcher Dodds, a Night Watch member at a small camp in Duskwood, asks travelers to clear the spiders away.",al={"quest giver","who gives eight-legged menaces","watcher dodds"},it="identity"},{q="Why can't the Night Watch handle the spiders themselves?",a="Commander Althea Ebonlocke keeps her small garrison near Darkshire to repel relentless undead assaults. Dodds has too few troops to attack the border nests and hold his post.",al={"why need help","why call adventurers","darkshire militia shortage"},it="why_me"},{q="Where are these spiders located?",a="Pygmy venom web spiders swarm Duskwood's western woods, in the brush just off the main road from Westfall.",al={"spider location","where are pygmy venom webs","spider woods"},it="place",gp=true},{q="What makes these spiders so dangerous to the watch?",a="The spiders are numerous, and their venom paralyzes and dissolves flesh. Night Watchmen caught in their webs hang helpless in the boughs, easy prey.",al={"spider poison","spider venom","spider victims"},it="threat"},{q="Are these the only spiders in Duskwood?",a="No. Pygmy venom web spiders are the smaller broodlings. Much larger and deadlier spiders live deeper in the woods, where they threaten travelers.",al={"other duskwood spiders","spider species","venom web spiders"}},{q="Why has the insect and spider population grown so aggressively?",a="Magical corruption blankets Duskwood and has twisted its native wildlife. The creatures have grown more aggressive, larger, and deadlier.",al={"why so many spiders","duskwood corruption nature","spider origin"},it="origin"},{q="Why does Watcher Dodds want the spiders culled?",a="Pygmy Venom Web Spiders have taken over Duskwood's western border, and the Night Watch is too short of men to deal with them. Watcher Dodds has already lost several of his men to their venom and webs, and Commander Ebonlocke cannot spare soldiers so far from Darkshire.",al={"why kill pygmy venom web spiders","dodds spider motive","why does dodds want this done"},it="motive",add="19037cd1"},{q="What are the Pygmy Venom Web Spiders?",a="Pygmy Venom Web Spiders are aggressively territorial arachnids that infest the western borderlands of Duskwood. Despite being smaller than the mature monstrous spiders deeper in the woods, they hunt in swarms, snare unwary travelers in web nests, and produce a potent venom capable of melting their prey's flesh from within.",al={"pygmy venom web spiders","who are we hunting","western duskwood spiders"},it="target",add="3807547d"}},ang={["faction:Alliance"]="The Night Watch receives no aid from the House of Nobles. Support from Alliance travelers helps keep the roads open.",["class:Hunter"]="As a Hunter, you face vicious venom web spiders in Duskwood. Careful footwork and anti-venom preparation help you hunt them."},kw={"darkshire","duskwood","eight-legged menaces","night watch","pygmy venom web spider","spiders","watcher dodds"},rel={"npc:watcher-dodds","topic:night-watch","quest:56","zone:duskwood","subzone:darkshire"},m={start="Watcher Dodds",level="21",faction="Alliance",id=245},src={"Eight-Legged Menaces"}}
E["quest:251"] = {t="quest",n="Translate Abercrombie's Note",z="duskwood",s="In Darkshire, a strange letter comes before the town's leaders for translation. Mayor Ello Ebonlocke turns to Sirra Von'Indi, the scholar who knows obscure scripts.",h="In Darkshire, a strange letter comes before the town's leaders for translation.",sec={{t="An Indecipherable Message",b="Abercrombie sends Mayor Ello Ebonlocke a sealed letter from his home. Ebonlocke expects an eccentric plea or bitter ramblings from the cemetery hermit, but the parchment bears strange writing that ordinary Common cannot explain. The mayor cannot read ancient or obscure languages, so he will not dismiss it. Even a mad hermit may pose a danger in Duskwood.",sp=0},{t="The Scholar of Darkshire",b="Ebonlocke sends you across the square to Sirra Von'Indi, Darkshire's scholar of esoteric lore. Sirra knows ancient arts and forgotten tongues. He scoffs at Abercrombie's sanity, saying anyone who lives beside a haunted graveyard must have a rotted brain. Still, he takes the parchment seriously and begins the slow work of transcription.",sp=0},{t="A Glimpse into the Hermit's Mind",b="Abercrombie's encoded letter reveals a mind beyond the frail, reclusive old man who asks for supplies and protection from ghouls. Its message warns of a reckoning, and Darkshire is ill prepared to face it.",sp=1}},faq={{q="Why can't Mayor Ebonlocke read the note himself?",a="Mayor Ello Ebonlocke cannot read the note's strange writing, so he sends it to Sirra Von'Indi, Darkshire's scholar of obscure scripts.",al={"why can't ello read note","ebonlocke letter translate","why need translator"},it="motive"},{q="Who is Sirra Von'Indi?",a="Sirra Von'Indi is Darkshire's scholar, known for his knowledge of obscure languages, history, and ancient arts. He examines mysterious texts and relics from the surrounding woods.",al={"sirra von indi who","who is the translator","darkshire scholar"},it="identity"},{q="Where does Abercrombie live?",a="Abercrombie lives in a ramshackle shack just northeast of Raven Hill Cemetery in western Duskwood, among restless undead and predatory beasts.",al={"where is abercrombie","hermit location","abercrombie duskwood"},it="place"},{q="What is Sirra's reaction to Abercrombie's note?",a="Sirra doubts Abercrombie's sanity, saying anyone who lives beside a graveyard must have a rotted brain. Still, he examines the letter and begins translating its obscure script.",al={"what does sirra think of abercrombie","sirra von indi dialogue"}},{q="What happens after giving the note to Sirra?",a="Sirra Von'Indi asks you to wait while he transcribes the letter. When he finishes, you carry the translation back to Lord Ello Ebonlocke.",al={"next quest after translate note","what comes after translate abercrombie note"},sp=1,it="next_step"},{q="Why did Abercrombie write to Mayor Ebonlocke?",a="Abercrombie wrote to Mayor Ebonlocke in a script Ello cannot read. Sirra Von'Indi's translation reveals what the hermit wrote.",al={"why did abercrombie send letter","hermit note purpose"},sp=1,it="purpose"}},ang={["class:Mage"]="As a mage, you may recognize the work Sirra Von'Indi undertakes as he studies Darkshire's obscure scripts.",["faction:Alliance"]="As an Alliance champion helping Duskwood, you see how vulnerable and isolated Darkshire's leaders feel amid the surrounding darkness."},kw={"abercrombie","cipher","darkshire","duskwood","ello ebonlocke","hermit","sirra von'indi","translation"},rel={"npc:lord-ello-ebonlocke","npc:sirra-von-indi","quest:401","npc:abercrombie","quest:165","zone:duskwood"},m={start="Lord Ello Ebonlocke",["end"]="Sirra Von'Indi",level="30",faction="Alliance",id=251},src={"Translate Abercrombie's Note"}}
E["quest:252"] = {t="quest",n="Translation to Ello",z="duskwood",s="In Duskwood, you carry Sirra Von'Indi's translation to Lord Ello Ebonlocke in Darkshire. It belongs to the Abercrombie story, and the letter bears news of the hermit's writings.",h="In Duskwood, you carry Sirra Von'Indi's translation to Lord Ello Ebonlocke in Darkshire.",sec={{t="A Belated Realization",b="Abercrombie's requests sent travelers across Duskwood for days. The elderly hermit asked for thread, preserved reagents, and personal belongings, claiming he needed them to survive. Sirra Von'Indi finally deciphered his private parchment, revealing the truth: the kindly old man is an unhinged embalmer. The gathered components went into a terrifying weapon of revenge aimed at Darkshire.",sp=1},{t="The Road to Darkshire",b="When the translated letter reaches Lord Ello Ebonlocke, the mayor's face loses all color. Whatever noble motives brought you to help, delivering those final supplies let Abercrombie finish his monstrous creation, Stitches. The letter's delivery sets the behemoth marching east along the road from Raven Hill Cemetery. Any Night Watch patrol in its path is slaughtered.",sp=1}},faq={{q="What is written in the translated letter?",a="Sirra fears Abercrombie has done something unspeakable. Take the translated letter urgently to Lord Ello Ebonlocke, who can judge the danger to Darkshire.",al={"what does the letter say","abercrombie letter text","what was translated"},it="item"},{q="Who is Sirra Von'Indi?",a="Sirra Von'Indi is a scholar living in Darkshire. His skill with language and analysis lets him decipher Abercrombie's cryptic notes and letters when others cannot read the script.",al={"who is sirra","sirra von indi lore"},it="identity"},{q="Why does Lord Ello blame the player?",a="Lord Ello's reaction comes when he reads the translated letter. Bring him the warning as quickly as possible.",al={"why is ello mad","did i cause stitches","ello reaction"},it="conflict"},{q="What happens immediately after completing this quest?",a="Take the translated letter to Lord Ello Ebonlocke in Darkshire. His response and the danger in the letter come to light when he reads it.",al={"what triggers stitches","does stitches spawn","stitches event"},sp=1},{q="Where does Stitches go after this?",a="Stitches is tied to the road between Raven Hill Cemetery and Darkshire. His part in Abercrombie's plot emerges through the investigation.",al={"stitches path","where is stitches marching"},sp=2,gp=true},{q="What quest comes next?",a="After you deliver the letter, Lord Ello sends adventurers onward to Bride of the Embalmer.",al={"next quest","after translation to ello"},sp=1,it="next_step",gp=true},{q="Why does Sirra Von'Indi want the letter delivered to Ello?",a="Upon deciphering the letter, Sirra realized Abercrombie has committed something unspeakable and unleashed a monstrous doom that is already lumbering toward Darkshire. He sends you to warn Lord Ello Ebonlocke immediately so the town leadership can prepare for the impending catastrophe before it strikes their gates.",al={"why send letter to ello","sirra von indi motive","why deliver translated note"},it="motive",add="203575b3"},{q="Why does Sirra send you to warn Lord Ello instead of going himself?",a="You were the one originally tasked by Lord Ello with deciphering Abercrombie's suspicious writings, and you carried the strange letter to Sirra in the first place. With a monstrous threat already on the move and every second counting, sending the capable adventurer standing right in front of him is the fastest way to get the warning into the mayor's hands.",al={"why me translation to ello","why doesnt sirra go to ello","why send player to ello"},it="why_me",add="4e225af8"}},ang={["faction:Alliance"]="As an Alliance champion, you face a painful lesson in Duskwood's treachery: misplaced trust in the woods can endanger an entire settlement of innocent citizens."},kw={"abercrombie","darkshire","ello ebonlocke","raven hill","sirra von'indi","translation to ello"},rel={"npc:lord-ello-ebonlocke","npc:abercrombie","npc:sirra-von-indi","quest:253","quest:401","subzone:darkshire","subzone:raven-hill-cemetery"},m={start="Sirra Von'Indi",["end"]="Lord Ello Ebonlocke",level="30",faction="Alliance",id=252},src={"Translation to Ello"}}
E["quest:253"] = {t="quest",n="Bride of the Embalmer",z="duskwood",s="In Darkshire, Lord Ello Ebonlocke sends you to find Eliza's grave. The town now knows the Embalmer is real, and you are to take his living heart from her cursed remains and strip him of his power.",h="In Darkshire, Lord Ello Ebonlocke sends you to find Eliza's grave.",sec={{t="A Bedtime Story Come Alive",b="Duskwood's children grew up hearing tales of the Embalmer. They said he was a kindly alchemist driven mad by the death of his beloved wife, Eliza. Desperate to cheat death, he turned to sorcery, cut out his own beating heart, and placed it in her chest. Lord Ello Ebonlocke once dismissed the tale as village folklore. Recent discoveries prove the Embalmer walks among the living, and his work festers beneath the graveyard dirt.",sp=0},{t="The Resurrected Bride",b="Eliza returned to life at a terrible cost. The stolen spark revived her as a ravenous abomination, forever hungry for living human flesh. Horrified by what he had made and unwilling to destroy her, the Embalmer hid his bride in a lonely grave. He visited her in secret as he plotted further wicked deeds.\n\nNow Lord Ebonlocke sends you to uncover Eliza's grave and kill the flesh hungry horror. Take the still beating heart that sustains the Embalmer's dark art.",sp=1},{t="Darkshire's Aegis",b="When you bring Eliza's beating heart to Darkshire, Lord Ebonlocke is relieved. The mayor does not mean to destroy it. He plans to turn the alchemist's craft against him, using the heart's eldritch magic as a defensive talisman over Darkshire.\n\nHe hopes it will shield the beleaguered town from whatever wrath the weakened Embalmer can still summon in vengeance.",sp=2}},faq={{q="Who is the Embalmer?",a="The Embalmer was an alchemist in Duskwood who went mad after his wife, Eliza, died. He turned to necromancy and cut out his living heart. Placing it in her corpse revived her and made him an elusive monster.",al={"embalmer lore","who is the embalmer","embalmer backstory"},it="identity"},{q="Why was Eliza buried if she was brought back to life?",a="The alchemist revived Eliza with his own heart, but dark magic made her ravenous for living human flesh. Unable to return her safely to society or satisfy her feral hunger, he hid her in a cemetery.",al={"why is eliza buried","eliza grave","why keep eliza in a grave"},it="history"},{q="Why does Lord Ebonlocke want the Embalmer's Heart?",a="Ello believes the Embalmer's heart is the source of his power. He asks you to take it from Eliza's grave while it still beats, hoping to break the alchemist's power.",al={"why get the heart","embalmer heart purpose"},it="why_wanted"},{q="Where does this quest chain begin?",a="The chain follows directly from 'Translation to Ello'. The old letters and research delivered to Lord Ello Ebonlocke prove that the Embalmer from local nursery tales is active and dangerous.",al={"quest prerequisite","how to get bride of the embalmer","embalmer prequest"},it="origin",gp=true},{q="Does retrieving the heart defeat the Embalmer permanently?",a="Ello believes taking the heart will break the Embalmer's power. What follows becomes clear when you return to Darkshire.",al={"is the embalmer dead","does this kill the embalmer"},sp=1,it="conflict"},{q="Who gives this quest?",a="Lord Ello Ebonlocke, Darkshire's mayor and leader, gives you this charge at the Darkshire Town Hall. He has learned the truth behind the town's folklore.",al={"quest giver","who starts bride of the embalmer"},it="in_charge",gp=true},{q="Why does Lord Ello Ebonlocke want Eliza's grave disturbed?",a="Lord Ello Ebonlocke wants to break the Embalmer's power before the mad alchemist brings ruin upon Darkshire. The Embalmer poured his own dark magic and heart into reviving his deceased wife, Eliza. By recovering the heart while it still beats, Ebonlocke intends to sap the monster's supernatural strength and turn its residual warding magic into an aegis to shield the town.",al={"why does ello want this done","ebonlocke motive bride of the embalmer","why find eliza's grave"},sp=1,it="motive",add="a9aedc81",bt={"q165.5"}},{q="What is Eliza, and why is she buried in Raven Hill?",a="Eliza is the reanimated bride of the Embalmer, resting in a neglected plot within the cemetery of Raven Hill. Driven mad by grief, her husband placed his own heart into her corpse to raise her. The ritual succeeded, but it cursed her with an insatiable hunger for living human flesh, forcing him to keep her entombed until he could find a way to sustain her.",al={"who is eliza","bride of the embalmer target","why is eliza buried"},it="target",add="b836fb1b"}},ang={["class:Paladin"]="As a paladin, you can see Eliza's foul reanimation as an affront to the Light and natural law. You can purge the flesh eating horror and sever the necromancer's blasphemous lifeline.",["class:Priest"]="As a priest, you can recognize the grieving widower's tragedy. Yet Eliza's flesh hungry mockery of life must be laid to rest with holy finality.",["faction:Alliance"]="With the Night Watch stretched thin against Duskwood's feral terrors, you must step in as an Alliance champion to defend Darkshire from this ancient, creeping madness."},kw={"alchemist","bride of the embalmer","darkshire","duskwood","eliza","ello ebonlocke","embalmer's heart","grave","the embalmer"},rel={"npc:lord-ello-ebonlocke","quest:252","subzone:darkshire","zone:duskwood"},m={start="Lord Ello Ebonlocke",level="30",faction="Alliance",id=253,ri={"The Embalmer's Heart"}},src={"Bride of the Embalmer"}}
E["quest:254"] = {t="quest",n="Digging Through the Dirt",z="duskwood",s="At Raven Hill Cemetery, you search for the Embalmer’s missing heart. A mound marked Eliza may hold the answer, buried beneath the dirt.",h="At Raven Hill Cemetery, you search for the Embalmer’s missing heart.",sec={{t="A Grave Disturbed",b="At Raven Hill Cemetery, one patch of loose soil bears the name Eliza. Other graves in Duskwood lie open to scavengers or feral ghouls, yet this earth was laid with care. Dig beneath the topsoil and you find splintered coffin boards. They cover the remnant the Embalmer meant to hide from daylight.",sp=0},{t="The Scratching Within",b="Eliza lies beneath splintered coffin boards, but she does not rest. The lid shudders as clawed fingers scrape and rotting jaws clatter. Abercrombie’s experiment stirs inside her pine coffin. The Embalmer’s missing heart beats in her breast as she waits for unwary hands to open the grave.",sp=1}},faq={{q="What is buried in Eliza's grave?",a="A coffin lies beneath the dirt, holding Eliza, an undead creature made by the Embalmer. His heart rests in her breast.",al={"what is in the grave","who is eliza","eliza grave contents"},sp=1,it="target"},{q="Where is this grave located?",a="Eliza’s grave lies in Raven Hill Cemetery in western Duskwood, among haunted crypts and roaming undead.",al={"where is elizas grave","eliza grave location","grave dirt location"},it="place",gp=true},{q="Why do you have to dig into the coffin?",a="You dig into the grave to face Eliza and recover the Embalmer’s heart. That ends the search for his foul schemes.",al={"why dig the grave","purpose of digging","why open the coffin"},sp=1,it="purpose"},{q="What happens when the coffin is opened?",a="When you open the coffin, Eliza breaks free. You must destroy the clawing ghoul to recover the heart sealed inside with her.",al={"what happens next","coffin opened","opening elizas coffin"},sp=1,it="next_step"},{q="Who put Eliza in the ground?",a="The Embalmer buried Eliza in Raven Hill Cemetery, hiding his creation and prized heart among its graves.",al={"who buried eliza","who put her there"},sp=1,it="origin"},{q="Is Eliza an ordinary ghoul?",a="Eliza was the Embalmer’s wife, raised by his dark magic with his heart in her breast. She is tougher and more deliberate than the mindless ghouls roaming Duskwood’s roads.",al={"what kind of monster is eliza","is eliza a ghoul"},sp=1,it="threat"}},ang={["class:Paladin"]="Disturbing a fresh grave violates the funeral rites of the Holy Light. Releasing and destroying the unnatural fiend within cleanses the grave.",["class:Priest"]="Clawing and gnashing beneath consecrated soil offend the peaceful rest the Light promises Duskwood’s dead.",["faction:Alliance"]="The Night Watch struggles against the terror spilling from Raven Hill. Finding the horrors the Embalmer buried is vital to Darkshire’s safety."},kw={"abercrombie","bride of the embalmer","coffin","digging through the dirt","duskwood","eliza","eliza's grave dirt","embalmer's heart","raven hill cemetery"},rel={"quest:253","zone:duskwood"},m={start="Eliza's Grave Dirt",level="30",faction="Alliance",id=254},src={"Digging Through the Dirt"}}
E["quest:262"] = {t="quest",n="The Shadowy Figure",z="duskwood",s="Near his ruined farm, Sven Yorgen seeks the stranger who watched his family die. He gives you a strange book found in the wreckage and asks you to learn who left it behind.",h="Near his ruined farm, Sven Yorgen seeks the stranger who watched his family die.",sec={{t="Echoes of a Slaughter",b="In Duskwood’s western hills, Sven Yorgen still grieves for his slaughtered family. He once blamed the black riders who terrorize the woods. Yet he remembers a shadowy figure nearby on the night of the massacre. Sven gives you the strange book found at his ransacked farm, the only physical clue in the wreckage.",sp=0},{t="Seeking Divination in Town",b="With no clear trail through the perilous wilderness, you head east to Darkshire. Sven hopes one of the superstitious townsfolk will recognize the curious book. Madame Eva is among them, and her occult senses reach beyond ordinary sight. Her divinations may reveal impressions left on mysterious relics.",sp=0},{t="Foreign Threads",b="Madame Eva reads faint impressions from the book. Sven’s recent desire for vengeance has marked its pages. Beneath that mark lies another presence. Eva senses that the first owner came from beyond Darkshire and Duskwood, and had visited the farm before the bloodshed began.",sp=1}},faq={{q="Who is Sven Yorgen?",a="Sven Yorgen is a devastated farmer who lives in exile in Duskwood’s western hills. After dark riders slaughtered his family at their homestead, grief drove him into the wilderness. There he seeks revenge against those responsible.",al={"who is sven","sven backstory","sven yorgen"},it="identity"},{q="What is the book found at Sven's farm?",a="The book is a physical artifact recovered from the dirt and rubble of Sven’s destroyed homestead. An elusive onlooker left it behind after lurking in the shadows during the attack on Sven’s family.",al={"what book is this","book from svens farm","mysterious book"},it="item"},{q="Why take the book to Madame Eva?",a="Madame Eva is Darkshire’s resident seer and fortune teller. Ordinary townsfolk can learn little from an unmarked volume, but her clairvoyance lets her read impressions left by whoever owned or carried it before.",al={"why madame eva","who reads the book","darkshire mystic"},it="next_step"},{q="What does Madame Eva learn from the book?",a="Madame Eva senses that Sven’s recent handling of the book left a powerful imprint of vengeance. Beneath it, she detects faint traces showing that the first owner came from beyond Darkshire.",al={"what does eva say","book owner identity","divination result"},sp=1},{q="Where does this investigation lead next?",a="Madame Eva learns that the book’s owner came from beyond Darkshire. She sends you to search the town’s records and familiar places for anyone who remembers an unfamiliar traveler like the figure.",al={"what next","next quest after book","who is the shadowy figure"},sp=1,it="next_step"},{q="Why does Sven Yorgen want this done?",a="Sven is consumed by grief and a desperate need for answers. On the night his family was slaughtered at his farm, he saw a mysterious figure lurking in the shadows. He believes that discovering the identity of this skulker is his only chance to learn the truth behind the massacre and see justice served.",al={"why does sven want the shadowy figure found","sven yorgen motive","why find the book's owner"},it="motive",add="d371091b"},{q="Why does Sven Yorgen ask you instead of the Night Watch?",a="Sven is an isolated, traumatized hermit hiding out in the wilds of Duskwood, far from Darkshire. You have already proved your resourcefulness by discovering the ruined journal at his devastated farmstead, convincing him that you possess the grit and cunning needed to unravel the mystery when no one else will.",al={"why doesn't sven ask the night watch","why does sven need my help","why me sven yorgen"},it="why_me",add="35559963"}},ang={["faction:Alliance"]="Darkshire receives little support from Stormwind. Its traumatized frontiersmen and local seers rely on wandering Alliance champions to investigate deadly atrocities in Duskwood.",["class:Priest"]="As a priest, you see how spiritual clairvoyance, shadow magic and the impressions lingering on ordinary objects can touch."},kw={"book","darkshire","duskwood","madame eva","shadowy figure","sven yorgen","sven's camp"},rel={"quest:230","quest:265","npc:sven-yorgen","npc:madame-eva","subzone:darkshire","zone:duskwood"},m={start="Sven Yorgen",["end"]="Madame Eva",level="25",faction="Alliance",id=262},src={"The Shadowy Figure"}}
E["quest:265"] = {t="quest",n="The Shadowy Search Continues",z="duskwood",s="In Duskwood, you trace the journal from Madame Eva to Clerk Daltry in Darkshire. It came from the ruins of Sven Yorgen’s ransacked farmstead.",h="In Duskwood, you trace the journal from Madame Eva to Clerk Daltry in Darkshire.",sec={{t="Tracing the Binding",b="Madame Eva found that the journal’s author was an outsider, though its binding came from Darkshire. Clerk Daltry sells blank ledgers and tomes to traveling scholars, spellcasters, and record-keepers. So you follow those local sales for a clue to the sinister trespasser in Duskwood’s groves.",sp=0},{t="A Jittery Buyer",b="Clerk Daltry remembers the sale, though many records pass through Darkshire’s town hall. About a month ago, a nervous traveler bought the blank book and gave no name. The furtive buyer kept glancing over his shoulder, leaving a clear impression on the clerk. Sven’s shadowy figure had walked openly among Darkshire’s citizens.",sp=1}},faq={{q="Where did the mysterious book come from?",a="Madame Eva says the author was an outsider, but the book was bought in Darkshire. Clerk Daltry sells blank books and may remember who bought it.",al={"origin of book","who sold the book","book source"},it="item"},{q="Why does Madame Eva send you to Clerk Daltry?",a="Madame Eva found that the book’s binding and materials came from a local purchase. Clerk Daltry sells blank ledgers and journals to locals and traveling scholars.",al={"why daltry","eva daltry connection","who made the book"},it="purpose"},{q="What does Clerk Daltry remember about the buyer?",a="Daltry remembers a nervous, nameless traveler who bought the blank book about a month ago.",al={"who bought book","buyer description","shadowy figure appearance"},it="identity"},{q="How does this connect to Sven's farm?",a="The book was salvaged from Sven Yorgen’s destroyed farm in southern Duskwood. It was left behind after a murderous raid wiped out his family.",al={"sven connection","why are we looking","sven yorgen"},it="ties"},{q="Where does the investigation lead next?",a="The search continues at Darkshire’s Scarlet Raven Tavern. Someone there may know where the nervous stranger stayed or whom he spoke with.",al={"what next","after daltry","next clue"},sp=1,it="next_step"},{q="Is Clerk Daltry in danger?",a="Daltry is helping identify a buyer from his ordinary book sales. Nothing in the exchange suggests he is personally threatened.",al={"clerk daltry danger","daltry safe"},it="danger"},{q="Why is Madame Eva helping with the search?",a="Madame Eva serves as Darkshire's seer and advisor, keeping watch over the shadowy omens that plague Duskwood. When you brought her the dirt-stained book from Sven's ruined farm, she sensed that someone driven by revenge had handled it recently, while the faint impressions of its original owner marked him as a stranger to Darkshire. She could also tell that the book itself was purchased in town, so she sends you to question the townsfolk in hopes they can link the book to its owner.",al={"why does madame eva help","madame eva motive","why does madame eva care about the book"},it="motive",add="9bf6b406"}},ang={["faction:Alliance"]="For the Alliance, tracing who supplied and aided the necromancers in Duskwood matters to Darkshire’s safety and justice for slaughtered frontier homesteaders.",["class:Rogue"]="As a rogue, you know purchase records and a merchant’s memory can help track a nervous target through town."},kw={"book","clerk daltry","darkshire","duskwood","journal","madame eva","shadowy figure","sven yorgen"},rel={"npc:clerk-daltry","npc:madame-eva","quest:262","quest:266","subzone:darkshire","zone:duskwood"},m={start="Madame Eva",["end"]="Clerk Daltry",level="25",faction="Alliance",id=265},src={"The Shadowy Search Continues"}}
E["quest:266"] = {t="quest",n="Inquire at the Inn",z="duskwood",s="Clerk Daltry sends you from Darkshire to the Scarlet Raven Tavern with a journal from Sven Yorgen's ruined farm. He hopes someone there knows who owned it.",h="Clerk Daltry sends you from Darkshire to the Scarlet Raven Tavern with a journal from Sven Yorgen's ruined...",sec={{t="A Lead at the Scarlet Raven",b="Clerk Daltry has finished examining the tattered book from Sven Yorgen's farm. He believes any stranger who came to Darkshire would have passed through its tavern. The Scarlet Raven Tavern stands across town as Darkshire's only gathering hall and lodging house. There, you may learn who came through and where they went.",sp=0},{t="The Paranoid Guest",b="Tavernkeep Smitts recognizes the journal when you show it to him. Its owner rented a room for several days and spent his evenings scribbling at the bar. Then the guest fled Darkshire in terror, convinced an unseen pursuer was hunting him. The stranger took the road west toward Raven Hill.",sp=1}},faq={{q="Who sends you to the inn?",a="Clerk Daltry, Darkshire's town record-keeper, sends you to the Scarlet Raven Tavern after examining the journal. He hopes someone there will recognize its owner.",al={"who gives this quest","quest giver","where does inquire at the inn start"},gp=true},{q="What is the book you are carrying?",a="The worn journal came from Sven Yorgen's ruined farmstead in southern Duskwood. It is believed to belong to the shadowy figure seen prowling nearby.",al={"what is the book","book from svens farm","journal"},it="item"},{q="Who runs the Scarlet Raven Tavern?",a="Tavernkeep Smitts runs the Scarlet Raven Tavern. He serves drinks and rents rooms to travelers who venture into Duskwood.",al={"who is the tavernkeeper","innkeeper darkshire","who is smitts"},it="people"},{q="What does Tavernkeep Smitts reveal about the guest?",a="The journal's owner rented a room for several days and spent his evenings writing at the bar. Then he fled Darkshire in terror, convinced an unseen pursuer was hunting him.",al={"what did smitts say","what happened to the shadowy figure","what does the innkeeper know"},it="next_step"},{q="Where did the shadowy figure flee?",a="The stranger fled west from Darkshire along the road toward Raven Hill.",al={"where did he go","where is the shadowy figure","where to next"},it="target"},{q="What quest follows Inquire at the Inn?",a="Tavernkeep Smitts points you west to follow the stranger's trail in Finding the Shadowy Figure.",al={"next quest","what comes after inquire at the inn","following quest"},gp=true},{q="Why does Clerk Daltry want you to inquire at the inn?",a="Clerk Daltry keeps the town records of Darkshire, but his ledgers cannot account for mysterious wanderers slipping through the shadows. Knowing you are tracking the elusive figure tied to the grim events at Sven's farm, he points you toward the Scarlet Raven Tavern. In a wary town like Darkshire, any stranger who stayed for a drink or a bed would have caught the innkeeper's eye.",al={"why does daltry send you to the inn","daltry inn motive","why ask at scarlet raven inn"},it="motive",add="5b964541"}},ang={["faction:Alliance"]="As an Alliance adventurer, you help protect Darkshire, an isolated frontier settlement in the southern Eastern Kingdoms, by investigating threats within its walls.",["class:Rogue"]="As a rogue, you can follow a fugitive's trail from tavern talk to desolate ruins through careful investigation."},kw={"clerk daltry","darkshire","duskwood","inquire at the inn","raven hill","scarlet raven","shadowy figure","sven yorgen","tavernkeep smitts"},rel={"npc:tavernkeep-smitts","npc:clerk-daltry","quest:265","quest:453","quest:262","quest:163","zone:duskwood"},m={start="Clerk Daltry",["end"]="Tavernkeep Smitts",level="25",faction="Alliance",id=266},src={"Inquire at the Inn"}}
E["quest:268"] = {t="quest",n="Return to Sven",z="duskwood",s="You bring Jitters' finished journal to Sven Yorgen's camp near Westfall. Its pages may answer the questions that have haunted him since his family's murder.",h="You bring Jitters' finished journal to Sven Yorgen's camp near Westfall.",sec={{t="A Coward's Confession",b="When Sven Yorgen's farm came under attack, Jitters fled into the woods and left an incomplete diary behind. Afraid of Sven's anger and haunted by what he had seen, he hid deep in Duskwood. When you find him, he willingly gives you his finished journal. He hopes the full account will spare him from facing Sven in person.",sp=0},{t="Unmasking the Dark Riders",b="Jitters' finished account explains why the Dark Riders killed Sven's family. They sought an artifact, rather than striking in a random undead surge or an attack by feral beasts. Sven also remembers those same hooded figures meeting in secret with the necromancer Morbent Fel near the Forlorn Rowe. Now his blind sorrow has become a hunt for retribution against Morbent Fel.",sp=1}},faq={{q="Why is Jitters so terrified of Sven Yorgen?",a="Jitters fled Sven's farm and fears facing the grieving farmer's anger. He asks you to carry his journal to Sven so he can read the account.",al={"why is jitters scared","jitters afraid of sven","what did jitters do"},it="motive"},{q="What is in Jitters' completed journal?",a="Jitters' finished journal gives his full account of what happened at Sven's farm. Sven needs to read it to understand what happened to his family.",al={"what does the journal say","jitters completed journal lore"},sp=1,it="item"},{q="Who are the Dark Riders mentioned by Sven?",a="The Dark Riders are mysterious, hooded figures who roam Duskwood. They seek powerful magical relics and leave death and ruin behind them.",al={"who are dark riders","riders in duskwood","black riders"},it="target"},{q="How is Morbent Fel connected to the attack on Sven's farm?",a="Morbent Fel is a powerful necromancer in western Duskwood. Sven's investigation and Jitters' journal reveal his connection to the attack.",al={"morbent fel connection","why morbent fel","who is morbent fel"},sp=1,it="ties"},{q="Where can Sven Yorgen be found?",a="Sven has left his ruined farmstead for a small camp in Duskwood's northwestern hills, near the border crossing into Westfall.",al={"where is sven","sven yorgen location","sven camp"},it="place",gp=true},{q="What happens after giving Sven the journal?",a="After reading Jitters' account, Sven asks you to prove your combat abilities in Proving Your Worth.",al={"next quest after return to sven","sven questline next"},sp=1,it="next_step"},{q="Why does Jitters need you to deliver the journal instead of taking it himself?",a="Jitters is completely consumed by fear. He hid unseen in Sven's barn while Sven's family was slaughtered, then fled, leaving his half-finished journal behind. Rather than risk facing Sven's wrath in person, he gladly hands you his completed journal to deliver the truth about what actually transpired.",al={"why send me jitters","why can't jitters talk to sven","why deliver jitters journal"},it="why_me",add="ba46c9da"}},ang={["faction:Alliance"]="The destruction of Yorgen Farmstead shows Stormwind's failure to protect Duskwood's frontier settlements from the encroaching shadows.",["class:Paladin"]="As a paladin, you help Sven uncover the forces behind his family's murder. Your holy duty calls you to protect the innocent and seek justice."},kw={"dark riders","duskwood","forlorn rowe","jitters","jitters' completed journal","morbent fel","sven yorgen","yorgen farmstead"},rel={"npc:sven-yorgen","npc:jitters","quest:453","topic:dark-riders","quest:55","subzone:forlorn-rowe","zone:duskwood","quest:262"},m={start="Jitters",["end"]="Sven Yorgen",level="25",faction="Alliance",id=268},src={"Return to Sven"}}
E["quest:270"] = {t="quest",n="The Doomed Fleet",z="duskwood",s="Bishop Farthing sends you north from Stormwind to find a way through Morbent Fel's wards. Your trail crosses Khaz Modan and ends at the wreck of Kul Tiras's Third Fleet off the Wetlands.",h="Bishop Farthing sends you north from Stormwind to find a way through Morbent Fel's wards.",sec={{t="A Weapon of Holy Truth",b="Morbent Fel's wards turn ordinary steel aside at his retreat on the Forlorn Rowe. Bishop Farthing sends you to seek a weapon bound to the Holy Light. Its key is Lightforge Iron, a rare consecrated metal whose strikes carry holy truth and pierce sorcerous protections.",sp=0},{t="The Wreck of the Third Fleet",b="Duskwood has no Lightforge Iron to hand. Bishop Farthing recalls that Kul Tiras's Third Fleet sank years ago along the dangerous Wetlands coast, north of Ironforge. One galleon carried a shipment of the precious ore. You travel to Menethil Harbor to meet Glorin Steelbrow, a dwarven contact who knows the marshes and their wrecks.",sp=0}},faq={{q="Why do I have to travel all the way to the Wetlands?",a="Morbent Fel's dark enchantments turn aside ordinary attacks. Bishop Farthing says only a weapon forged from sacred Lightforge Iron can break through his wards. The known shipment lies among Kul Tiras's wrecked Third Fleet off Menethil Harbor.",al={"why go to wetlands","why menethil harbor","wetlands trip"},it="purpose"},{q="Who is Morbent Fel?",a="Morbent Fel is a necromancer who dwells on the Forlorn Rowe in Duskwood. His sorcery has fueled much of the undead uprising threatening the region. Darkshire's survival depends on defeating him.",al={"morbent fel identity","who is the necromancer","duskwood necromancer"},it="target"},{q="Who is Glorin Steelbrow?",a="Glorin Steelbrow is a dwarf at Menethil Harbor in the Wetlands. He is an ally of the Church of the Holy Light and knows the coastline, shipwrecks and salvage work in the marsh.",al={"who is steelbrow","steelbrow role"},it="identity"},{q="What is Lightforge Iron?",a="Lightforge Iron is a specially consecrated metal prized by the priesthood. Weapons forged from it carry holy power that can pierce dark shields and necromantic curses ordinary iron cannot overcome.",al={"what does lightforge iron do","lightforge metal","blessed iron"},it="item"},{q="What happened to the Third Fleet of Kul Tiras?",a="Years ago, Kul Tiras's Third Fleet sank along the rough, swampy Wetlands coast. Its hulls still lie beneath the water, with lost cargo, drowned sailors and aquatic predators among the wrecks.",al={"third fleet fate","kul tiras ships wetlands","how did ships sink"},it="history"},{q="Does this quest involve any fighting right away?",a="You travel as a courier from Duskwood through the Kingdom of Stormwind and Khaz Modan to Menethil Harbor. There, you contact Glorin Steelbrow.",al={"is there combat","just travel quest"},gp=true},{q="Why does Bishop Farthing send you on this quest?",a="Bishop Farthing knows that the necromancer Morbent Fel poses a lethal threat to Duskwood and cannot be vanquished by ordinary means. To defeat such a dark force, you need a weapon blessed with sacred power, forged from sacred Lightforge iron. Because that iron was lost at sea with the Third Fleet of Kul Tiras, Farthing sends you north to Menethil Harbor to consult his dwarven associate, Glorin Steelbrow, in hopes of reclaiming the sunken metal.",al={"why does bishop farthing want lightforge iron","farthing motive doomed fleet","why find the doomed fleet"},it="motive",add="ade8f412"},{q="Why can't Bishop Farthing or the Night Watch handle Morbent Fel themselves?",a="The Night Watch is stretched dangerously thin just keeping Duskwood's borders from collapsing under the weight of mindless undead, worgen, and spiders. Bishop Farthing must tend to his duties at the Cathedral of Light in Stormwind, and neither he nor the local militia can spare the time or manpower for a lengthy trek across the continent to the Wetlands. As an independent traveler, you have the freedom and resolve to seek out the lost iron and face the necromancer directly.",al={"why send me doomed fleet","why doesn't the night watch go","why bishop farthing needs me"},it="why_me",add="a631378f"}},ang={["class:Paladin"]="As a Paladin, you seek holy metal to strike down an unholy necromancer. You wield weapons sanctified by the Light to purge darkness.",["class:Priest"]="As a Priest, you follow Bishop Farthing's guidance and the Church's old knowledge of blessed relics and consecrated ores.",["faction:Alliance"]="As an Alliance traveler, you connect the isolated human towns of the south with dwarven harbors and ancient sea routes.",["profession:Blacksmithing"]="As a Blacksmith, you learn of rare Lightforge Iron, a metal imbued with faith and shaped by master craftsmanship."},kw={"bishop farthing","doomed fleet","glorin steelbrow","kul tiras","lightforge iron","menethil harbor","morbent fel","third fleet","wetlands"},rel={"quest:269","quest:321","quest:55","npc:glorin-steelbrow","subzone:menethil-harbor","zone:wetlands","zone:duskwood","topic:kul-tiras"},m={start="Bishop Farthing",["end"]="Glorin Steelbrow",level="29",faction="Alliance",id=270},src={"The Doomed Fleet"}}
E["quest:323"] = {t="quest",n="Proving Your Worth",z="duskwood",s="In Duskwood, Sven Yorgen tests your strength before you face Morbent Fel. The hermit wants revenge for his family and needs proof you can defeat the undead at Raven Hill Cemetery.",h="In Duskwood, Sven Yorgen tests your strength before you face Morbent Fel.",sec={{t="A Bitter Hermit's Test",b="Sven Yorgen grieves at a secluded camp north of the howling woods. Fury burns in him over the slaughter of his family. He has learned that the Dark Riders who destroyed his homestead were allied with the necromancer Morbent Fel. Sven wants revenge, but he will not send an untried ally into Fel's grasp. First, he asks you to prove your fighting skill against the skeletons at Raven Hill Cemetery.",sp=0},{t="The Raven Hill Crypts",b="Raven Hill Cemetery lies south of Forlorn Rowe, and corpses bound by Fel's magic fill its grounds and mausoleum. Skeletal Raiders patrol among the tombstones with swords. Below, Skeletal Warders and Healers tend the chambers. To earn Sven's trust, you must press deep into the necropolis and clear this vanguard. Mor'Ladim, a vengeful phantom, prowls the cemetery paths.",sp=0},{t="The Road to the Necromancer",b="Surviving Raven Hill's catacombs convinces Sven that you have more than courage. Fel's lesser minions are only the first obstacle. Morbent Fel's dark enchantments shield him from ordinary weapons. So Sven seeks greater wisdom and ancient relics before the final confrontation.",sp=1}},faq={{q="Why does Sven make me fight skeletons before facing Morbent Fel?",a="Sven knows Morbent Fel is a deadly necromancer allied with the mysterious Dark Riders. He will not send you to face Fel until you prove you can fight through a vanguard of undead.",al={"why proving your worth","why sven makes me kill skeletons","sven test"},it="motive"},{q="Where are the Skeletal Warders and Healers found?",a="Skeletal Raiders patrol the open cemetery south of Forlorn Rowe. Skeletal Healers and Warders gather in and around the large mausoleum and the crypt tunnels west of the cemetery's center.",al={"where are warders","where are skeletal healers","find skeletal warders"},gp=true},{q="Who is Mor'Ladim and why should I watch out for him here?",a="Mor'Ladim is a powerful undead knight who roams Raven Hill Cemetery. He is far stronger than the ordinary skeletons and can quickly cut down the unwary.",al={"morladim danger","who is mor'ladim","wandering elite raven hill"},it="danger"},{q="How is Morbent Fel connected to the Dark Riders?",a="Sven learned that Morbent Fel allied with the cloaked Dark Riders who butchered his wife and children. The riders vanished into the shadows, while Fel remains in Duskwood and continues his necromancy.",al={"morbent fel dark riders connection","why dark riders and fel","sven family killers"},it="ties"},{q="What happens after completing this quest?",a="After you prove your strength, Sven explains that brute force alone cannot kill Morbent Fel. He sends you to Bishop Farthing at Stormwind's Cathedral of Light to learn how to strip away the necromancer's protections.",al={"next quest after proving your worth","what to do after skeletons"},sp=1,it="next_step"},{q="Where is Sven Yorgen's camp located?",a="Sven keeps a hidden camp in the hills at Duskwood's far northwestern edge. It lies north of Raven Hill and west of the road to Westfall.",al={"where is sven","sven camp location"},it="place",gp=true},{q="Who are the skeletal minions at Raven Hill?",a="The skeletal raiders, healers, and warders haunting Raven Hill Cemetery are the reanimated dead raised by the necromancer Morbent Fel. Drawn from the desecrated graves of Duskwood, these restless dead now form an unholy bulwark guarding the cemetery crypts and carrying out the dark will of their master.",al={"skeletal raiders raven hill","who are the skeletons raven hill","morbent fel minions"},it="target",add="865aa68b"},{q="Why does Sven Yorgen need you to fight Morbent Fel's minions?",a="Sven Yorgen is an isolated hermit surviving alone in the haunted wilderness of Duskwood. Shattered by grief and driven by hatred for the Dark Riders who slaughtered his family, he lacks the strength and resources to assault Morbent Fel's undead army alone. He turns to capable adventurers willing to brave Raven Hill Cemetery to exact his vengeance.",al={"why does sven need help","why doesn't sven fight","why ask me sven"},it="why_me",add="fbdf818d"}},ang={["faction:Alliance"]="In western Duskwood, regular Stormwind patrols are absent and anarchy has taken hold. As an Alliance champion, you can help frontiersmen like Sven push back the undead.",["class:Paladin"]="As a paladin, you can bring the Light's justice to Raven Hill Cemetery and cleanse the restless dead of Morbent Fel's magic.",["class:Priest"]="As a priest, you can answer the desecration of Raven Hill's tombs with spiritual cleansing and end the warders' and healers' corruption of life and death."},kw={"dark riders","duskwood","forlorn rowe","morbent fel","proving your worth","raven hill cemetery","skeletal healer","skeletal raider","skeletal warder","sven yorgen"},rel={"npc:sven-yorgen","quest:268","quest:269","quest:55","subzone:raven-hill-cemetery","subzone:forlorn-rowe","topic:mor-ladim","topic:dark-riders"},m={start="Sven Yorgen",level="28",faction="Alliance",id=323},src={"Proving Your Worth (Classic)"}}
E["quest:401"] = {t="quest",n="Wait for Sirra to Finish",z="duskwood",s="In Darkshire's Town Hall, Sirra Von'Indi writes as he deciphers Abercrombie's cryptic note. Dread settles over the room, and the hermit's words hint at danger.",h="In Darkshire's Town Hall, Sirra Von'Indi writes as he deciphers Abercrombie's cryptic note.",sec={{t="A Moment of Translation",b="Sirra Von'Indi has the note Abercrombie sent from his seclusion. He aids the Night Watch and Darkshire's leaders, and needs only a short time to decipher the message. He does not yet know what horrors the words conceal.",sp=0},{t="An Ominous Chill",b="When Sirra finishes the transcription, a sudden heaviness fills the room, like a black curtain falling over the region. The note warns of great danger for Darkshire. Abercrombie's seemingly harmless errands served a sinister, vengeful design.",sp=1}},faq={{q="Who is Sirra Von'Indi?",a="Sirra Von'Indi is a scholar in Darkshire's Town Hall. He helps Mayor Ello Ebonlocke and the local authorities translate ancient scripts, strange documents, and ciphered messages brought in from Duskwood's gloomy wilds.",al={"sirra von'indi","who is sirra","sirra duskwood"},it="identity"},{q="What note is Sirra translating?",a="Abercrombie, the hermit in a shack near Duskwood's western edge, wrote the note. You carried out a string of errands for him before it came to Sirra for translation.",al={"what is the note","abercrombie note","what did abercrombie write"},sp=1,it="item"},{q="Why does the air feel heavy when he finishes?",a="The heaviness is an omen of impending doom. The note brings grim news for Darkshire, and its full meaning becomes clear when the translation reaches Lord Ello Ebonlocke.",al={"why does air grow heavy","black curtain over land","duskwood dark air"},sp=2,it="threat"},{q="Who should receive the translated letter next?",a="When Sirra finishes translating, he asks you to carry the chilling words across the room to Mayor Ello Ebonlocke, so the Night Watch can prepare for what is coming.",al={"where do i take the translation","who gets the note next","next step after sirra"},it="next_step"},{q="Is Abercrombie actually an enemy of Darkshire?",a="Abercrombie presents himself as a harmless, reclusive old man who needs help to survive. The dread that falls as Sirra finishes suggests grim news for Darkshire, and the note's full meaning becomes clear when it reaches Lord Ello Ebonlocke.",al={"is abercrombie evil","hermit enemy","abercrombie lore"},sp=2,it="conflict"},{q="Why do you have to wait for him?",a="Sirra needs time and focus to translate ancient ciphers. He parses the hermit's handwriting and coded phrasing before producing a readable transcript for the mayor.",al={"why wait for sirra","how long do i wait","sirra waiting"},it="purpose"},{q="Why is Sirra Von'Indi translating Abercrombie's note?",a="Sirra Von'Indi is a scholar assisting the Night Watch and town leadership with matters beyond standard patrols. When you brought him Abercrombie's cryptic parchment, its odd script required careful deciphering. He wants it translated to uncover the hermit's true intentions and determine whether any lingering danger threatens Darkshire and its beleaguered people.",al={"sirra von'indi motive","why translate abercrombie note","why does sirra help translate"},it="motive",add="a1bfeb31"}},ang={["faction:Alliance"]="As an Alliance traveler, you know Darkshire's fragile safety hangs by a thread.",["class:Mage"]="As a mage, you recognize the dark, lingering resonance of a cursed message as its contents are laid bare."},kw={"abercrombie","darkshire","duskwood","ello ebonlocke","sirra von'indi","translation"},rel={"npc:sirra-von-indi","quest:251","quest:252","zone:duskwood"},m={start="Sirra Von'Indi",level="30",faction="Alliance",id=401},src={"Wait for Sirra to Finish"}}
E["quest:453"] = {t="quest",n="Finding the Shadowy Figure",z="duskwood",s="Sven Yorgen's farm has been devastated, and Finding the Shadowy Figure turns toward the stranger who fled it. Tavernkeep Smitts points the search west from Darkshire into Duskwood's haunted woods.",h="Sven Yorgen's farm has been devastated, and Finding the Shadowy Figure turns toward the stranger who fled it.",sec={{t="On the Trail of a Ghost",b="Sven Yorgen pleads for help identifying the figure who fled his devastated homestead. The trail leads to the Scarlet Raven Tavern, where Tavernkeep Smitts offers several clues. The fugitive was a complete stranger to Darkshire, nervous and jittery, and left the faint lamps at the town's edge in haste. He vanished into the wilderness to the west.",sp=0},{t="Unmasking Jitters",b="Jitters is found shivering among Duskwood's dangers, after the stranger's trail leads west. Shown the diary recovered from the ruined farm, he confesses that he wrote the tattered journal. Jitters is a terrified witness who fled the horrors unleashed on the region, not a calculated villain. He hints that the diary holds only part of the nightmare.",sp=1}},faq={{q="Who is the shadowy figure?",a="The shadowy figure is Jitters, a skittish wanderer who wrote about the dark events around Sven Yorgen's farm before fleeing west into the woods.",al={"shadowy figure identity","who is jitters","who is the stranger"},sp=2,it="identity"},{q="Where does Tavernkeep Smitts say the figure went?",a="Tavernkeep Smitts says the man was a stranger to Darkshire, visibly terrified, and fled west into the wilderness.",al={"where did he go","where is jitters","which way west"},gp=true},{q="Why was Jitters running from Sven's farm?",a="Jitters witnessed horrors strike Sven's farm and fled for his life, afraid that whatever destroyed Sven's family would come for him next.",al={"why did jitters run","what happened at sven farm","why is jitters scared"},sp=1,it="motive"},{q="What is the book found at Sven's farm?",a="The book found at Sven's farm is a journal written by Jitters about the ominous events before the massacre. Jitters admits it tells only half the story.",al={"book from sven's farm","jitters journal","what is the diary"},sp=2,it="item"},{q="Where can Jitters be found?",a="Jitters is in the western wilds of Duskwood, near the Raven Hill encampment, away from Darkshire and the forest's prowling beasts.",al={"jitters location","where is jitters in duskwood","jitters coordinates"},it="place",gp=true},{q="What happens after finding Jitters?",a="After confessing that he wrote the journal, Jitters prepares a complete account of what happened and sends you back to Sven Yorgen with the truth.",al={"what next","after finding jitters","where do i go next"},sp=1,it="next_step"},{q="Why does Tavernkeep Smitts want you to find the shadowy figure?",a="Tavernkeep Smitts does not harbor personal stakes in the tragedy at Sven's farm, but he recognizes the danger of Duskwood's wilderness. Knowing a nervous stranger fled the safety of Darkshire and headed west into beast-ridden woods, Smitts genuinely hopes the poor fellow is found before the horrors of the land tear him apart.",al={"smitts motive","why find shadowy figure","why does smitts care"},it="motive",add="033a8771"}},ang={["faction:Alliance"]="For the Alliance, learning why Jitters fled matters to understanding the growing darkness threatening the kingdom's southern frontier.",["class:Rogue"]="As a rogue, you rely on keen observation and tracking to follow a panicked suspect through dense, shadow-draped woods and separate rumor from true tracks."},kw={"darkshire","duskwood","finding the shadowy figure","raven hill","scarlet raven tavern","sven yorgen","tavernkeep smitts"},rel={"quest:266","quest:268","quest:262","npc:jitters","npc:tavernkeep-smitts","subzone:darkshire","zone:duskwood"},m={start="Tavernkeep Smitts",["end"]="Jitters",level="25",faction="Alliance",id=453},src={"Finding the Shadowy Figure"}}
E["quest:5"] = {t="quest",n="Jitters' Growling Gut",z="duskwood",s="In Raven Hill, Jitters is starving and afraid, with only weeds and insects to eat. He asks you to travel east to Darkshire for Chef Grual’s famous Dusky Crab Cakes.",h="In Raven Hill, Jitters is starving and afraid, with only weeds and insects to eat.",sec={{t="Starving in Raven Hill",b="Raven Hill shelters ravenous undead and lurking beasts among its ruined streets. Jitters has hidden there for weeks, moving through crumbling shanties beneath a sky that never seems to brighten. He has found only grubs in the dirt and wild weeds to eat. Hunger and fear wear him down, far from ordinary comforts.",sp=0},{t="A Plea for Crab Cakes",b="Jitters longs for a taste of safety: the seasoned patties made at the Scarlet Raven Tavern in Darkshire. He asks you to cross the haunted road and speak with Chef Grual. If the chef agrees to make Dusky Crab Cakes, a hot meal may quiet Jitters’ growling gut.",sp=0}},faq={{q="Who is Jitters?",a="Jitters is a frightened, paranoid man hiding in the ruined township of Raven Hill in western Duskwood. The undead there terrify him, and he fears starvation and slaughter.",al={"jitters","who is jitters","where is jitters"},it="identity"},{q="Where can I find Chef Grual?",a="Chef Grual works in the kitchen of the Scarlet Raven Tavern in Darkshire, on Duskwood’s eastern side.",al={"chef grual location","find grual","scarlet raven chef"},gp=true},{q="Why is Jitters eating grubs?",a="Jitters has spent weeks trapped in ruined Raven Hill, cut off from civilization by roaming undead and predatory worgen. With no provisions, he scavenges insects and foliage to survive.",al={"jitters eating bugs","why eats grubs","raven hill food"},it="motive"},{q="What dish does Jitters want?",a="Jitters wants Dusky Crab Cakes, a local specialty Chef Grual prepares at the Scarlet Raven Tavern.",al={"jitters food","crab cakes quest","what does jitters want to eat"},it="purpose"},{q="What happens after speaking with Chef Grual?",a="Chef Grual agrees to cook for Jitters, but he has no fresh ingredients. He asks you to gather gooey spider legs for the Dusky Crab Cakes.",al={"after jitters growling gut","next quest jitters gut","chef grual task"},sp=1,it="next_step",gp=true},{q="Can Horde players complete this quest?",a="No. Jitters and Darkshire are aligned with the Alliance, so only Alliance adventurers can help him.",al={"is jitters alliance only","horde jitters growling gut"},gp=true},{q="Why can't Jitters get food from Darkshire himself?",a="Jitters is utterly terrified and has spent weeks cowering in the abandoned ruins of Raven Hill. Surrounded by roaming undead, feral beasts, and the horrors that haunt Duskwood, he is too petrified to brave the roads to Darkshire on his own. He relies on passing travelers like you who have the strength and courage to make the dangerous trek through the gloom.",al={"why does jitters need me","why cant jitters go to darkshire","jitters why me"},it="why_me",add="6935fdd7"}},ang={["profession:Cooking"]="Chef Grual’s Dusky Crab Cakes show how cooks in Duskwood use local, unusual ingredients when regular shipments fail to arrive.",["faction:Alliance"]="Helping Jitters brings you closer to the fragile settlements and survivors holding on in Duskwood’s shadowed corners."},kw={"chef grual","crab cakes","darkshire","growling gut","jitters","raven hill","scarlet raven tavern"},rel={"npc:jitters","npc:chef-grual","quest:93","quest:240","subzone:scarlet-raven-tavern","subzone:darkshire","zone:duskwood","npc:grub"},m={start="Jitters",["end"]="Chef Grual",level="20",faction="Alliance",id=5},src={"Jitters' Growling Gut"}}
E["quest:55"] = {t="quest",n="Morbent Fel",z="duskwood",s="Above Raven Hill Cemetery, Morbent Fel's wards keep ordinary steel from reaching him. Sven Yorgen sends you with Morbent's Bane to break them and end the necromancer's terror in western Duskwood.",h="Above Raven Hill Cemetery, Morbent Fel's wards keep ordinary steel from reaching him.",sec={{t="The Perch Above the Dead",b="Morbent Fel haunts an abandoned house atop a rocky ridge just east of Sven's camp. The house looks over the sprawl of Raven Hill Cemetery. From there, the necromancer sends undead through the surrounding forest and defiles Duskwood's graves. Dark magic and loyal undead thralls keep ordinary steel from reaching him.",sp=0},{t="Sven's Vengeance",b="Dark forces butchered Sven Yorgen's family and drove him into hiding, leaving him mad with grief. Sven knows the Dark Riders of Karazhan were responsible for the massacre at his farm. Morbent Fel's vile sorcery keeps the region's nightmare alive. Striking down the necromancer offers Sven the only tangible shred of justice left in this blighted land.",sp=1},{t="Morbent's Bane",b="Morbent Fel's wards turn a direct assault into suicide and deflect conventional attacks. Sven entrusts you with Morbent's Bane, an enchanted artifact made to unravel that magical shielding. Invoke the relic and the barrier collapses. Then Fel is open to a mortal strike.",sp=0}},faq={{q="Who is Morbent Fel?",a="Morbent Fel commands the undead infesting the Raven Hill region. He lurks in a house atop a hill overlooking Raven Hill Cemetery, using dark sorcery to shield himself while tormenting Duskwood's living.",al={"morbent fel lore","who is morbent fel","morbent fel background"},it="target"},{q="Why is Morbent's Bane necessary to kill him?",a="Morbent Fel's potent wards turn aside ordinary attacks and leave him almost invulnerable. Morbent's Bane is an enchanted relic made to dispel those protections and expose him to harm.",al={"morbents bane","why use morbents bane","how to beat morbent fel"},it="item"},{q="What is Sven Yorgen's connection to Morbent Fel?",a="The Dark Riders were responsible for slaughtering Sven Yorgen's family at their farm. Morbent Fel did not commit that massacre, but his necromantic grip on the countryside embodies the evil plaguing western Duskwood. Destroying Fel gives Sven a target for his vengeance.",al={"why does sven want morbent dead","sven yorgen morbent fel","sven revenge"},it="motive"},{q="Where can Morbent Fel be found?",a="Morbent Fel lives on the upper floor of a decrepit, ruined house on a hill directly east of Sven Yorgen's camp. The house overlooks the western side of Raven Hill Cemetery.",al={"morbent fel location","where is morbent fel","morbent house"},gp=true},{q="Did Morbent Fel kill Sven's family?",a="No. The mysterious Dark Riders seeking the Scythe of Elune slaughtered Sven's family. Morbent Fel's necromancy plagued the surrounding region and desecrated Duskwood's graves, so his destruction is essential to reclaiming peace.",al={"did morbent kill sven family","who slaughtered sven family"},sp=1,it="ties"},{q="What happens after Morbent Fel is slain?",a="Returning Morbent's Bane to Sven brings the grieving hermit a small measure of solace. The elusive Dark Riders remain at large, but Fel's death breaks the necromantic grip over Raven Hill and secures your reputation across Duskwood.",al={"after morbent fel","quest conclusion","does sven get peace"},sp=1,it="next_step"},{q="Why does Sven Yorgen need you to face Morbent Fel instead of doing it himself?",a="Sven is an isolated, traumatized hermit driven nearly mad by grief and paranoia. Hiding in a makeshift camp on the western fringes of Duskwood, he lacks the strength, protective wards, and martial prowess to storm Raven Hill alone. Morbent Fel commands dark magics and rests surrounded by undead guardians atop the cemetery hill. Sven needed a seasoned champion to carry Morbent's Bane directly into the necromancer's den to enact the vengeance he cannot achieve on his own.",al={"why does sven need me","why doesn't sven kill morbent fel","why me sven yorgen"},it="why_me",add="bd8ba8cc"}},ang={["faction:Alliance"]="Slaying Morbent Fel removes one of the gravest threats over Duskwood's people, secures the road, and honors the suffering of western settlements like Raven Hill.",["class:Paladin"]="As a paladin, striking down a foul necromancer and cleansing Raven Hill of his unnatural wards answers the calling of a knight of the Holy Light.",["class:Priest"]="As a priest, you can answer Raven Hill Cemetery's desecration with spiritual cleansing and dispel Fel's sorcerous wards as a holy duty."},kw={"duskwood","morbent fel","morbent's bane","necromancer","raven hill","raven hill cemetery","sven yorgen"},rel={"npc:sven-yorgen","subzone:raven-hill-cemetery","zone:duskwood","quest:163","topic:dark-riders"},m={start="Sven Yorgen",level="32",faction="Alliance",id=55},src={"Morbent Fel (quest)"}}
E["quest:56"] = {t="quest",n="The Night Watch",z="duskwood",s="In Darkshire, The Night Watch holds the line against the dead rising nearby. Stormwind has withdrawn its garrison, leaving the town’s local militia to rely on travelers at Tranquil Gardens Cemetery.",h="In Darkshire, The Night Watch holds the line against the dead rising nearby.",sec={{t="Abandoned by the Crown",b="Stormwind once guarded Duskwood, but its royal resources dwindled as political discord took hold in the capital. Then the crown withdrew its commissioned soldiers, leaving Darkshire with little defense against the forest’s encroaching shadows. The people formed a local militia called the Night Watch, led by Commander Althea Ebonlocke. It stands between the cursed forest and the town’s remaining residents.",sp=0},{t="Clearing the Tranquil Gardens",b="South of Darkshire, Tranquil Gardens Cemetery was once a peaceful resting place. Now restless skeletons and reanimated spellcasters roam its graves. The Night Watch is stretched thin along Duskwood’s borders, so Commander Ebonlocke sends arriving travelers to strike down Skeletal Warriors and Skeletal Mages before the dead reach the roads.",sp=0}},faq={{q="Why does the Night Watch need outside help?",a="Stormwind recalled its commissioned garrison from Duskwood, leaving Darkshire to defend itself. The Night Watch is a local militia with too few people and supplies to fight the undead across the territory alone.",al={"why need help","why darkshire weak","why no guards"},it="why_me"},{q="Who is Commander Althea Ebonlocke?",a="Althea Ebonlocke is a relative of Darkshire’s mayor, Lord Ello Ebonlocke, and commands the Night Watch. She organizes the town’s defenses and rallies those able to stand against Duskwood’s dark menaces.",al={"who is althea","commander ebonlocke","althea ebonlocke lore"},it="identity"},{q="Where is the Tranquil Gardens Cemetery?",a="Tranquil Gardens Cemetery lies just south of Darkshire. It remains an active burial site, but dark magic in Duskwood has raised the dead, who now harass travelers near the town’s edge.",al={"tranquil gardens location","where is cemetery","where to find skeletons"},it="place",gp=true},{q="What creatures are rising in the Tranquil Gardens?",a="Skeletal Warriors and Skeletal Mages overrun the cemetery. These animated remains retain martial skill and arcane power, making them a deadly threat to ordinary townsfolk.",al={"what undead are there","skeletons in duskwood"},it="target"},{q="Is Stormwind sending any reinforcements?",a="No. Stormwind withdrew its commissioned guards, leaving remote Duskwood to defend itself.",al={"stormwind help duskwood","will stormwind send troops"},it="threat"},{q="Does this assignment end the threat at the cemetery?",a="No. Clearing skeletons from Tranquil Gardens is only the first effort. The Night Watch faces growing threats deeper in the woods, and further expeditions are needed to manage Duskwood’s worsening corruption.",al={"is this the only quest","night watch chain"},it="next_step"},{q="Why does Commander Althea Ebonlocke want this done?",a="Commander Althea Ebonlocke is sworn to defend the people of Darkshire, but with Stormwind withdrawing its royal garrison, the burden falls entirely on her homegrown Night Watch. The Tranquil Gardens cemetery lies dangerously close just south of town. If the walking dead rising from its graves are not cut down before their ranks swell, Darkshire risks being completely overrun by the horrors of the woods.",al={"why does althea want this done","althea ebonlocke motive","why fight the skeletons darkshire"},it="motive",add="bf57f222"}},ang={["faction:Alliance"]="For Alliance loyalists, this duty shows Stormwind’s neglect. Frontier citizens must fight for their own survival without royal aid.",["class:Paladin"]="As a paladin, you face an affront to the Light at Tranquil Gardens. Desecrated graves call for consecrated steel and righteous judgment.",["class:Priest"]="As a priest, you can lay tormented, restless skeletons to rest as an act of spiritual mercy in a land under sinister curses."},kw={"althea ebonlocke","darkshire","duskwood","night watch","skeletal mage","skeletal warrior","stormwind","tranquil gardens"},rel={"topic:night-watch","npc:althea-ebonlocke","subzone:darkshire","zone:duskwood","topic:stormwind-kingdom"},m={start="Commander Althea Ebonlocke",level="24",faction="Alliance",id=56},src={"The Night Watch (Classic)"}}
E["quest:57"] = {t="quest",n="The Night Watch",z="duskwood",s="Across Duskwood, restless dead rise from their graves, and The Night Watch struggles to hold them back. Commander Althea Ebonlocke sends travelers into the haunted barrows to defend Darkshire. Their fight may keep the town from falling to darkness.",h="Across Duskwood, restless dead rise from their graves, and The Night Watch struggles to hold them back.",sec={{t="The Dead Do Not Rest",b="Duskwood’s graveyards stir beneath the forest’s twilight. Commander Althea Ebonlocke leads Darkshire’s volunteer militia, The Night Watch, against the rising dead. Stormwind sends no aid, and her forces are stretched thin. Skeletons and other horrors threaten the eastern settlements, so the militia calls on able travelers to enter the deadlands.",sp=0},{t="Haunted Soil",b="Two places hold the militia’s attention: Tranquil Gardens Cemetery, just south of town, and Raven Hill Graveyard, far to the west. Skeletons rise from forgotten tombs and shallow graves beside the roads, stirred by dark magic in the forest’s shadows. Cutting them down gives Darkshire’s beleaguered citizens room to breathe. Yet the battle against this entrenched evil never ends.",sp=0}},faq={{q="Why is the Night Watch relying on travelers rather than Stormwind guards?",a="Stormwind has left Duskwood to defend itself, so Commander Althea Ebonlocke and her militia hold the region. Strife in the capital and the king’s absence keep guards from reinforcing them, so the Night Watch turns to passing adventurers.",al={"why no stormwind help","where is stormwind army","why darkshire alone"},it="why_me"},{q="Where are the skeletons coming from?",a="Skeletons rise from Tranquil Gardens Cemetery and Raven Hill Graveyard. Dark magic in the woods has disturbed old burials and raised the remains as violent, mindless sentries.",al={"skeletons duskwood origin","why are there skeletons","undead source duskwood"},it="origin"},{q="Who leads the Night Watch?",a="Commander Althea Ebonlocke leads the Night Watch. She is related to Darkshire’s mayor, Lord Ello Ebonlocke, and directs the town’s defense against Duskwood’s undead and monstrous threats.",al={"night watch leader","who is althea ebonlocke","commander ebonlocke"},it="leader"},{q="What is the difference between Tranquil Gardens and Raven Hill?",a="Tranquil Gardens Cemetery lies just south of Darkshire and threatens the nearby town. Raven Hill Graveyard lies far to the west, across the forest, and is a vast burial ground at the heart of Duskwood’s undead infestation.",al={"tranquil gardens vs raven hill","which graveyard is better","graveyard locations duskwood"},it="place"},{q="What happens after culling these skeletons?",a="Althea’s campaign continues after the skeletons and fiends are cut down. The Night Watch watches for new threats across the forest, from ghouls and skeletons to more dangerous undead and the necromancers directing them deeper in Duskwood.",al={"what next night watch","night watch questline","after night watch 2"},it="next_step"},{q="Why is Darkshire in constant danger?",a="Duskwood was once a peaceful province of the Kingdom of Stormwind, but magical twilight and shadowy curses consumed it. Feral worgen, ravenous spiders, and restless undead overrun the woods. Darkshire remains the zone’s last bastion of living humanity.",al={"why duskwood dangerous","darkshire danger","what cursed duskwood"},it="danger"},{q="Why does Commander Althea Ebonlocke want this done?",a="Commander Althea Ebonlocke is responsible for protecting the beleaguered town of Darkshire and its surrounding woods. With reports pouring in of an aggressive undead surge rising from the local burial grounds, Darkshire faces an existential threat. Driving back the horrors and fiends roaming Raven Hill and Tranquil Gardens Cemetery is crucial to keeping the town safe from being completely overrun.",al={"why kill skeletons for althea","althea ebonlocke motive","why purge the undead duskwood"},it="motive",add="dfb05d16"},{q="What are Skeletal Fiends and Skeletal Horrors?",a="They are animated human remains imbued with dark necrotic magic, rising from the desecrated soil of Duskwood's cemeteries. More resilient and vicious than simple shambling bones, these undead fiends and horrors stalk Raven Hill Graveyard and the Tranquil Gardens, attacking any living beings who cross their path.",al={"skeletal fiends horrors","who are we hunting night watch","skeletons duskwood target"},it="target",add="8863b63d"}},ang={["faction:Alliance"]="Darkshire marks the Alliance’s fragile southeastern border in the southern Eastern Kingdoms. Helping the Night Watch keeps the town a viable foothold and guards it from ruin.",["class:Paladin"]="For the Silver Hand and knights of the Light, facing the defiled dead in Tranquil Gardens is a sacred duty. They seek to cleanse corrupted resting places.",["class:Priest"]="At Raven Hill, priests walk tainted soil and face the raw perversion of burial traditions. Their faith can bring quiet rest to tormented souls.",["race:Human"]="Many skeletons rising from Duskwood’s earth are ancestors of living Stormwind and Darkshire citizens. For human defenders, the fight is deeply personal."},kw={"althea ebonlocke","darkshire","duskwood","night watch","raven hill","skeletal fiend","skeletal horror","tranquil gardens"},rel={"quest:56","npc:althea-ebonlocke","topic:night-watch","zone:duskwood","subzone:darkshire","subzone:tranquil-gardens-cemetery","quest:163"},m={start="Commander Althea Ebonlocke",level="26",faction="Alliance",id=57},src={"The Night Watch (2)"}}
E["quest:58"] = {t="quest",n="The Night Watch",z="duskwood",s="In eastern Raven Hill, The Night Watch sends for help as Darkshire faces the undead. Commander Althea Ebonlocke calls on travelers to enter the crypts and destroy the plague spreaders while her guards defend the town. This is the last chapter in the guard’s direct fight against the undead overrun.",h="In eastern Raven Hill, The Night Watch sends for help as Darkshire faces the undead.",sec={{t="A Desperate Frontier",b="Darkshire stands nearly alone, with no soldiers from Stormwind to rely on. Its civilian militia, The Night Watch, must hold the town. Commander Althea Ebonlocke has few guards to spare, and she uses them to protect the crossroads, the town’s edge, and the supply lines. As the restless dead multiply across Duskwood, she calls on wandering champions to carry the fight into Raven Hill’s depths.",sp=0},{t="Purging the Mausoleum",b="The eastern mausoleum in Raven Hill Cemetery holds one of the region’s largest concentrations of undead. Unlike the open barrows, its stone crypts teem with plague spreaders. These ghouls carry afflictions that can sicken the living. Destroying twenty gives The Night Watch room to breathe and helps keep Darkshire from facing a united undead surge from the west.",sp=0}},faq={{q="Why is the Night Watch sending adventurers instead of their own men?",a="The Night Watch has too few guards to cover Duskwood. Stormwind sends no official troops, so Commander Althea Ebonlocke can barely hold Darkshire’s edge and watch the roads. No militia remains to enter fortified crypts like Raven Hill.",al={"why help darkshire","why the night watch needs help","night watch low numbers"},it="why_me"},{q="Where is the eastern mausoleum located?",a="The eastern mausoleum lies in the eastern part of Raven Hill Cemetery, in northwestern Duskwood. Its entrance opens into stone crypts where plague spreaders gather.",al={"where are plague spreaders","eastern mausoleum location","where is the mausoleum"},it="place",gp=true},{q="What makes the plague spreaders dangerous?",a="Plague spreaders are ravenous ghouls that carry virulent decay. Their corruption could spread beyond the cemetery and taint Darkshire’s surviving residents.",al={"why kill plague spreaders","what are plague spreaders"},it="threat"},{q="Who is Commander Althea Ebonlocke?",a="Althea Ebonlocke commands The Night Watch and is related to Darkshire’s mayor, Lord Ello Ebonlocke. She directs Duskwood’s defense from inside Darkshire.",al={"who is althea","commander ebonlocke","who leads the night watch"},it="in_charge"},{q="Does completing this chain end the undead threat in Duskwood?",a="No. Thinning the mausoleum’s ranks eases the immediate pressure on Darkshire, but Raven Hill remains infested. Darker powers across Duskwood still stir the dead.",al={"is raven hill saved","is darkshire safe now"},it="conflict"},{q="How does this fit into the Night Watch questline?",a="This is the third and final chapter in Commander Ebonlocke’s direct martial campaign for The Night Watch. The fight moves from the open roads to the graveyard’s outskirts, then deep into the mausoleum.",al={"what chain is this","is this the last night watch quest"},it="history"},{q="Why does Commander Althea Ebonlocke want this done?",a="Commander Althea Ebonlocke bears the heavy burden of defending Darkshire with severely depleted militia ranks. The sprawling cemetery of Raven Hill has become a festering hotbed of undead corruption, and she fears that if the foul creatures gathering within its crypts are left unchecked, they will inevitably surge eastward and overwhelm the town entirely. Destroying the plague spreaders is a desperate measure to blunt that looming tide and safeguard the living.",al={"why kill plague spreaders","ebonlocke motive duskwood","why send to raven hill again"},it="motive",add="f0d896f3"},{q="What are the plague spreaders in the mausoleum?",a="Plague spreaders are putrid, reanimated corpses that haunt the desecrated tombs of Raven Hill Cemetery. Infused with foul blights and rot, they lurk deep inside the eastern mausoleum, desecrating the graves of Duskwood's dead and threatening to carry their contagious filth across the woods. Their lingering presence transforms the ancient burial grounds into an enduring fountain of undeath.",al={"who are plague spreaders","plague spreaders duskwood","undead in eastern mausoleum"},it="target",add="0678b7f2"}},ang={["faction:Alliance"]="With Stormwind’s crown ignoring Duskwood’s pleas, Alliance champions must step forward to save loyal citizens from the undead.",["class:Paladin"]="As a paladin, you face a profane mockery of sacred burial rites in Raven Hill’s plague-ridden vaults. Cleansing the crypts is a vital duty to the Holy Light.",["class:Priest"]="As a priest, you face the vile contagion spread by ghouls in the eastern mausoleum. The threat calls for cleansing in spirit and body."},kw={"althea ebonlocke","darkshire","duskwood","ghouls","mausoleum","night watch","plague spreaders","raven hill","undead"},rel={"topic:night-watch","npc:althea-ebonlocke","quest:56","subzone:darkshire","zone:duskwood","quest:163","topic:light"},m={start="Commander Althea Ebonlocke",level="30",faction="Alliance",id=58},src={"The Night Watch (3)"}}
E["quest:66"] = {t="quest",n="The Legend of Stalvan",z="duskwood",s="Madame Eva's vision in Darkshire names Stalvan and warns of death for her granddaughter, Alyssa. She sends you to the Darkshire Town Hall to search the records.",h="Madame Eva's vision in Darkshire names Stalvan and warns of death for her granddaughter, Alyssa.",sec={{t="A Vision of Death",b="In Darkshire, Madame Eva reads cards and portents for troubled locals. A terrible disturbance jolts her awake, and she draws the Death card for her young granddaughter, Alyssa. Eva enters a deep trance to learn what the omen means. One clue comes to her: the name Stalvan. Fearing for her family and the town, she asks you to follow that name before tragedy strikes.",sp=0},{t="Inquiries at Town Hall",b="Madame Eva sends you across the square to the Darkshire Town Hall. Search its records for Stalvan, and speak with Clerk Daltry, who keeps the town's ledgers and public archives. He can help determine whether Stalvan once lived in Darkshire, passed through as a traveler, or belongs to Duskwood's past.",sp=0}},faq={{q="Who is Madame Eva?",a="Madame Eva is a fortune teller and diviner who lives in Darkshire. She reads cards and enters trances to seek portents and sense magical disturbances across Duskwood.",al={"madame eva","who is eva","darkshire fortune teller"},it="people"},{q="Why does Madame Eva need help?",a="Madame Eva fears for her granddaughter, Alyssa, after a vision of death. Her cards showed the Death card, and her trance revealed the name Stalvan, so she seeks help investigating.",al={"why start stalvan","eva vision","why help eva"},it="motive"},{q="Who is Clerk Daltry?",a="Clerk Daltry keeps Darkshire's records in the Town Hall. He manages the town's ledgers, registries, and historical documents, and can be asked about unfamiliar names.",al={"clerk daltry","daltry","who is town clerk"},it="people"},{q="What is Darkshire Town Hall?",a="The Darkshire Town Hall houses the town's officials, historical records, and the Night Watch's command staff.",al={"darkshire town hall","town hall duskwood"},it="place"},{q="Who is Alyssa?",a="Alyssa is Madame Eva's young granddaughter, who lives in Darkshire. Eva's reading warned of a deadly omen for her, tied to someone named Stalvan.",al={"alyssa","madame eva granddaughter"},it="people"},{q="Where does this investigation lead next?",a="Speaking with Clerk Daltry leads you to town records and earlier inquiries. From there, the search reaches across Duskwood and neighboring regions to uncover Stalvan's history and fate.",al={"stalvan next step","what does daltry say"},it="next_step"},{q="Who is Stalvan?",a="At this stage, Stalvan is little more than a shadowy name whispered through Madame Eva's divination. Disturbed by a premonition of mortal danger surrounding her granddaughter Alyssa, Eva cast her cards and entered a deep trance to find answers. Death was revealed, along with only this single name. You are sent to uncover who Stalvan was in Darkshire's past records.",al={"who is stalvan","stalvan who","what is stalvan"},it="target",add="aeb2106e"},{q="Why does Madame Eva ask you instead of the Night Watch?",a="Madame Eva relies on omens and divinations rather than conventional crimes, making an obscure name drawn from a card reading difficult to bring formally before the Night Watch. With Darkshire already besieged by wolves, spiders, and the undead, the local garrison is stretched to its limit defending the town perimeter. She needs an independent adventurer willing to discreetly dig into old municipal records on her behalf.",al={"why ask me","why not town guard","why not night watch"},it="why_me",add="9e863436"}},ang={["faction:Alliance"]="With Duskwood lacking regular army support from Stormwind, Alliance adventurers often help the town's elders and protect families like Madame Eva's.",["class:Priest"]="As a priest on Darkshire's dark roads, you may heed spiritual warnings. Madame Eva's omen of death calls for your pastoral care."},kw={"alyssa","clerk daltry","darkshire","death card","duskwood","madame eva","stalvan","town hall"},rel={"npc:madame-eva","npc:clerk-daltry","subzone:darkshire-town-hall","subzone:darkshire","zone:duskwood"},m={start="Madame Eva",["end"]="Clerk Daltry",level="28",faction="Alliance",id=66},src={"The Legend of Stalvan (Classic)"}}
E["quest:67"] = {t="quest",n="The Legend of Stalvan",z="duskwood",s="In Darkshire, Clerk Daltry searches the town records for Stalvan Mistmantle. An old address points west to Moonbrook in Westfall, where the search for Stalvan’s past begins.",h="In Darkshire, Clerk Daltry searches the town records for Stalvan Mistmantle.",sec={{t="The Town Clerk's Request",b="After your inquiries in Darkshire, Clerk Daltry searches the town registry for Stalvan Mistmantle. The ledger has gone years without an update, and lists Stalvan’s last known home as the schoolhouse in Moonbrook, far to the west. Daltry takes the old address as routine record keeping. He asks you to investigate and bring back any records that could bring Darkshire’s archives up to date.",sp=0},{t="The Ruins of Moonbrook",b="The trail runs from Duskwood into Westfall, where the Defias Brotherhood holds Moonbrook. Once a thriving farming settlement, the town is now under outlaw control. Near its center stands the abandoned schoolhouse. Inside, an old footlocker holds the first clear clues to Stalvan’s former life as an educator. A sorrow still lingers around the chest.",sp=0},{t="A Tragic Haunting",b="Opening the old footlocker summons a Forlorn Spirit. It attacks anyone who uncovers Stalvan’s past, using mournful magic to curse intruders. The spirit points to an unresolved tragedy tied to the schoolmaster’s departure from Westfall. The search for old records has become a haunting.",sp=1}},faq={{q="Who is Clerk Daltry?",a="Clerk Daltry keeps Darkshire’s town records in the Town Hall of Duskwood. He searches the registry for Stalvan Mistmantle and finds entries left unchanged for years.",al={"daltry","darkshire clerk","who starts legend of stalvan 2"},it="identity"},{q="Where is the Moonbrook Schoolhouse?",a="The Moonbrook Schoolhouse stands in the center of Moonbrook, in southwestern Westfall. Its architecture resembles Darkshire Town Hall, and Defias bandits surround it.",al={"moonbrook schoolhouse location","where is the schoolhouse","where is stalvan footlocker"},it="place",gp=true},{q="What is inside the Old Footlocker?",a="The footlocker holds old records and personal belongings from Stalvan Mistmantle’s time as an instructor in Moonbrook. They provide the next lead in the search for his whereabouts.",al={"stalvan footlocker","what is in the footlocker"},it="item"},{q="Why does a ghost attack when opening the footlocker?",a="Opening the footlocker summons a Forlorn Spirit, which attacks with polymorph and curses. The spirit is bound to the tragedy around Stalvan’s past and his departure from Moonbrook.",al={"forlorn spirit","why does a ghost spawn","curse of stalvan ghost"},sp=1,it="danger"},{q="Why did Stalvan leave Westfall?",a="Stalvan was a schoolmaster in Moonbrook before leaving to seek private tutoring work elsewhere in the kingdom. His belongings remained locked in the old schoolhouse.",al={"why did stalvan leave moonbrook","stalvan moonbrook history"},it="history"},{q="Is Moonbrook safe to enter?",a="No. The Defias Brotherhood controls Moonbrook, so reaching the schoolhouse means facing armed thieves and outlaws.",al={"is moonbrook dangerous","mobs in moonbrook"},it="place",gp=true},{q="Why does Clerk Daltry want this done?",a="Clerk Daltry takes great professional pride in maintaining the Darkshire town registry. Upon checking the records for Stalvan Mistmantle, he discovers the man's last known address is listed as the Moonbrook Schoolhouse in Westfall. Knowing how badly outdated that entry is, he wants you to visit the schoolhouse and uncover any recent information so he can keep his ledgers neat, clean, and accurate.",al={"why does daltry want stalvan records","clerk daltry motive","why find stalvan"},it="motive",add="803ebeb2"}},ang={["faction:Alliance"]="This search shows how far the kingdom’s rural towns have fractured. You must cross Defias-held Westfall to follow a Darkshire registry entry.",["class:Mage"]="The Forlorn Spirit guarding the footlocker uses polymorphism and debilitating curses. You face sorrow-bound magic in an otherwise ordinary classroom."},kw={"daltry","duskwood","footlocker","forlorn spirit","mistmantle","moonbrook","schoolhouse","stalvan","westfall"},rel={"npc:clerk-daltry","subzone:moonbrook-schoolhouse","subzone:moonbrook","zone:westfall","zone:duskwood"},m={start="Clerk Daltry",["end"]="Old Footlocker",level="28",faction="Alliance",id=67},src={"The Legend of Stalvan (2)"}}
E["quest:68"] = {t="quest",n="The Legend of Stalvan",z="duskwood",s="In Moonbrook, The Legend of Stalvan leads you back to Darkshire's records. A dusty, unsent letter from an old footlocker proves Stalvan Mistmantle stayed there before his trail went cold.",h="In Moonbrook, The Legend of Stalvan leads you back to Darkshire's records.",sec={{t="A Forgotten Trace in Moonbrook",b="You find a dusty, unsent letter in an old footlocker while tracing Stalvan Mistmantle's past. Moonbrook was once an agricultural settlement, but now lies in ruin, crowded with outlaws and restless specters. Few remember his brief stay, yet the letter places him in the hamlet.",sp=0},{t="A Haunting at the Footlocker",b="Disturbing the footlocker draws a Forlorn Spirit from the shadows to guard what remains. It attacks with bewitching magic and the debilitating Curse of Stalvan. Sorrow and dark enchantment still cling to Stalvan's belongings.",sp=1},{t="Updating the Town Registry",b="You carry the letter across the border to Darkshire, where Clerk Daltry keeps the town records. He finds it strange that the letter was never mailed, but the evidence confirms Stalvan's connection to Moonbrook. The records can now point toward where Stalvan fled next.",sp=0}},faq={{q="What is inside the old footlocker in Moonbrook?",a="The old footlocker holds a Dusty Unsent Letter from Stalvan Mistmantle's stay in Moonbrook. It confirms he lived there before disappearing.",al={"what did i find","footlocker contents","stalvan letter"},it="item"},{q="Why does a spirit attack when the chest is opened?",a="A Forlorn Spirit guards Stalvan's forgotten possessions and attacks anyone who disturbs the trunk. It uses unsettling magic, including fears, polymorph spells, and the Curse of Stalvan.",al={"forlorn spirit","why am i attacked","footlocker ghost"},it="hostile"},{q="Why take the letter to Clerk Daltry?",a="Clerk Daltry oversees Darkshire's town records and registry. He needs proof of Stalvan's past whereabouts before he can help track him further.",al={"who is clerk daltry","why daltry","darkshire town hall"},it="purpose"},{q="Why is it significant that the letter was never sent?",a="The abandoned letter remained in the footlocker, suggesting Stalvan left abruptly or grew paranoid. Its presence deepens the mystery around his movements.",al={"unsent letter mystery","why wasn't it mailed"},it="history"},{q="What does the Curse of Stalvan do?",a="The Forlorn Spirit's Curse of Stalvan is a debilitating hex that lowers all of its victim's primary attributes for ten minutes.",al={"curse of stalvan debuff","spirit curse"},it="power",gp=true},{q="Where does the trail lead after giving the letter to Daltry?",a="After Clerk Daltry records the proof from Moonbrook, he can direct you toward Stalvan's next known destination.",al={"what next","where after daltry","next clue"},it="next_step"}},ang={["faction:Alliance"]="As an Alliance traveler, you help Darkshire record the shadowy figures who have crossed the region's borders.",["class:Priest"]="As a priest, you can see how a Forlorn Spirit bound to a simple chest of keepsakes bears an emotional burden that did not end in death.",["class:Mage"]="As a mage, you recognize the shade's deceptive arcane tools, from polymorph to a crippling curse, among the unnatural forces in Stalvan's wake."},kw={"clerk daltry","curse of stalvan","darkshire","duskwood","dusty unsent letter","footlocker","forlorn spirit","mistmantle","moonbrook","stalvan"},rel={"npc:clerk-daltry","subzone:moonbrook","zone:duskwood"},m={start="Old Footlocker",["end"]="Clerk Daltry",level="28",faction="Alliance",id=68},src={"The Legend of Stalvan (3)"}}
E["quest:69"] = {t="quest",n="The Legend of Stalvan",z="duskwood",s="In Darkshire, a scratched registry entry sends the search for Stalvan Mistmantle toward Goldshire.",h="In Darkshire, a scratched registry entry sends the search for Stalvan Mistmantle toward Goldshire.",sec={{t="A Clue in the Ledger",b="Clerk Daltry finds another destination beneath Stalvan Mistmantle's earlier entry in Darkshire's town registry. The hurried note is partly scratched out. Someone meant to hide the route or changed their mind. It points northwest toward the Lion's Pride Inn in Elwynn Forest.",sp=0},{t="Crossing into Elwynn",b="You leave Duskwood's shadowed groves for Goldshire's sunny roads, where Stalvan's trail reaches too. The Lion's Pride Inn stands at Elwynn Forest's crossroads, where travelers, merchants, and soldiers gather. Innkeeper Farley runs the busy taproom and may know of an educated wanderer looking for a room.",sp=0}},faq={{q="Why does the trail lead to Goldshire?",a="Clerk Daltry found a second address beneath Stalvan's first entry in Darkshire's registry. Though partly scratched out, it points to the Lion's Pride Inn in Goldshire.",al={"why goldshire","why go to goldshire","stalvan in goldshire"},it="place"},{q="Who is Clerk Daltry?",a="Clerk Daltry keeps records in Darkshire's town hall. He maintains the local registries and helps uncover old documents about past residents.",al={"daltry","who is daltry"},it="identity"},{q="Who do I speak to at the Lion's Pride Inn?",a="Speak with Innkeeper Farley, who runs the Lion's Pride Inn and keeps track of travelers and patrons passing through Goldshire.",al={"who to talk to","lion's pride contact","innkeeper goldshire"},it="next_step",gp=true},{q="Why was the entry scratched out in the registry?",a="The registry entry is only partly erased. Someone may have hurriedly tried to hide Stalvan's route toward Elwynn Forest as he left Duskwood.",al={"scratched out note","why scratched out"},it="history"},{q="Does this quest involve any combat?",a="No. You travel from Darkshire's Town Hall to the taproom in Goldshire and ask about Stalvan.",al={"is there fighting","do i fight anything"},gp=true},{q="What is the Lion's Pride Inn?",a="The Lion's Pride Inn is Goldshire's central gathering place in Elwynn Forest. Travelers rest there on the roads between Stormwind City, Westfall, and Duskwood.",al={"lions pride inn","goldshire inn"},it="place"},{q="Why does Clerk Daltry want Stalvan tracked down?",a="As town clerk of Darkshire, Daltry maintains the town records and registry. After Madame Eva initially set you on the trail of the mysterious figure known as Stalvan Mistmantle, Daltry aided the search by scouring his ledgers. Catching an overlooked, partially scratched-out entry beneath the first address, he directs you to follow up on the new clue to help piece together the elusive man's history.",al={"why does daltry care","daltry motive stalvan","why track stalvan"},it="motive",add="f40d5969"},{q="Why does Clerk Daltry send you to Goldshire instead of going himself?",a="Clerk Daltry is a civil clerk tied to Darkshire's town hall, responsible for keeping records and serving the local populace in a settlement besieged by horrors. Traveling all the way across the river into Elwynn Forest to question barkeeps is outside his station and duties, making an able-bodied adventurer far better suited to run down distant leads.",al={"why send me","why doesn't daltry go","why daltry needs an adventurer"},it="why_me",add="136b3a3d"}},ang={["race:Human"]="From Duskwood's haunted frontier, Stalvan's trail crosses the heart of the Kingdom of Stormwind toward familiar Elwynn Forest.",["faction:Alliance"]="Local histories and cold trails lead across the southern Alliance, between frontier outposts like Darkshire and hamlets like Goldshire."},kw={"clerk daltry","darkshire","duskwood","elwynn forest","goldshire","innkeeper farley","lion's pride inn","stalvan"},rel={"npc:clerk-daltry","npc:innkeeper-farley","subzone:lion-s-pride-inn","subzone:goldshire","zone:duskwood","zone:elwynn"},m={start="Clerk Daltry",["end"]="Innkeeper Farley",level="28",faction="Alliance",id=69},src={"The Legend of Stalvan (4)"}}
E["quest:70"] = {t="quest",n="The Legend of Stalvan",z="duskwood",s="In Goldshire, an old letter renews the search for Stalvan Mistmantle. Its trail runs from Elwynn Forest to Stormwind's Canal District.",h="In Goldshire, an old letter renews the search for Stalvan Mistmantle.",sec={{t="A Midnight Terror",b="At the Lion's Pride Inn, Innkeeper Farley recalls a stormy night years ago. A traveling courier came in from the rain to find shelter. Around midnight, he rushed downstairs in a panic, wearing only his sleepwear. He vanished into the storm, and no one saw him again.",sp=0},{t="The Leftover Parcel",b="The courier left his satchel and personal chest in the upstairs room. Among the forgotten cargo was an unsent letter bearing the name Stalvan, addressed to someone in Stormwind City's Canal District. The chest remained untouched at the foot of the bed until Farley allowed it to be opened.",sp=0},{t="A Chilly Welcome",b="Caretaker Folsom watches over property along Stormwind's canals near the Park. When you bring him the long-overdue letter, he meets Stalvan's name and handwriting with disgust and hostility, not gratitude. His reaction points to old scandals tied to the sender.",sp=1}},faq={{q="Where is the undelivered letter kept?",a="The undelivered letter is in a storage chest upstairs at the Lion's Pride Inn in Goldshire. Climb the stairs, turn right, and enter the bedroom with the bed. The chest rests at the foot of the bed frame.",al={"find letter","stalvan chest location","where is the chest"},it="item",gp=true},{q="Why was the letter never delivered originally?",a="Years ago, the courier took shelter from a downpour at the Lion's Pride Inn. Near midnight, something terrified him, and he fled into the storm in his nightclothes, leaving his chest and deliveries behind.",al={"why abandoned letter","what scared the courier","why did messenger run"},it="history"},{q="Where do I find Caretaker Folsom in Stormwind?",a="Caretaker Folsom is along the Canals in Stormwind City, near the edge of the Park district.",al={"folsom location","where is caretaker folsom","canal district turn in"},it="target",gp=true},{q="Why is Caretaker Folsom angry about receiving the letter?",a="Folsom recognizes Stalvan's name and handwriting, and reacts with indignation. Stalvan Mistmantle left bitter memories and outrage among the people connected to his past in Stormwind.",al={"why is folsom mad","folsom reaction","you have some nerve"},it="motive"},{q="How does this connect to the trouble in Duskwood?",a="The town council in Darkshire is investigating a lingering evil tied to Stalvan Mistmantle. To learn who he was, you retrace his earlier travels and associations through Elwynn Forest and Stormwind.",al={"why duskwood quest in goldshire","how does this relate to duskwood"},it="threat"},{q="What happens after giving the letter to Caretaker Folsom?",a="Caretaker Folsom's sharp response opens the Stormwind chapter of the investigation. You must uncover Stalvan's former employment and the grim events involving the noble family he served.",al={"next step","what follows this quest"},sp=1,it="next_step"},{q="Why does Innkeeper Farley want Stalvan's letter delivered?",a="Innkeeper Farley has no personal stake in Stalvan's affairs or the old letter; he is merely helping you piece together the mystery you are investigating. When you ask about Stalvan Mistmantle, Farley recalls a terrified courier who fled the Lion's Pride Inn years ago during a storm, abandoning his dispatch chest upstairs. Remembering that an undelivered letter from Stalvan was left behind and addressed to Stormwind's Canal District, Farley offers it up so you can track down your elusive lead.",al={"why does farley help","innkeeper farley motive","why deliver the letter"},it="motive",add="1a6ccbd1"},{q="What is the Undelivered Letter?",a="The letter is an old piece of correspondence written by Stalvan Mistmantle years ago, intended for an address in Stormwind's Canal District. It was left behind at the Lion's Pride Inn when a messenger fled into the night in sheer terror, leaving his belongings locked in a chest upstairs. For your investigation, the letter serves as a crucial physical clue, directing you to Caretaker Folsom in Stormwind to discover who Stalvan was contacting and what became of him.",al={"what is an undelivered letter","stalvan undelivered letter","what does the letter say"},it="item",add="b7fa74bd"}},ang={["faction:Alliance"]="To unravel Stalvan's mystery, you travel through the heartlands of the Alliance. An old trail leads from Goldshire to the capital's grand canals.",["race:Human"]="As a human, you see the darker undercurrents of the Kingdom of Stormwind. The evils haunting Duskwood reach to the capital's doorstep."},kw={"canals","caretaker folsom","goldshire","innkeeper farley","lion's pride inn","mistmantle","stalvan","stormwind","undelivered letter"},rel={"npc:innkeeper-farley","npc:caretaker-folsom","subzone:lion-s-pride-inn","subzone:canals-stormwind-city","subzone:park","zone:duskwood","topic:stormwind-kingdom"},m={start="Innkeeper Farley",["end"]="Caretaker Folsom",level="28",faction="Alliance",id=70,ri={"An Undelivered Letter"}},src={"The Legend of Stalvan (5)"}}
E["quest:72"] = {t="quest",n="The Legend of Stalvan",z="duskwood",s="In Stormwind, you search for Stalvan Mistmantle among the Flintridge belongings. By the canals, sealed crates hold what remains of the household, watched over by restless spirits tied to the massacre.",h="In Stormwind, you search for Stalvan Mistmantle among the Flintridge belongings.",sec={{t="Echoes of a Massacre",b="You follow Stalvan’s path from Duskwood to Stormwind. Beside the city canals, Caretaker Folsom guards what remains of the Flintridge household. His father served the estate before him and had to mop up blood after a massacre claimed the household. Somehow, Stalvan’s name is tied to that slaughter.",sp=0},{t="The Auction of a Ruined House",b="The Flintridge trust funds are gone, and royal tax collectors press the estate. Surviving heirlooms and packed belongings wait inside sealed shipping crates along the canal embankment, awaiting auction. You search them for Stalvan’s trail before the family’s remaining goods scatter to collectors across the kingdom.",sp=0},{t="A Restless Shade",b="A Forlorn Spirit attacks anyone who disturbs the Flintridge crates. The trauma of the murders clings to the family’s salvaged possessions. Many believe the weeping apparition is the shade of young Tilloa Flintridge, still bound to relics of the life cut short.",sp=1}},faq={{q="Where can I find Caretaker Folsom?",a="Caretaker Folsom watches over the Flintridge goods beside the Canals in Stormwind City, near shipping crates stacked by the waterway.",al={"caretaker folsom location","where is folsom","where is caretaker folsom in stormwind"},it="place",gp=true},{q="What happened to the Flintridge family?",a="A sudden massacre tore apart the wealthy Flintridge household. Caretaker Folsom says his father had to mop up the blood afterward. Who was responsible remains unclear.",al={"flintridge massacre","what was the massacre","who killed the flintridge family"},it="history"},{q="Why are the family's possessions packed in crates along the canal?",a="The Flintridge trust funds ran dry after the tragedy. Their remaining belongings were crated beside the canals for auction, under pressure from kingdom tax collectors.",al={"why auction flintridge items","why are crates in the canals","flintridge trust"},it="why_here"},{q="Why does a spirit attack when the crate is opened?",a="The massacre’s trauma bound the victims’ souls to their former belongings. A Forlorn Spirit attacks to defend the crates, and many believe it is the shade of Tilloa Flintridge, one of the murdered children.",al={"forlorn spirit stormwind","who is the forlorn spirit","why ghost in stormwind canals"},it="threat"},{q="How does this connect back to Duskwood?",a="The investigation began in Darkshire as a search for Stalvan Mistmantle. Tracing his history led to his time as tutor to the Flintridge family in Elwynn and Stormwind.",al={"stalvan duskwood connection","why are we in stormwind for a duskwood quest","legend of stalvan city connection"},it="ties"},{q="What do you find inside the sealed crate?",a="The crate holds musty heirlooms among packed furniture and personal effects. Near the bottom, you find a torn page from Stalvan’s journal, the next clue.",al={"what is in the crate","sealed crate clue","flintridge crate contents"},it="item"},{q="Why does Caretaker Folsom let you search the crates?",a="Caretaker Folsom personally has little left to care for. The Flintridge family trust has completely dried up, leaving their remaining estate in ruin and their last possessions slated for the auction house to satisfy tax collectors. While his family served the estate for generations—his father having cleaned up the gore following the gruesome massacre—Folsom himself has no reason to hide the grim truth and simply permits your curiosity to rummage through what remains.",al={"caretaker folsom motive","why does folsom help","why let me search crates"},it="motive",add="d6eccd2d"}},ang={["faction:Alliance"]="The Flintridge tragedy unfolds in Stormwind, the kingdom’s capital, where violence can undo even its most sheltered noble lines.",["class:Priest"]="As a priest, you face the weeping Forlorn Spirit in the city canals. Its torment belongs to innocent souls murdered before their time, and it demands peace from the Light."},kw={"canals","caretaker folsom","duskwood","flintridge","forlorn spirit","legend of stalvan","massacre","sealed crate","stormwind","tilloa"},rel={"npc:caretaker-folsom","subzone:canals-stormwind-city","zone:duskwood","topic:stormwind-kingdom"},m={start="Caretaker Folsom",["end"]="Sealed Crate",level="28",faction="Alliance",id=72},src={"The Legend of Stalvan (6)"}}
E["quest:74"] = {t="quest",n="The Legend of Stalvan",z="duskwood",s="Beside Stormwind City's canals, you find a clue to Stalvan Mistmantle's past in the Flintridge crate. Its torn journal page points toward Marshal Haggard in Elwynn Forest.",h="Beside Stormwind City's canals, you find a clue to Stalvan Mistmantle's past in the Flintridge crate.",sec={{t="Unearthing the Past",b="Beneath a ceramic vase in the sealed crate lies a torn page from Stalvan Mistmantle's journal. Musty Flintridge heirlooms, old hunting trophies, and family portraits fill the crate. Stalvan's own hand offers a glimpse of the reclusive scholar before tragedy struck.",sp=0},{t="A Marshal's Fading Sight",b="Marshal Haggard strains to read the battered parchment through his failing sight. Its distinctive handwriting stirs memories of documents and incidents from years past, before darkness took his sight.",sp=1}},faq={{q="Where is the sealed crate located?",a="The sealed crate sits beside the Canals of Stormwind City, directly behind Caretaker Folsom. Inside are the Flintridge family's belongings, and the page from it goes to Marshal Haggard in southeastern Elwynn Forest.",al={"crate location","where is crate","haggard crate"},it="place",gp=true},{q="What is inside the sealed crate?",a="The crate holds dusty heirlooms, a family portrait, old books, hunting trophies, and a ceramic vase. Beneath the vase lies a torn page from Stalvan's journal.",al={"crate contents","what is in the crate","torn page crate"},it="item"},{q="Who is Marshal Haggard?",a="Marshal Haggard is an elderly, retired Stormwind officer who lives alone in southern Elwynn Forest. His sight is failing and he is frail, but his memories of old records and travelers make him a crucial witness to past events.",al={"who is haggard","marshal haggard lore","old marshal elwynn"},it="identity"},{q="Why is this journal page important?",a="The torn page is direct evidence in Stalvan Mistmantle's own hand. Its distinctive writing and lingering thoughts connect accounts across Duskwood and Elwynn to his personal downfall.",al={"why torn page matters","journal page clue","stalvan journal"},it="purpose"},{q="What happens when the crate is opened?",a="Disturbing the remnants of Stalvan's past stirs the restless dead. A vengeful Forlorn Spirit appears and strikes at those trying to unravel the tragedy.",al={"forlorn spirit spawn","ghost after crate","why did a ghost attack me"},it="danger",gp=true},{q="Where does the investigation lead next?",a="Once the torn page reaches Marshal Haggard, his memory of the handwriting guides the investigation toward more surviving fragments of Stalvan's history.",al={"next step","after torn page","where do I go next"},it="next_step",gp=true}},ang={["faction:Alliance"]="As an Alliance investigator, you uncover how personal horrors in the heart of Elwynn can slip past Stormwind's marshals.",["race:Human"]="As a human, you see Marshal Haggard as part of Stormwind's aging veteran generation. He carries vital memories of the kingdom before the First and Second Wars tore families apart."},kw={"duskwood","elwynn forest","forlorn spirit","marshal haggard","mistmantle","sealed crate","stalvan","torn journal page"},rel={"quest:1666","zone:elwynn","zone:duskwood"},m={start="Sealed Crate",["end"]="Marshal Haggard",level="28",faction="Alliance",id=74},src={"The Legend of Stalvan (7)"}}
E["quest:75"] = {t="quest",n="The Legend of Stalvan",z="duskwood",s="In Elwynn, your search for The Legend of Stalvan leads you to Marshal Haggard's home. The veteran's failing eyesight left an upstairs chest of papers unread.",h="In Elwynn, your search for The Legend of Stalvan leads you to Marshal Haggard's home.",sec={{t="A Veteran's Attic",b="Marshal Haggard lives near Elwynn Forest's southeastern edge, close to Duskwood and Redridge. Upstairs, an old chest holds parchments he found when he moved into his secluded home. His failing eyesight kept him from reading them, and they have remained untouched until you ask about Stalvan.",sp=0},{t="Lingering Shadows",b="The papers in Haggard's upstairs chest stir a restless force tied to Stalvan's past. When you disturb his belongings, a Forlorn Spirit appears. Among the papers, a journal page bears Stalvan's own words and shows that the reclusive scholar left his mark in Elwynn before he vanished.",sp=1}},faq={{q="Who is Marshal Haggard?",a="Marshal Haggard is an aging veteran who lives in a secluded cabin in southeastern Elwynn Forest. His home holds old papers that belonged to Stalvan Mistmantle.",al={"marshal haggard","haggard elwynn","who is haggard"},it="identity"},{q="Why did the trail lead back to Elwynn Forest?",a="Clues from Darkshire and Moonbrook trace Stalvan's travels across southern Stormwind territory. Haggard's home holds papers Stalvan left behind.",al={"why elwynn forest","stalvan elwynn","why go to haggard"},it="history"},{q="What is inside the chest upstairs?",a="The upstairs chest holds a faded journal page written by Stalvan Mistmantle, among parchments Haggard never managed to examine properly.",al={"upstairs chest","faded journal page","what is in the chest"},it="item"},{q="Why does a spirit attack when the chest is opened?",a="A Forlorn Spirit haunts relics from Stalvan's past. It attacks when an outsider disturbs his writings and memories.",al={"forlorn spirit","why ghost attacks","ghost in haggard house"},it="target"},{q="How does this advance the Stalvan investigation?",a="The faded page offers firsthand evidence in Stalvan's own hand, helping you piece together his past.",al={"stalvan mystery","what does the page reveal","stalvan questline step"},sp=1,it="next_step"},{q="Why couldn't Marshal Haggard read the papers himself?",a="Age has left Haggard's eyesight weak and clouded. He could not read the small, weathered writing on the faded papers.",al={"haggard blind","why haggard needs help"},it="why_me"},{q="Why does Marshal Haggard want this done?",a="Marshal Haggard is an old soldier living in quiet retirement, but he still carries the instincts of an officer of the realm. When you come seeking the truth about Stalvan Mistmantle, he remembers the discarded parchments left in the chest when he took over the home. Though he has no personal stake in the dark mystery, he wants to aid your investigation as best he can—even if his failing eyesight prevents him from examining the papers himself.",al={"why help haggard","marshal haggard motive","why does haggard want journal"},it="motive",add="7284e072"}},ang={["faction:Alliance"]="Tracing Stalvan's past brings you into the darker history hidden within Elwynn's peaceful farmlands.",["race:Human"]="As a human, you follow Stalvan through familiar settlements and see how isolation and malice can hide in plain sight."},kw={"duskwood","elwynn forest","faded journal page","forlorn spirit","marshal haggard","stalvan"},rel={"zone:elwynn","zone:duskwood","quest:1666"},m={start="Marshal Haggard",level="28",faction="Alliance",id=75,ri={"A Faded Journal Page"}},src={"The Legend of Stalvan (8)"}}
E["quest:78"] = {t="quest",n="The Legend of Stalvan",z="duskwood",s="Marshal Haggard sends you to find Tavernkeep Smitts, who may know the hand behind a page from Stalvan's journal.",h="Marshal Haggard sends you to find Tavernkeep Smitts, who may know the hand behind a page from Stalvan's...",sec={{t="A Lead from the Marshal",b="Marshal Haggard cannot read the faded writing on the torn journal page you recovered from his chest in Elwynn Forest. His failing eyesight leaves the words beyond him. He recalls serving with the Stormwind Guard and spending evenings at the Scarlet Raven Tavern in Darkshire. So he sends you across the river to Tavernkeep Smitts, whose years behind the bar have made him a keeper of local history and rumors.",sp=0},{t="Return to the Scarlet Raven",b="You cross Duskwood's gloomy woods and show the faded page to Smitts behind the counter. He is glad to hear of his old acquaintance Haggard, though he grieves for the veteran's failing health. Then Smitts sees the parchment, and alarm overtakes his easy manner. He knows the distinctive handwriting without doubt, bringing the search closer to the truth of Stalvan's madness.",sp=1}},faq={{q="Why does Marshal Haggard send me back to Darkshire?",a="Marshal Haggard is aging and nearly blind, so he cannot examine the recovered journal page. He remembers Tavernkeep Smitts as a keeper of local lore from his Stormwind Guard days, and sends you to ask him about the writing.",al={"why go to darkshire","haggard to darkshire","why smitts"},it="purpose"},{q="Where is Tavernkeep Smitts located?",a="Tavernkeep Smitts tends the bar inside the Scarlet Raven Tavern, on the eastern side of Darkshire in Duskwood.",al={"where is smitts","smitts location","scarlet raven tavern location"},gp=true},{q="What item do you carry to Tavernkeep Smitts?",a="You carry a Faded Journal Page, an excerpt from Stalvan Mistmantle's lost journal, found secured inside Marshal Haggard's footlocker.",al={"what item","faded journal page","stalvan journal page"},it="item"},{q="Does Tavernkeep Smitts recognize the handwriting?",a="Yes. Smitts recognizes the handwriting as soon as he sees the faded page, and his alarm gives the search for Stalvan its next lead.",al={"does smitts know the writing","smitts reaction to journal"}},{q="How does Smitts know Marshal Haggard?",a="Smitts hosted Haggard years ago, when Haggard led Stormwind Guard patrols into Duskwood and visited the Scarlet Raven Tavern for drinks.",al={"smitts haggard relationship","how smitts knows haggard"},it="ties"},{q="What comes next in the search for Stalvan?",a="Take the faded journal page to Smitts at the Scarlet Raven Tavern and follow the lead he gives you.",al={"what is next","next step stalvan","stalvan chain continue"},it="next_step"},{q="Why does Marshal Haggard want this done?",a="Marshal Haggard cannot read the faded journal page because his eyesight is failing. He remembers Tavernkeep Smitts as an old acquaintance with a strong knowledge of local history, and asks you to bring the page to him in Darkshire.",al={"why does haggard want this done","marshal haggard motive","why help find stalvan"},it="motive",add="bf062962"},{q="Why does Marshal Haggard send you instead of going himself?",a="Haggard is an old, retired marshal living in isolation, rapidly losing his eyesight. The roads through the woods are dangerous, and he simply lacks the youth and physical stamina to trek back across the border to Duskwood. He relies on an capable traveler like you to run his errand and show the journal page to his old acquaintance.",al={"why can't haggard go","why does haggard need me","why doesn't haggard visit smitts"},it="why_me",add="c297959a"}},ang={["faction:Alliance"]="As an Alliance defender, you see bonds between former Stormwind guardsmen and keepers of local history across the Kingdom of Stormwind.",["race:Human"]="As a human, you see how tragedies in Elwynn and Darkshire remain part of the settlements' memories."},kw={"darkshire","duskwood","elwynn","journal","marshal haggard","mistmantle","scarlet raven tavern","stalvan","tavernkeep smitts"},rel={"quest:1666","npc:tavernkeep-smitts","subzone:scarlet-raven-tavern","subzone:darkshire","zone:duskwood","zone:elwynn","topic:stormwind-guard","topic:stormwind-kingdom"},m={start="Marshal Haggard",["end"]="Tavernkeep Smitts",level="28",faction="Alliance",id=78},src={"The Legend of Stalvan (9)"}}
E["quest:79"] = {t="quest",n="The Legend of Stalvan",z="duskwood",s="In Darkshire, The Legend of Stalvan rests on muddy pages and new proof. Tavernkeep Smitts gives you the pages and sends you to Commander Althea Ebonlocke.",h="In Darkshire, The Legend of Stalvan rests on muddy pages and new proof.",sec={{t="A Breakthrough in Darkshire",b="Tavernkeep Smitts and Marshal Haggard once investigated the slaughter of a visiting noble family in Duskwood. Haggard then led the Stormwind Guard. At the scene, they found torn, muddy journal pages, but had no handwriting samples or other papers to confirm who wrote them. So the notes could not formally implicate the recluse rumored to live in the wilderness.\n\nNow evidence gathered across Elwynn, Westfall, and Duskwood links the handwriting to Stalvan Mistmantle. The old rumors have become proof of murder.",sp=0},{t="Taking It to the Watch",b="Commander Althea Ebonlocke leads the Night Watch as Darkshire faces undead, feral beasts, and worse horrors in the forest. With the town's survival at stake, she has little time for tall tales or suspicions without proof. You bring Smitts's muddy pages to her, making a cold case the Night Watch's concern. The pages record a massacre on Duskwood soil and give the Watch reason to treat Stalvan Mistmantle as a dangerous fugitive who must face justice.",sp=1}},faq={{q="What evidence did Tavernkeep Smitts have all along?",a="Years ago, Tavernkeep Smitts and Marshal Haggard found torn, muddy journal pages at the scene where visiting nobles were slaughtered. They lacked handwriting samples to prove Stalvan Mistmantle wrote them until now.",al={"smitts journal pages","muddy journal pages","what did smitts find"},it="item"},{q="Why didn't Smitts report this to Commander Ebonlocke earlier?",a="Smitts and Haggard had no proof linking the handwriting on the muddy pages to the reclusive tutor. Without that link, they had only circumstantial scraps to bring to Commander Ebonlocke.",al={"why wait so long","why keep the pages secret","why didn't smitts tell the guard"}},{q="Who is Commander Althea Ebonlocke?",a="Commander Althea Ebonlocke leads the Night Watch, Darkshire's militia. Her watchmen guard the town and patrol Duskwood's roads against the undead and woodland predators.",al={"who is ebonlocke","althea ebonlocke role","commander of darkshire"},it="identity"},{q="What massacre took place in Duskwood?",a="A visiting noble family was slaughtered in Duskwood several years ago. Though rumors blamed their former tutor, Stalvan Mistmantle, local investigators lacked proof to charge him.",al={"what massacre","slaughter of nobles","who was murdered"},it="history"},{q="Where does this step fit into the overall investigation?",a="After searching registries, school records, and family crates across three territories, you bring the evidence to local authorities. It moves the investigation into formal justice and gives them grounds to act against Stalvan.",al={"stalvan quest chain step","how far in is this","is this the end of the quest"},it="place"},{q="Why is the Night Watch so reluctant to investigate old crimes?",a="Darkshire faces daily threats from wandering abominations, worgen packs, and spiders. Commander Ebonlocke must use her watchmen to defend the town, so old crimes need undeniable proof before she can spare them.",al={"why is ebonlocke busy","darkshire defense priority","night watch priorities"},it="threat"},{q="Why does Tavernkeep Smitts want you to speak with Commander Ebonlocke?",a="Smitts has quietly tracked the legend of Stalvan for years, ever since visiting nobles were slaughtered outside Darkshire. When he and Haggard inspected the grisly scene back then, they found muddy journal pages but lacked handwriting to link them to the hermit in the woods. Now that your investigation has unearthed samples proving Stalvan's authorship, Smitts finally possesses irrefutable evidence of the murderer's identity. He wants you to present the truth immediately so the town's defenders can officially confront the killer.",al={"why does smitts send you to ebonlocke","tavernkeep smitts motive","why tell ebonlocke now"},it="motive",add="3928db26"},{q="Why does Smitts send you rather than reporting this himself?",a="Smitts keeps the bar at the Scarlet Raven Tavern and only held a few loose fragments from the original slaughter. You are the one who actually tracked the trail across Elwynn, Westfall, and Duskwood, recovering the letters and journals that link the handwriting to Stalvan. Because you uncovered the vital clues connecting the entire puzzle, Commander Ebonlocke needs to hear the full account firsthand from the investigator who proved it.",al={"why doesn't smitts talk to ebonlocke","why me stalvan report","why do i report to ebonlocke"},it="why_me",add="225fd2ad"}},ang={["faction:Alliance"]="As an Alliance hero, you help the southern territories pursue justice when Stormwind's official support is absent.",["class:Paladin"]="As a paladin, you bring long-buried murders into the light and demand accountability for innocent lives taken in Duskwood's shadows.",["class:Rogue"]="As a rogue, you piece together handwriting samples from taverns and dusty trunks, using patient detective work to track elusive quarry."},kw={"darkshire","duskwood","ebonlocke","investigation","mistmantle","muddy journal","night watch","smitts","stalvan"},rel={"subzone:darkshire","zone:duskwood","npc:althea-ebonlocke","npc:tavernkeep-smitts","topic:light"},m={start="Tavernkeep Smitts",["end"]="Commander Althea Ebonlocke",level="28",faction="Alliance",id=79},src={"The Legend of Stalvan (10)"}}
E["quest:80"] = {t="quest",n="The Legend of Stalvan",z="duskwood",s="In Darkshire, the search for Stalvan Mistmantle brings a bloodstained journal page to the Night Watch. Commander Althea Ebonlocke sends you to Clerk Daltry to compare its writing with the town records.",h="In Darkshire, the search for Stalvan Mistmantle brings a bloodstained journal page to the Night Watch.",sec={{t="Closing the Net",b="The Night Watch has gathered journal pages from across Duskwood and the surrounding human territories. Together, they seem to condemn Stalvan Mistmantle, the elusive tutor. Commander Althea Ebonlocke has suspected him for some time, but she needs proof before passing judgment. The bloodstained page alone cannot show who wrote it. Its hand must be matched to Stalvan’s.",sp=0},{t="The Clerk's Eye",b="Clerk Daltry keeps Darkshire’s town records and has examined countless ledgers and signatures over the years. You bring him the newly discovered journal page to compare with Stalvan’s signatures in the registry. His judgment can establish whether the page is truly Stalvan’s and give the Night Watch the certainty it needs.",sp=1}},faq={{q="Why does Commander Ebonlocke need Clerk Daltry's confirmation?",a="Commander Althea Ebonlocke needs Clerk Daltry to check whether the bloodstained page matches Stalvan’s handwriting in Darkshire’s records. Daltry keeps the town registry and has long experience examining signatures, so his word can establish Stalvan’s guilt before Ebonlocke acts.",al={"why daltry","why check handwriting","clerk daltry purpose"},it="motive"},{q="Where does this step fit into the Legend of Stalvan storyline?",a="This is the eleventh chapter of the investigation, after the bloodstained journal page is recovered. Daltry’s comparison is the final check of the evidence before the Night Watch acts against Stalvan.",al={"what part is this","how far in chain","stalvan quest chain order"},gp=true},{q="Where is Clerk Daltry located in Darkshire?",a="Clerk Daltry is inside Darkshire’s town hall, where he keeps the community’s local records and property registries.",al={"daltry location","where is clerk daltry","find daltry"},it="place",gp=true},{q="What evidence did the investigator bring to Darkshire?",a="You bring a bloodstained journal page recovered during the search for Stalvan. It describes his grim thoughts and experiences, but its writing still needs to be checked against official records.",al={"what is the evidence","what page is this","bloodstained page lore"},it="item"},{q="Does Clerk Daltry confirm the handwriting is Stalvan's?",a="Yes. Daltry compares the bloodstained page with signatures in the town registry and confirms the writing matches Stalvan’s. Ebonlocke now has the certainty she sought before acting.",al={"does the handwriting match","is it stalvan","did stalvan write it"},sp=1,it="next_step"},{q="Why is the Night Watch so cautious about accusing Stalvan?",a="The Night Watch wants proof it can verify before accusing a former scholar of horrific crimes. Even in Duskwood’s troubled, isolated forest, it strives to uphold lawful order instead of relying on rumor or conjecture.",al={"why proof needed","why not just kill stalvan","ebonlocke suspicion"},it="motive"},{q="Why does Commander Althea Ebonlocke have you take the page to Clerk Daltry?",a="Commander Ebonlocke is responsible for the defense of Duskwood and Darkshire, keeping watch over the settlement's perimeter while you have been handling the fieldwork on Stalvan Mistmantle. Since you brought the bloodstained journal page directly to her, it is fastest to have you walk it over to Clerk Daltry at the town hall to verify the script while she remains on duty.",al={"why me ebonlocke","why doesn't ebonlocke talk to daltry","why send me to daltry"},it="why_me",add="5aad2c8f"}},ang={["faction:Alliance"]="Darkshire’s investigation shows how frontier towns keep law, order, and civil records while undead and shadowed beasts besiege them.",["race:Human"]="As a human of the southern kingdoms, you can see the tragedies that link Stormwind nobility, Duskwood settlers, and Elwynn’s scattered manors."},kw={"althea ebonlocke","bloodstained journal page","clerk daltry","darkshire","duskwood","legend of stalvan","night watch","stalvan mistmantle"},rel={"npc:althea-ebonlocke","npc:clerk-daltry","subzone:darkshire","zone:duskwood"},m={start="Commander Althea Ebonlocke",["end"]="Clerk Daltry",level="28",faction="Alliance",id=80},src={"The Legend of Stalvan (11)"}}
E["quest:90"] = {t="quest",n="Seasoned Wolf Kabobs",z="duskwood",s="At the Scarlet Raven Tavern, Chef Grual prepares his signature dish for Darkshire. He asks you to hunt Duskwood wolves for meat while his herbs arrive from Stormwind City.",h="At the Scarlet Raven Tavern, Chef Grual prepares his signature dish for Darkshire.",sec={{t="A Dish for Darkshire",b="Darkshire stands isolated among the horrors creeping through Duskwood. Trade caravans seldom reach town, farming has failed, and undead lurk nearby, yet people still need food. At the Scarlet Raven Tavern, Chef Grual turns dangerous forest wolves into hearty skewers. The local soil and timber cannot support delicate crops, so he relies on spices from the capital to make the gamey meat palatable.",sp=0},{t="A Shipment from Stormwind",b="Grual has just received a shipment of Stormwind Seasoning Herbs. Now he needs lean meat from the ferocious wolves stalking Duskwood. The delivery shows how Darkshire remains tied to the wider kingdom. Royal military aid has dwindled, while supply lines between city merchants and outer hamlets barely endure.",sp=0}},faq={{q="Who is Chef Grual?",a="Chef Grual is the cook stationed at the Scarlet Raven Tavern in Darkshire. He feeds patrons, locals, and Night Watch members hearty meals made from game hunted in the surrounding woods.",al={"chef grual","grual darkshire","who gives seasoned wolf kabobs"},it="identity"},{q="Where do you get the Stormwind Seasoning Herbs?",a="You do not need to fetch the Stormwind Seasoning Herbs. Grual has just received a shipment and needs ten Lean Wolf Flanks from you.",al={"stormwind herbs location","where are seasoning herbs"},gp=true},{q="Where are the wolves for the wolf flanks found?",a="Wild wolves roam Duskwood’s dark forests, especially in the groves and pathways just outside Darkshire. Any local wolf yields the lean meat Grual needs.",al={"lean wolf flank location","wolf flanks duskwood","where to hunt wolves"},gp=true},{q="Why does Darkshire need wolf meat for food?",a="Darkshire’s farmland is ruined and monsters cut it off, making livestock and crops nearly impossible to raise. Locals hunt dangerous wildlife, including wolves prowling beyond town’s borders.",al={"why eat wolves","darkshire food supply","why wolf kabobs"},it="motive"},{q="Why can't Grual get herbs locally in Duskwood?",a="Duskwood’s curse has corrupted much of its native plant life, leaving few edible or fragrant cooking herbs. Grual relies on cultivated varieties brought from Stormwind to season his dishes.",al={"why buy herbs in stormwind","duskwood herbs"}},{q="Does this quest tie into a larger storyline?",a="This is a standalone local tale, separate from any grand narrative. It shows Darkshire’s self-reliant way of life and its tenuous supply link to Stormwind.",al={"wolf kabobs lore significance","is seasoned wolf kabobs important"},it="ties"},{q="What are the Lean Wolf Flanks for?",a="Chef Grual uses the flanks as the primary meat for his local specialty, Seasoned Wolf Kabobs. With food scarce in the shadowed reaches of Darkshire and wolves prowling outside the town boundaries, lean wolf meat provides a plentiful staple for the Scarlet Raven Tavern's kitchen.",al={"lean wolf flank use","why wolf flanks","what is lean wolf flank for"},it="item",add="d7293b81"},{q="What are the Stormwind Seasoning Herbs for?",a="Wild wolf meat from the corrupted woods of Duskwood has a notoriously gamier, harsh flavor. Chef Grual relies on fragrant herbs brought in from Felicia Gump's flower shop in Stormwind to properly season the meat and turn it into a palatable delicacy for the patrons of Darkshire.",al={"stormwind seasoning herbs use","why get herbs from stormwind","what are the herbs for"},it="item",add="e8f8f6ed"},{q="Why does Chef Grual ask you instead of gathering the supplies himself?",a="Grual is a cook, not a huntsman or courier, and he must tend the fires at the Scarlet Raven Tavern. Venturing into the haunted wilds outside Darkshire exposes anyone to prowling beasts and worse threats, while the Night Watch has its hands full defending the town perimeter rather than hunting game or running errands to Stormwind.",al={"why can't chef grual get the meat","why does grual need an adventurer","why doesn't the night watch hunt the wolves"},it="why_me",add="4102789d"}},ang={["profession:Cooking"]="Grual’s recipe shows how wilderness hunters make tough predator meat palatable with refined city spices.",["faction:Alliance"]="The delivery between Darkshire and Stormwind shows how isolated settlements rely on the capital’s markets, even as military garrisons are withheld.",["class:Hunter"]="You track Duskwood’s ravenous wolf packs, using your skills to protect the hamlet and keep the tavern’s larder stocked."},kw={"chef grual","darkshire","duskwood","lean wolf flank","scarlet raven tavern","stormwind","wolf kabobs"},rel={"npc:chef-grual","subzone:darkshire","zone:duskwood","subzone:trade-district","subzone:old-town","topic:stormwind-kingdom"},m={start="Chef Grual",level="25",faction="Alliance",id=90,ri={"Lean Wolf Flank","Stormwind Seasoning Herbs"}},src={"Seasoned Wolf Kabobs (Classic)"}}
E["quest:93"] = {t="quest",n="Dusky Crab Cakes",z="duskwood",s="In Darkshire, Dusky Crab Cakes are a favorite snack with no crab in them. Chef Grual sends you to gather spider legs for Jitters, who is hungry and nervous.",h="In Darkshire, Dusky Crab Cakes are a favorite snack with no crab in them.",sec={{t="A Questionable Delicacy",b="Chef Grual cooks at the Scarlet Raven Tavern in Darkshire. Isolation, dark magic, and severed supply routes have left Duskwood short of food, so locals have changed what they eat. Grual says the cakes get their tangy flavor from the gooey legs of local giant spiders, not seafood from distant shores.",sp=0},{t="Hunting the Venom Webs",b="Chef Grual sends you north to the foothills and riverbanks, where Venom Web Spiders spin their snares. Undead and feral beasts make the gloomy forest dangerous, but fresh spider meat is one of the few ready sources of protein in the blighted woods. Grual fries the seasoned limbs on a hot skillet until crisp.",sp=0},{t="Comfort for a Cursed Soul",b="Jitters shelters in the abandoned village of Raven Hill in western Duskwood. Guilt and trembling terror haunt him after he inadvertently unleashed horrors upon the region. The agitated vagrant thinks of little besides his starving stomach. A hot batch of Chef Grual's savory spider cakes gives him rare comfort in exile.",sp=1}},faq={{q="Are Dusky Crab Cakes actually made of crab?",a="No. Chef Grual openly admits that Dusky Crab Cakes are made entirely from gooey spider legs. Darkshire has no access to the sea or fresh crab, so he uses local giant spiders for their texture and sharp, tangy flavor.",al={"is it real crab","crab cakes secret","what are crab cakes made of"}},{q="Where does Chef Grual get the spider legs?",a="Grual relies on adventurers to gather gooey legs from aggressive Venom Web Spiders. They nest mainly in northern Duskwood, between the forest foothills and the river.",al={"where to find spider legs","spider locations duskwood","venom web spiders location"},it="target"},{q="Who are these crab cakes being made for?",a="Chef Grual makes this batch for Jitters, though he serves the cakes to patrons in Darkshire. Jitters is a frightened hermit in the ghost town of Raven Hill in western Duskwood, desperate for food.",al={"who wants the crab cakes","who eats the crab cakes","why make crab cakes"},it="motive"},{q="Will Chef Grual teach me how to make Dusky Crab Cakes?",a="Chef Grual keeps his precise Dusky Crab Cakes recipe secret and refuses to share his trademark spice blend. He does give helpful adventurers another recipe from his cooking repertoire.",al={"can i learn crab cakes recipe","crab cake recipe cooking"}},{q="Why does Darkshire rely on spiders for food?",a="Undead, Nightbane worgen, and hostile creatures besiege Duskwood's roads, badly disrupting trade caravans and farming. With fresh livestock and imported goods scarce, Darkshire's inhabitants make use of whatever wildlife they can catch.",al={"why eat spiders in darkshire","duskwood food shortages"}},{q="Does Jitters know the cakes are made of spiders?",a="Jitters craves Chef Grual's famous crab cakes and cares little about their ingredients. Paralyzed by dread and starvation in the woods, he is eager for any familiar meal from Darkshire, whatever its creepy origin.",al={"does jitters know about the spiders","jitters reaction to spider meat"}},{q="What is the Gooey Spider Leg used for?",a="Despite the pleasant name on the tavern menu, Gooey Spider Legs are the core meat inside Chef Grual's famous Dusky Crab Cakes. Grual seasons the skittering limbs with his secret blend of spices and sears them in a skillet, relying on their natural juices to give the savory cakes their distinctive, tangy flavor.",al={"gooey spider leg use","why gooey spider legs","spider legs crab cakes"},it="item",add="e54432be"}},ang={["profession:Cooking"]="As a cook on the frontier, you learn that even terrifying predators like giant venomous spiders can become a town's regional delicacy.",["faction:Alliance"]="As an Alliance traveler, you see how neglected infrastructure and severed supply lines push towns like Darkshire to live on giant vermin."},kw={"chef grual","darkshire","duskwood","dusky crab cakes","jitters","scarlet raven tavern","spider legs","venom web spider"},rel={"quest:5","quest:240","npc:chef-grual","npc:jitters","subzone:darkshire","zone:duskwood"},m={start="Chef Grual",level="20",faction="Alliance",id=93,ri={"Gooey Spider Leg"}},src={"Dusky Crab Cakes (Classic)"}}
E["quest:95"] = {t="quest",n="Sven's Revenge",z="duskwood",s="In Sven's Revenge, grief drives Sven Yorgen from his ruined farm in southern Duskwood to hunt its killers. Now camped in the western hills, he asks travelers to return to the farmstead, where a stranger buried something near the barn.",h="In Sven's Revenge, grief drives Sven Yorgen from his ruined farm in southern Duskwood to hunt its killers.",sec={{t="Tragedy at the Farmstead",b="Hooded Dark Riders came from Deadwind Pass and attacked Sven Yorgen's farm in southeastern Duskwood. Sven was away, and they killed his family. When he returned to the slaughter, he saw an unknown figure skulking near the barn and hurriedly burying something. Sven left the object hidden and set out to hunt the killers.",sp=0},{t="Unearthing Secrets",b="Sven Yorgen is camped in the western hills, consumed by wrath and seeking help at his farmstead. Between the farmhouse and ruined barn, a mound of loose dirt behind an old tree stump marks where something was hastily buried. Recovering it may explain why the shadowy riders targeted a quiet Duskwood farmer.",sp=0}},faq={{q="Who is Sven Yorgen?",a="Sven Yorgen was a farmer in southeastern Duskwood near the border of Deadwind Pass. After hooded riders murdered his family, he left his farm and became a recluse bent on vengeance.",al={"who is sven","sven lore","sven backstory"},it="people"},{q="What happened to Sven's farm?",a="Dark Riders from Deadwind Pass attacked Sven Yorgen's farmstead and killed his family. The property lay in ruins while Sven was away.",al={"yorgen farmstead tragedy","what happened to sven farm","why is sven farm destroyed"},it="history"},{q="Who buried something behind the barn?",a="After the massacre, Sven saw a shadowy figure burying something near his barn. He pursued the Dark Riders before he could catch the stranger or uncover what was buried.",al={"who buried the item","shadowy figure sven farm","who dug the mound"},it="identity"},{q="Where is the mound of loose dirt located?",a="At the Yorgen Farmstead in southeastern Duskwood, a mound of loose dirt lies behind an old tree stump between the barn and ruined farmhouse.",al={"where is the dirt mound","dirt mound location","where is the stump"},it="place",gp=true},{q="Who are the Dark Riders?",a="The Dark Riders are hooded horsemen who ride out of Deadwind Pass. Their origins are unknown, but their attacks in Duskwood bring death and ruin.",al={"what are the dark riders","dark riders lore","riders of deadwind pass"},it="threat"},{q="Why didn't Sven dig up the buried item himself?",a="Sven was overcome with grief when he returned home and saw a figure burying something. He immediately pursued the retreating Dark Riders, leaving the object behind.",al={"why didn't sven check the dirt","why did sven leave"},it="why_me"},{q="Why does Sven Yorgen want the buried object recovered?",a="Sven seeks vengeance for the brutal slaughter of his family by the mysterious Dark Riders of Deadwind Pass. When he discovered the massacre, he witnessed a shadowy figure hurriedly burying something near his barn before fleeing. Driven by rage and the need for answers, Sven believes whatever lies beneath the soil holds the key to uncovering why his farm was targeted and who aided in his family's destruction.",al={"why does sven want this","sven yorgen motive","sven revenge quest reason"},it="motive",add="e064b97c"}},ang={["faction:Alliance"]="The slaughter of the Yorgen family shows how far dark forces reach in isolated Duskwood, where Stormwind army patrols are scarce.",["class:Paladin"]="As a paladin, you see the slaughter of innocents by forces from Deadwind Pass as a call for justice for the dead."},kw={"dark riders","deadwind pass","duskwood","mound of loose dirt","stump","sven yorgen","sven's revenge","yorgen farmstead"},rel={"npc:sven-yorgen","subzone:yorgen-farmstead","topic:dark-riders","quest:164","quest:230","zone:duskwood","zone:deadwind"},m={start="Sven Yorgen",["end"]="Mound of loose dirt",level="25",faction="Alliance",id=95},src={"Sven's Revenge"}}
E["quest:96139"] = {t="quest",n="The Valor Family",z="duskwood",s="In Darkshire, Sirra Von'Indi seeks records of Raven Hill's lost people. The village remembers their courage, but her library holds little of Raven Hill's history.",h="In Darkshire, Sirra Von'Indi seeks records of Raven Hill's lost people.",sec={{t="A Lost History",b="Sirra Von'Indi says brave people helped Darkshire endure. Lady Althea was among them, as were those who died at Raven Hill. You are asked to search for anything that might preserve their memory.",sp=0},{t="The Tome",b="The book you bring back tells of the Valor family. Sirra offers to copy it and welcomes any other material about them.",sp=1}},faq={{q="Who is asking me to search Raven Hill?",a="Sirra Von'Indi, whose library is in Darkshire, asks you to search Raven Hill for material about its people.",al={"who wants the book","sirra raven hill","who is sirra"}},{q="Why does Sirra want records from Raven Hill?",a="Sirra wants Raven Hill's history remembered. It was lost along with the people who lived there.",al={"why search raven hill","raven hill history","remember raven hill"}},{q="Who does Sirra say helped keep Darkshire standing?",a="Sirra names Lady Althea and those who lost their lives at Raven Hill as brave people whose actions helped Darkshire endure.",al={"darkshire heroes","lady althea","who saved darkshire"}},{q="What is Raven Hill's history like?",a="Sirra says Raven Hill's history was lost along with its people. Her library holds little about it.",al={"what happened to raven hill","raven hill past","raven hill lost"}}},kw={"darkshire","duskwood","history","lady althea","raven hill","sirra von'indi","tome","valor family"},rel={"quest:163","subzone:darkshire","npc:sirra-von-indi","zone:duskwood"},m={id=96139},src={"In-game quest text: The Valor Family"},fv=true}
E["quest:97"] = {t="quest",n="The Legend of Stalvan",z="duskwood",s="In Darkshire, Clerk Daltry matches the recovered handwriting to Stalvan Mistmantle. His report makes the Night Watch's suspicion certain.",h="In Darkshire, Clerk Daltry matches the recovered handwriting to Stalvan Mistmantle.",sec={{t="A Match in the Records",b="Back in Darkshire's town hall, Clerk Daltry compares the bloodstained journal page with signatures in the Town Registry. The handwriting matches Stalvan Mistmantle exactly. After the trail led through manors, inns, and civic records across the human kingdoms, the Night Watch now has proof that the danger is close at hand.",sp=0},{t="The Night Watch's Suspicions",b="Commander Althea Ebonlocke has feared Stalvan from the beginning. Duskwood already faces feral worgen, skeletal undead, and lurking necromancers. She cannot ignore another danger: an unaccounted-for murderer in the woods. Daltry's confirmation sets the Night Watch on a course to find Stalvan and stop him for good.",sp=1}},faq={{q="What did Clerk Daltry discover?",a="Clerk Daltry compared the bloodstained journal page with signatures in Darkshire's Town Registry. The handwriting matched Stalvan Mistmantle exactly, as Commander Ebonlocke suspected.",al={"what did daltry find","daltry handwriting match","stalvan handwriting proof"}},{q="Why does Commander Althea Ebonlocke care so much about Stalvan?",a="Commander Althea Ebonlocke leads the Night Watch, Darkshire's beleaguered militia. With terrors already threatening the land, she cannot leave a violent, shadowy figure with a dark past loose and unaccounted for in Duskwood.",al={"why does althea care","ebonlocke investigation","night watch stalvan"},it="motive"},{q="Where does this step take place?",a="This step takes place entirely within Darkshire. Clerk Daltry is in the town hall, while Commander Althea Ebonlocke patrols nearby on the town's central roads.",al={"where is this quest","quest location","darkshire stalvan turn in"},it="place",gp=true},{q="What happens after reporting the handwriting match?",a="After Clerk Daltry confirms the match, the investigation turns to hunting for Stalvan's whereabouts in Duskwood's haunted wilds.",al={"what next stalvan","after daltry match","next step stalvan chain"},it="next_step"},{q="Who was Stalvan Mistmantle originally?",a="Stalvan Mistmantle once taught at the Moonbrook schoolhouse and later tutored the Flintridge family's children privately. His letters and journal pages lead from Moonbrook and Goldshire back to Duskwood, where he lives as a dangerous recluse in the woods.",al={"who is stalvan","stalvan background","stalvan mistmantle story"},it="identity"},{q="Why was handwriting analysis necessary?",a="Events and accusations about Stalvan span Moonbrook and Goldshire, so official records are scattered. Darkshire's civic registry holds verified local samples that can definitively tie those foreign clues to this specific man.",al={"why match handwriting","why did daltry check writing","proving stalvan identity"}},{q="Why is Clerk Daltry so eager for you to report to Commander Ebonlocke?",a="Clerk Daltry is a town record-keeper, not an officer of the Night Watch, and confirming that the handwriting belongs to Stalvan Mistmantle validates Commander Ebonlocke's grave suspicions. Daltry recognizes that an official murder inquiry requires immediate armed authority, making it urgent that Althea receives definitive proof without delay.",al={"why does daltry want this done","daltry motive","why report to althea"},it="motive",add="cc1b58e5"}},ang={["faction:Alliance"]="For Alliance investigators, Stalvan's trail shows how Darkshire's battered leaders and wandering adventurers must work together to keep the southern territories secure.",["race:Human"]="As a human, you see your society's decay in respected tutors and rural towns slipping from civilization into madness and isolation."},kw={"althea ebonlocke","clerk daltry","darkshire","duskwood","handwriting","mistmantle","night watch","stalvan"},rel={"npc:clerk-daltry","npc:althea-ebonlocke","subzone:darkshire","zone:duskwood"},m={start="Clerk Daltry",["end"]="Commander Althea Ebonlocke",level="28",faction="Alliance",id=97},src={"The Legend of Stalvan (12)"}}
E["quest:98"] = {t="quest",n="The Legend of Stalvan",z="duskwood",s="Madame Eva's foreboding points to a threat against Darkshire: Stalvan Mistmantle, a killer with a family ring. You are asked to confront him and bring the ring to her.",h="Madame Eva's foreboding points to a threat against Darkshire: Stalvan Mistmantle, a killer with a family ring.",sec={{t="A Threat to Darkshire",b="Madame Eva's premonition has led you to Stalvan Mistmantle, whose crimes have brought fear to Darkshire. He is said to threaten the town from his cottage just north of it. You are asked to put an end to that danger and take his family ring to Madame Eva.",sp=0}},faq={{q="Who is Stalvan Mistmantle?",a="Stalvan Mistmantle is described as a killer responsible for many crimes, and he threatens Darkshire.",al={"stalvan","who is stalvan","stalvan backstory"}},{q="Why does Madame Eva send me after Stalvan?",a="Madame Eva's premonition led to the discovery of Stalvan's threat against Darkshire.",al={"why stalvan","eva stalvan","why kill stalvan"}},{q="Where is Stalvan's cottage?",a="Stalvan's cottage is just north of Darkshire.",al={"stalvan cottage","where stalvan","cottage location"}},{q="What does Madame Eva ask me to bring back?",a="She asks you to show her Stalvan's family ring.",al={"family ring","stalvan ring","bring eva what"}},{q="What happened after Stalvan was killed?",a="Madame Eva says Stalvan is dead, and that Duskwood is free from his bloodthirst.",al={"stalvan ending","is stalvan dead","what happened to stalvan"}},{q="Why is Madame Eva glad?",a="She sensed hope spread through the tainted forest after Stalvan's death, though she grieves for his victims.",al={"eva happy","why is eva glad","madame eva reaction"}}},kw={"cottage","darkshire","duskwood","family ring","madame eva","stalvan","stalvan mistmantle"},rel={"zone:duskwood","subzone:darkshire","npc:madame-eva"},m={id=98},src={"In-game quest text: The Legend of Stalvan"},fv=true}
E["subzone:addle-s-stead"] = {t="subzone",n="Addle's Stead",z="duskwood",s="In southwestern Duskwood, Addle's Stead lies abandoned south of Raven Hill. Its first homesteaders fled long ago. Now the Defias Brotherhood uses the farm as a hidden staging ground.",h="In southwestern Duskwood, Addle's Stead lies abandoned south of Raven Hill.",sec={{t="A Outpost in the Dark",b="Addle's Stead lies in ruin beneath Duskwood's darkness. The Defias Brotherhood now uses the old farm. Agents watch the perimeter and lurk in the farmhouse, while supplies fill the barn. Shadows in southwestern Duskwood help them evade the Night Watch and Stormwind authorities.",sp=0},{t="Tangled in the King's Disappearance",b="Addle's Stead holds more than a bandit hideout. The Defias Brotherhood keeps sensitive records there, including documents and dockets linking regional conspirators to King Varian Wrynn's disappearance. Those papers make the ruined farm a thread to follow in uncovering treason within the Alliance.",sp=1}},faq={{q="Where is Addle's Stead located?",a="Addle's Stead lies in southwestern Duskwood, south of the Raven Hill township and directly west of the Vul'Gol Ogre Mound.",al={"addle's stead location","where is addles stead","find addles stead"},it="place",gp=true},{q="Who controls Addle's Stead right now?",a="The Defias Brotherhood occupies Addle's Stead. Night runners, night blades, and enchanters use the old house and barn as a remote hideout.",al={"who is at addles stead","mobs at addles stead","addles stead enemies"},it="residents"},{q="Why is the farm abandoned?",a="The farm's first inhabitants fled when a curse of darkness, beasts, and undead overtook Duskwood and drove common folk away.",al={"what happened to the farm","who was addle","why is addles stead ruined"},it="ruin"},{q="What brings Alliance adventurers to Addle's Stead?",a="Alliance adventurers following clues through Duskwood may be sent to search the Defias hideout at Addle's Stead for an important docket.",al={"why go to addles stead","addles stead quest","missing king duskwood"},sp=1,it="purpose"},{q="What is Addle's Stead?",a="Addle's Stead is an abandoned farmstead in southwestern Duskwood, situated south of Raven Hill and just west of the Vul'Gol Ogre Mound. Like many homesteads across the region, it was swallowed by the spreading gloom and forsaken by its original owners, leaving its overgrown fields and dilapidated farmhouse behind.",al={"what is addles stead","addle stead","about addles stead"},it="place",add="84087cc5"},{q="What happened at Addle's Stead?",a="Once a peaceful homestead, the farm fell into ruin when dark curses fell across Duskwood and drove out its inhabitants. Agents of the Defias Brotherhood eventually moved in to claim the barn and farmhouse as an outpost.",al={"addles stead history","what happened here","history of addles stead"},it="history",add="c80be076"},{q="Is Addle's Stead dangerous?",a="Very much so. The abandoned property is patrolled by hostile Defias operatives, including stealthy Night Runners, deadly Night Blades, and enchanters lurking near the farmhouse.",al={"how dangerous is addles stead","is addle's stead safe","threats at addle's stead"},it="danger",add="67874313"}},ang={["faction:Alliance"]="As an Alliance investigator tracking the missing King Varian Wrynn, you can find vital conspiratorial dockets left by the Defias Brotherhood in the dilapidated farmhouse.",["class:Rogue"]="As a rogue, you can see how the Defias syndicates slip unnoticed across borders, hiding operatives in Duskwood's gloom."},kw={"addle's stead","addles stead","defias","defias brotherhood","duskwood","raven hill"},rel={"zone:duskwood","topic:defias-brotherhood","topic:varian-wrynn","quest:163","subzone:vul-gol-ogre-mound","topic:alliance"},src={"Addle's Stead"}}
E["subzone:beggar-s-haunt"] = {t="subzone",n="Beggar's Haunt",z="duskwood",s="Forsaken agents watch the eastern approaches from Beggar's Haunt, an old Stormwind tower. It stands on a hillside in northeastern Duskwood, near the mountain road to Deadwind Pass.",h="Forsaken agents watch the eastern approaches from Beggar's Haunt, an old Stormwind tower.",sec={{t="A Watchtower in the Shadows",b="Beggar's Haunt looks over the hills east of Manor Mistmantle. Stormwind once kept guards here to watch the kingdom's eastern approaches. As Duskwood sank into gloom, the patrols withdrew to Darkshire and left the tower to weather and ruin. Now Forsaken agents study the region from within Alliance territory. Among them are members of the Royal Apothecary Society and the Deathstalkers.",sp=0},{t="Knight's Hollow and the Forgotten Dead",b="A winding path behind Beggar's Haunt descends to Knight's Hollow, where a secluded pool lies beneath a waterfall. An unmarked grave rests between two hooded stone statues, like the guardians beside the Dark Portal. Nearby graves include the resting place of an Unknown Soldier. These graves recall forgotten clashes along the frontier, fought long before the Forsaken took the watchtower.",sp=0}},faq={{q="Why are there Forsaken at Beggar's Haunt?",a="Forsaken agents from the Undercity have claimed the abandoned tower. Among them are Apothecary Faustin of the Royal Apothecary Society and Deathstalker Zraedus. They watch Alliance movements and quietly conduct experiments far to the south.",al={"who is at beggars haunt","why is horde here","undead at beggars haunt"},it="why_here"},{q="Was this tower originally built by the Forsaken?",a="No. Stormwind built the tower as a scout outpost. When local defenses faltered and the region became Duskwood, the Stormwind Guard abandoned it. Forsaken scouts later seized the empty tower.",al={"who built beggars haunt","beggars haunt history","is this an alliance tower"},it="history"},{q="What is the strange grave behind the tower?",a="Knight's Hollow lies down the path behind Beggar's Haunt. At its secluded waterfall pool, an unmarked grave rests between hooded guardian statues like those beside the Dark Portal.",al={"knights hollow statues","grave behind tower","dark portal statues duskwood"},it="place"},{q="Is Beggar's Haunt hostile to Alliance travelers?",a="Yes. The Forsaken agents at the tower are seasoned and strike down Alliance travelers who come too close to their hillside refuge.",al={"will they attack me","beggars haunt guards","is beggars haunt safe"},it="hostile"},{q="What is Beggar's Haunt?",a="Beggar's Haunt is an old, abandoned watchtower originally erected by the Stormwind Guard in northeastern Duskwood. Positioned high along the ridge east of Manor Mistmantle and overlooking the pass to Deadwind, this fortified stone outpost has long since fallen out of human control and fallen prey to the encroaching darkness of the woods.",al={"beggars haunt","what is this tower","beggars haunt duskwood"},it="place",add="221bad0c"},{q="Who lives in Beggar's Haunt?",a="The tower is occupied by two high-ranking Forsaken agents: Apothecary Faustin of the Royal Apothecary Society and his protector, Deathstalker Zraedus. Together, they use the secluded outpost to conduct dark alchemical research far away from the eyes of both Stormwind and their enemies in Lordaeron.",al={"who is at beggars haunt","who controls beggars haunt","beggars haunt inhabitants"},it="residents",add="945d85f8"},{q="Why was Beggar's Haunt abandoned?",a="Like much of Duskwood, the outpost was abandoned when the kingdom of Stormwind's military presence collapsed across the region. With the Night Watch struggling to defend even Darkshire from ravenous beasts, undead horrors, and spiders, remote guard towers along the ridges were left deserted and quickly commandeered by hostile forces.",al={"why is beggars haunt abandoned","beggars haunt ruin","why did stormwind leave beggars haunt"},it="ruin",add="29ce06ab"},{q="Is Beggar's Haunt dangerous?",a="Extremely so, particularly for unsuspecting Alliance explorers traveling through eastern Duskwood. Apothecary Faustin and Deathstalker Zraedus are seasoned veterans far deadlier than the surrounding wildlife, and they will mercilessly strike down anyone from the Alliance who wanders too close to their secluded stronghold.",al={"is beggars haunt safe","beggars haunt level","danger at beggars haunt"},it="danger",add="dbe0cc4e"}},ang={["faction:Alliance"]="Forsaken agents in an old Stormwind scout tower just off the main road show that the Horde has reached Darkshire's doorstep.",["race:Undead"]="As a Forsaken, you hold a secluded and dangerous foothold deep in the human lands of the south."},kw={"apothecary faustin","beggar's haunt","deathstalker zraedus","duskwood","knight's hollow","scout tower","stormwind guard"},rel={"zone:duskwood","topic:forsaken","topic:royal-apothecary-society","topic:stormwind-guard","subzone:manor-mistmantle","zone:deadwind","subzone:darkshire","subzone:dark-portal"},src={"Beggar's Haunt"}}
E["subzone:brightwood-grove"] = {t="subzone",n="Brightwood Grove",z="duskwood",s="West of Darkshire, ruined farms and overgrown clearings shelter savage Nightbane worgen in Brightwood Grove.",h="West of Darkshire, ruined farms and overgrown clearings shelter savage Nightbane worgen in Brightwood Grove.",sec={{t="A Grove in Shadow",b="Brightwood Grove lies within sight of Darkshire, where ruined farms and fences mark the town's edge. Nightbane worgen make crude camps among the overgrown clearings and prowl close to town. Their presence threatens Darkshire. So the Night Watch and travelers passing through keep their numbers down to protect the settlement.",sp=0}},faq={{q="Where is Brightwood Grove?",a="Brightwood Grove lies in eastern Duskwood, just west of Darkshire along the main paths.",al={"brightwood grove location","where is brightwood grove","brightwood duskwood"},it="place",gp=true},{q="What creatures inhabit Brightwood Grove?",a="Savage Nightbane worgen inhabit Brightwood Grove. They make crude camps in ruined buildings and attack anyone who comes near.",al={"monsters in brightwood grove","brightwood enemies","what lives in brightwood"},it="threat"},{q="Why is the grove dangerous to Darkshire?",a="Brightwood Grove lies just west of Darkshire. Aggressive worgen packs in the brush threaten town patrols, supply lines, and travelers arriving by road.",al={"why is brightwood grove dangerous","darkshire brightwood threat"},it="conflict"},{q="Are there any friendly settlements in the grove?",a="No friendly settlements remain in the grove. Its few stone buildings and farmsteads lie in ruins, abandoned to the elements and occupied by roving worgen.",al={"is anyone friendly in brightwood","brightwood town"},it="residents"},{q="What is Brightwood Grove?",a="Brightwood Grove is a shadowy expanse situated just west of Darkshire in Duskwood. Once part of the verdant forest before darkness crept over the region, the grove now lies under an oppressive gloom. The scattered buildings that once stood along its borders have collapsed into ruins, and feral packs of Nightbane worgen have claimed the overgrown fields and woods as their hunting grounds.",al={"brightwood grove","what is brightwood grove","brightwood duskwood"},it="place",add="d7b16ad8"},{q="Why is Brightwood Grove ruined?",a="Like much of Duskwood, Brightwood Grove succumbed to the spreading curse and terror that consumed the region. The homesteads and structures on its outskirts were abandoned and broke down into decay as predatory Nightbane worgen moved into the area. Now, instead of peaceful farmlands or sheltered outposts, only crude beasts' camps and shattered stone foundations remain.",al={"why is brightwood grove ruined","brightwood ruins","why was brightwood grove abandoned"},it="ruin",add="d83f7d45"},{q="Is Brightwood Grove dangerous?",a="Brightwood Grove is extremely perilous for travelers. Ferocious Nightbane worgen prowl the dark fields, pitching crude encampments and viciously attacking anyone who approaches. Because it sits directly west of Darkshire, the ravenous wolf-men present a constant threat to the town's perimeter, requiring stalwart defenders and adventurers to actively cull their numbers.",al={"is brightwood grove dangerous","brightwood danger","how dangerous is brightwood grove"},it="danger",add="f237257f"},{q="Why is it called Brightwood Grove?",a="No surviving account explains the grove's name. It seems to recall a brighter past, when Duskwood was a lush, sunlit woodland under Stormwind's care; the shadows, curses, and worgen have since utterly stolen the light from the forest.",al={"why is it called brightwood grove","brightwood grove name meaning","brightwood name origin"},it="name",add="90b29732"}},ang={["faction:Alliance"]="Brightwood Grove lies just outside Darkshire's gates. Clearing out its worgen packs helps keep the beleaguered town connected to the west.",["class:Hunter"]="As a hunter, the grove's dark thickets make tracking the vicious Nightbane difficult. Stay alert for ambushes behind the tree line."},kw={"brightwood grove","darkshire","duskwood","night watch","nightbane","wolf men","worgen"},rel={"zone:duskwood","subzone:darkshire","topic:worgen","topic:alliance"},src={"Brightwood Grove"}}
E["subzone:darkened-bank"] = {t="subzone",n="Darkened Bank",z="duskwood",s="At Duskwood’s northern edge, Darkened Bank runs beside Elwynn Forest. Its shore reaches east toward the Redridge Mountains, between safer ground and the forest’s terrors.",h="At Duskwood’s northern edge, Darkened Bank runs beside Elwynn Forest.",sec={{t="A Precarious Boundary",b="Darkened Bank follows the river that divides Duskwood from Elwynn Forest. Its shore stretches from the western bends to the stone span leading to the Redridge Mountains. Beneath Duskwood’s gloomy canopy, travelers coming south from Elwynn often reach this ground first. Near the western tip, a makeshift camp shelters the displaced Sven Yorgen and Lars, just beyond the deep woods.",sp=0}},faq={{q="Where is the Darkened Bank located?",a="Darkened Bank follows Duskwood’s northern shore along the river, opposite Elwynn Forest. It runs from the zone’s far west to the bridge crossing into the Redridge Mountains.",al={"darkened bank location","where is darkened bank","darkened bank duskwood"},it="place",gp=true},{q="Who lives along the Darkened Bank?",a="A modest refuge camp at the far western edge shelters Sven Yorgen and Lars. Driven from their former lives deeper in the territory, they use the riverbank as a fragile haven while seeking aid against Duskwood’s threats.",al={"camp on darkened bank","who is at darkened bank","darkened bank npcs"},it="residents"},{q="How do travelers usually reach this area?",a="You can reach the western shore by swimming south across the river from southwestern Elwynn Forest. Or follow the southern riverbank west from the Redridge bridge.",al={"how to get to darkened bank","getting to darkened bank"},it="arrival",gp=true},{q="What is the Darkened Bank?",a="The Darkened Bank is the long northern shoreline of Duskwood, stretching from the western edge of the woods eastward toward the bridge leading into the Redridge Mountains. Looking out across the river toward Elwynn Forest, this borderland marks the transition from the golden light of the north into the unnatural gloom that blankets Duskwood.",al={"what is darkened bank","darkened bank duskwood","tell me about darkened bank"},it="place",add="84b37a17"},{q="Is the Darkened Bank dangerous?",a="While the Darkened Bank is home to relatively weaker wildlife and prowlers compared to the deadly terrors lurking deeper within Duskwood, it is far from safe. Predatory beasts stalk the brush along the river's edge, and refugees encamped on the western bank remain on high alert against the encroaching darkness.",al={"darkened bank danger","is darkened bank safe","threats darkened bank"},it="danger",add="180e4478"}},ang={["faction:Alliance"]="As an Alliance adventurer leaving Elwynn Forest, you can stop first at Darkened Bank before heading deeper into Duskwood’s haunted heart."},kw={"darkened bank","duskwood","elwynn forest","lars","river","shoreline","sven yorgen"},rel={"zone:duskwood","zone:elwynn","zone:redridge","npc:sven-yorgen","npc:lars"},src={"Darkened Bank"}}
E["subzone:darkshire"] = {t="subzone",n="Darkshire",z="duskwood",s="Darkshire's Night Watch holds the line while Duskwood's unnatural gloom closes around the town. With little aid from Stormwind, the people must guard their homes.",h="Darkshire's Night Watch holds the line while Duskwood's unnatural gloom closes around the town.",sec={{t="A Town Abandoned",b="Darkshire began as Grand Hamlet, a peaceful woodland settlement. The Old Horde razed it during the First War, and the village rose again. After Medivh fell at Karazhan, the death throes left in the surrounding woods made them the shadowed wilderness of Duskwood.\n\nDarkshire belongs to the Kingdom of Stormwind, yet the crown sends virtually no aid to its town hall. Political paralysis in Stormwind City has left the garrison unstaffed and the borders unpatrolled. Mayor Ello Ebonlocke and the local council govern alone, enforcing harsh, insular justice in the shadows.",sp=0},{t="The Line in the Dark",b="Walking dead from the western graveyards and feral worgen in the woods press against Darkshire's palisades. The Night Watch, a voluntary civilian militia led by Althea Ebonlocke, is the town's chief defense. From the town square, weary sentries patrol the pitch-black roads, keep them open, and turn back terrors at the tree line.\n\nAt the Scarlet Raven Tavern, travelers meet locals who are suspicious, frightened, and desperate for anyone able to wield a blade.",sp=0}},faq={{q="Why was the town renamed from Grand Hamlet?",a="The settlement was called Grand Hamlet when the region was a sunny forest. After Medivh died at nearby Karazhan, dark magic spread through the woods, blocking sunlight and raising the dead. As the forest decayed into Duskwood, residents renamed the village Darkshire to reflect their bleak, cursed surroundings.",al={"why is it called darkshire","grand hamlet name change","darkshire history"},it="name"},{q="Why isn't Stormwind helping defend Darkshire?",a="Stormwind withdrew its troops from Duskwood amid political turmoil after King Varian Wrynn disappeared. The townspeople formed the Night Watch to face threats the crown no longer contained.",al={"where is the stormwind army","why no guards in duskwood","why did stormwind abandon darkshire"},it="conflict"},{q="Who leads Darkshire?",a="Lord Ello Ebonlocke and the Council of Darkshire hold civic authority from the town hall, alongside town clerk Daltry. Ello's daughter, Commander Althea Ebonlocke, leads the Night Watch in the town's defense.",al={"who is in charge of darkshire","darkshire leadership","mayor of darkshire"},it="leader"},{q="What is the Night Watch?",a="The Night Watch is a civilian militia formed by Althea Ebonlocke out of necessity. With no Stormwind Army troops sent to Duskwood, townsfolk patrol the gloomy roads, guard the borders, and drive back ghouls and rogue beasts.",al={"what is the nightwatch","darkshire guards","who protects darkshire"},it="allies"},{q="Who was Morgan Ladimore?",a="Morgan Ladimore was a veteran who returned after the Third War to find his home ruined and his family missing. His search brought him to Darkshire, where local accounts preserve the rest of his story.",al={"morla dime lore","ladimore darkshire","who is the ladimore guy"},it="history"},{q="What is Darkshire?",a="Darkshire is the last surviving human settlement in Duskwood. Once a peaceful woodland village called Grand Hamlet, it now stands as an isolated, besieged outpost cloaked in perpetual gloom. The town contains an inn, a blacksmith, and a town hall, serving as the sole refuge for travelers and beleaguered locals holding out against the horrors of the woods.",al={"what is this town","tell me about darkshire","darkshire info"},it="place",add="59ecffc1"},{q="What happened to Darkshire in the past?",a="Originally founded as Grand Hamlet in what were then sunny woods, the town was razed by the Old Horde during the First War. Rebuilt after the Second War, the settlement faced a slow descent into horror when Medivh's death corrupted the surrounding forest into Duskwood. As perpetual twilight enveloped the land, the town took the name Darkshire.",al={"darkshire history","grand hamlet history","what happened to grand hamlet"},it="history",add="2c565dbf"},{q="Who lives in Darkshire?",a="Darkshire is inhabited by stubborn, jumpy locals, craftsmen, and the local government led by Lord Ello Ebonlocke and Clerk Daltry. Defended by Althea Ebonlocke and her volunteer Night Watch militia, the populace lives in constant fear and suspicion, cut off from royal aid yet fiercely committed to holding their ancestral home against the encroaching dark.",al={"who lives here","darkshire residents","who lives in darkshire"},it="residents",add="a7f74618"},{q="Is Darkshire dangerous?",a="While the settlement itself is heavily guarded by the Night Watch, danger presses against its very gates. Walking dead choke nearby cemeteries and roads, ferocious worgen stalk the darkened forests, and Stormwind has abandoned the region to its fate. Wandering beyond the dim lantern light of the town unescorted is an invitation to an early grave.",al={"is it safe here","is darkshire dangerous","how dangerous is darkshire"},it="danger",add="a9d39424"}},ang={["faction:Alliance"]="For the Alliance, Darkshire shows how the kingdom's frontier is fracturing. The townsfolk are grateful to its heroes, yet bitter toward the unresponsive nobility in Stormwind City.",["class:Paladin"]="As a paladin, you find the dead rising in every surrounding cemetery and frightened locals who have nearly forgotten the Light. Unholy blights are plentiful around the village perimeter."},kw={"brightwood","darkshire","duskwood","ebonlocke","grand hamlet","night watch","scarlet raven"},rel={"zone:duskwood","npc:althea-ebonlocke","npc:lord-ello-ebonlocke","topic:night-watch","subzone:scarlet-raven-tavern","zone:stormwind","quest:56","subzone:raven-hill-cemetery"},src={"Darkshire"}}
E["subzone:darkshire-town-hall"] = {t="subzone",n="Darkshire Town Hall",z="duskwood",s="In Darkshire Town Hall, the mayor and council govern a town besieged by darkness and undead. Its dim halls are the seat of their rule.",h="In Darkshire Town Hall, the mayor and council govern a town besieged by darkness and undead.",sec={{t="The Seat of Darkshire",b="Just west of Darkshire's main square, the Town Hall is where the town's leaders govern an increasingly isolated territory. Mayor Lord Ello Ebonlocke struggles to keep order and protect the people while Stormwind sends little military aid.\n\nClerk Daltry and other officials track town records and the travelers who brave Duskwood's dangerous roads. With danger all around, keeping those ledgers current is grim work.",sp=0}},faq={{q="Who leads the town from this building?",a="Lord Ello Ebonlocke leads Darkshire as its mayor and presides over the town council from the Town Hall. He directs local defenses and appeals to visiting adventurers for help, since Stormwind sends almost no reinforcements.",al={"who is the mayor","who runs darkshire","who is in the town hall"},it="in_charge"},{q="What records are kept inside the Town Hall?",a="Clerk Daltry keeps town registries of residents and travelers passing through Darkshire. Chaos and frequent dangers in Duskwood have left many records out of date.",al={"clerk daltry records","what does daltry do","town registry"}},{q="Why is the Town Hall so important to Duskwood's survival?",a="With Duskwood cut off from direct military support from Stormwind, the Town Hall is the working center for the Night Watch and local authorities. The council coordinates civilian defense and sends aid across the shadowy region.",al={"why does the town hall matter","darkshire council role"},it="purpose"},{q="What is Darkshire Town Hall?",a="Darkshire Town Hall serves as the administrative heart and seat of local government for the settlement of Darkshire. Perched on the western edge of the town square, the building is where local leaders, council members, and civic clerks coordinate civil affairs, maintain public registries, and attempt to govern a frightened population surrounded by the blighted wilderness of Duskwood.",al={"what is darkshire town hall","darkshire town hall purpose","about darkshire town hall"},it="place",add="e48299c3"},{q="Who lives in or runs Darkshire Town Hall?",a="The town hall is run by Mayor Lord Ello Ebonlocke and the Darkshire Council, alongside administrative staff like Clerk Daltry. Rather than a private residence, it functions as a municipal hub where Darkshire's civic authorities, historians, and scribes work daily to keep track of town records, manage civil matters, and deliberate over the settlement's defense.",al={"who works in darkshire town hall","who is in darkshire town hall","darkshire town hall staff"},it="residents",add="bcc317cc"},{q="Is Darkshire Town Hall dangerous?",a="The building itself is one of the safest sanctuaries in Duskwood. Heavily guarded by the Night Watch and surrounded by the town's defensive perimeter, it remains secure from the undead, feral beasts, and darker threats haunting the surrounding woods, provided the town perimeter holds against outside attacks.",al={"is darkshire town hall safe","darkshire town hall danger","danger inside darkshire town hall"},it="danger",add="8f432bfa"}},ang={["faction:Alliance"]="For Alliance travelers, the Town Hall reflects the fragile authority of the kingdom's southern frontier and the limits of Stormwind's protection in isolated settlements."},kw={"clerk daltry","council","darkshire","duskwood","ello ebonlocke","town hall"},rel={"subzone:darkshire","npc:lord-ello-ebonlocke","npc:clerk-daltry","quest:1041","zone:duskwood"},src={"Darkshire Town Hall"}}
E["subzone:dawning-wood-catacombs"] = {t="subzone",n="Dawning Wood Catacombs",z="duskwood",s="Beneath Raven Hill Cemetery in western Duskwood, undead fill the Dawning Wood Catacombs. Skeletal guards and ravenous ghouls haunt their stone tunnels.",h="Beneath Raven Hill Cemetery in western Duskwood, undead fill the Dawning Wood Catacombs.",sec={{t="Beneath Raven Hill",b="Beneath the ruined Raven Hill Cemetery, the Dawning Wood Catacombs hold the dead of the surrounding woods. Before twilight cursed the forest, those dead rested in these stone corridors. Now the catacombs shelter some of the region’s deadliest undead, and lone travelers face danger in their depths.\n\nTwo underground wings divide the catacombs. Animated skeletons guard ancestral tombs in the western passages. To the east, tunnels descend into a foul warren overrun by ravenous, disease-bearing ghouls.",sp=0}},faq={{q="Where are the Dawning Wood Catacombs located?",a="The Dawning Wood Catacombs lie beneath Raven Hill Cemetery on Duskwood’s far western edge. Their entrances descend among sprawling grave markers and ruined crypts.",al={"catacombs location","where is dawning wood catacombs","how to get to catacombs"},it="place",gp=true},{q="What lurks inside the catacombs?",a="Duskwood’s most concentrated and ferocious undead lurk inside. Heavily armed skeletal warriors defend the western wing, while savage, plague-ridden ghouls infest the eastern tunnels.",al={"catacombs enemies","what is in dawning wood catacombs","catacomb monsters"},it="threat"},{q="Why were the catacombs built in the first place?",a="The catacombs were excavated as a grand burial vault for local families and luminaries, when the region was still green. The curse that later engulfed the woods reanimated those buried within.",al={"catacombs history","why build catacombs","original purpose of catacombs"},it="purpose"},{q="Is it safe to explore the catacombs alone?",a="Exploring the catacombs alone is perilous. Tight packs of aggressive undead can overwhelm isolated travelers, and the close tunnels leave little room to retreat.",al={"can i solo catacombs","catacombs danger","is catacombs hard"},it="danger",gp=true},{q="What are the Dawning Wood Catacombs?",a="The Dawning Wood Catacombs are a twisting underground labyrinth carved beneath the sprawling Raven Hill Cemetery in western Duskwood. Originally dug to lay the dead of the region to rest, these cavernous stone halls have since become infested with some of the most ferocious and diseased undead prowling the forest. Split into two main wings, one side serves as a wretched den of rabid ghouls, while the other is haunted by armed skeletal guardians.",al={"what are the catacombs","dawning wood catacombs overview","raven hill catacombs"},it="place",add="fdcc93ff"},{q="Is it dangerous to enter the Dawning Wood Catacombs?",a="Venturing beneath the cemetery is among the most lethal undertakings in Duskwood. The catacombs teem with swarms of relentless undead that can quickly overwhelm a lone traveler in the pitch black. The eastern wing is packed with disease-carrying ghouls that tear through flesh, while the western side is held by seasoned skeletal sentinels standing vigil over desecrated tombs. Without seasoned allies at your back, a trip down these stairs is almost certainly fatal.",al={"catacombs danger","are catacombs dangerous","how dangerous are the catacombs"},it="danger",add="514fe1a3"}},ang={["class:Paladin"]="For a paladin, these catacombs hold the kingdom’s fallen, and their desecrated tombs call for the Light’s holy wrath.",["class:Priest"]="For a priest, restless spirits and decaying corpses lie beneath Raven Hill’s stone vaults, denied their final rest. The catacombs test the faith of those who enter."},kw={"crypts","dawning wood catacombs","duskwood","ghouls","raven hill cemetery","skeletons","undead"},rel={"subzone:raven-hill-cemetery","zone:duskwood","quest:163","topic:alliance"},src={"Dawning Wood Catacombs"}}
E["subzone:forlorn-rowe"] = {t="subzone",n="Forlorn Rowe",z="duskwood",s="At Raven Hill Cemetery's northern edge, Forlorn Rowe lies beneath a shadow of dread. Morbent Fel makes his home there, and his magic raises the restless dead across Duskwood.",h="At Raven Hill Cemetery's northern edge, Forlorn Rowe lies beneath a shadow of dread.",sec={{t="A Seat of Necromancy",b="Forlorn Rowe climbs the northern edge of Raven Hill Cemetery in gloom. Morbent Fel makes his home on the hill. The necromancer raises many of the dead who roam the surrounding wilderness. From above, his foul enchantments command skeletal servants, making Duskwood's northwestern corner perilous for travelers.",sp=0},{t="Cleansing the Hill",b="Morbent Fel's hold on Forlorn Rowe cannot be broken with ordinary steel. Dark enchantments shield him from mortal weapons until relics of holy power weaken him. To bring down the necromancer and break his hold over the woods, adventurers must find consecrated arms and strike at the curse smothering the cemetery grounds.",sp=1}},faq={{q="Where is the Forlorn Rowe located?",a="Forlorn Rowe rises along Raven Hill Cemetery's northern ridge in northwestern Duskwood, overlooking the cemetery.",al={"forlorn rowe location","where is forlorn rowe","find forlorn rowe"},it="place",gp=true},{q="Who lives at the Forlorn Rowe?",a="Morbent Fel makes his lair at Forlorn Rowe. The powerful necromancer uses dark arcane rites to raise and command the undead who wander Duskwood.",al={"who is at forlorn rowe","forlorn rowe boss","house on the hill duskwood"},it="residents"},{q="Why is Morbent Fel so hard to fight here?",a="Morbent Fel shields himself with foul sorcery. Ordinary attacks are nearly useless until a consecrated relic made to dispel his magic strips away his protections.",al={"morbent fel shield","morbent fel immune","how to kill morbent fel"},sp=1,it="power",gp=true},{q="Is the Forlorn Rowe part of the cemetery?",a="Yes. Forlorn Rowe rises along Raven Hill Cemetery's northern boundary, overlooking the graves and crypts below.",al={"is forlorn rowe raven hill","raven hill connection"},it="place"},{q="What is the Forlorn Rowe?",a="The Forlorn Rowe is a dark, desolate hill perched along the northern rim of Raven Hill Cemetery in northwestern Duskwood. Shrouded in unnatural gloom, this blighted rise overlooks the sprawling graveyard and serves as the personal redoubt of Morbent Fel, an evil necromancer who uses his foul sorcery to command the forest's wandering dead.",al={"what is forlorn rowe","forlorn rowe overview","about forlorn rowe"},it="place",add="aabdcca0"},{q="Is the Forlorn Rowe dangerous?",a="It is extremely hazardous. Morbent Fel wields lethal necromantic magic from his home atop the rise, actively binding and commanding the undead swarming the northern graveyard. Stepping onto these shadowed slopes invites the wrath of both the restless corpses he animates and the master sorcerer himself.",al={"forlorn rowe danger","how dangerous is forlorn rowe","is it safe here"},it="danger",add="e9789594"}},ang={["class:Paladin"]="As a paladin, you face dark rites at Forlorn Rowe that defy the Holy Light. Consecrated relics and righteous wrath can pierce the necromancer's wards.",["faction:Alliance"]="As an Alliance member, you know driving Morbent Fel from Forlorn Rowe is vital to bringing some safety back to Duskwood's western border."},kw={"cemetery","duskwood","forlorn rowe","morbent fel","necromancer","raven hill","undead"},rel={"quest:55","subzone:raven-hill-cemetery","zone:duskwood","quest:163","topic:alliance"},src={"Forlorn Rowe"}}
E["subzone:hushed-bank"] = {t="subzone",n="Hushed Bank",z="duskwood",s="At Hushed Bank, Duskwood’s western river marks the way from Three Corners toward Stranglethorn Vale. Beasts stalk its quiet shore, where dark mysteries linger.",h="At Hushed Bank, Duskwood’s western river marks the way from Three Corners toward Stranglethorn Vale.",sec={{t="A Frontier Along the River",b="Hushed Bank follows Duskwood’s western edge beside the river that divides the forest from Westfall. A covered wooden bridge carries travelers west, out of the grim wood. Near the bridge, open plains and sunlit farms give way to unnatural twilight. Thick underbrush and creeping fog crowd the riverbanks, where large spiders and hungry forest wolves stalk anyone who strays from the path.",sp=0},{t="Outcasts and Hermits",b="Near Hushed Bank’s northern end, Sven Yorgen and his companion Lars keep camp in the dense woods, beyond Darkshire’s suspicious eyes. They watch the treeline and carry bitter grievances tied to the region’s dark tragedies. Their refuge lies far from others, one of the few signs of living humanoids along this lonely shore.",sp=1}},faq={{q="Where is the Hushed Bank located?",a="Hushed Bank follows Duskwood’s western edge beside the river that separates the forest from Westfall. It runs from the fork near Three Corners south toward the borders leading to Stranglethorn Vale.",al={"hushed bank location","where is hushed bank","hushed bank map"},it="place"},{q="What connects the Hushed Bank to Westfall?",a="A covered wooden bridge spans the river at Hushed Bank, carrying travelers and carts between Westfall and Duskwood.",al={"bridge to westfall","westfall bridge duskwood","how to cross river to westfall"}},{q="Who lives along the Hushed Bank?",a="Sven Yorgen and his companion Lars keep camp in northern Hushed Bank. They live as isolated recluses, having fled the horrors that claimed Sven’s nearby farm.",al={"camp on hushed bank","who is at hushed bank","npcs hushed bank"},it="residents"},{q="What threats are found along this shoreline?",a="Large woodland beasts prowl Hushed Bank, including webwood spiders and dusking wolves that prey on anything moving through the brush.",al={"hushed bank mobs","dangers of hushed bank","hushed bank monsters"},it="danger"}},ang={["class:Hunter"]="As a hunter, you can track the wolves and spiders haunting the dense foliage along the riverbank, familiar beasts of the forest’s darker reaches.",["faction:Alliance"]="As an Alliance traveler, you can cross the covered bridge linking Westfall’s farmlands with Duskwood’s besieged outpost."},kw={"covered bridge","duskwood","hushed bank","lars","riverbank","sven yorgen","westfall"},rel={"zone:duskwood","zone:westfall","npc:sven-yorgen","npc:lars","subzone:three-corners","zone:elwynn","zone:stranglethorn"},src={"Hushed Bank"}}
E["subzone:manor-mistmantle"] = {t="subzone",n="Manor Mistmantle",z="duskwood",s="In northeastern Duskwood, Manor Mistmantle lies north of Darkshire. The old family homestead has fallen to ruin, and ghouls prowl its grounds.",h="In northeastern Duskwood, Manor Mistmantle lies north of Darkshire.",sec={{t="A Blighted Homestead",b="West of Beggar's Haunt, decay chokes the ruined grounds of Manor Mistmantle. Vicious ghouls guard the broken house. In the untended garden, the Tear of Tilloa blooms alone, the last sign of living beauty on the estate.",sp=0},{t="The Master of the Estate",b="Stalvan Mistmantle once taught school and served as a private tutor. Now he acts as an agent of the undead. His horrific crimes against his student's family became a dark legend across the kingdom.\n\nStalvan lurks on the upper floor of his family home, among the remains of those he slaughtered. Shambling horrors guard him. Travelers and investigators from Darkshire often find that the trail of Duskwood's most notorious phantom ends at this blood-soaked manor.",sp=1,bt={"q66.7"}}},faq={{q="Where is Manor Mistmantle located?",a="Manor Mistmantle lies in northeastern Duskwood, north of Darkshire and just west of Beggar's Haunt.",al={"manor mistmantle location","where is mistmantle manor","how to find manor mistmantle"},it="place",gp=true},{q="Who lives in Manor Mistmantle?",a="Stalvan Mistmantle owns the estate. The former tutor now exists as an undead creature, surrounded by ghouls.",al={"who is in mistmantle manor","manor mistmantle boss","stalvan house"},sp=1,it="residents",bt={"q66.7"}},{q="What is the Tear of Tilloa?",a="The Tear of Tilloa is a delicate flower blooming alone in Manor Mistmantle's garden. It is the only sign of natural life amid the decayed grounds.",al={"tear of tilloa flower","mistmantle garden flower","tilloa flower"},it="item"},{q="Why are there undead guarding the grounds?",a="Ghouls roam the manor grounds as minions bound to Stalvan Mistmantle. They guard their master and slaughter trespassers on his blighted estate.",al={"why are ghouls at mistmantle","mistmantle undead","manor mistmantle enemies"},sp=1,it="threat"},{q="What is Manor Mistmantle?",a="Manor Mistmantle is a secluded estate situated in the shadowy woods north of Darkshire and west of Beggar's Haunt. Once a respectable family homestead, it has devolved into a wretched haunt swarming with the undead. The grounds are rotten, silent, and grim, save for a solitary, eerie bloom growing amid the garden decay.",al={"what is manor mistmantle","mistmantle manor","about manor mistmantle"},it="place",add="9fd71122"},{q="What happened at Manor Mistmantle?",a="The estate belonged to the Mistmantle line, serving as the home of Stalvan Mistmantle, a former schoolmaster and tutor. Over time, Stalvan turned away from the light of civilized life and fell to dark madness, transforming into an agent of undeath. His downfall dragged the entire estate into ruin, blighting the land and drawing rotten horrors to dwell where a gentleman once lived.",al={"manor mistmantle history","what happened to mistmantle manor","history of manor mistmantle"},sp=1,it="history",add="592aed39"},{q="Why is Manor Mistmantle ruined and abandoned?",a="The manor collapsed into decay alongside its master, Stalvan Mistmantle. When Stalvan was consumed by death and corruption, the living caretakers vanished, and any semblance of normal life withered away. The unhallowed presence of the undead blighted the soil, leaving the estate rotted, forsaken, and overgrown by foul shadows.",al={"why is manor mistmantle ruined","mistmantle manor abandoned","why fell into ruin"},sp=1,it="ruin",add="2075468e"},{q="Is Manor Mistmantle dangerous?",a="It is exceptionally dangerous. The rotten estate is heavily guarded by Stalvan's ghoulish minions, who viciously slaughter anyone trespassing upon their master's rotting grounds. Approaching without proper preparation invites a swift and bloody demise at the hands of the restless dead.",al={"how dangerous is manor mistmantle","manor mistmantle threats","is mistmantle estate safe"},it="danger",add="136a4555"},{q="Why is it called Manor Mistmantle?",a="The estate takes its name from Stalvan Mistmantle and his family lineage. It served as his personal home and family stead before his descent into horror and corruption forever bound the family name to a place of nightmare.",al={"why called manor mistmantle","manor mistmantle name origin","who named manor mistmantle"},it="name",add="a2b55f99"}},ang={["faction:Alliance"]="As an Alliance investigator tracking the grim fate of Stalvan's victims, you reach Manor Mistmantle, the tragic end of the Legend of Stalvan."},kw={"beggar's haunt","darkshire","duskwood","ghouls","manor mistmantle","stalvan","stalvan mistmantle","tear of tilloa"},rel={"zone:duskwood","subzone:darkshire","subzone:beggar-s-haunt"},src={"Manor Mistmantle"}}
E["subzone:raven-hill"] = {t="subzone",n="Raven Hill",z="duskwood",s="The ruins of Raven Hill lie beneath the shadow of its vast cemetery in western Duskwood. Frightened squatters and invisible spirits are all that remain of the once lively human settlement.",h="The ruins of Raven Hill lie beneath the shadow of its vast cemetery in western Duskwood.",sec={{t="A Town Lost to Darkness",b="Raven Hill lies along Duskwood’s western road, just north of Addle’s Stead. Dark magic and undead horrors swept through the Grand Hamlet region, driving the living east toward Darkshire or out of the territory. Now ruined timber homes decay beneath the gloom. Travelers keep away, fearing the restless dead from the neighboring cemetery and the invisible Unseen among the crumbling walls.",sp=0},{t="The Few Who Remain",b="Only a handful remain among Raven Hill’s ruins. Jitters, a nervous adventurer, hides in the abandoned structures, afraid of the horrors stalking the woods. In a dilapidated attic, the goblin Bliztik ekes out a solitary living by selling supplies to wary passersby. They share the ruins with the invisible spirits called the Unseen, beside the sprawling burial grounds.",sp=0}},faq={{q="Why is Raven Hill abandoned?",a="Raven Hill was abandoned when darkness fell over Duskwood, bringing undead horrors, dark magic, and predatory beasts. So close to the vast cemetery, the town was difficult to defend, and survivors fled east toward Darkshire.",al={"what happened to raven hill","why is raven hill ruined","who lived in raven hill"},it="ruin"},{q="Who actually lives in the village now?",a="Only a few desperate or daring souls remain. Jitters, a terrified human, hides among the ruined foundations, burdened by guilt and fear. Bliztik, a goblin vendor, works from an upper floor and trades with anyone brave enough to search the abandoned buildings.",al={"who is in raven hill","raven hill npcs","living people raven hill"},it="residents"},{q="What are the Unseen haunting Raven Hill?",a="The Unseen are invisible, hostile spirits that wander Raven Hill and the nearby cemetery. They can become a sudden, deadly threat to any unwary traveler exploring the desolate township.",al={"unseen raven hill","invisible monsters raven hill","ghosts in raven hill"}},{q="Where does the road through Raven Hill lead?",a="The road past Raven Hill runs west toward the river bridge into Westfall, south toward Addle’s Stead and the border of Stranglethorn Vale, and east through Duskwood to Darkshire.",al={"raven hill road","where does road go","travel raven hill"},it="place",gp=true},{q="What is Raven Hill?",a="Raven Hill is an abandoned human village situated in western Duskwood, sitting just south of the vast Raven Hill Cemetery and north of Addle's Stead. Once a tranquil settlement of Grand Hamlet before the shadow fell across the region, it now stands desolate and broken amidst the encroaching gloom.",al={"what is raven hill","raven hill town","tell me about raven hill"},it="place",add="7c03a2db"},{q="What happened to Raven Hill?",a="Raven Hill shared the grim fate of the rest of Duskwood when dark sorcery and corrupting forces overtook the land. As horrors arose and the dead stirred in the adjacent graveyard, the town's folk were driven out or slaughtered, leaving behind dilapidated houses, roving predators, and a lingering shadow.",al={"raven hill history","what happened here raven hill","how did raven hill fall"},it="history",add="5a9ec9d9"},{q="Is Raven Hill dangerous?",a="Very dangerous. Beyond the beasts prowling the western woods, the abandoned buildings harbor invisible spirits known as the Unseen, while the monstrous undead of the nearby cemetery constantly threaten to spill into the empty streets.",al={"how dangerous is raven hill","threats in raven hill","is raven hill safe"},it="danger",add="03463183"}},ang={["faction:Alliance"]="For Alliance travelers crossing the bridge from Westfall, Raven Hill gives an ominous welcome to the nightmare overtaking western Duskwood.",["race:Human"]="As a human, these decaying cottages show how much territory the kingdom of Stormwind has lost to creeping darkness and neglect."},kw={"abandoned town","bliztik","cemetery","duskwood","jitters","raven hill","unseen"},rel={"subzone:raven-hill-cemetery","npc:jitters","subzone:darkshire","zone:duskwood","subzone:addle-s-stead","zone:westfall","topic:goblin","quest:163"},src={"Raven Hill"}}
E["subzone:raven-hill-cemetery"] = {t="subzone",n="Raven Hill Cemetery",z="duskwood",s="In western Duskwood, the dead rise from their graves at Raven Hill Cemetery. The burial ground once served nearby hamlets, but undead, spiders, and grave robbers now roam among the tombs.",h="In western Duskwood, the dead rise from their graves at Raven Hill Cemetery.",sec={{t="A Garden of the Restless Dead",b="Settlements around the Dawning Wood once buried their dead at Raven Hill Cemetery. Then dark sorceries fell upon the region, and the dead began clawing out of their plots. Skeletons, ghouls, and shambling horrors crowd the graveyard now. Rotting abominations and giant spiders prowl among the tombs, while desperate grave robbers plunder ancestral crypts beyond the reach of local authorities. Raven Hill remains one of Duskwood's most dangerous places.",sp=0},{t="Restless Spirits and Dark Powers",b="Morgan Ladimore patrols the headstones as Mor'Ladim, a mindless skeletal horror. Madness and sorrow drove the fallen knight to take his own life. North of the cemetery, the rises of Forlorn Rowe hold the necromancer Morbent Fel. He draws on the graves' foul energy to raise and bind legions of undead. Near the cemetery's northeastern edge, Abercrombie the hermit watches from his secluded shack at the edge of the mist.",sp=1}},faq={{q="Why are so many undead rising in Raven Hill Cemetery?",a="Dark corruption spread through the cemetery when Duskwood was blighted, and necromantic power seeped into the earth. From Forlorn Rowe, Morbent Fel twists that power to raise and control the dead.",al={"why are there zombies","why is raven hill haunted","who raised the dead in raven hill"},it="threat"},{q="Who is Mor'Ladim?",a="Mor'Ladim is a skeletal revenant who patrols the graveyard and attacks travelers. An investigation in Darkshire reveals his identity and past.",al={"morladim","skeleton wandering the graveyard","morgan ladimore"},sp=1,it="identity"},{q="Where is Morbent Fel located in the cemetery?",a="Morbent Fel dwells atop Forlorn Rowe, in the northwestern corner of Raven Hill Cemetery. From a decrepit house overlooking the tombstones, he directs the undead around him.",al={"morbent fel location","where is morbent fel","forlorn rowe"},it="target",gp=true},{q="Who is the hermit living on the edge of the cemetery?",a="Abercrombie is the hermit who lives in a ramshackle hut near the cemetery's northeastern borders. Frail and eccentric, he often asks passing travelers to gather strange components and ingredients for his morbid projects.",al={"hermit at raven hill","abercrombie","shack in raven hill"},it="residents"},{q="What is Raven Hill Cemetery?",a="Raven Hill Cemetery is a massive, sprawling graveyard located north of the town of Raven Hill in western Duskwood. Once a modest burial ground for the region, it has expanded to dominate much of the countryside following the dark curse that settled over the woods. Now abandoned by the living, the mist-shrouded grounds are overrun with restless ghouls, skeletons, venomous spiders, and ruthless grave robbers who scavenge among the defiled headstones and crypts.",al={"what is raven hill graveyard","raven hill cemetery info","about raven hill cemetery"},it="place",add="7e74b027"},{q="What happened at Raven Hill Cemetery?",a="Originally a peaceful resting place, the cemetery grew dramatically as dark forces corrupted Duskwood. With the land blighted and no one left to tend the graves, the necromancer Morbent Fel moved into the house at Forlorn Rowe to weave fell enchantments that stirred the dead from their graves.",al={"raven hill cemetery lore","history of raven hill cemetery","what happened here"},sp=1,it="history",add="0b017ec9"},{q="Why is Raven Hill Cemetery abandoned?",a="The cemetery fell into ruin as Duskwood fell victim to darkness and the dead began to rise. With no one left to tend the plots and the necromancer Morbent Fel actively animating corpses across the grounds, ordinary folk fled the area, leaving it to scavenging grave robbers and ravenous undead.",al={"why is raven hill ruined","why is the cemetery abandoned","who abandoned raven hill cemetery"},sp=1,it="ruin",add="d27e3c55"},{q="Is Raven Hill Cemetery dangerous?",a="It is one of the most perilous places in Duskwood. The cemetery crawls with flesh eaters, plague spreaders, skeletal horrors, and deadly black widow spiders, while ruthless grave robbers attack anyone who disrupts their plunder. Far worse is the terrifying, wandering shade of Mor'Ladim, an exceptionally powerful undead monster who roams the gravestones and brings swift death to travelers caught unawares.",al={"how dangerous is raven hill cemetery","is raven hill cemetery safe","threats in raven hill cemetery"},it="danger",add="323c5989"}},ang={["class:Paladin"]="As a paladin, you face graves and corruption that call for holy consecration.",["class:Priest"]="As a priest, you find shadow and sorrow in these graves, a bleak reminder of spirits denied passage to the Light."},kw={"abercrombie","duskwood","forlorn rowe","grave robbers","mor'ladim","morbent fel","raven hill cemetery","skeletons"},rel={"zone:duskwood","topic:mor-ladim","subzone:forlorn-rowe","quest:55","npc:abercrombie","subzone:darkshire","quest:163"},src={"Raven Hill Cemetery"}}
E["subzone:roland-s-doom"] = {t="subzone",n="Roland's Doom",z="duskwood",s="Nightbane worgen prowl the abandoned mine at Roland's Doom, east of the Rotting Orchard in southeastern Duskwood.",h="Nightbane worgen prowl the abandoned mine at Roland's Doom, east of the Rotting Orchard in southeastern...",sec={{t="A Den of Shadows and Savagery",b="East of the Rotting Orchard, Roland's Doom lies among the ridges of southeastern Duskwood. The mine has stood idle for a long while. Now Nightbane worgen use its tunnels as a staging ground, led by such chieftains as Gutspill and Nefaru. Their snarls carry through the dark shafts. Blood stains the damp earth, and those who enter face one of Duskwood's most perilous places.",sp=0},{t="The Fall of Velinde Starsong",b="Velinde Starsong, a night elven priestess, met her end deep in Roland's Doom while bearing the Scythe of Elune. The ancient artifact held immense and volatile power. Disturbed earth in the mine can stir Velinde's lingering spirit, who speaks of her final moments. Later, the terrified wanderer Jitters found the scythe there. By accident, he released more savage worgen, drawing the deadly Dark Riders to Duskwood.",sp=1,bt={"q1022.6"}}},faq={{q="What is Roland's Doom?",a="Roland's Doom lies east of the Rotting Orchard in southeastern Duskwood. Nightbane worgen have overrun the abandoned mine.",al={"where is rolands doom","what is this mine"},it="place"},{q="Why are there worgen inside the mine?",a="Nightbane worgen occupy the mine after the Scythe of Elune was lost there. Powerful beasts, including Nefaru and Gutspill, make their lair in its shafts.",al={"why worgen here","who lives in rolands doom"},sp=1,it="why_here"},{q="Who was Velinde Starsong and why is she connected to this place?",a="Velinde Starsong was a night elven priestess of Elune who wielded the Scythe of Elune against demons in Felwood. Her journey carried her across the sea to Duskwood, where she died inside Roland's Doom and left the scythe behind.",al={"velinde starsong rolands doom","who died here"},sp=1,it="people",bt={"q1022.6"}},{q="How does Jitters fit into the story of Roland's Doom?",a="Jitters entered Roland's Doom and found the buried Scythe of Elune. His meddling accidentally released more worgen into Duskwood and drew the Dark Riders to the region, bringing greater peril to the forest.",al={"jitters mine","jitters scythe"},sp=1,it="ties"},{q="What happened at Roland's Doom?",a="This abandoned mine became the tragic crossroads of Duskwood's curse. The night elf priestess Velinde Starsong perished here while bearing the Scythe of Elune. Later, a terrified man named Jitters uncovered the artifact buried within the dark tunnels. His meddling unleashed the ferocious worgen upon the surrounding hills, drawing dark powers to the region and cementing Duskwood's descent into nightmare.",al={"history of rolands doom","what happened in the mine","rolands doom backstory"},sp=1,it="history",add="c3cc68a4",bt={"q1022.6"}},{q="Who controls Roland's Doom?",a="The mine has been completely overrun by feral worgen of the Nightbane pack. Deep inside lurk Nefaru and Gutspill, vicious alpha beasts who command the pack infesting both the subterranean shafts and the nearby Rotting Orchard.",al={"who lives in rolands doom","who leads rolands doom","rolands doom boss"},it="residents",add="4c556f83"},{q="Is Roland's Doom dangerous?",a="It is exceptionally perilous. The tight, unlit tunnels are crawling with aggressive worgen ready to ambush anyone who steps inside. Beyond the beasts themselves, the mine is steeped in dark sorcery tied to the Scythe of Elune, and the restless spirits of those who died here still linger in the shadows.",al={"how dangerous is rolands doom","rolands doom threats"},it="danger",add="fe4bd8ed"}},ang={["race:NightElf"]="For night elves, the search for the missing priestess Velinde Starsong and the Scythe of Elune brings thoughts of their kin's fate at Roland's Doom.",["profession:Mining"]="As a miner, you know Roland's Doom is no place to work a pick. Bloodthirsty worgen stalk its tunnels."},kw={"gutspill","jitters","nefaru","nightbane","roland's doom","rolands doom","rotting orchard","scythe of elune","velinde starsong"},rel={"quest:1043","quest:1044","quest:1037","topic:worgen","subzone:rotting-orchard","zone:duskwood","npc:jitters","topic:dark-riders"},src={"Roland's Doom"}}
E["subzone:rotting-orchard"] = {t="subzone",n="Rotting Orchard",z="duskwood",s="In southern Duskwood, the Rotting Orchard has fallen to the Nightbane worgen. Its fruit once fed nearby Darkshire, but now the trees and buildings lie in ruin.",h="In southern Duskwood, the Rotting Orchard has fallen to the Nightbane worgen.",sec={{t="Den of the Nightbane",b="Nightbane worgen have made camps among the Rotting Orchard’s ruined barns and outbuildings. The grove lies east of the ruined Yorgen Farmstead and west of Tranquil Gardens Cemetery. Withered fruit hangs from the trees as Nightbane Stalkers prowl the twisted brush. Nightbane Shadow Weavers practice dark magic among the decaying timber. The fierce worgen Gutspill and Nefaru lead the pack from their lair in the nearby mine of Roland's Doom.",sp=0}},faq={{q="What creatures occupy the Rotting Orchard?",a="Ravenous worgen of the Nightbane pack occupy the orchard. Nightbane Stalkers prowl its brush, while Nightbane Shadow Weavers cast dark spells among the trees and buildings.",al={"rotting orchard mobs","who lives in rotting orchard","what is at rotting orchard"},it="residents"},{q="Where is the Rotting Orchard located in Duskwood?",a="The Rotting Orchard lies in southern Duskwood, southwest of Darkshire. It lies between the ruined Yorgen Farmstead to the west and Tranquil Gardens Cemetery to the east.",al={"rotting orchard location","where is rotting orchard","how to find rotting orchard"},it="place"},{q="Who leads the worgen in this orchard?",a="Gutspill and Nefaru lead the Nightbane worgen from their lair in the mine of Roland's Doom, just east of the orchard.",al={"rotting orchard boss","who leads nightbane"},it="leader"},{q="Was this place always overrun by monsters?",a="No. The orchard once served as a productive farm and fruit grove for the local human populace. Dark curses and supernatural horrors overtook the region and drove the farmers away.",al={"orchard history","why is orchard rotting"},it="history"},{q="What is the Rotting Orchard?",a="The Rotting Orchard is an abandoned, blighted farmstead located in southern Duskwood, resting between the Yorgen Farmstead and the Tranquil Gardens Cemetery. Once a productive fruit grove, it has deteriorated into a desolate ruin overrun by the ravenous worgen of the Nightbane pack, who nest among its crumbling barns and shadowy trees.",al={"what is rotting orchard","rotting orchard duskwood lore","tell me about the rotting orchard"},it="place",add="a6a9a2a8"},{q="Is the Rotting Orchard dangerous?",a="It is extremely hazardous. The orchard crawls with ferocious Nightbane worgen. Stalkers lurk unseen in the dim shadows while dark weavers cast foul magics across their camps. To make matters worse, the pack's brutal leaders, Gutspill and Nefaru, lurk in the nearby mine of Roland's Doom.",al={"is rotting orchard safe","rotting orchard danger","threats in rotting orchard"},it="danger",add="144dad4c"}},ang={["faction:Alliance"]="For the Alliance, the Nightbane worgen threaten Darkshire’s fragile security from just up the road.",["class:Hunter"]="As a hunter, you can stalk through the twisted trees and ruined outbuildings. But the Nightbane pack’s keen senses and spellcraft make every approach dangerous."},kw={"darkshire","duskwood","nightbane","rotting orchard","shadow weavers","worgen"},rel={"zone:duskwood","topic:worgen","subzone:darkshire","subzone:yorgen-farmstead","subzone:tranquil-gardens-cemetery"},src={"Rotting Orchard"}}
E["subzone:scarlet-raven-tavern"] = {t="subzone",n="Scarlet Raven Tavern",z="duskwood",s="In Darkshire, Scarlet Raven Tavern is the town’s primary inn and gathering place. Tavernkeep Smitts welcomes weary locals, passing adventurers and frightened travelers seeking shelter from the horrors beyond town.",h="In Darkshire, Scarlet Raven Tavern is the town’s primary inn and gathering place.",sec={{t="A Dim Refuge",b="The Scarlet Raven Tavern offers a dim refuge in Darkshire, where the hearth burns beneath the forest’s eternal dusk. Years ago, Marshal Haggard and the Stormwind Guard stopped here for pints after patrols. Since then, business has dwindled as the town’s security has weakened.\n\nTavernkeep Smitts tends the bar for a somber, anxious crowd seeking warmth against the cold and fear. The inn remains a place to trade rumors and a starting point for travelers seeking answers about the dark forces consuming the region.",sp=0},{t="Secrets and Stolen Pints",b="Jitters rented a room at the Scarlet Raven for several days. By night, the reclusive wanderer filled his journal with frantic notes, then fled town ahead of the Dark Riders.\n\nOld gossip and guest records kept beneath the tavern also hold ties to figures such as Stalvan Mistmantle. Those who investigate Duskwood’s restless dead begin their search in Smitts’ taproom.",sp=1}},faq={{q="Who runs the Scarlet Raven Tavern?",a="Tavernkeep Smitts runs the Scarlet Raven Tavern. An innkeeper and other staff also serve travelers in Darkshire.",al={"innkeeper of darkshire","who owns the scarlet raven","tavernkeep smitts"},it="residents"},{q="Why is the tavern's atmosphere so gloomy?",a="The curse over Duskwood has choked trade routes and terrified the locals. Undead, feral worgen and shadowy riders prowl the woods, so frightened townsfolk and desperate mercenaries fill the tavern instead of carefree travelers.",al={"why is scarlet raven depressing","darkshire inn atmosphere"}},{q="Did Jitters stay at the Scarlet Raven?",a="Jitters stayed at the Scarlet Raven Tavern and filled his journal with frantic notes before fleeing town. His reasons emerge during the investigation into Duskwood.",al={"jitters room","jitters tavern","did jitters live here"}},{q="What connection does this tavern have to the Legend of Stalvan?",a="Old patrons and town records preserved in and around the tavern hold clues about Stalvan Mistmantle. He once frequented the settlement before tragedy and infamy claimed him.",al={"stalvan inn connection","stalvan mistmantle darkshire inn"},it="history"},{q="What is the Scarlet Raven Tavern?",a="The Scarlet Raven Tavern is the local inn of Darkshire, providing a roof, warm hearth, and cold drink to the beleaguered folk of Duskwood. In a region choked by encroaching shadows and terrors, it remains the primary gathering point for townsfolk, weary travelers, and wandering adventurers looking to trade gossip or rest their feet.",al={"what is scarlet raven tavern","scarlet raven darkshire","darkshire inn"},it="place",add="81b305d7"},{q="Is the Scarlet Raven Tavern dangerous?",a="Within its walls, the Scarlet Raven is one of the few safe havens left in Duskwood. Protected by the proximity of the Night Watch and the shelter of Darkshire, the inn keeps the horrors of the woods outside, even if the patrons inside are troubled and watchful.",al={"is scarlet raven dangerous","is darkshire inn safe","scarlet raven safe"},it="danger",add="27f7fada"}},ang={["faction:Alliance"]="For Alliance travelers crossing the southern border, the Scarlet Raven offers one of the few safe hearths and resting places between Elwynn Forest and Deadwind Pass.",["profession:Cooking"]="The inn serves regional delicacies such as Dusky Crab Cakes, a local staple that desperate wanderers like Jitters crave even while hiding in the graveyard."},kw={"darkshire","duskwood","dusky crab cakes","haggard","jitters","scarlet raven","smitts","tavernkeep smitts"},rel={"subzone:darkshire","zone:duskwood","npc:tavernkeep-smitts","npc:jitters","quest:266","quest:93","quest:66","topic:dark-riders"},src={"Scarlet Raven Tavern"}}
E["subzone:tranquil-gardens-cemetery"] = {t="subzone",n="Tranquil Gardens Cemetery",z="duskwood",s="Southeast of Darkshire, Tranquil Gardens Cemetery is overrun by shambling skeletons and ghouls. The dead make it a danger to the nearby town.",h="Southeast of Darkshire, Tranquil Gardens Cemetery is overrun by shambling skeletons and ghouls.",sec={{t="Restless Grounds",b="Once the people of Grand Hamlet laid their dead in Tranquil Gardens Cemetery. Then dark curses settled over Duskwood, and the buried began clawing out of their plots. Skeletal warriors and mages haunt the gravestones, along with wandering undead. They are weaker than the horrors deeper in the woods, but their nearness to Darkshire makes them a constant threat to the townsfolk.",sp=0},{t="On the Town's Threshold",b="Tranquil Gardens Cemetery lies near Darkshire's edge, where the Night Watch holds its line. The Watch sends fresh recruits and arriving adventurers to thin the rising dead before they reach the settlement. Yet more dangerous foes lurk among the tumbled headstones and the ruined chapel. The Insane Ghoul is one of them.",sp=0}},faq={{q="Why is it called Tranquil Gardens if it is full of undead?",a="Tranquil Gardens Cemetery was established when Darkshire was still Grand Hamlet, a peaceful settlement in a sunlit forest. Local families meant it to be a quiet and dignified resting place. The name turned grimly ironic when the curse fell over the region and the dead began rising from their graves.",al={"why tranquil","tranquil gardens name origin","why is it called tranquil"},it="name"},{q="What threats wander around the cemetery?",a="Shambling skeletons, skeletal warriors and skeletal mages haunt the grounds. A particularly vicious Insane Ghoul haunts the ruined chapel or roams among the headstones.",al={"enemies in tranquil gardens","what mobs are here","cemetery mobs"},it="danger"},{q="Why does the Night Watch send recruits here?",a="The cemetery sits immediately southeast of Darkshire, and unchecked undead threaten to spill into town. The Night Watch sends recruits there to face weaker undead before they enter the dangerous forest.",al={"night watch cemetery quest","why cull tranquil gardens","who protects the cemetery"},it="purpose"},{q="Who lives just north of the cemetery?",a="Just north of Tranquil Gardens Cemetery, an isolated cottage is home to Blind Mary, a spirit who lingers near the blighted graveyard.",al={"house near tranquil gardens","ghost north of cemetery","blind mary house"},it="residents"},{q="What is Tranquil Gardens Cemetery?",a="Tranquil Gardens Cemetery is an old burial ground lying just southeast of Darkshire in Duskwood. Once a peaceful resting place, the dark curse overtaking the region has stirred the dead from their graves. The cemetery features overgrown plots and a ruined chapel, now overrun by wandering skeletons and ghouls.",al={"what is tranquil gardens","tranquil gardens cemetery lore","tell me about tranquil gardens"},it="place",add="86a6efa8"},{q="Why is Tranquil Gardens Cemetery in ruins?",a="Like much of Duskwood, Tranquil Gardens fell into decay when darkness and unnatural blights consumed the territory. The graveyard's church fell to ruin, and the dead clawed their way out of the consecrated ground, forcing living caretakers to abandon the grounds entirely.",al={"why is tranquil gardens ruined","tranquil gardens cemetery ruined","why is the chapel ruined"},it="ruin",add="77d44972"}},ang={["class:Paladin"]="As a paladin, you face an affront to the Holy Light in Tranquil Gardens Cemetery. There, you prove yourself by bringing peace to Duskwood's restless dead.",["faction:Alliance"]="As an Alliance champion arriving in Darkshire, you help defend the nearby graveyard and keep the town's perimeter safe from the undead."},kw={"cemetery","darkshire","duskwood","gardens","insane ghoul","skeletons","tranquil"},rel={"subzone:darkshire","topic:night-watch","quest:56","npc:blind-mary","zone:duskwood"},src={"Tranquil Gardens Cemetery"}}
E["subzone:twilight-grove"] = {t="subzone",n="Twilight Grove",z="duskwood",s="At Duskwood's center, Twilight Grove shelters lush Kalimdor flora beneath its great tree. A moonwell and ancient night elf architecture surround a massive emerald gateway to the Emerald Dream.",h="At Duskwood's center, Twilight Grove shelters lush Kalimdor flora beneath its great tree.",sec={{t="A Sanctuary in the Gloom",b="Behind steep crater ridges in Duskwood's heart, Twilight Grove seems utterly alien to the Eastern Kingdoms. Night elf gazebos and green meadows surround a serene moonwell. An unnamed great tree towers over the gloomy canopy.\n\nThe tree draws vigor from the Emerald Dream into the waking world. So the crater thrives beneath Duskwood's eternal gloom.",sp=0},{t="The Emerald Gateway",b="At the great tree's base stands a massive stone portal, one of four known gateways linking the physical realm directly to the Emerald Dream. Ysera's green dragonflight traditionally watches over this gateway. Dark whispers say malevolent forces have begun twisting the tranquil realm beyond.\n\nThe gateway remains largely silent. Yet its emerald swirl warns that cosmic corruption may spill into Duskwood from paths deeper than the Scourge or the local worgen.",sp=0}},faq={{q="Why is there night elf architecture in Duskwood?",a="Night elf hands raised the gazebos and moonwell around the grove's great tree and its gateway to the Emerald Dream. Few know when or how they came to stand so far from Kalimdor.",al={"elf ruins duskwood","why night elf buildings here","moonwell in duskwood"},it="origin"},{q="What is the giant glowing green portal?",a="It is a Great Tree portal leading directly into the Emerald Dream, the primordial blueprint of Azeroth overseen by the green dragonflight. Three similar portals stand in Ashenvale, Feralas, and the Hinterlands.",al={"green portal duskwood","emerald dream portal duskwood","stone archway in grove"},it="purpose"},{q="Who watches over the grove today?",a="Lieutenants of Ysera's green dragonflight have guarded the sanctuary. Travelers often find it empty, but growing disturbances within the Emerald Dream threaten to send corrupted guardians through the portal into the mortal world.",al={"who guards twilight grove","green dragons twilight grove"},it="residents"},{q="Why doesn't the Twilight Grove look dead like the rest of Duskwood?",a="The great tree channels the Emerald Dream's pure, untamed life energy. Its steady flow protects the inner basin from the supernatural curse and blight choking the surrounding woods.",al={"why is twilight grove green","why alive in duskwood"},it="today"},{q="What is Twilight Grove?",a="Twilight Grove is a secluded, lush basin hidden in the center of Duskwood. Centered around an unnamed Great Tree, a tranquil moonwell, and elven architecture, it connects Azeroth directly to the Emerald Dream through a massive, swirling portal. Unlike the rest of the dark and haunted forest, nature here remains vibrantly alive.",al={"what is twilight grove","twilight grove duskwood","twilight grove lore"},it="place",add="a63f3ab3"},{q="What happened at Twilight Grove?",a="Little is recorded of the grove's origins. Its great tree serves as a conduit to the Emerald Dream, and the night elven gazebos and moonwell around it show that kaldorei once tended it. Today, growing corruption within the Dream threatens the green dragons who watch over the portal.",al={"twilight grove history","history of twilight grove","how was twilight grove created"},it="history",add="4ad09d10"},{q="Is Twilight Grove dangerous?",a="While the grove appears serene compared to the undead horrors roaming Duskwood, its portal leads into the Emerald Dream, which suffers from growing nightmare corruption. The green dragons charged with watching over these boughs risk succumbing to madness, making the tranquil hollow a place of immense slumbering peril.",al={"is twilight grove safe","twilight grove danger","dangers of twilight grove"},it="danger",add="69043853"}},ang={["class:Druid"]="As a druid exploring the Eastern Kingdoms, you find a rare oasis of home here, with an active moonwell and a direct link to the ancestral dreamways.",["race:NightElf"]="For you, a secluded moonwell and traditional gazebos so far from Kalimdor recall your people's ancient duty to heal Azeroth's wounds."},kw={"duskwood","emerald dream","great tree","green dragonflight","moonwell","portal","twilight grove"},rel={"zone:duskwood","topic:emerald-dream","topic:druid","zone:ashenvale","zone:feralas","zone:hinterlands"},src={"Twilight Grove"}}
E["subzone:vul-gol-ogre-mound"] = {t="subzone",n="Vul'Gol Ogre Mound",z="duskwood",s="In southern Duskwood, Vul'Gol Ogre Mound shelters the Splinter Fist ogres and their chieftain, Zzarc'Vul. Ruined farmhouses and a cavern beneath the basin hold the clan's carcasses and scavenged plunder.",h="In southern Duskwood, Vul'Gol Ogre Mound shelters the Splinter Fist ogres and their chieftain, Zzarc'Vul.",sec={{t="A Blighted Homestead",b="Southwest of the fork toward Stranglethorn Vale, the basin belongs to the Splinter Fist clan. Human families once farmed here, but they fled or perished. Hollow cabins remain, and the ogres use them for shelter. In the cavern beneath the rise, slaughtered black bears lie in piles. Zzarc'Vul rules the encampment, keeping odd trinkets beside ordinary goods the clan has scavenged.",sp=0},{t="A Menace on the Southern Border",b="Darkshire's Night Watch is stretched thin, guarding the town from rabid worgen and restless dead. Commander Althea Ebonlocke and her militia rely on outside mercenaries to thin the Splinter Fist ranks before the ogres push north. The clan has also raided the recluse Abercrombie and stolen a crate of his alchemical tools. Inquisitive mages seek arcane lenses that Zzarc'Vul is rumored to possess.",sp=0}},faq={{q="Who lives in the Vul'Gol Ogre Mound?",a="The Splinter Fist clan of ogres lives at Vul'Gol, led by the chieftain Zzarc'Vul. They dwell in ruined human cottages and a cavern beneath the basin.",al={"who is at vul'gol","vul'gol enemies","ogres in duskwood"},it="residents"},{q="Why hasn't the Night Watch cleared out the ogres?",a="The Night Watch lacks the manpower to attack the southern basin in force. Darkshire faces undead, worgen, and the horrors of Addle's Stead, so the militia hires traveling adventurers to thin the Splinter Fist ranks instead of risking its guards.",al={"night watch ogres","why doesn't darkshire attack vul'gol"},it="threat"},{q="Who lived here before the ogres?",a="Human homesteaders once farmed this peaceful pocket of southern Duskwood. When the curse fell on the land, the farms fell to ruin, and invading ogres claimed the abandoned buildings.",al={"ruined buildings vul'gol","vul'gol history"},it="ruin"},{q="Why did the hermit Abercrombie send me here?",a="The Splinter Fist ogres ambushed Abercrombie and stole a crate of his herbs and embalming tools. Unable to fight them himself, he sends travelers to the mound to recover his goods.",al={"abercrombie ogres","abercrombie crate"},it="why_here"},{q="Where is the mound located?",a="Vul'Gol lies in far southern Duskwood, southwest of the road junction that leads south toward the Stranglethorn Vale border.",al={"vul'gol location","how to get to vul'gol"},it="place",gp=true},{q="What is Vul'Gol Ogre Mound?",a="The Vul'Gol Ogre Mound is a sunken basin in southern Duskwood, situated just southwest of the fork where the road turns toward Stranglethorn Vale. Once home to human farmers, the hollow has been seized and transformed into a crude stronghold for the brutish Splinter Fist ogres, complete with muddy earthen mounds and a cave filled with their grisly kills.",al={"what is vulgol ogre mound","vulgol mound info","what is this place"},it="place",add="40dc9221"},{q="What happened to the farmsteads at Vul'Gol?",a="Human homesteaders once farmed this fertile basin before Duskwood fell under shadow and fell beasts encroached. When the Splinter Fist ogres invaded the area, the settlers were killed or driven out, and their farmhouses were left in ruins. Today, the basin stands fully corrupted into an ogre outpost, littered with bear carcasses and bones instead of crops.",al={"history of vulgol","what happened at vulgol","vulgol ogre mound past"},it="history",add="7dda38fd"},{q="Is Vul'Gol Ogre Mound dangerous?",a="It is exceptionally perilous. The hollow teems with aggressive Splinter Fist ogres and their enforcers, who attack travelers on sight and ransack nearby wanderers. Furthermore, deep within their cavern lair resides their cunning leader, Zzarc'Vul. The Night Watch considers clearing the basin far too costly for their sparse ranks, relying instead on seasoned mercenaries to cull the threat.",al={"how dangerous is vulgol","is vulgol dangerous","vulgol mound danger level"},it="danger",add="60de4358"}},ang={["faction:Alliance"]="For Alliance travelers, keeping the Splinter Fist contained at Vul'Gol helps keep the southern route to Stranglethorn Vale open through a dangerous forest.",["race:Human"]="As a human, the smashed farmsteads in the basin remind you how much of Duskwood the kingdom of Stormwind has lost over the past generation."},kw={"abercrombie","duskwood","night watch","ogres","splinter fist","vul'gol","zzarc'vul"},rel={"zone:duskwood","topic:night-watch","npc:abercrombie","quest:134","npc:viktori-prism-antras","zone:stranglethorn","topic:alliance"},src={"Vul'Gol Ogre Mound"}}
E["subzone:yorgen-farmstead"] = {t="subzone",n="Yorgen Farmstead",z="duskwood",s="Defias outlaws hold Yorgen Farmstead in southern Duskwood. Sven Yorgen fled north to a camp along the Darkened Bank.",h="Defias outlaws hold Yorgen Farmstead in southern Duskwood.",sec={{t="A Ruined Homestead",b="Yorgen Farmstead lies in southern Duskwood, where Sven Yorgen once worked the land. Danger drove him north to a makeshift camp along the Darkened Bank. Outlaws took the farm after he left, seeking ground beyond Stormwind's reach.",sp=0},{t="Defias Infiltration",b="The Defias Brotherhood uses Yorgen Farmstead as a staging ground. Masked highwaymen and cutthroats hide among its fences and outbuildings, screened by dense trees. Defias assassins patrol the grounds and ambush travelers who trespass.",sp=0}},faq={{q="Who owns the Yorgen Farmstead?",a="Sven Yorgen once owned and farmed Yorgen Farmstead. Rising dangers drove him from home to a solitary camp farther north along the Darkened Bank.",al={"who lived here","who owns yorgen farm","sven yorgen farm"},it="name"},{q="Who occupies the farmstead now?",a="The Defias Brotherhood occupies the deserted farm. Cutpurses, bandits, and hidden assassins prowl its overgrown yards and barnyards, making any visit dangerous.",al={"who is at yorgen farmstead","what enemies are here","who lives here now"},it="residents"},{q="Where did Sven Yorgen go?",a="Sven Yorgen left the farm for a modest camp along the Darkened Bank. It lies north of Yorgen Farmstead beside the river between Duskwood and Elwynn Forest.",al={"where is sven","sven yorgen location","find sven yorgen"}},{q="Why is the Defias Brotherhood in Duskwood?",a="The Defias Brotherhood has carried its operations far beyond Westfall. Disorganized rural settlements and weakened defenses let its agents establish hidden camps and strongholds beyond the reach of Stormwind's marshals.",al={"defias in duskwood","why are bandits here","defias brotherhood farm"}},{q="What is the Yorgen Farmstead?",a="The Yorgen Farmstead is a derelict farm situated in southern Duskwood. Once a peaceful homestead owned and worked by Sven Yorgen, it has fallen into ruin along with much of the shadowed region. Today, the farm has been seized and occupied by brigands of the Defias Brotherhood.",al={"what is yorgen farmstead","yorgen farmstead info","tell me about yorgen farmstead"},it="place",add="70ba336a"},{q="Is the Yorgen Farmstead dangerous?",a="Yes, approaching the farmstead is exceptionally perilous. The grounds are infested with members of the Defias Brotherhood, including stealthy assassins who patrol unseen among the ruined buildings and overgrown fields, ready to ambus anyone who strays too close.",al={"is yorgen farmstead dangerous","danger yorgen farmstead","yorgen farm threats"},it="danger",add="7755c939"}},ang={["class:Rogue"]="As a rogue, you can see Defias assassins using the neglected farmstead as a concealed hideout.",["faction:Alliance"]="As an Alliance member, you can see how far the Defias Brotherhood has spread through Duskwood. The Night Watch struggles to keep order in Darkshire."},kw={"darkened bank","defias","defias brotherhood","duskwood","farm","sven yorgen","yorgen farmstead"},rel={"npc:sven-yorgen","zone:duskwood","topic:defias-brotherhood","subzone:darkened-bank"},src={"Yorgen Farmstead"}}
E["topic:mor-ladim"] = {t="topic",n="Mor'Ladim",z="duskwood",s="At Raven Hill Cemetery, Mor'Ladim stalks the grounds as a vengeful skeletal warrior. Once Morgan Ladimore, he lost his family to Duskwood's ruin, then grief and madness drove him to rise in undeath and kill those who cross his path.",h="At Raven Hill Cemetery, Mor'Ladim stalks the grounds as a vengeful skeletal warrior.",sec={{t="A Knight of the Silver Hand",b="Before Raven Hill feared his name, Morgan Ladimore defended the helpless from Grand Hamlet, now called Darkshire. He married Lys at eighteen, and they raised three children in peace. Then war called him north. During the Third War, Morgan marched with Uther the Lightbringer to Lordaeron. There he witnessed the fall of the Knights of the Silver Hand, the spread of Kel'Thuzad's plague, and Uther's death.",sp=0},{t="The Fall of Morgan Ladimore",b="After the war, Morgan returned to a darkened Duskwood and found his homestead in ruins. Among the headstones at Raven Hill Cemetery, he found the graves of Lys and two of their children. Grief and fury overtook him, and he struck at the stones. When cemetery attendants tried to calm him, Morgan killed them in a blind frenzy.\n\nClarity returned, and horror at what he had done drove Morgan to plunge his own blade into his heart. Ashamed, the townsfolk buried him in a remote, unmarked corner of the cemetery.",sp=1},{t="The Scourge of Raven Hill",b="Guilt over the innocent blood Morgan had shed and his suffocating grief stirred his corrupted remains from the earth. He rose as a hulking skeletal revenant, finding no peace in the grave. Travelers and the Night Watch soon learned to fear the name Mor'Ladim. With his ancestral blade Archeus, he patrols the misty graves, cutting down beasts and unwary travelers who stray near his resting place.",sp=0}},faq={{q="Who was Mor'Ladim in life?",a="In life, Mor'Ladim was Morgan Ladimore, an honorable paladin and knight from Grand Hamlet. During the Third War, he fought alongside Uther the Lightbringer in Lordaeron.",al={"who is morladim","morladim backstory","morgan ladimore lore","who was morladim"},sp=1,it="identity"},{q="Why is Mor'Ladim hostile?",a="Grief drove Morgan mad when he found his family's graves. After killing innocent cemetery attendants and taking his own life, guilt and anguish bound his soul to his body. He rose as a murderous undead warrior.",al={"why does morladim attack","why is he angry","morladim madness"},sp=1,it="hostile"},{q="Where does Mor'Ladim roam?",a="Mor'Ladim roams Raven Hill Cemetery in western Duskwood, patrolling its paths and mausoleums. His wide patrol route often catches travelers unaware.",al={"morladim path","where to find morladim","morladim location"},it="why_here"},{q="Did all of Morgan Ladimore's family die?",a="No. Lys and two of Morgan's children died, but their third child survived Duskwood's decline. Morgan never learned this in his despair at the graveyard.",al={"did morgan ladimore family survive","morgan ladimore daughter","who survived in ladimore family"},sp=1},{q="What is the weapon Mor'Ladim carries?",a="Mor'Ladim carries Archeus, the fine blade that served him as a knight in life and became his weapon in undeath.",al={"morladim sword","archeus sword","what sword does morladim use"},sp=1},{q="Who wants Mor'Ladim destroyed?",a="Commander Althea Ebonlocke and the Night Watch of Darkshire seek Mor'Ladim's destruction. They aim to protect patrols and travelers from his ambushes in western Duskwood.",al={"who wants morladim dead","night watch morladim","althea ebonlocke morladim"},it="threat"},{q="What is the history of Mor'Ladim?",a="Mor'Ladim was once Sir Morgan Ladimore, a noble knight from Duskwood who marched north to fight the Scourge in Lordaeron under Uther the Lightbringer. When he returned home years later, he found his homeland corrupted into Duskwood and his house destroyed. Searching Raven Hill Cemetery, he discovered the graves of his wife and two of his children. Overcome by grief and madness, he slaughtered the cemetery attendants who tried to calm him. Horrified by what he had done upon coming to his senses, Morgan took his own life. Shortly after his hasty burial, dark energies resurrected him as a restless monstrosity.",al={"mor'ladim backstory","morgan ladimore lore","how did mor'ladim die"},it="history",add="fdd06828"},{q="How did Mor'Ladim get his name?",a="His monstrous moniker is a corrupted derivation of his living name, Morgan Ladimore. When the knight rose from his unhallowed grave as a semi-sentient undead horror, the tormented remnant of his identity became twisted into the terror the locals now dread as Mor'Ladim.",al={"why is he called mor'ladim","mor'ladim name origin","mor'ladim name meaning"},it="name",add="aff5d09b"}},ang={["class:Paladin"]="As a paladin, you can see Morgan Ladimore was once an honorable warrior of the Light who fought alongside Uther the Lightbringer. His fall shows the danger of letting sorrow and wrath eclipse sacred vows.",["faction:Alliance"]="As an Alliance member, you can see how the Third War shattered southern kingdoms like Stormwind. Morgan Ladimore returned from war to find his family and home ruined."},kw={"althea ebonlocke","archeus","duskwood","grand hamlet","lys ladimore","mor'ladim","morgan ladimore","raven hill"},rel={"subzone:raven-hill-cemetery","zone:duskwood","subzone:darkshire","npc:althea-ebonlocke","topic:knights-of-the-silver-hand","topic:third-war","topic:lordaeron","topic:light"},src={"Mor'Ladim"}}
E["topic:night-watch"] = {t="topic",n="Night Watch",z="duskwood",s="In Duskwood, the Night Watch holds Darkshire and the forest roads against rising threats. Stormwind's House of Nobles has left the volunteers to face undead, feral worgen, and necromancy under Commander Althea Ebonlocke. They rely on travelers to defend their home.",h="In Duskwood, the Night Watch holds Darkshire and the forest roads against rising threats.",sec={{t="Abandoned by the Crown",b="Stormwind withdrew its royal garrison after foul magic consumed the Grand Hamlet and changed the forest into Duskwood. King Varian Wrynn had disappeared, so the troops were recalled to the capital. Darkshire's townsfolk were left without royal soldiers or supplies. They formed the Night Watch and swore to defend the borders from horrors creeping out of the woods.",sp=0},{t="A Frontline in the Mist",b="From its headquarters in Darkshire, the Night Watch patrols roads buried in unnatural mist. Skeletal fiends and ghouls rise from Raven Hill and Tranquil Gardens cemeteries. Feral worgen prowl Roland's Doom and Brightwood Grove. The militia is badly outnumbered and short of resources, and many of its finest defenders have fallen to threats like Mor'Ladim, the wandering skeletal warrior.",sp=0},{t="The Vigil of Commander Ebonlocke",b="Commander Althea Ebonlocke, daughter of Darkshire's mayor, directs the defense with grim resolve. With no veteran reinforcements, she calls on capable travelers to thin skeletal legions, cull starving wolf packs, and investigate mysterious local murders. The Night Watch is the last barrier protecting human life in the region. If its lines break, Darkshire will fall into shadow.",sp=0}},faq={{q="Why does Stormwind not send troops to help the Night Watch?",a="With King Varian Wrynn missing, Stormwind's House of Nobles is caught in political gridlock. The crown withdrew its garrisons, leaving Duskwood's people to defend themselves.",al={"why no stormwind guards","where is stormwind army","why duskwood abandoned"},it="conflict"},{q="Who commands the Night Watch?",a="Commander Althea Ebonlocke leads the Night Watch from its office in Darkshire. Daughter of Mayor Lord Ello Ebonlocke, she organizes road patrols, bounties, and defenses across Duskwood.",al={"who leads the night watch","night watch commander","who is in charge of darkshire watch"},it="leader"},{q="What threats does the Night Watch fight most often?",a="The Night Watch most often faces risen undead from Tranquil Gardens Cemetery and Raven Hill, feral wolf packs, and worgen stalking Brightwood Grove and Roland's Doom.",al={"duskwood enemies","what do watchers fight","night watch threats"},it="threat"},{q="Who is Mor'Ladim, and why do the Watchers fear him?",a="Mor'Ladim is a powerful undead warrior who wanders Raven Hill Cemetery. He has slain several of the Night Watch's strongest patrols and is among the zone's deadliest threats.",al={"mor'ladim lore","morladim night watch","cemetery boss duskwood"},it="danger"},{q="Are the Watchers professional soldiers or volunteers?",a="The Watchers are local volunteers: farmers, hunters, and townsfolk who took up weapons to survive. Local veterans trained them, but they lack formal military backing, royal equipment, and regular military wages.",al={"are watchers guards","night watch background","is night watch an army"},it="people"},{q="Where is the Night Watch headquarters located?",a="The Night Watch headquarters is in the heart of Darkshire. Commander Althea Ebonlocke and her officers plan patrols there and receive reports from sentries along the trails.",al={"night watch building","where to find watchers","darkshire watch hall"},it="place"},{q="What is the Night Watch?",a="The Night Watch is a local policing militia formed and maintained by the people of Darkshire to defend Duskwood. After Stormwind withdrew its garrisons from the region, the local townsfolk were left entirely to fend for themselves. Armed with torches, steel, and stubborn resolve, these Watchers patrol the misty roads and woods to guard innocent settlers from the ravenous undead, feral worgen, and lurking predators that threaten to overrun the dark forest.",al={"who are the night watch","night watch darkshire","what is night watch"},it="identity",add="56aed563"},{q="Why was the Night Watch formed?",a="When King Varian Wrynn disappeared, political intrigue in Stormwind—heavily influenced by Lady Katrana Prestor—resulted in royal troops being recalled from Duskwood. Abandoned by the crown and beset by horrors emerging from the cursed woods, the citizens of Darkshire were forced to raise their own defense force. Trained by their own commanders, they organized to hold back the encroaching cemetery undead and the savage worgen stalking the groves.",al={"history of night watch","why did night watch form","night watch origin"},it="history",add="ab90ac97"},{q="Who is the Night Watch allied with?",a="The Night Watch serves the town of Darkshire and the people of Duskwood, answering directly to Mayor Ello Ebonlocke and their commander, Althea Ebonlocke. While Duskwood remains loyal in spirit to the Grand Alliance, the kingdom of Stormwind provides them no official military reinforcement or aid. As a result, the Watch relies heavily on passing Alliance adventurers and brave travelers willing to lend their weapons against the surrounding terrors.",al={"night watch allies","who does night watch work for","night watch stormwind"},it="allies",add="4f96e3a4"}},ang={["race:Human"]="As a human of the kingdom, you see how Stormwind's noble court has left fellow citizens to face death in the shadows.",["faction:Alliance"]="As an Alliance hero in Darkshire, you find a frontline community defending the border against nightmarish forces without aid from the high command.",["class:Paladin"]="As a paladin, you can answer the Night Watch's desperate vigil with holy magic and shield ordinary townsfolk from rampant necromancy.",["class:Warrior"]="As a warrior, you stand beside rugged militia members who face ghouls, giant spiders, and worgen with basic steel and raw grit."},kw={"althea ebonlocke","darkshire","duskwood","militia","mor'ladim","night watch","raven hill","stormwind","worgen"},rel={"subzone:darkshire","zone:duskwood","npc:althea-ebonlocke","quest:56","subzone:raven-hill-cemetery","topic:mor-ladim","topic:worgen","quest:145"},src={"Night Watch"}}
E["zone:duskwood"] = {t="zone",n="Duskwood",z="duskwood",s="In Duskwood, unending gloom hides the forest's sunlit past beneath a curse. Stormwind has abandoned its human inhabitants, who cling to survival in Darkshire under the Night Watch's protection. Ghouls, giant venomous spiders, raiding ogres, and savage, mysterious worgen roam the groves and haunted barrows.",h="In Duskwood, unending gloom hides the forest's sunlit past beneath a curse.",sec={{t="From Sunlight to Shadow",b="Duskwood once fed the Kingdom of Stormwind with rich farmland and prosperous settlements such as Grand Hamlet and Raven Hill. Its ruin began when Guardian Medivh fell at Karazhan during the First War. Waves of corrupted fel magic twisted the woodland into a gnarled, shadowy morass.\n\nSpiders became terrible predators, and fleeing wolves spilled north into Elwynn Forest. Grand Hamlet became Darkshire, where townsfolk were left largely to fend for themselves after the royal garrison withdrew to defend the capital.",sp=0},{t="The Scythe and the Wolf-Men",b="Night elf priestess Velinde Starsong brought the Scythe of Elune to Duskwood. After she vanished in Roland's Doom, a disused mine, prospecting laborer Jitters eventually unearthed the relic. Careless handling of the weapon unleashed worgen, ravenous bipedal wolf-beasts from beyond this world. Shrouded in perpetual mist and bloodlust, these predators tore through the western groves. They added to the misery of a region already burdened by undead curses.",sp=1,bt={"q1022.6"}},{t="A Beleaguered Borderland",b="Commander Althea Ebonlocke and her volunteer militia, the Night Watch, keep Darkshire alive. Lord Ello Ebonlocke tries to govern the crumbling settlement. Beyond the town's lantern-lit perimeter, danger fills the land. The restless dead raised by necromancer Morbent Fel stir in massive Raven Hill Cemetery. Vul'Gol ogres came from Deadwind Pass to claim the south, while Dark Riders stalk the crossroads in relentless search of the lost Scythe.",sp=0},{t="The Twilight Grove",b="Near Duskwood's center lies a deep, ancient crater untouched by the surrounding corruption: the Twilight Grove. An ancient Great Tree there holds a dormant portal into the Emerald Dream. Soft, ethereal twilight bathes this unearthly sanctuary in the dying land. Sleeping druidic energies watch over it.",sp=0}},faq={{q="Why is it called Duskwood?",a="Duskwood was once a vibrant, sunlit province of Stormwind. When Guardian Medivh was slain at nearby Karazhan during the First War, volatile fel energies washed over the forest, choking out the sunlight and twisting the flora. The darkness gave the land its name.",al={"why duskwood dark","brightwood history","what happened to brightwood"},it="name"},{q="Where did the worgen come from?",a="Night elf Velinde Starsong brought the mystical Scythe of Elune to the region and vanished near Roland's Doom. Years later, a frightened worker named Jitters disturbed the scythe in the mine. Unwittingly, he opened tears that summoned savage wolf-men into the forest.",al={"why are there worgen","worgen origin duskwood","scythe of elune worgen"},sp=1,it="origin",bt={"q1022.6"}},{q="Why are there so many undead in Raven Hill?",a="Raven Hill Cemetery holds countless souls lost to famine, beasts, and war. The vile necromancer Morbent Fel made his lair on Forlorn Rowe and used dark sorcery to animate the graves into ghouls, skeletons, and abominations.",al={"raven hill undead","why ghosts in duskwood","morbent fel undead"},it="threat"},{q="Why hasn't Stormwind sent soldiers to help Darkshire?",a="With King Varian Wrynn missing and resources stretched thin, Stormwind's regency pulled its military back to protect Elwynn and the throne. Darkshire is left to its own devices, defended solely by the volunteer Night Watch.",al={"why no stormwind guard","stormwind abandoned darkshire","where is the army"},it="conflict"},{q="Who are the Dark Riders stalking the woods?",a="The Dark Riders are mysterious hooded horsemen from Deadwind Pass near Karazhan. Drawn by the Scythe of Elune's release, they swept into Duskwood and ruthlessly slaughtered Sven Yorgen's family while hunting the artifact.",al={"black riders deadwind","riders at yorgen farm","who are dark riders"},sp=1,it="identity"},{q="What is the massive tree in the center crater?",a="The crater is the Twilight Grove, home to an ancient Great Tree. The tree contains a dormant portal to the Emerald Dream. The grove keeps a calm, mystical twilight distinct from the forest's cursed darkness.",al={"twilight grove tree","green portal duskwood","crater tree"},it="place"},{q="What is Duskwood? Why is it always dark here?",a="Duskwood is a gloomy, heavily forested region south of Elwynn. It was once a verdant province of the Kingdom of Stormwind. The land fell into unnatural perpetual twilight when Medivh was slain at Karazhan, unleashing waves of dark magical energy that withered the flora, summoned a dense black fog, and attracted countless abominations to wander beneath the boughs.",al={"why is duskwood dark","what happened to duskwood","duskwood lore"},it="place",add="31aef3fe",nx={8,9}},{q="Was Duskwood always like this?",a="No. Before the First War, it was a sunlit region featuring thriving settlements like Grand Hamlet and Raven Hill. Raids by the Old Horde and the magical cataclysm stemming from Medivh's fall transformed the sunny woodland into the shadowed realm of nightmares you see today.",al={"was duskwood always dark","brightwood history","past of duskwood"},it="history",add="a3ed01d1"},{q="Is the darkness in Duskwood magical or natural?",a="It is entirely magical. The constant overcast sky and choking fog stem from dark curses unleashed by Medivh's demise in nearby Deadwind Pass, combined with ancient artifacts like the Scythe of Elune disturbing the natural order of the forest.",al={"is duskwood fog magic","magical curse duskwood","why no sun duskwood"},it="power",add="9267ad89"},{q="Who's in charge of Darkshire?",a="Darkshire is governed by Lord Ello Ebonlocke, the mayor, alongside the Council of Darkshire. The town relies heavily on its own citizens to maintain order and dispense justice in the town hall.",al={"darkshire leader","who rules darkshire","council of darkshire"},it="in_charge",add="aa573e0c",nx={11,12}},{q="Who is Lord Ello Ebonlocke?",a="Lord Ello Ebonlocke is the patriarch of the prominent Ebonlocke nobility whose roots in Grand Hamlet predate the First War. As mayor, he stubbornly struggles to keep Darkshire running despite being cut off from military aid by Stormwind's royal court.",al={"who is ello ebonlocke","lord ebonlocke","mayor of darkshire"},it="leader",add="63356d06"},{q="Is Darkshire still loyal to Stormwind?",a="Yes, Darkshire remains technically loyal to the Alliance and King Anduin, but the people harbor deep bitterness. They feel completely abandoned by the capital's nobility, leaving them to fend for themselves against monsters on every border.",al={"is darkshire alliance","darkshire stormwind loyal","does darkshire answer to stormwind"},it="ties",add="a73a6b59"},{q="What is the Night Watch and why do they need my help?",a="The Night Watch is a local volunteer militia formed and trained by Darkshire's citizens to patrol the main roads and defend the village. With Stormwind's army withdrawn, they are spread far too thin fighting ghouls, skeletons, worgen, and beasts, forcing them to hire traveling adventurers to thin the threats.",al={"what is the night watch","night watch militia","why help night watch"},it="purpose",add="ec7f551f",nx={14}},{q="Who is Commander Althea Ebonlocke?",a="Commander Althea Ebonlocke is Lord Ello's daughter and the resolute leader of the Night Watch. She coordinates the defense of Darkshire and directly enlists heroes to strike back at the undead and other monstrosities creeping out of the woods.",al={"commander althea","who is althea ebonlocke","night watch commander"},it="identity",add="be442b70"},{q="Where are all these skeletons and ghouls coming from?",a="The dead stir primarily from Raven Hill Cemetery and Tranquil Gardens Cemetery. The necromancer Morbent Fel, lurking in his home atop Forlorn Rowe, actively practices dark arts to raise corpses, turning the region's resting places into walking legions.",al={"why undead duskwood","skeletons duskwood source","where do ghouls come from"},it="threat",add="c10a928d"},{q="What happened at Raven Hill? Why is it abandoned?",a="Raven Hill was once a sizable town sister to Grand Hamlet. When dark curses and monstrous creatures overran the surrounding countryside, the living fled or were slaughtered. Today, its sprawling cemetery has swallowed the area, and only a few terrified outcasts like Jitters dare step near its ruins.",al={"raven hill history","why is raven hill abandoned","what happened raven hill"},it="history",add="f53dcf97"},{q="Why is everyone in Darkshire so grim and scared?",a="The villagers live in constant dread. They are besieged on all sides by unnatural predators, worgen, and restless dead, with no official reinforcements from Stormwind. Any journey beyond the torchlit center of town risks an ambush by horrors creeping in the dark.",al={"darkshire people afraid","why is darkshire scared","darkshire paranoia"},it="threat",add="64d771df"},{q="Is Duskwood dangerous?",a="Extremely dangerous. The roads are prowled by feral worgen, giant venomous spiders, roving ghouls, aggressive ogres, and Defias bandits. Straying even slightly off the path into the woods can put you face-to-face with lethal undead champions or unseen horrors.",al={"is duskwood dangerous","how dangerous is duskwood","threat level duskwood"},it="danger",add="2e45eefe"},{q="How did I end up in Duskwood?",a="You likely crossed south from the sunny orchards of Elwynn across the Nazferiti River, or followed the road southeast from the arid plains of Westfall. Alternatively, travelers often arrive over the southern bridge from Redridge after aiding the folk of Lakeshire. As soon as you passed beneath the thick canopy, the daylight vanished behind an impenetrable gloom. The Kingdom of Stormwind still claims this province on parchment, but its soldiers have long since abandoned the frontier, leaving anyone who steps across its borders to walk these shadowed roads alone.",al={"how did i get to duskwood","how did i get here","where did i come from duskwood"},it="arrival",add="4f653c45"},{q="What am I supposed to be doing in Duskwood?",a="Darkshire is fighting a desperate war for its own survival, and with Stormwind refusing to send reinforcements, its citizens look to any capable traveler for aid. The local militia, the Night Watch, needs your blade to beat back the ghouls, skeletons, and nightmarish worgen encroaching upon the town and roads. Inquire with Commander Althea Ebonlocke and Mayor Ello Ebonlocke in Darkshire, or travel west to investigate the graveyard horrors surrounding Raven Hill. Whether clearing overgrown spiders or investigating the dark history haunting abandoned homesteads, this land will test your mettle to its absolute limits.",al={"what do i do in duskwood","why am i here duskwood","what is my goal here"},it="purpose",add="39e18767"}},ang={["faction:Alliance"]="As an Alliance holding, Duskwood gets no official troop support from Stormwind. The Night Watch and heroic adventurers alone stand between its people and annihilation.",["class:Paladin"]="As a paladin, you face an urgent trial in Raven Hill's desecrated barrows, where Morbent Fel's sinister necromancy calls for the Light.",["class:Druid"]="As a druid, you can study the ancient Great Tree's deep ties to the Emerald Dream and investigate the world's slumbering magic.",["profession:Herbalism"]="As an herbalist, you can find rare plants such as Grave Moss and Kingsblood in the haunted barrows and cursed soil. They draw gatherers willing to brave the restless undead in the cemeteries."},kw={"althea ebonlocke","brightwood","darkshire","duskwood","ello ebonlocke","jitters","morbent fel","night watch","raven hill","scythe of elune","sven yorgen","twilight grove","worgen"},rel={"subzone:darkshire","subzone:raven-hill-cemetery","subzone:twilight-grove","topic:night-watch","npc:althea-ebonlocke","npc:jitters","quest:1043","quest:55"},m={levels="18-30"},src={"Duskwood (Classic)","Duskwood"}}
